function CreateNewLandSubteam(iPlateau, iIsland, tAiBotBrainsInSubteam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'CreateNewLandSubteam'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    iTotalLandSubteamCount = iTotalLandSubteamCount + 1
    tLandSubteamData[iTotalLandSubteamCount] = {}
    tLandSubteamData[iTotalLandSubteamCount][subrefiLandCorePlateau] = iPlateau
    tLandSubteamData[iTotalLandSubteamCount][subrefiLandCoreIsland] = iIsland
    tLandSubteamData[iTotalLandSubteamCount][subrefBlueprintBlacklist] = {}

    tLandSubteamData[iTotalLandSubteamCount][subreftoFriendlyAiBotBrains] = {}
    for iBrain, oBrain in tAiBotBrainsInSubteam do
        table.insert(tLandSubteamData[iTotalLandSubteamCount][subreftoFriendlyAiBotBrains], oBrain)
        oBrain.AiBotLandSubteam = iTotalLandSubteamCount
    end
    tLandSubteamData[iTotalLandSubteamCount][subrefFactoriesByTypeFactionAndTech] = {[AiBotFactory.refiFactoryTypeLand] = {},
                                                                                     [AiBotFactory.refiFactoryTypeAir] = {},
                                                                                     [AiBotFactory.refiFactoryTypeNaval] = {},
                                                                                     [AiBotFactory.refiFactoryTypeOther] = {}}
    for iFactoryType, tSubtable in tLandSubteamData[iTotalLandSubteamCount][subrefFactoriesByTypeFactionAndTech] do
        tLandSubteamData[iTotalLandSubteamCount][subrefFactoriesByTypeFactionAndTech][iFactoryType] = {[AiBotUnitInfo.refFactionUEF] = {},
                     [AiBotUnitInfo.refFactionAeon] = {},
                     [AiBotUnitInfo.refFactionCybran] = {},
                     [AiBotUnitInfo.refFactionSeraphim] = {},
                     [AiBotUnitInfo.refFactionNomads] = {},
                     [AiBotUnitInfo.refFactionUnrecognised] = {}}
        for iFaction, tSubtable in tLandSubteamData[iTotalLandSubteamCount][subrefFactoriesByTypeFactionAndTech][iFactoryType] do
            tLandSubteamData[iTotalLandSubteamCount][subrefFactoriesByTypeFactionAndTech][iFactoryType][iFaction] = {[1]=0,[2]=0,[3]=0}
        end
    end
    ForkThread(AiBotLand.LandSubteamOverseer, iTotalLandSubteamCount)
    if bDebugMessages == true then LOG(sFunctionRef..': Finished creating subteam for '..iTotalLandSubteamCount..'; tLandSubteamData[iTotalLandSubteamCount][subrefFactoriesByTypeFactionAndTech]='..repru(tLandSubteamData[iTotalLandSubteamCount][subrefFactoriesByTypeFactionAndTech])) end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)

end



function CreateNewAirSubteam(aiBrain)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'CreateNewAirSubteam'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    iTotalAirSubteamCount = iTotalAirSubteamCount + 1
    aiBrain.AiBotAirSubteam = iTotalAirSubteamCount
    tAirSubteamData[aiBrain.AiBotAirSubteam] = {}
    tAirSubteamData[aiBrain.AiBotAirSubteam][subreftoFriendlyAiBotBrains] = {}
    tAirSubteamData[aiBrain.AiBotAirSubteam][reftACUExpAndPriorityDefenceOnSubteam] = {}
    tAirSubteamData[iTotalAirSubteamCount][reftWaterZonesHasFriendlyTorps] = {}
    if not(tTeamData[aiBrain.AiBotTeam][subrefAirSubteamsInTeam]) then tTeamData[aiBrain.AiBotTeam][subrefAirSubteamsInTeam] = {} end
    table.insert(tTeamData[aiBrain.AiBotTeam][subrefAirSubteamsInTeam], iTotalAirSubteamCount)
    table.insert(tAirSubteamData[aiBrain.AiBotAirSubteam][subreftoFriendlyAiBotBrains], aiBrain)


    local tNearestEnemyBase = AiBotMap.GetPrimaryEnemyBaseLocation(aiBrain)
    if bDebugMessages == true then LOG(sFunctionRef..': aiBrain='..aiBrain.Nickname..'; Index='..aiBrain:GetArmyIndex()..'; tNearestEnemyBase='..repru(tNearestEnemyBase)..'; Our start point='..repru(AiBotMap.PlayerStartPoints[aiBrain:GetArmyIndex()])) end
    local iOurAngleToNearestEnemy = AiBotUtilities.GetAngleFromAToB(AiBotMap.GetPlayerStartPosition(aiBrain), tNearestEnemyBase)
    local bSameAirSubteam
    --Low threshold - if within this dist will be grouped regardless of angle difference
    --High threshold - if within certain angle differential then will group if satisfy this distance
    local iDistThresholdLow = math.max(math.min(aiBrain[AiBotOverseer.refiDistanceToNearestEnemyBase] * 0.8, 100), aiBrain[AiBotOverseer.refiDistanceToNearestEnemyBase] * 0.3)
    local iDistThresholdHigh = math.max(math.min(aiBrain[AiBotOverseer.refiDistanceToNearestEnemyBase] * 0.9, 130), aiBrain[AiBotOverseer.refiDistanceToNearestEnemyBase] * 0.5)
    if bDebugMessages == true then LOG(sFunctionRef..': Our dist to enemy='..aiBrain[AiBotOverseer.refiDistanceToNearestEnemyBase]..'; Low threshold='..iDistThresholdLow..'; High threshold='..iDistThresholdHigh..'; Angle to nearest enemy='..iOurAngleToNearestEnemy) end

    --Cycle through each brain in our team without a AirSubteam and consider if they should be in the same AirSubteam as this brain
    for iBrain, oBrain in tTeamData[aiBrain.AiBotTeam][subreftoFriendlyActiveAiBotBrains] do
        --Make sure we have a primary base and distance to nearest enemy recorded
        AiBotMap.GetPrimaryEnemyBaseLocation(oBrain)
        if not(oBrain.AiBotAirSubteam) and not(oBrain == aiBrain) then
            bSameAirSubteam = false
            local iBaseDistDif = AiBotUtilities.GetDistanceBetweenPositions(AiBotMap.GetPlayerStartPosition(oBrain), AiBotMap.GetPlayerStartPosition(aiBrain))
            if bDebugMessages == true then LOG(sFunctionRef..': Considering ally brain '..oBrain.Nickname..'; iBaseDistDif='..iBaseDistDif..'; iAngleDif='..AiBotUtilities.GetAngleDifference(iOurAngleToNearestEnemy, AiBotUtilities.GetAngleFromAToB(AiBotMap.GetPlayerStartPosition(oBrain), tNearestEnemyBase))) end
            if iBaseDistDif <= iDistThresholdLow then
                bSameAirSubteam = true
            else
                local iAngleDif = AiBotUtilities.GetAngleDifference(iOurAngleToNearestEnemy, AiBotUtilities.GetAngleFromAToB(AiBotMap.GetPlayerStartPosition(oBrain), tNearestEnemyBase))
                if iAngleDif <= 40 or (iAngleDif <= 60 and iBaseDistDif <= iDistThresholdHigh) then
                    bSameAirSubteam = true
                else
                    --Are we close to the start position of any of the other brains already recorded in this AirSubteam?
                    for iAirSubteamBrain, oAirSubteamBrain in tAirSubteamData[aiBrain.AiBotAirSubteam][subreftoFriendlyAiBotBrains] do
                        if not(oAirSubteamBrain == aiBrain) and not(oAirSubteamBrain == oBrain) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Dist to alternative AirSubteam member '..oAirSubteamBrain.Nickname..' = '..AiBotUtilities.GetDistanceBetweenPositions(AiBotMap.GetPlayerStartPosition(oBrain), AiBotMap.GetPlayerStartPosition(oAirSubteamBrain))) end
                            if AiBotUtilities.GetDistanceBetweenPositions(AiBotMap.GetPlayerStartPosition(oBrain), AiBotMap.GetPlayerStartPosition(oAirSubteamBrain)) <= iDistThresholdLow then
                                bSameAirSubteam = true
                            end
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': On same AirSubteam='..tostring(bSameAirSubteam)) end
            if bSameAirSubteam then
                oBrain.AiBotAirSubteam = aiBrain.AiBotAirSubteam
                table.insert(tAirSubteamData[aiBrain.AiBotAirSubteam][subreftoFriendlyAiBotBrains], oBrain)
            end
        end
    end

    AiBotAir.AirSubteamInitialisation(aiBrain.AiBotTeam, aiBrain.AiBotAirSubteam) --Dont fork thread
    if bDebugMessages == true then LOG(sFunctionRef..': Finished creating air subteam for aiBrain='..aiBrain.Nickname..' on AiBotTeam='..aiBrain.AiBotTeam..'; AiBotAirSubteam='..aiBrain.AiBotAirSubteam) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function UpdateUpgradeTrackingOfUnit(oUnitDoingUpgrade, bUnitDeadOrCompletedUpgrade, sUnitUpgradingRef)
    --bUnitDeadOrCompletedUpgrade is true if  a structure has just died or completed building a structure, in which case the unit might not have been upgrading but want to check
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'UpdateUpgradeTrackingOfUnit'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local sUpgradeTableRef
    if EntityCategoryContains(AiBotUnitInfo.refCategoryAllHQFactories, oUnitDoingUpgrade.UnitId) then
        sUpgradeTableRef = subreftTeamUpgradingHQs
    elseif EntityCategoryContains(AiBotUnitInfo.refCategoryMex, oUnitDoingUpgrade.UnitId) then
        sUpgradeTableRef = subreftTeamUpgradingMexes
    elseif EntityCategoryContains(categories.COMMAND, oUnitDoingUpgrade.UnitId) then
        sUpgradeTableRef = subreftTeamUpgradingACUs
    else
        sUpgradeTableRef = subreftTeamUpgradingOther
    end
    local iTableRefOfUnit

    if AiBotUtilities.IsTableEmpty(tTeamData[oUnitDoingUpgrade:GetAIBrain().AiBotTeam][sUpgradeTableRef]) == false then
        for iUnit, oUnit in tTeamData[oUnitDoingUpgrade:GetAIBrain().AiBotTeam][sUpgradeTableRef] do
            if oUnit == oUnitDoingUpgrade then
                iTableRefOfUnit = iUnit
                break
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': sUpgradeTableRef='..sUpgradeTableRef..'; Is table of upgrading units empty='..tostring(AiBotUtilities.IsTableEmpty(tTeamData[oUnitDoingUpgrade:GetAIBrain().AiBotTeam][sUpgradeTableRef]))..'; iTableRefOfUnit if already in table='..(iTableRefOfUnit or 'nil')..'; oUnitDoingUpgrade='..oUnitDoingUpgrade.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitDoingUpgrade)) end
    if iTableRefOfUnit then
        if bUnitDeadOrCompletedUpgrade then
            local iTeam = oUnitDoingUpgrade:GetAIBrain().AiBotTeam
            table.remove(tTeamData[iTeam][sUpgradeTableRef], iTableRefOfUnit)
            local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnitDoingUpgrade:GetPosition(), true, oUnitDoingUpgrade)
            local iWaterZone, iPond
            local tBackupLZData, tLZOrWZTeamData
            if (iLandZone or 0) > 0 then tLZOrWZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTeamData][iTeam]
            else
                iWaterZone = AiBotMap.GetWaterZoneFromPosition(oUnitDoingUpgrade:GetPosition())
                iPond = AiBotMap.tiPondByWaterZone[iWaterZone]
                if iWaterZone > 0 and iPond > 0 then
                    tLZOrWZTeamData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iWaterZone][AiBotMap.subrefWZTeamData][iTeam]
                end
            end
            if not(tLZOrWZTeamData) then
                tBackupLZData, tLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnitDoingUpgrade:GetPosition(), true, iTeam)
                if bDebugMessages == true then LOG(sFunctionRef..': Activated backup logic for locating zone, is tLZOrWZTeamData empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZTeamData))) end
                if not(tLZOrWZTeamData) then
                    AiBotUtilities.ErrorHandler('Unable to find a land zone for unit doing upgrade='..(oUnitDoingUpgrade.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnitDoingUpgrade) or 'nil'))
                    if bDebugMessages == true then LOG(sFunctionRef..': Error further details: reftAssignedPlateauAndLandZoneByTeam='..repru(oUnitDoingUpgrade[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam])) end
                end
            end
            if AiBotUtilities.IsTableEmpty(tTeamData[iTeam][AiBotMap.subreftoActiveUpgrades]) == false then
                for iUnit, oUnit in tTeamData[iTeam][AiBotMap.subreftoActiveUpgrades] do
                    if oUnit == oUnitDoingUpgrade then
                        if bDebugMessages == true then LOG(sFunctionRef..': About to remove unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' from the table of upgrades for the team '..iTeam..'; Unit iPlateau='..iPlateau..'; iLZ='..iLandZone) end
                        table.remove(tTeamData[iTeam][AiBotMap.subreftoActiveUpgrades], iUnit)
                        break
                    end
                end
            end
            --Remove from land zone list of upgrades
            if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoActiveUpgrades]) == false then
                for iUnit, oUnit in tLZOrWZTeamData[AiBotMap.subreftoActiveUpgrades] do
                    if oUnit == oUnitDoingUpgrade then
                        if bDebugMessages == true then LOG(sFunctionRef..': About to remove unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' from the table of upgrades for iPlateau '..iPlateau..'; iLZ='..(iLandZone or 'nil')..'; iWaterZone='..(iWaterZone or 'nil')) end
                        table.remove(tLZOrWZTeamData[AiBotMap.subreftoActiveUpgrades], iUnit)
                    end
                end
            end
            local iActiveMexUpgrades = 0
            if AiBotConditions.IsTableOfUnitsStillValid(tLZOrWZTeamData[AiBotMap.subreftoActiveUpgrades]) then
                for iUnit, oUnit in tLZOrWZTeamData[AiBotMap.subreftoActiveUpgrades] do
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryMex, oUnit.UnitId) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Recording we have an active mex upgrade, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Work progress='..oUnit:GetWorkProgress()..'; Fraction complete='..oUnit:GetFractionComplete()..'; Unit state='..AiBotUnitInfo.GetUnitState(oUnit)) end
                        iActiveMexUpgrades = iActiveMexUpgrades + 1
                    end
                end
            end
            if tLZOrWZTeamData then
                tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades] = iActiveMexUpgrades
            else
                if bDebugMessages == true then LOG(sFunctionRef..': Failed ot have valid team data so wont update number of active mex upgrades') end
            end
            if AiBotMap.bIsCampaignMap then
                --Trigger on death callback if relevant

                if bDebugMessages == true then LOG(sFunctionRef..': Finished upgrading oUnitDoingUpgrade='..oUnitDoingUpgrade.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitDoingUpgrade)..'; Have we run unit killed event='..tostring(oUnitDoingUpgrade[AiBotEvents.refbAlreadyRunUnitKilled] or false)..'; Brain='..oUnitDoingUpgrade:GetAIBrain().Nickname..'; Objective unit='..tostring(oUnitDoingUpgrade[AiBotUnitInfo.refbObjectiveUnit] or false)) end
                if oUnitDoingUpgrade[AiBotUnitInfo.refbObjectiveUnit] and not(oUnitDoingUpgrade[AiBotEvents.refbAlreadyRunUnitKilled]) and oUnitDoingUpgrade:GetAIBrain().CampaignAI and oUnitDoingUpgrade.DoUnitCallbacks and EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oUnitDoingUpgrade.UnitId) then
                    --local ScenarioFramework = import('/lua/ScenarioFramework.lua')
                    oUnitDoingUpgrade:DoUnitCallbacks('OnKilled')
                    if bDebugMessages == true then LOG(sFunctionRef..': Have manually run an onkilled callback for the objective unit') end
                end

            end
        elseif bDebugMessages == true then LOG(sFunctionRef..': Unit already in the table so wont readd it')
        end
    else
        if not(bUnitDeadOrCompletedUpgrade) then
            local iTeam = oUnitDoingUpgrade:GetAIBrain().AiBotTeam
            table.insert(tTeamData[iTeam][sUpgradeTableRef], oUnitDoingUpgrade)
            if sUnitUpgradingRef then
                local oNewUnitBP = __blueprints[sUnitUpgradingRef]
                if bDebugMessages == true then LOG(sFunctionRef..': About to update the energy and mass upgrades started this cycle for the unti energy and amss costs. Mass upgrade before this='..(tTeamData[iTeam][subrefiMassUpgradesStartedThisCycle] or 'nil')) end
                if oNewUnitBP then
                    local iOurBuildPower = oUnitDoingUpgrade:GetBlueprint().Economy.BuildRate
                    local iBuildCost = oNewUnitBP.Economy.BuildTime
                    if iBuildCost > 0 and iOurBuildPower > 0 then
                        local iResourceFactor = 0.1 * iOurBuildPower / iBuildCost
                        tTeamData[iTeam][subrefiEnergyUpgradesStartedThisCycle] = (tTeamData[iTeam][subrefiEnergyUpgradesStartedThisCycle] or 0) + (oNewUnitBP.Economy.BuildCostEnergy or 0) * iResourceFactor
                        tTeamData[iTeam][subrefiMassUpgradesStartedThisCycle] = (tTeamData[iTeam][subrefiMassUpgradesStartedThisCycle] or 0) + (oNewUnitBP.Economy.BuildCostMass or 0) * iResourceFactor
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Updated this cycle check, tTeamData[iTeam][subrefiMassUpgradesStartedThisCycle]='..(tTeamData[iTeam][subrefiMassUpgradesStartedThisCycle] or 'nil')) end
            end
            local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnitDoingUpgrade:GetPosition(), true, oUnitDoingUpgrade)
            local iWaterZone, iPond
            local tLZOrWZTeamData
            if (iLandZone or 0) > 0 then tLZOrWZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTeamData][iTeam]
            else
                iWaterZone = AiBotMap.GetWaterZoneFromPosition(oUnitDoingUpgrade:GetPosition())
                iPond = AiBotMap.tiPondByWaterZone[iWaterZone]
                if iWaterZone > 0 and iPond > 0 then
                    tLZOrWZTeamData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iWaterZone][AiBotMap.subrefWZTeamData][iTeam]
                end
            end
            if not(tLZOrWZTeamData) then
                local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnitDoingUpgrade:GetPosition())
                if (iPlateauOrZero or -1) >= 0 then
                    if iPlateauOrZero == 0 then
                        tLZOrWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone][AiBotMap.subrefWZTeamData][iTeam]
                        iWaterZone = iLandOrWaterZone
                    else
                        iLandZone = iLandOrWaterZone
                        iPlateau = iPlateauOrZero
                        tLZOrWZTeamData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone][AiBotMap.subrefLZTeamData][iTeam]
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': tTeamData[iTeam][AiBotMap.subreftoActiveUpgrades] before adding unit='..reprs(tTeamData[iTeam][AiBotMap.subreftoActiveUpgrades])) end
            if tLZOrWZTeamData then
                if not(tLZOrWZTeamData[AiBotMap.subreftoActiveUpgrades]) then
                    tLZOrWZTeamData[AiBotMap.subreftoActiveUpgrades] = {}
                    if bDebugMessages == true then LOG(sFunctionRef..': LZ Upgrade was nil so making it a table, reprs='..reprs(tLZOrWZTeamData[AiBotMap.subreftoActiveUpgrades])) end
                end
                table.insert(tLZOrWZTeamData[AiBotMap.subreftoActiveUpgrades], oUnitDoingUpgrade)
                local iActiveMexUpgrades = 0
                for iUnit, oUnit in tLZOrWZTeamData[AiBotMap.subreftoActiveUpgrades] do
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryMex, oUnit.UnitId) then
                        iActiveMexUpgrades = iActiveMexUpgrades + 1
                        if bDebugMessages == true then LOG(sFunctionRef..': Updating iActiveMexUpgrades for oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Work progress='..oUnit:GetWorkProgress()..'; Fraction complete='..oUnit:GetFractionComplete()..'; Unit state='..AiBotUnitInfo.GetUnitState(oUnit)) end
                    end
                end
                tLZOrWZTeamData[AiBotMap.subrefiActiveMexUpgrades] = iActiveMexUpgrades
                if bDebugMessages == true then LOG(sFunctionRef..': Just added unit to the upgrade table for the team '..iTeam..'; Plateau '..iPlateau..'; LZ='..(iLandZone or 'nil')..'; iWaterZone='..(iWaterZone or 'nil')..'; Is table of active upgrades empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoActiveUpgrades]))..'; Reprs of tLZOrWZTeamData[activeupgrades]='..reprs(tLZOrWZTeamData[AiBotMap.subreftoActiveUpgrades])) end
            end
        elseif bDebugMessages == true then LOG(sFunctionRef..': Unit dead or compelted, but not in the table so no need to remove it')
        end
    end

    --Clear trackers from the unit that was doing the upgrade

    if bUnitDeadOrCompletedUpgrade and oUnitDoingUpgrade.UnitId then
        if bDebugMessages == true then LOG(sFunctionRef..': Just finished upgrading '..(oUnitDoingUpgrade.UnitId or 'nil')..AiBotUnitInfo.GetUnitLifetimeCount(oUnitDoingUpgrade)..'; is table of units assisting this empty='..tostring(AiBotUtilities.IsTableEmpty(oUnitDoingUpgrade[AiBotUnitInfo.reftoUnitsAssistingThis]))) end
        if AiBotUtilities.IsTableEmpty(oUnitDoingUpgrade[AiBotUnitInfo.reftoUnitsAssistingThis]) == false then
            local tUnitsToClear = {}
            for iUnit, oUnit in oUnitDoingUpgrade[AiBotUnitInfo.reftoUnitsAssistingThis] do
                if AiBotUnitInfo.IsUnitValid(oUnit) and EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer, oUnit.UnitId) and oUnit[AiBotEngineer.refiAssignedAction] == AiBotEngineer.refActionAssistUpgrade then
                    table.insert(tUnitsToClear, oUnit)
                end
            end
            if AiBotUtilities.IsTableEmpty(tUnitsToClear) == false then
                if bDebugMessages == true then LOG(sFunctionRef..': Just finished upgrading '..oUnitDoingUpgrade.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitDoingUpgrade)..'; will clear assisting engineers, table size='..table.getn(tUnitsToClear)) end
                for iUnit, oUnit in tUnitsToClear do
                    AiBotOrders.IssueTrackedClearCommands(oUnit)
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function InitialTeamInitialisationForReference() end --To help find the below more easily
function CreateNewTeam(aiBrain)
    --See also TeamInitialisation which sets up team variables for zones
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'CreateNewTeam'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)


    iTotalTeamCount = iTotalTeamCount + 1
    tTeamData[iTotalTeamCount] = {}
    tTeamData[iTotalTeamCount][subreftoFriendlyActiveAiBotBrains] = {}
    tTeamData[iTotalTeamCount][subreftoFriendlyHumanAndAIBrains] = {}
    tTeamData[iTotalTeamCount][subrefbTeamHasOmniVision] = false
    tTeamData[iTotalTeamCount][subrefbEnemyHasOmni] = false
    tTeamData[iTotalTeamCount][subreftoEnemyBrains] = {}
    tTeamData[iTotalTeamCount][subrefiActiveAiBotBrainCount] = 0
    tTeamData[iTotalTeamCount][subreftTeamUpgradingOther] = {}
    tTeamData[iTotalTeamCount][subreftTeamUpgradingACUs] = {}
    tTeamData[iTotalTeamCount][subreftTeamUpgradingMexes] = {}
    tTeamData[iTotalTeamCount][subreftTeamUpgradingHQs] = {}
    tTeamData[iTotalTeamCount][subrefiHighestEnemyGroundTech] = 0
    tTeamData[iTotalTeamCount][subrefiHighestEnemyAirTech] = 0
    tTeamData[iTotalTeamCount][subrefiHighestEnemyNavyTech] = 0
    tTeamData[iTotalTeamCount][subrefbTeamIsStallingEnergy] = false
    tTeamData[iTotalTeamCount][subrefbTeamIsStallingMass] = false
    tTeamData[iTotalTeamCount][subreftiPrevTeamNetMass] = {}
    tTeamData[iTotalTeamCount][subrefiGrossEnergyWhenStalled] = 0
    tTeamData[iTotalTeamCount][refiTimeOfLastEnergyStall] = 0
    tTeamData[iTotalTeamCount][refiTimeOfLastEngiSelfDestruct] = 0
    tTeamData[iTotalTeamCount][refbNeedResourcesForMissile] = false
    tTeamData[iTotalTeamCount][subrefiLandZonesWantingSupportByPlateau] = {}
    tTeamData[iTotalTeamCount][subrefiTotalFactoryCountByType] = {[AiBotFactory.refiFactoryTypeLand] = 0, [AiBotFactory.refiFactoryTypeAir] = 0, [AiBotFactory.refiFactoryTypeNaval] = 0, [AiBotFactory.refiFactoryTypeOther] = 0}
    tTeamData[iTotalTeamCount][subrefiAlliedDFThreat] = 0
    tTeamData[iTotalTeamCount][subrefiAlliedIndirectThreat] = 0
    tTeamData[iTotalTeamCount][subrefiAlliedGroundAAThreat] = 0
    tTeamData[iTotalTeamCount][subrefiAlliedMAAThreat] = 0
    tTeamData[iTotalTeamCount][refiLastTimeNoShieldTargetsByIsland] = {}
    tTeamData[iTotalTeamCount][refiLastTimeNoShieldBoatTargetsByPond] = {}
    tTeamData[iTotalTeamCount][refiLastTimeNoStealthTargetsByPlateau] = {}
    tTeamData[iTotalTeamCount][refiLastTimeNoStealthBoatTargetsByPond] = {}
    tTeamData[iTotalTeamCount][refiLastTimeNoMAATargetsByIsland] = {}
    tTeamData[iTotalTeamCount][refiEnemyHighestMobileLandHealth] = 300
    tTeamData[iTotalTeamCount][reftEnemyFirebaseByPlateauAndLZ] = {}
    tTeamData[iTotalTeamCount][reftEnemyTML] = {}
    tTeamData[iTotalTeamCount][reftEnemyLandExperimentals] = {}
    tTeamData[iTotalTeamCount][reftEnemyArtiAndExpStructure] = {}
    tTeamData[iTotalTeamCount][reftEnemyNukeLaunchers] = {}
    tTeamData[iTotalTeamCount][reftEnemySMD] = {}
    tTeamData[iTotalTeamCount][reftEnemyMobileSatellites] = {}
    tTeamData[iTotalTeamCount][reftEnemyAirExperimentals] = {}
    tTeamData[iTotalTeamCount][subreftTeamEngineersBuildingExperimentals] = {}
    tTeamData[iTotalTeamCount][refiLastFailedIslandDropTime] = {}
    tTeamData[iTotalTeamCount][refiLastFailedIslandAndZoneDropTime] = {}
    tTeamData[iTotalTeamCount][subrefbUseFrigatesAsScoutsByPond] = {}
    AiBotEngineer.tiLastBuildingSizeFromActionForTeam[iTotalTeamCount] = {}
    tTeamData[iTotalTeamCount][refiHighestBrainResourceMultiplier] = 0.1
    tTeamData[iTotalTeamCount][refiHighestBrainBuildMultiplier] = 0.1
    tTeamData[iTotalTeamCount][refiConstructedExperimentalCount] = 0
    tTeamData[iTotalTeamCount][refiFriendlyGameEnderCount] = 0
    tTeamData[iTotalTeamCount][refiMexCountByTech] = {[1]=0,[2]=0,[3]=0,[4]=0}
    tTeamData[iTotalTeamCount][refiEnemyT3ArtiCount] = 0
    tTeamData[iTotalTeamCount][refiEnemyNovaxCount] = 0
    tTeamData[iTotalTeamCount][reftoCampaignNeutralUnitsNotRecorded] = {}
    tTeamData[iTotalTeamCount][iEnemyT3MAAActiveCount] = 0
    tTeamData[iTotalTeamCount][toActiveSnipeTargets] = {}
    tTeamData[iTotalTeamCount][reftAiBotACUs] = {}
    tTeamData[iTotalTeamCount][tPotentiallyActiveGETemplates] = {}
    tTeamData[iTotalTeamCount][subrefiLongestOverdueScoutingTarget] = 0
    tTeamData[iTotalTeamCount][refiPausedUnitCount] = 0
    tTeamData[iTotalTeamCount][subreftoPausedUnitsByPriority] = {}
    tTeamData[iTotalTeamCount][refiLastMassStallCategoryAndEngineerTables] = {}
    tTeamData[iTotalTeamCount][refiLastEnergyStallCategoryAndEngineerTables] = {}
    tTeamData[iTotalTeamCount][refiGunshipLosses] = 0
    tTeamData[iTotalTeamCount][refiBomberLosses] = 0
    tTeamData[iTotalTeamCount][refiGunshipKills] = 0
    tTeamData[iTotalTeamCount][refiT1ToT3BomberKills] = 0
    tTeamData[iTotalTeamCount][refiAirAALossesToAir] = 0
    tTeamData[iTotalTeamCount][refiAirAAKills] = 0


    local bHaveCampaignAiBotAI = false
    if aiBrain.AiBotAI and aiBrain.CampaignAI then bHaveCampaignAiBotAI = true end
    local bHaveAiBotBrainInTeam = false

    local tbBrainsWithLandSubteam = {}
    local bAlreadyRecordedBrain

    for iCurBrain, oBrain in ArmyBrains do
        if bDebugMessages == true then LOG(sFunctionRef..': Doing setup for team '..iTotalTeamCount..'; Considering brain '..oBrain.Nickname..'; oBrain.AiBotTeam='..(oBrain.AiBotTeam or 'nil')..'; ScenarioInfo.Options.CommonArmy='..reprs(ScenarioInfo.Options.CommonArmy)..'; ScenarioInfo.Options.CommonArmy=true='..tostring(ScenarioInfo.Options.CommonArmy == true)..'; is table of AiBot for this brain empty='..tostring(AiBotUtilities.IsTableEmpty(tTeamData[iTotalTeamCount][subreftoFriendlyActiveAiBotBrains]))) end
        --First make sure we have recorded all brains (redundancy for AI like dillidalli) - the function below will check if we have already recorded the brain
        ForkThread(AiBotEvents.OnCreateBrain, oBrain, nil, nil)
        --[[if not(AiBotMap.PlayerStartPoints[oBrain:GetArmyIndex()]) then --redundancy
            local iStartPositionX, iStartPositionZ = oBrain:GetArmyStartPos()
            AiBotMap.PlayerStartPoints[oBrain:GetArmyIndex()] = {iStartPositionX, GetSurfaceHeight(iStartPositionX, iStartPositionZ), iStartPositionZ}
            AiBotOverseer.tAllAIBrainsByArmyIndex[oBrain:GetArmyIndex()] = oBrain
        end--]]

        --if not(oBrain.AiBotTeam) then
        bAlreadyRecordedBrain = false
        if oBrain == aiBrain or ((not(ScenarioInfo.Options.CommonArmy == true) and not(ScenarioInfo.Options.CommonArmy == 'true')) or (not(aiBrain.AiBotAI) and AiBotUtilities.IsTableEmpty(tTeamData[iTotalTeamCount][subreftoFriendlyActiveAiBotBrains]))) and IsAlly(oBrain:GetArmyIndex(), aiBrain:GetArmyIndex()) and not(AiBotConditions.IsCivilianBrain(oBrain)) then
            --Have we already recorded this as an ally?
            if AiBotUtilities.IsTableEmpty(tTeamData[iTotalTeamCount][subreftoFriendlyHumanAndAIBrains]) == false then
                for iRecorded, oRecorded in tTeamData[iTotalTeamCount][subreftoFriendlyHumanAndAIBrains] do
                    if oRecorded == oBrain then bAlreadyRecordedBrain = true break end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Considering oBrain='..oBrain.Nickname..'; bAlreadyRecordedBrain='..tostring(bAlreadyRecordedBrain)) end
            if not(bAlreadyRecordedBrain) then

                --Check we have the same enemies if this is a campaign AI
                if oBrain.AiBotAI and oBrain.CampaignAI then bHaveCampaignAiBotAI = true end
                local bHaveSameEnemies = true
                if bHaveCampaignAiBotAI and not(oBrain == aiBrain) then
                    --Check if we have the same enemies
                    local iIndexOrigBrain = aiBrain:GetArmyIndex()
                    local iIndexoBrain = oBrain:GetArmyIndex()
                    for iAltBrain, oAltBrain in ArmyBrains do
                        if not(oAltBrain == oBrain) and not(oAltBrain == aiBrain) then
                            if not(IsAlly(iIndexOrigBrain, oAltBrain:GetArmyIndex()) == IsAlly(iIndexoBrain, oAltBrain:GetArmyIndex())) then
                                bHaveSameEnemies = false
                                break
                            end
                            if not(IsEnemy(iIndexOrigBrain, oAltBrain:GetArmyIndex()) == IsEnemy(iIndexoBrain, oAltBrain:GetArmyIndex())) then
                                bHaveSameEnemies = false
                                break
                            end
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Considering aiBrain '..aiBrain.Nickname..'; oBrain='..oBrain.Nickname..'; iTotalTeamCount='..iTotalTeamCount..'; bHaveSameEnemies='..tostring(bHaveSameEnemies)) end
                --Special excemptions for certain campaign maps where the AI will change teams part-way through
                if bHaveSameEnemies and AiBotMap.bIsCampaignMap and not(oBrain == aiBrain) then
                    --FA Mission 2 - want QAI and Order to be on different teams
                    if (oBrain.Nickname == 'QAI' or oBrain.Nickname == 'Order') and (aiBrain.Nickname == 'QAI' or aiBrain.Nickname == 'Order') and ScenarioInfo.QAI and ScenarioInfo.Order then
                        bHaveSameEnemies = false
                    end
                end
                if bHaveSameEnemies then
                    if not(oBrain.AiBotTeam) or oBrain.AiBotTeam == iTotalTeamCount then --e.g. campaign might change team part-way through, dont want to change team of existing players or breaks their logic
                        oBrain.AiBotTeam = iTotalTeamCount
                        table.insert(tTeamData[iTotalTeamCount][subreftoFriendlyHumanAndAIBrains], oBrain)
                        if bDebugMessages == true then LOG(sFunctionRef..': Will add brain to table of friendly active AiBot brains if it is an AiBotAI brain, oBrain='..oBrain.Nickname..'; oBrain.AiBotAI='..tostring(oBrain.AiBotAI)..'; .CheatEnabled='..tostring(oBrain.CheatEnabled or false)..'; oBrain.PCxModifier='..tostring(oBrain.PCxModifier or false)..'; refiBrainResourceMultiplier='..(oBrain[AiBotEconomy.refiBrainResourceMultiplier] or 'nil')) end
                        if oBrain.AiBotAI then
                            table.insert(tTeamData[iTotalTeamCount][subreftoFriendlyActiveAiBotBrains], oBrain)
                            tTeamData[iTotalTeamCount][subrefiActiveAiBotBrainCount] = tTeamData[iTotalTeamCount][subrefiActiveAiBotBrainCount] + 1
                        end
                        if oBrain.CheatEnabled then
                            if oBrain.PCxModifier then
                                tTeamData[iTotalTeamCount][refiHighestBrainResourceMultiplier] = math.max(tTeamData[iTotalTeamCount][refiHighestBrainResourceMultiplier], (oBrain[AiBotEconomy.refiBrainResourceMultiplier] or 1))
                                tTeamData[iTotalTeamCount][refiHighestBrainBuildMultiplier] = math.max(tTeamData[iTotalTeamCount][refiHighestBrainBuildMultiplier], (oBrain[AiBotEconomy.refiBrainBuildRateMultiplier] or 1))
                            else
                                tTeamData[iTotalTeamCount][refiHighestBrainResourceMultiplier] = math.max(tTeamData[iTotalTeamCount][refiHighestBrainResourceMultiplier], tonumber(ScenarioInfo.Options.CheatMult or 1.5))
                                tTeamData[iTotalTeamCount][refiHighestBrainBuildMultiplier] = math.max(tTeamData[iTotalTeamCount][refiHighestBrainBuildMultiplier], tonumber(ScenarioInfo.Options.BuildMult or 1.5))
                                oBrain[AiBotEconomy.refiBrainResourceMultiplier] = (oBrain.CheatValue or tonumber(ScenarioInfo.Options.CheatMult or 1.5))
                                oBrain[AiBotEconomy.refiBrainBuildRateMultiplier] = (oBrain.CheatValue or tonumber(ScenarioInfo.Options.BuildMult or 1.5))
                            end
                        else
                            oBrain[AiBotEconomy.refiBrainResourceMultiplier] = 1
                            oBrain[AiBotEconomy.refiBrainBuildRateMultiplier] = 1
                            tTeamData[iTotalTeamCount][refiHighestBrainResourceMultiplier] = math.max(tTeamData[iTotalTeamCount][refiHighestBrainResourceMultiplier], 1)
                            tTeamData[iTotalTeamCount][refiHighestBrainBuildMultiplier] = math.max(tTeamData[iTotalTeamCount][refiHighestBrainBuildMultiplier], 1)
                        end
                        bHaveAiBotBrainInTeam = true
                        --Check if we have omni vision for the team
                        if AiBotConditions.DoesBrainHaveOmniVision(oBrain) then
                            tTeamData[iTotalTeamCount][subrefbTeamHasOmniVision] = true
                        end
                        --Record brain details in log for ease of reference
                        local sAIxref = ''
                        if bDebugMessages == true then LOG(sFunctionRef..': Brain '..oBrain.Nickname..': .CheatEnabled='..tostring(oBrain.CheatEnabled or false)..'; ScenarioInfo.Options.CheatMult='..(ScenarioInfo.Options.CheatMult or 'nil')..'; ScenarioInfo.Options.BuildMult='..(ScenarioInfo.Options.BuildMult or 'nil')..'; oBrain[AiBotEconomy.refiBrainResourceMultiplier]='..(oBrain[AiBotEconomy.refiBrainResourceMultiplier] or 'nil')) end
                        if oBrain.CheatEnabled then
                            sAIxref = ' AIx Res '..tonumber(ScenarioInfo.Options.CheatMult or -1)..'; BP '..tonumber(ScenarioInfo.Options.BuildMult or -1)
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': ScenarioInfo.Options.Ratings='..repru(ScenarioInfo.Options.Ratings)) end
                        --Record the rating
                        if AiBotUtilities.IsTableEmpty(ScenarioInfo.Options.Ratings) == false then
                            for sBrainWithRating, iRating in ScenarioInfo.Options.Ratings do
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering if this is '..sBrainWithRating..'; iRating of this='..iRating) end
                                if sBrainWithRating == oBrain.Nickname or sBrainWithRating == oBrain.Name then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Have a match so recording the rating') end
                                    oBrain.Rating = iRating
                                    break
                                end
                            end
                        end
                        LOG(sFunctionRef..': Recorded non-civilian brain '..oBrain.Nickname..' with chat personality '..(oBrain[AiBotChat.refiAssignedPersonality] or 'nil')..' and index '..oBrain:GetArmyIndex()..' for team '..iTotalTeamCount..sAIxref..'; Land team='..(oBrain.AiBotLandSubteam or 'nil')..'; Air subteam='..(oBrain.AiBotAirSubteam or 'nil')..'; AiBotEasy='..tostring(oBrain.AiBotEasy or false)..'; AiBotAI='..tostring(oBrain.AiBotAI or false)..'; Unit prioritisation='..(ScenarioInfo.Options.AiBotPrioritiseBPs or 'nil')..'; rating (FAF only)='..(ScenarioInfo.Options.Ratings[aiBrain.Nickname] or 'nil')..'; oBrain.Rating='..(oBrain.Rating or 'nil')) --Dont know the land and air subteams yet
                    end
                end
            end
        elseif IsEnemy(oBrain:GetArmyIndex(), aiBrain:GetArmyIndex()) and not(AiBotConditions.IsCivilianBrain(oBrain)) then
            if AiBotUtilities.IsTableEmpty(tTeamData[iTotalTeamCount][subreftoEnemyBrains]) == false then
                for iRecorded, oRecorded in tTeamData[iTotalTeamCount][subreftoEnemyBrains] do
                    if oRecorded == oBrain then
                        bAlreadyRecordedBrain = true break
                    end
                end
            end
            if not(bAlreadyRecordedBrain) then
                if bDebugMessages == true then LOG(sFunctionRef..': Recording enemy brain '..oBrain.Nickname..' for team '..iTotalTeamCount..' at time='..GetGameTimeSeconds()) end
                table.insert(tTeamData[iTotalTeamCount][subreftoEnemyBrains], oBrain)
                tBrainIndexesRecordedAsEnemies[oBrain:GetArmyIndex()] = true
                --Check if anyone on enemy team has omni
                if oBrain.CheatEnabled and ScenarioInfo.Options.OmniCheat == 'on' and not(aiBrain.PCxModifier) then
                    tTeamData[iTotalTeamCount][subrefbEnemyHasOmni] = true
                end
            end
        end
        --end
    end
    if not(bHaveAiBotBrainInTeam) and aiBrain.AiBotAI then bHaveAiBotBrainInTeam = true end
    if bDebugMessages == true then LOG(sFunctionRef..': Setup a team with team ref/iTotalTeamCount='..iTotalTeamCount..'; do we have AiBot brain in this team='..tostring(bHaveAiBotBrainInTeam)) end
    if bHaveAiBotBrainInTeam then
        UpdateTeamHighestAndLowestFactories(iTotalTeamCount)

        --Group allies into AirSubteams based on nearest enemy; then split the air subteam between land subteams if they are in different plateaus
        if bDebugMessages == true then LOG(sFunctionRef..': will group allies into air subteams, is table of active AiBot brains empty for this team='..tostring(AiBotUtilities.IsTableEmpty(tTeamData[iTotalTeamCount][subreftoFriendlyActiveAiBotBrains]))) end
        for iBrain, oBrain in tTeamData[iTotalTeamCount][subreftoFriendlyActiveAiBotBrains] do
            if bDebugMessages == true then LOG(sFunctionRef..': Considering brains in team '..iTotalTeamCount..', oBrain='..(oBrain.Nickname or 'nil')..'; .AiBotAirSubteam='..(oBrain.AiBotAirSubteam or 'nil')..'; if was nil then will assign a new one') end
            if not(oBrain.AiBotAirSubteam) then
                CreateNewAirSubteam(oBrain)
                local tiIslandBrainsInSubteam = {}
                local tiPlateauByIslandRefs = {}
                local iStartPlateau, iStartIsland
                for iBrain, oBrain in tAirSubteamData[oBrain.AiBotAirSubteam][subreftoFriendlyAiBotBrains] do
                    iStartPlateau = NavUtils.GetLabel(AiBotMap.refPathingTypeHover, AiBotMap.GetPlayerStartPosition(oBrain))
                    iStartIsland = (NavUtils.GetLabel(AiBotMap.refPathingTypeLand, AiBotMap.GetPlayerStartPosition(oBrain)) or -1)
                    if (iStartIsland or 0) > 0 or iStartPlateau then
                        if not(tiIslandBrainsInSubteam[iStartIsland]) then tiIslandBrainsInSubteam[iStartIsland] = {} end
                        table.insert(tiIslandBrainsInSubteam[iStartIsland], oBrain)
                        tbBrainsWithLandSubteam[oBrain:GetArmyIndex()] = true
                        tiPlateauByIslandRefs[iStartIsland] = iStartPlateau
                    else
                        AiBotUtilities.ErrorHandler('Dont have a valid start plateau or island for oBrain='..(oBrain.Nickname or 'Brain index '..oBrain:GetArmyIndex()))
                    end
                end
                if AiBotUtilities.IsTableEmpty(tiIslandBrainsInSubteam) == false then
                    for iStartIsland, tBrains in tiIslandBrainsInSubteam do
                        CreateNewLandSubteam(tiPlateauByIslandRefs[iStartIsland], iStartIsland, tBrains)
                    end
                end
            end
        end
        ForkThread(TeamInitialisation, iTotalTeamCount)
        AiBotAir.UpdateTeamAirThreats(iTotalTeamCount)
    end
    ForkThread(TeamDeathChecker)
    if bHaveCampaignAiBotAI then
        local bTeamHasPlayerAiBotAI = false
        for iBrain, oBrain in tTeamData[iTotalTeamCount][subreftoFriendlyActiveAiBotBrains] do
            if not(oBrain.CampaignAI) then
                bTeamHasPlayerAiBotAI = true
                break
            end
        end
        if not(bTeamHasPlayerAiBotAI) then
            tTeamData[iTotalTeamCount][rebTeamOnlyHasCampaignAI] = true
        end
        ForkThread(CheckIfCampaignTeamHasBuildings, iTotalTeamCount)
    end

    --Check every brain is on a land subteam (even if have a water start)
    ForkThread(CheckForBrainsWithoutLandSubteam, iTotalTeamCount, tbBrainsWithLandSubteam)

    --Record if we have a mix of human and AI on team with shared armies
    if not(AiBotUnitInfo.bDontConsiderCombinedArmy) or (not(tonumber(ScenarioInfo.Options.AiBotCombinedArmy or 2) == 2) and not(ScenarioInfo.Options.AiBotCombinedArmy == 5)) then
        if AiBotUtilities.IsTableEmpty(tTeamData[iTotalTeamCount][subreftoFriendlyActiveAiBotBrains]) == false then
            local iHumanCount = 0
            local iPureAICount = 0
            for iBrain, oBrain in tTeamData[iTotalTeamCount][subreftoFriendlyActiveAiBotBrains] do
                if oBrain.BrainType == 'Human' then
                    iHumanCount = iHumanCount + 1
                else
                    iPureAICount = iPureAICount + 1
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Shared army check, iHumanCount='..iHumanCount..'; iPureAICount='..iPureAICount) end
            if iHumanCount > 0 and iPureAICount > 0 then
                tTeamData[iTotalTeamCount][refbContainsPureAiBotAndSharedAiBot] = true
            end
        end
    end

    --List out every AiBot brain on this team by subteam if debug enabled
    if bDebugMessages == true and bHaveAiBotBrainInTeam then
        for iBrain, oBrain in tTeamData[iTotalTeamCount][subreftoFriendlyActiveAiBotBrains] do
            LOG('AiBot brain '..oBrain.Nickname..' land subteam='..(oBrain.AiBotLandSubteam or 'nil')..'; Air subteam='..(oBrain.AiBotAirSubteam or 'nil'))
        end
    end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function CheckForBrainsWithoutLandSubteam(iTeam, tbBrainsWithLandSubteam, bDontWait)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'CheckForBrainsWithoutLandSubteam'

    while not(AiBotMap.bWaterZoneInitialCreation) do
        WaitTicks(1)
    end
    if not(bDontWait) then
        WaitTicks(1)
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if bDebugMessages == true then LOG(sFunctionRef..': About to check if any brains in team '..iTeam..'; are missing a land subteam, tbBrainsWithLandSubteam='..repru(tbBrainsWithLandSubteam)) end
    if AiBotUtilities.IsTableEmpty(tTeamData[iTeam][subreftoFriendlyActiveAiBotBrains]) == false then
        for iBrain, oBrain in tTeamData[iTeam][subreftoFriendlyActiveAiBotBrains] do
            if not(tbBrainsWithLandSubteam[oBrain:GetArmyIndex()]) and not(oBrain.AiBotLandSubteam) and oBrain.AiBotAI then
                if bDebugMessages == true then LOG(sFunctionRef..': No land subteam recorded yet for brain '..oBrain.Nickname..'; will try and search for one, Index='..oBrain:GetArmyIndex()..'; Start point='..repru(AiBotMap.PlayerStartPoints[oBrain:GetArmyIndex()])..'; Time='..GetGameTimeSeconds()) end
                --Campaign map - find hte closest factory to the player start, if we have one
                local tStartPoint = AiBotMap.GetPlayerStartPosition(oBrain)
                local iStartIsland
                local tFriendlyFactories = oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryLandHQ + AiBotUnitInfo.refCategoryAirHQ, false, true)
                local iStartPlateau
                if AiBotUtilities.IsTableEmpty(tFriendlyFactories) == false then
                    local iCurDist
                    local iClosestDist = 100000
                    for iFactory, oFactory in tFriendlyFactories do
                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tStartPoint, oFactory:GetPosition())
                        if iCurDist < iClosestDist then
                            iClosestDist = iCurDist
                            iStartIsland = NavUtils.GetLabel(AiBotMap.refPathingTypeLand, oFactory:GetPosition())
                            iStartPlateau = NavUtils.GetLabel(AiBotMap.refPathingTypeHover, oFactory:GetPosition())
                        end
                    end
                end
                if not(iStartIsland) or not(iStartPlateau) then
                    --Non-campaign map, or campaign map where no factories - Find the nearest land area to the brain's start position
                    local tStartLZOrWZData = AiBotMap.GetLandOrWaterZoneData(tStartPoint)
                    if bDebugMessages == true then LOG(sFunctionRef..': tStartPoint='..repru(tStartPoint)..'; Is LZOrWZData empty='..tostring(AiBotUtilities.IsTableEmpty(tStartLZOrWZData))..'; Water zone setup started='..tostring(AiBotMap.bWaterZoneInitialCreation)) end
                    AiBotAir.RecordOtherLandAndWaterZonesByDistance(tStartLZOrWZData)
                    if AiBotUtilities.IsTableEmpty(tStartLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) == false then
                        for iEntry, tSubtable in tStartLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
                            if not(tSubtable[AiBotMap.subrefbIsWaterZone]) then
                                local tCurLZData = AiBotMap.tAllPlateaus[tSubtable[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPlateauLandZones][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]]
                                iStartIsland = NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tCurLZData[AiBotMap.subrefMidpoint])
                                iStartPlateau =  NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tCurLZData[AiBotMap.subrefMidpoint])
                                if iStartIsland and iStartPlateau then break end
                            end
                        end
                    end
                end
                if not(iStartIsland) or not(iStartPlateau) then
                    AiBotUtilities.ErrorHandler('Unable to find a starting island for brain nickname '..(oBrain.Nickname or 'nil')..' so wont have a land subteam created for it with a valid island')
                    --Basic values so wont completely error out:
                    iStartPlateau = 1
                    iStartIsland = 1
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Will create a backup land subteam for oBrain='..oBrain.Nickname..'; iStartPlateau='..(iStartPlateau or 'nil')..'; iStartIsland='..(iStartIsland or 'nil')) end
                CreateNewLandSubteam(iStartPlateau, iStartIsland, { oBrain})
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ActivateAdminBrainAfterTeamSetup(aiBrain)
    -- CreateNewTeam records every human brain, but only brains that were AiBot
    -- at that moment receive active-brain membership and subteams.  An admin
    -- can opt in later, so fill in exactly those missing per-brain structures.
    local iTeam = aiBrain and aiBrain.AiBotTeam
    if not(iTeam) or not(tTeamData[iTeam]) then
        return false
    end

    local bAlreadyActive = false
    for _, oBrain in tTeamData[iTeam][subreftoFriendlyActiveAiBotBrains] do
        if oBrain == aiBrain then
            bAlreadyActive = true
            break
        end
    end

    if not(bAlreadyActive) then
        table.insert(tTeamData[iTeam][subreftoFriendlyActiveAiBotBrains], aiBrain)
        tTeamData[iTeam][subrefiActiveAiBotBrainCount] =
            (tTeamData[iTeam][subrefiActiveAiBotBrainCount] or 0) + 1
    end

    if not(aiBrain.AiBotAirSubteam) then
        CreateNewAirSubteam(aiBrain)
    end

    if not(aiBrain.AiBotLandSubteam) then
        CheckForBrainsWithoutLandSubteam(iTeam, {}, true)
    end

    -- The general recovery search can fail while a team is joining the already
    -- built map.  A normal skirmish spawn has direct nav labels, which are all
    -- CreateNewLandSubteam needs.
    if not(aiBrain.AiBotLandSubteam) then
        local tStartPoint = AiBotMap.GetPlayerStartPosition(aiBrain)
        local iStartPlateau = NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tStartPoint)
        local iStartIsland = NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tStartPoint)
        if (iStartPlateau or 0) > 0 and (iStartIsland or 0) > 0 then
            CreateNewLandSubteam(iStartPlateau, iStartIsland, { aiBrain })
        end
    end

    -- Safe for an already running team: TeamInitialisation has its own guard.
    ForkThread(TeamInitialisation, iTeam)
    AiBotAir.UpdateTeamAirThreats(iTeam)

    LOG('Late AiBot admin brain activated for '..aiBrain.Nickname
        ..'; team='..iTeam
        ..'; land subteam='..(aiBrain.AiBotLandSubteam or 'nil')
        ..'; air subteam='..(aiBrain.AiBotAirSubteam or 'nil'))
    return aiBrain.AiBotLandSubteam != nil and aiBrain.AiBotAirSubteam != nil
end

function RecordAllPlayers()

    --Call via ForkThread from initialisation, so 1 tick after the first brain will have been created
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RecordAllPlayers'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if not(bRecordedAllPlayers) then
        bRecordedAllPlayers = true
        for iBrain, oBrain in ArmyBrains do
            if bDebugMessages == true then LOG(sFunctionRef..': Considering iBrain '..iBrain..'; oBrain.Nickname='..(oBrain.Nickname or 'nil')..'; Is civilian='..tostring(AiBotConditions.IsCivilianBrain(oBrain))..'; Is AiBotAI='..tostring(oBrain.AiBotAI or false)..'; Time='..GetGameTimeSeconds()..'; AiBotTeam value='..(oBrain.AiBotTeam or 'nil')) end
            if not(AiBotConditions.IsCivilianBrain(oBrain)) or AiBotMap.bIsCampaignMap then --Compatibility with making civilian brains use AiBot logic - means they need to be part of a team
                iPlayersAtGameStart = iPlayersAtGameStart + 1
                if not(oBrain.AiBotTeam) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Will create a new team for brain '..oBrain.Nickname) end
                    CreateNewTeam(oBrain)
                end
            end
        end
    end


    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

