function UpdateUnitPreviousZones(oUnit, iPlateau, iLandZone)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'UpdateUnitPreviousZones'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    oUnit[AiBotUnitInfo.refbUnitStuckAlternating] = false
    if not(oUnit[AiBotUnitInfo.reftRecentPlateauAndZoneByTeam]) then
        oUnit[AiBotUnitInfo.reftRecentPlateauAndZoneByTeam] = {}
    end
    table.insert(oUnit[AiBotUnitInfo.reftRecentPlateauAndZoneByTeam], 1, {iPlateau, iLandZone})
    if oUnit[AiBotUnitInfo.reftRecentPlateauAndZoneByTeam][8] then
        if oUnit[AiBotUnitInfo.reftRecentPlateauAndZoneByTeam][9] then
            table.remove(oUnit[AiBotUnitInfo.reftRecentPlateauAndZoneByTeam], 9)
        end

        --Check if we have been alternating between the same two zones
        local tiPlateauOrZeroAndZones = {}
        local iUniqueCount = 0
        for iEntry, tPlateauOrZeroAndZone in  oUnit[AiBotUnitInfo.reftRecentPlateauAndZoneByTeam] do
            if not(tiPlateauOrZeroAndZones[tPlateauOrZeroAndZone[1]]) then
                tiPlateauOrZeroAndZones[tPlateauOrZeroAndZone[1]] = {}
            end
            if not(tiPlateauOrZeroAndZones[tPlateauOrZeroAndZone[1]][tPlateauOrZeroAndZone[2]]) then
                tiPlateauOrZeroAndZones[tPlateauOrZeroAndZone[1]][tPlateauOrZeroAndZone[2]] = 0
                iUniqueCount = iUniqueCount + 1
            else
                tiPlateauOrZeroAndZones[tPlateauOrZeroAndZone[1]][tPlateauOrZeroAndZone[2]] = tiPlateauOrZeroAndZones[tPlateauOrZeroAndZone[1]][tPlateauOrZeroAndZone[2]] + 1
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Considering unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iUniqueCount='..iUniqueCount..'; tiPlateauOrZeroAndZones='..repru(tiPlateauOrZeroAndZones)..'; oUnit[AiBotUnitInfo.reftRecentPlateauAndZoneByTeam]='..repru(oUnit[AiBotUnitInfo.reftRecentPlateauAndZoneByTeam])..'; Time since unit last retreated='..GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiTimeLastTriedRetreating] or -100)..'; Time='..GetGameTimeSeconds()) end
        if iUniqueCount <= 3 then --if only 3 dif zones then chances are we have been alternating
            if GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiTimeLastTriedRetreating] or -100) >= 30 then
                if bDebugMessages == true then LOG(sFunctionRef..': Unit is stuck alternating between zones so will flag accordingly') end
                oUnit[AiBotUnitInfo.refbUnitStuckAlternating] = true
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function RecordUnitInLandZone()  end --DONE TO HELP LOCATE
function AddUnitToLandZoneForBrain(aiBrain, oUnit, iPlateau, iLandZone, bIsEnemyAirUnit)
    --If unit already has a land zone assigned then remove this
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'AddUnitToLandZoneForBrain'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    if EntityCategoryContains(categories.MOBILE * categories.AIR, oUnit.UnitId) and not(bIsEnemyAirUnit) and oUnit:GetFractionComplete() == 1 and not(EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer + categories.EXPERIMENTAL, oUnit.UnitId)) then
        AiBotUtilities.ErrorHandler('Havent flagged that a constructed air unit is an air unit, UnitId='..oUnit.UnitId)
    end


    local bAddToZone = true
    --The function in AiBotLand, UpdateUnitPositionsAndLandZone, should remove a unit from a zone if it is in the wrong one based on its position, so no need for below - commented out (pre v1) in case change my mind
    --Decided to re-add, as the second issue is duplicate entries, e.g. where an event triggers for a unit to be added to a land zone


    if oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam] and oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][aiBrain.AiBotTeam] then
        --Is the unit already assigned to this zone?
        if oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][aiBrain.AiBotTeam][1] == iPlateau and oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][aiBrain.AiBotLandTeam][2] == iLandZone then
            if bDebugMessages == true then LOG(sFunctionRef..': Unit is already assigned to this plateau and land zone so will abort adding it') end
            bAddToZone = false
            --[[else
                if bDebugMessages == true then LOG(sFunctionRef..': Unit already has a plateau and LZ assigned but is dif from the desired one so will remove from its current zone first') end
                RemoveUnitFromCurrentLandZone(aiBrain, oUnit)--]]
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..'; Considering adding unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to iPlateau '..(iPlateau or 'nil')..'; iLandZone='..(iLandZone or 'nil')..' for brain '..aiBrain.Nickname..'; team='..aiBrain.AiBotTeam..'; bAddToZone='..tostring(bAddToZone)..'; Is enemy='..tostring(IsEnemy(aiBrain:GetArmyIndex(), oUnit:GetAIBrain():GetArmyIndex()))..'; Is ally='..tostring(IsAlly(aiBrain:GetArmyIndex(), oUnit:GetAIBrain():GetArmyIndex()))) end
    if bAddToZone then
        local iPlateauRef = iPlateau
        local iLandZoneRef = iLandZone
        local tLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTeamData]
        if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to add unit to zone, iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; is LZTeamData nil='..tostring(tLZTeamData == nil)..'; is oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam] nil='..tostring(oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam] == nil)..'; Unit position='..repru(oUnit:GetPosition())) end
        if AiBotUtilities.IsTableEmpty(oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam]) then
            oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam] = {}
            if AiBotUtilities.IsTableEmpty(tLZTeamData) then
                iPlateauRef, iLandZoneRef = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
                tLZTeamData = AiBotMap.tAllPlateaus[iPlateauRef][AiBotMap.subrefPlateauLandZones][iLandZoneRef][AiBotMap.subrefLZTeamData]
                if bDebugMessages == true then LOG(sFunctionRef..': Got the closest plateau and zone to position, iPlateauRef='..(iPlateauRef or 'nil')..'; iLandZoneRef='..(iLandZoneRef or 'nil')..'; is tLZTeamData empty='..tostring(tLZTeamData == nil)) end
            end
        else
            --Backup - sometimes if an enemy unit goes over a cliff on larger maps there can be an inconsistency where the plateau is different to the land zone; in such cases the land zone logic should update the unit position, but also want to avoid an unhandled error here
            if AiBotUtilities.IsTableEmpty(tLZTeamData) then
                iPlateauRef = oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][aiBrain.AiBotTeam][1]
                iLandZoneRef = oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][aiBrain.AiBotTeam][2]
                tLZTeamData = AiBotMap.tAllPlateaus[iPlateauRef][AiBotMap.subrefPlateauLandZones][iLandZoneRef][AiBotMap.subrefLZTeamData]
            end
        end

        if tLZTeamData then
            oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][aiBrain.AiBotTeam] = {iPlateauRef, iLandZoneRef}
            local iUnitArmyIndex = oUnit:GetAIBrain():GetArmyIndex()
            local bIsEnemy = IsEnemy(aiBrain:GetArmyIndex(), iUnitArmyIndex)
            local bIsAlly = IsAlly(aiBrain:GetArmyIndex(), iUnitArmyIndex)
            if not(bIsEnemy) and not(bIsAlly) and AiBotMap.bIsCampaignMap and aiBrain.CampaignAI and tTeamData[aiBrain.AiBotTeam][subrefiActiveAiBotBrainCount] > 1 and AiBotUtilities.IsTableEmpty(tTeamData[aiBrain.AiBotTeam][subreftoFriendlyActiveAiBotBrains]) == false then
                --Consider switching brain if any other aibrain members of this team are an enemy to this unit
                for iBrain, oBrain in tTeamData[aiBrain.AiBotTeam][subreftoFriendlyActiveAiBotBrains] do
                    if not(oBrain == aiBrain) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Have unit that is neither an enemy nor an ally in campaign, check if other brains on the team have it as an enemy, IsEnemy='..tostring(IsEnemy(oBrain:GetArmyIndex(), iUnitArmyIndex))..'; IsAlly='..tostring(IsAlly(oBrain:GetArmyIndex(), iUnitArmyIndex))) end
                        if IsEnemy(oBrain:GetArmyIndex(), iUnitArmyIndex) then
                            bIsEnemy = true
                            aiBrain = oBrain
                            break
                        elseif IsAlly(oBrain:GetArmyIndex(), iUnitArmyIndex) then
                            bIsAlly = true
                            aiBrain = oBrain
                            break
                        end
                    end
                end
            end
            if bIsEnemy then
                if bDebugMessages == true then
                    LOG(sFunctionRef..': Is an enemy so will add to list of enemy air units or enemy units depending on if it is air, Is team data for this plateau and land zone empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateauRef][AiBotMap.subrefPlateauLandZones][iLandZoneRef][AiBotMap.subrefLZTeamData][aiBrain.AiBotTeam]))..'; aiBrain='..aiBrain.Nickname..'; team='..aiBrain.AiBotTeam..'; Unit position='..repru(oUnit:GetPosition())..'; bIsEnemyAirUnit='..tostring(bIsEnemyAirUnit or false)..'; AiBotMap.bWaterZoneInitialCreation='..tostring(AiBotMap.bWaterZoneInitialCreation or false))
                    if AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateauRef][AiBotMap.subrefPlateauLandZones][iLandZoneRef][AiBotMap.subrefLZTeamData][aiBrain.AiBotTeam]) then
                        AiBotUtilities.DrawLocation(oUnit:GetPosition(), 2)
                    end
                end
                if bIsEnemyAirUnit then
                    table.insert(AiBotMap.tAllPlateaus[iPlateauRef][AiBotMap.subrefPlateauLandZones][iLandZoneRef][AiBotMap.subrefLZTeamData][aiBrain.AiBotTeam][AiBotMap.reftLZEnemyAirUnits], oUnit)
                else
                    if bDebugMessages == true then LOG(sFunctionRef..': About to add enemy to table of enemy units, iPlateauRef='..(iPlateauRef or 'nil')..'; iLandZoneRef='..(iLandZoneRef or 'nil')..'; oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Is this a T2 arti unit='..tostring(EntityCategoryContains(AiBotUnitInfo.refCategoryFixedT2Arti, oUnit.UnitId))) end
                    table.insert(AiBotMap.tAllPlateaus[iPlateauRef][AiBotMap.subrefPlateauLandZones][iLandZoneRef][AiBotMap.subrefLZTeamData][aiBrain.AiBotTeam][AiBotMap.subrefTEnemyUnits], oUnit)
                    --T2 arti tracking - consider firebase
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryFixedT2Arti, oUnit.UnitId) then
                        AiBotLand.ConsiderIfHaveEnemyFirebase(aiBrain.AiBotTeam, oUnit)
                    end
                end
                --Update desc for mobile units owned by player (so easier to debug)
                if AiBotConfig.AiBotShowEnemyUnitNames and not(oUnit:GetAIBrain().AiBotAI) then
                    oUnit:SetCustomName((oUnit.UnitId or oUnit:GetBlueprint().BlueprintId)..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'P'..(iPlateauRef or 0)..'Z'..(iLandZoneRef or 0))
                end
            elseif bIsAlly then
                --Dont add allied air units, or units from a different (allied) team
                if oUnit:GetAIBrain().AiBotTeam == aiBrain.AiBotTeam and (not(EntityCategoryContains(AiBotUnitInfo.refCategoryAllAir - AiBotUnitInfo.refCategoryEngineer, oUnit.UnitId)) or oUnit:GetFractionComplete() < 1) then
                    local tLZData = AiBotMap.tAllPlateaus[iPlateauRef][AiBotMap.subrefPlateauLandZones][iLandZoneRef]
                    local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][aiBrain.AiBotTeam]
                    table.insert(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits], oUnit)
                    if oUnit[AiBotUnitInfo.refiCombatRange] > 0 and not(EntityCategoryContains(AiBotUnitInfo.refCategoryMAA, oUnit.UnitId)) then
                        if not(tLZTeamData[AiBotMap.subrefLZTAlliedCombatUnits]) then tLZTeamData[AiBotMap.subrefLZTAlliedCombatUnits] = {} end --redundancy for campaign scenarios with a delayed start where a unit might have moved to a zone that hasnt been setup yet
                        table.insert(tLZTeamData[AiBotMap.subrefLZTAlliedCombatUnits], oUnit)
                    end
                    if AiBotConfig.AiBotShowUnitNames then oUnit:SetCustomName(oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'New P'..iPlateauRef..'LZ'..iLandZoneRef) end
                    --Reset assigned value (if it has one) if the zone it last had orders from is no longer adjacent
                    if oUnit[AiBotLand.refiCurrentAssignmentValue] then
                        local iLastOrderZone = oUnit[AiBotLand.refiCurrentAssignmentPlateauAndLZ][2]
                        local bOrderZoneAdjacent = false
                        if iLastOrderZone == iLandZoneRef then
                            bOrderZoneAdjacent = true
                        elseif AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                            for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                if iAdjLZ == iLastOrderZone then
                                    bOrderZoneAdjacent = true
                                    break
                                end
                            end
                        end
                        if not(bOrderZoneAdjacent) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Units assigned zone isnt adjacent to its current zone, so will reset its assignment value, unit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)) end
                            oUnit[AiBotLand.refiCurrentAssignmentValue] = 0 --reset so unit should get new orders from the current zone or an adjacent zone
                        end
                    end
                    --Update table of previous entries
                    UpdateUnitPreviousZones(oUnit, iPlateau, iLandZone)
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryTMD, oUnit.UnitId) then
                        AiBotBuilding.AlliedTMDFirstRecorded(aiBrain.AiBotTeam, oUnit)
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Add unit as a friendly unit to Plateau-LZ='..iPlateauRef..'-'..iLandZoneRef..' and team='..aiBrain.AiBotTeam..'; Is table of friendly units empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateauRef][AiBotMap.subrefPlateauLandZones][iLandZoneRef][AiBotMap.subrefLZTeamData][aiBrain.AiBotTeam][AiBotMap.subreftoLZOrWZAlliedUnits]))) end
                elseif bDebugMessages == true then LOG(sFunctionRef..': have a complete allied air unit so wont record as a land unit')
                end
            end
        elseif iPlateauRef == 0 and iLandZoneRef then
            if bDebugMessages == true then LOG(sFunctionRef..': Will try adding to water zone instead') end
            if (GetGameTimeSeconds() - (oUnit['BackupZoneAssignmentTime'] or -1)) >= 1 then
                oUnit['BackupZoneAssignmentTime'] = GetGameTimeSeconds() --Preemptive to stop potential infinite loop if we call addunittolandzone from addunittowaterzone
                AddUnitToWaterZoneForBrain(aiBrain, oUnit, iLandZoneRef, bIsEnemyAirUnit)
            end
        else
            AiBotUtilities.ErrorHandler('Still dont have valid plateau and land zone combination for air unit')
            if bDebugMessages == true then LOG(sFunctionRef..': oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam]='..repru(oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam])..'; unit pos='..repru(oUnit:GetPosition())) end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)

end

--Use below if want to track where aiBrain (which should be an AiBot brain) has assigned a unit every second - e.g. useful for naval units if trying to figure out what zone an enemy unit is in at a particular time point
function TestCustomMonitor(oUnit, aiBrain)
    if not(oUnit['AiBotTestCustomMonitor']) then
        oUnit['AiBotTestCustomMonitor'] = true
        while AiBotUnitInfo.IsUnitValid(oUnit) do
            if AiBotUtilities.IsTableEmpty(oUnit[AiBotUnitInfo.reftLastKnownPositionByTeam][aiBrain.AiBotTeam]) == false then
                LOG('TestCustomOnitor: Can brain '..aiBrain.Nickname..' see unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'='..tostring(AiBotUnitInfo.CanSeeUnit(aiBrain, oUnit, false))..'; oUnit position='..repru(oUnit:GetPosition())..'; Dist to last known position='..AiBotUtilities.GetDistanceBetweenPositions(oUnit[AiBotUnitInfo.reftLastKnownPositionByTeam][aiBrain.AiBotTeam], oUnit:GetPosition())..'; team='..aiBrain.AiBotTeam..'; time='..GetGameTimeSeconds())
                local iCurPlateau, iCurZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
                local iAltPlateau, iAltZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit[AiBotUnitInfo.reftLastKnownPositionByTeam][aiBrain.AiBotTeam])
                LOG('Based on unit position P'..(iCurPlateau or 'nil')..'Z'..(iCurZone or 'nil')..'; based on last known position Z='..(iAltZone or 'nil')..'; assigned water zone='..(oUnit[AiBotUnitInfo.reftAssignedWaterZoneByTeam][aiBrain.AiBotTeam] or 'nil'))
                WaitSeconds(1)
            end
        end
    end
end

function AddUnitToWaterZoneForBrain(aiBrain, oUnit, iWaterZone, bIsEnemyAirUnit)
    --If unit already has a land zone assigned then remove this
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'AddUnitToWaterZoneForBrain'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    if not(AiBotMap.bWaterZoneInitialCreation) or not(AiBotMap.bWaterZoneFirstTeamInitialisation) then
        if GetGameTimeSeconds() >= 10 then
            AiBotUtilities.ErrorHandler('Trying to add unit to water zone but we havent setup initial water zone variables yet, will try waiting 1 second, bWaterZoneInitialCreation='..tostring(AiBotMap.bWaterZoneInitialCreation or false)..'; AiBotMap.bWaterZoneFirstTeamInitialisation='..tostring(AiBotMap.bWaterZoneFirstTeamInitialisation or false))
            WaitSeconds(1)
        else

            while not(AiBotMap.bWaterZoneInitialCreation) or not(AiBotMap.bWaterZoneFirstTeamInitialisation) do
                WaitTicks(1)
                if GetGameTimeSeconds() >= 11 then break end
            end
        end
    end

    if EntityCategoryContains(categories.MOBILE * categories.AIR - AiBotUnitInfo.refCategoryEngineer, oUnit.UnitId) and not(bIsEnemyAirUnit) and oUnit:GetFractionComplete() == 1 then AiBotUtilities.ErrorHandler('Havent flagged that a constructed air unit is an air unit') end


    local bAddToZone = true
    --The function in AiBotNavy, UpdateUnitPositionsAndWaterZone, should also remove a unit from a zone if it is in the wrong one based on its position

    if oUnit[AiBotUnitInfo.reftAssignedWaterZoneByTeam] and oUnit[AiBotUnitInfo.reftAssignedWaterZoneByTeam][aiBrain.AiBotTeam] then
        --Is the unit already assigned to this zone?
        if oUnit[AiBotUnitInfo.reftAssignedWaterZoneByTeam][aiBrain.AiBotTeam] == iWaterZone then
            if bDebugMessages == true then LOG(sFunctionRef..': Unit is already assigned to this water zone so will abort adding it') end
            bAddToZone = false
            --[[else
                if bDebugMessages == true then LOG(sFunctionRef..': Unit already has a plateau and LZ assigned but is dif from the desired one so will remove from its current zone first') end
                RemoveUnitFromCurrentLandZone(aiBrain, oUnit)--]]
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..'; Considering adding unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to iWaterZone '..(iWaterZone or 'nil')..' for brain '..aiBrain.Nickname..'; bAddToZone='..tostring(bAddToZone)..'; Is enemy='..tostring(IsEnemy(aiBrain:GetArmyIndex(), oUnit:GetAIBrain():GetArmyIndex()))..'; Is ally='..tostring(IsAlly(aiBrain:GetArmyIndex(), oUnit:GetAIBrain():GetArmyIndex()))..'; bWaterZoneFirstTeamInitialisation='..tostring(AiBotMap.bWaterZoneFirstTeamInitialisation or false)) end
    if bAddToZone then
        if not(oUnit[AiBotUnitInfo.reftAssignedWaterZoneByTeam]) then oUnit[AiBotUnitInfo.reftAssignedWaterZoneByTeam] = {} end
        oUnit[AiBotUnitInfo.reftAssignedWaterZoneByTeam][aiBrain.AiBotTeam] = iWaterZone
        local iPond = AiBotMap.tiPondByWaterZone[iWaterZone]
        local tWZData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iWaterZone]
        local tWZTeamData = tWZData[AiBotMap.subrefWZTeamData][aiBrain.AiBotTeam]
        --NOTE: If run into same issue that had with land zones (of not having valid plateau/land zone combination), DO NOT call the 'addunittolandzone' function from here, or else will create an infinite loop
        if bDebugMessages == true then LOG(sFunctionRef..': iPond='..(iPond or 'nil')..'; iWaterZone='..(iWaterZone or 'nil')..'; Team='..(aiBrain.AiBotTeam or 'nil')..'; IsEnemy='..tostring(IsEnemy(aiBrain:GetArmyIndex(), oUnit:GetAIBrain():GetArmyIndex()))..'; Is tWZTeamData empty='..tostring(AiBotUtilities.IsTableEmpty(tWZTeamData))) end
        if IsEnemy(aiBrain:GetArmyIndex(), oUnit:GetAIBrain():GetArmyIndex()) then
            if bDebugMessages == true then LOG(sFunctionRef..': Is an enemy so will add to list of enemy air units or enemy units depending on if it is air; aiBrain='..aiBrain.Nickname..'; team='..aiBrain.AiBotTeam..'; Unit position='..repru(oUnit:GetPosition())..'; bIsEnemyAirUnit='..tostring(bIsEnemyAirUnit or false)) end
            if bIsEnemyAirUnit then
                table.insert(tWZTeamData[AiBotMap.reftWZEnemyAirUnits], oUnit)
            else
                table.insert(tWZTeamData[AiBotMap.subrefTEnemyUnits], oUnit)
            end
            --Record if enemy has sub
            if EntityCategoryContains(AiBotUnitInfo.refCategorySubmarine, oUnit.UnitId) then
                tTeamData[aiBrain.AiBotTeam][refiEnemySubCount] = (tTeamData[aiBrain.AiBotTeam][refiEnemySubCount] or 0) + AiBotUnitInfo.GetUnitTechLevel(oUnit)
            end
            if AiBotConfig.AiBotShowEnemyUnitNames and not(oUnit:GetAIBrain().AiBotAI) then
                oUnit:SetCustomName((oUnit.UnitId or oUnit:GetBlueprint().BlueprintId)..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'P0Z'..(iWaterZone or 0))
            end
        elseif IsAlly(aiBrain:GetArmyIndex(), oUnit:GetAIBrain():GetArmyIndex()) then
            oUnit[AiBotNavy.refiCurrentWZAssignmentValue] = 0 --dont want to retain orders in case it was from an adjacent zone
            table.insert(tWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits], oUnit)
            if AiBotConfig.AiBotShowUnitNames then oUnit:SetCustomName(oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'New WZ'..iWaterZone) end




            if oUnit[AiBotNavy.refiCurrentWZAssignmentValue] then
                local iLastOrderZone = oUnit[AiBotNavy.refiCurrentAssignmentWaterZone]
                local bOrderZoneAdjacent = false
                if iLastOrderZone == iWaterZone then
                    bOrderZoneAdjacent = true
                elseif AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefWZAdjacentWaterZones]) == false then
                    for _, iAdjWZ in tWZData[AiBotMap.subrefWZAdjacentWaterZones] do
                        if iAdjWZ == iLastOrderZone then
                            bOrderZoneAdjacent = true
                            break
                        end
                    end
                end
                if not(bOrderZoneAdjacent) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Units assigned water zone isnt adjacent to its current zone, so will reset its assignment value, unit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)) end
                    oUnit[AiBotNavy.refiCurrentWZAssignmentValue] = 0 --reset so unit should get new orders from the current zone or an adjacent zone
                end
            end
            if oUnit[AiBotUnitInfo.refbUnitInStuckPondMass] and (oUnit[AiBotUnitInfo.refiNavalPathingStuckCountByZone][iWaterZone] or 0) == 0 then
                --Remove unit from stuck count
                oUnit[AiBotUnitInfo.refbUnitInStuckPondMass] = false
                local iPond = AiBotMap.tiPondByWaterZone[iWaterZone]
                local iUnitTech = AiBotUnitInfo.GetUnitTechLevel(oUnit)
                tTeamData[aiBrain.AiBotTeam][refiStuckMassByPondByTech][iPond][iUnitTech] = math.max(0, (tTeamData[aiBrain.AiBotTeam][refiStuckMassByPondByTech][iPond][iUnitTech] or 0) - (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)))
            end
            UpdateUnitPreviousZones(oUnit, 0, iWaterZone)

            if EntityCategoryContains(AiBotUnitInfo.refCategoryTMD, oUnit.UnitId) then
                AiBotBuilding.AlliedTMDFirstRecorded(aiBrain.AiBotTeam, oUnit)
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Add unit as a friendly unit to iWaterZone='..iWaterZone..' and team='..aiBrain.AiBotTeam..'; Is table of friendly units empty='..tostring(AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]))) end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function UpdateUnitLastKnownPosition(aiBrain, oUnit, bDontCheckIfCanSeeUnit, bInWaterZone)
    --Only updates the position if the unit isnt on the same team as us (to save space), since we can use :GetPosition() for allied units
    --Checks if the unti needs reassigning if it is a land or naval unit
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'UpdateUnitLastKnownPosition'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local oUnitBrain = oUnit:GetAIBrain()
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, considering whether to update last known position, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' owned by '..oUnit:GetAIBrain().Nickname..' for iTeam='..aiBrain.AiBotTeam..'; bDontCheckIfCanSeeUnit='..tostring(bDontCheckIfCanSeeUnit or false)..'; Cur dif in unit position and lastknownposition='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oUnit[AiBotUnitInfo.reftLastKnownPositionByTeam][aiBrain.AiBotTeam])..'; Time='..GetGameTimeSeconds()) end
    if not(oUnitBrain == aiBrain or IsAlly(aiBrain:GetArmyIndex(), oUnitBrain:GetArmyIndex())) then
        if bDontCheckIfCanSeeUnit or AiBotUnitInfo.CanSeeUnit(aiBrain, oUnit) then
            if not(oUnit[AiBotUnitInfo.reftLastKnownPositionByTeam]) then oUnit[AiBotUnitInfo.reftLastKnownPositionByTeam] = {} end
            local tCurPosition = oUnit:GetPosition()
            oUnit[AiBotUnitInfo.reftLastKnownPositionByTeam][aiBrain.AiBotTeam] = {tCurPosition[1], tCurPosition[2], tCurPosition[3]} --Do a copy of table as :GetPosition() means it will always update for the unit's latest position even when we lack intel of it
            if bDebugMessages == true then LOG(sFunctionRef..': We can see the unit or we are ignoring if we can see unit, so updating last known position') end
        else
            --Below to try and approximate scenarios where enemy retreats temporarily with the unit and we end up with units thinking the enemy is right infront of them (even though they can see the location it used to be to confirm it isnt there); will approximate by saying if we have friendly units in the same land zone as the last known position, and that position has changed by more than 10, then we can refresh its position
            if not(bInWaterZone) then
                local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnit[AiBotUnitInfo.reftLastKnownPositionByTeam][aiBrain.AiBotTeam])
                if AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTeamData][aiBrain.AiBotTeam][AiBotMap.subreftoLZOrWZAlliedUnits]) == false
                    --Require unit to have moved significnatly from last known position as want to limit use of this to get balance between AI recognising enemy no longer where it thinks it was, vs AI knowing where enemy actually is
                        and (AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(),oUnit[AiBotUnitInfo.reftLastKnownPositionByTeam][aiBrain.AiBotTeam]) >= 10)  then
                    local tCurPosition = oUnit:GetPosition()
                    if bDebugMessages == true then LOG(sFunctionRef..': Updating unit last known position to actual since it has moved significantly further away and we have a unit in the same zone') end
                    oUnit[AiBotUnitInfo.reftLastKnownPositionByTeam][aiBrain.AiBotTeam] = {tCurPosition[1], tCurPosition[2], tCurPosition[3]}
                end
            else
                local iLastSegmentX, iLastSegmentZ = AiBotMap.GetPathingSegmentFromPosition(oUnit[AiBotUnitInfo.reftLastKnownPositionByTeam][aiBrain.AiBotTeam])
                local iWaterZone = AiBotMap.tWaterZoneBySegment[iLastSegmentX][iLastSegmentZ]
                if iWaterZone then
                    local iPond = AiBotMap.tiPondByWaterZone[iWaterZone]
                    if AiBotUtilities.IsTableEmpty(AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iWaterZone][AiBotMap.subrefLZTeamData][aiBrain.AiBotTeam][AiBotMap.subreftoLZOrWZAlliedUnits]) == false
                            and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(),oUnit[AiBotUnitInfo.reftLastKnownPositionByTeam][aiBrain.AiBotTeam]) >= 10 then
                        local tCurPosition = oUnit:GetPosition()
                        if bDebugMessages == true then LOG(sFunctionRef..': Updating unit last known position to actual since it has moved significantly further away and we have a unit in the same water zone') end
                        oUnit[AiBotUnitInfo.reftLastKnownPositionByTeam][aiBrain.AiBotTeam] = {tCurPosition[1], tCurPosition[2], tCurPosition[3]}
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function DelayedUnitAssignmentForTeamSetup(aiBrain, oUnit)
    while not(AiBotMap.bFirstAiBotTeamHasBeenInitialised) or not(AiBotMap.bMapLandSetupComplete) or not(AiBotMap.bWaterZoneInitialCreation) do
        WaitTicks(1)
        if GetGameTimeSeconds() >= 120 then
            AiBotUtilities.ErrorHandler('Still dont have a team setup after waiting a long time so will abort')
            break
        end
    end
    WaitTicks(1)
    if AiBotUnitInfo.IsUnitValid(oUnit) then
        ConsiderAssigningUnitToZoneForBrain(aiBrain, oUnit)
    end
end

function ConsiderAssigningUnitToZoneForBrain(aiBrain, oUnit)
    --Assumes called from an event that means we will have visibility of the unit (e.g. directly via intel, or indirectly via weapon firing)
    if aiBrain.AiBotAI and not(aiBrain.AiBotIsDefeated) then
        local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
        local sFunctionRef = 'ConsiderAssigningUnitToZoneForBrain'
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

        if not(aiBrain.AiBotTeam) and not(AiBotMap.bFirstAiBotTeamHasBeenInitialised) then ForkThread(DelayedUnitAssignmentForTeamSetup, aiBrain, oUnit)
        else


            if bDebugMessages == true then LOG(sFunctionRef..': Checking at time '..GetGameTimeSeconds()..' if should assign unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to a plateau/other table. Considered for assignment repru='..repru(oUnit[AiBotUnitInfo.reftbConsideredForAssignmentByTeam])..'; Unit brain team='..(oUnit:GetAIBrain().AiBotTeam or 'nil')..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))..'; aiBrain.AiBotIsDefeated='..tostring(aiBrain.AiBotIsDefeated or false)) end
            if AiBotUnitInfo.IsUnitValid(oUnit) then --redundancy
                if (not(oUnit[AiBotUnitInfo.reftbConsideredForAssignmentByTeam]) or not(oUnit[AiBotUnitInfo.reftbConsideredForAssignmentByTeam][aiBrain.AiBotTeam])) and AiBotUnitInfo.IsUnitValid(oUnit) and not(aiBrain.AiBotIsDefeated) then
                    AssignUnitToLandZoneOrPond(aiBrain, oUnit)
                else
                    UpdateUnitLastKnownPosition(aiBrain, oUnit, true)
                end
            end
        end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    end
end

function DelayedUnitPlateauAssignment(aiBrain, oUnit, iDelayInTicks, bAlreadyUpdatedPosition, bAlreadyTriedReassignment)
    WaitTicks(iDelayInTicks)
    AssignUnitToLandZoneOrPond(aiBrain, oUnit, bAlreadyUpdatedPosition, bAlreadyTriedReassignment)
end

function RemoveUnitFromBigThreatTable(oDeadUnit)
    --Removes all dead units from each team's listings, assuming oDeadUnit is a big threat
    local sTableRef
    local bIsSMD = false
    if EntityCategoryContains(AiBotUnitInfo.refCategorySMD, oDeadUnit.UnitId) then bIsSMD = true end
    for sReferenceTable, iCategory in tEnemyBigThreatCategories do
        if EntityCategoryContains(iCategory, oDeadUnit.UnitId) then
            sTableRef = sReferenceTable
            break
        end
    end
    for iTeam, bRecorded in oDeadUnit[AiBotUnitInfo.reftbInArmyIndexBigThreatTable] do
        local iRevisedIndex = 1
        local iTableSize = table.getn(tTeamData[iTeam][sTableRef])

        for iOrigIndex=1, iTableSize do
            if tTeamData[iTeam][sTableRef][iOrigIndex] then
                if AiBotUnitInfo.IsUnitValid(tTeamData[iTeam][sTableRef][iOrigIndex]) then --I.e. this should run the logic to decide whether we want to keep this entry of the table or remove it
                    --We want to keep the entry; Move the original index to be the revised index number (so if e.g. a table of 1,2,3 removed 2, then this would've resulted in the revised index being 2 (i.e. it starts at 1, then icnreases by 1 for the first valid entry); this then means we change the table index for orig index 3 to be 2
                    if (iOrigIndex ~= iRevisedIndex) then
                        tTeamData[iTeam][sTableRef][iRevisedIndex] = tTeamData[iTeam][sTableRef][iOrigIndex];
                        tTeamData[iTeam][sTableRef][iOrigIndex] = nil;
                    end
                    iRevisedIndex = iRevisedIndex + 1; --i.e. this will be the position of where the next value that we keep will be located
                else
                    if bIsSMD then tTeamData[iTeam][refbEnemySMDDiedSinceLastNukeCheck] = true end --used to refresh nuke target zone logic
                    tTeamData[iTeam][sTableRef][iOrigIndex] = nil;
                end
                if EntityCategoryContains(AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategoryExperimentalArti + AiBotUnitInfo.refCategorySatellite + AiBotUnitInfo.refCategoryNovaxCentre, oDeadUnit.UnitId) then
                    RefreshArtiAndNovaxCount(iTeam)
                end
            end
        end
        if iRevisedIndex < iTableSize then
            --table.setn(tTeamData[iTeam][sTableRef], iRevisedIndex - 1)
            for iRemovalEntry = iTableSize, iRevisedIndex, -1 do
                table.remove(tTeamData[iTeam][sTableRef], iRemovalEntry)
            end
        end
    end
end
function LongRangeDFAndIFThreatMonitor(iTeam, bDealingWithIndirectThreat)
    --Call via forkthread
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'LongRangeDFAndIFThreatMonitor'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    local iTableSize
    local sreftiLastPlateauAndZone = 'AiBotLRLstPZ'
    local iPlateauOrZero, iLandOrWaterZone

    if bDebugMessages == true then LOG(sFunctionRef..': About to start long range enemy unit monitor for team '..iTeam..'; Is table empty='..tostring(AiBotUtilities.IsTableEmpty(tTeamData[iTeam][reftoLongRangeEnemyDFUnits]))) end
    local sreftLREnemyUnitsTableRef, sLZTeamDataLRUnitsTableRef
    if bDealingWithIndirectThreat then
        sreftLREnemyUnitsTableRef = reftoLongRangeEnemyIndirectUnits
        sLZTeamDataLRUnitsTableRef = AiBotMap.subrefoNearbyEnemyLongRangeIFThreats
    else
        sreftLREnemyUnitsTableRef = reftoLongRangeEnemyDFUnits
        sLZTeamDataLRUnitsTableRef = AiBotMap.subrefoNearbyEnemyLongRangeDFThreats
    end
    while AiBotUtilities.IsTableEmpty(tTeamData[iTeam][sreftLREnemyUnitsTableRef]) == false do
        --Check all units still alive
        iTableSize = table.getn(tTeamData[iTeam][sreftLREnemyUnitsTableRef])
        if bDebugMessages == true then LOG(sFunctionRef..': Size of table at time '..GetGameTimeSeconds()..'='..iTableSize) end
        for iCurEntry = iTableSize, 1, -1 do
            local oUnit = tTeamData[iTeam][sreftLREnemyUnitsTableRef][iCurEntry]

            if bDebugMessages == true then LOG(sFunctionRef..': Considering unit '..(oUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil')..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))) end
            if not(AiBotUnitInfo.IsUnitValid(oUnit)) then
                table.remove(tTeamData[iTeam][sreftLREnemyUnitsTableRef], iCurEntry)
            else
                if oUnit:GetFractionComplete() >= 0.95 then
                    iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
                    --Has this changed from last time? if so need to refresh
                    if bDebugMessages == true then LOG(sFunctionRef..': iPlateauOrZero='..(iPlateauOrZero or 'nil')..'; iLandOrWaterZone='..(iLandOrWaterZone or 'nil')..'; sreftiLastPlateauAndZone='..repru( oUnit[sreftiLastPlateauAndZone])) end
                    if iPlateauOrZero == oUnit[sreftiLastPlateauAndZone][1] and iLandOrWaterZone == oUnit[sreftiLastPlateauAndZone][2] then
                        --Do nothing - no change
                        if bDebugMessages == true then LOG(sFunctionRef..': No change in units zone from last time we ran so dont need to do anything further') end
                    else
                        --has changed - remove from previous entries if it had any
                        if (oUnit[sreftiLastPlateauAndZone][2] or 0) > 0 then
                            --Remove previous entries if was land zone
                            if (oUnit[sreftiLastPlateauAndZone][1] or 0) > 0 then
                                local tLZData = AiBotMap.tAllPlateaus[oUnit[sreftiLastPlateauAndZone][1]][AiBotMap.subrefPlateauLandZones][oUnit[sreftiLastPlateauAndZone][2]]
                                local iAdjLZ
                                if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZPathingToOtherLandZones]) == false then
                                    for iEntry, tSubtable in tLZData[AiBotMap.subrefLZPathingToOtherLandZones] do
                                        iAdjLZ = tSubtable[AiBotMap.subrefLZNumber]
                                        local tAdjLZTeamData = AiBotMap.tAllPlateaus[oUnit[sreftiLastPlateauAndZone][1]][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                                        if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[sLZTeamDataLRUnitsTableRef]) == false then
                                            for iRecordedUnit, oRecordedUnit in tAdjLZTeamData[sLZTeamDataLRUnitsTableRef] do
                                                if oUnit == oRecordedUnit then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': removing unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' from iAdjLZ='..iAdjLZ) end
                                                    table.remove(tAdjLZTeamData[sLZTeamDataLRUnitsTableRef], iRecordedUnit)
                                                    break
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end

                        --Add to nearby zones
                        oUnit[sreftiLastPlateauAndZone] = {[1]=iPlateauOrZero,[2]=iLandOrWaterZone}
                        local iMaxDist
                        if bDealingWithIndirectThreat then iMaxDist = oUnit[AiBotUnitInfo.refiIndirectRange] + 140
                        else iMaxDist = oUnit[AiBotUnitInfo.refiDFRange] + 140 --tried +40 (meaning 140 range on fatboy) but led to fatboy getting free hits on units with the dist between zones being 195; have therefore increased the dist threshold, and added in a distance check into the zone itself which will go with a slightly lower distance.  With +120 still had cases where e.g. 100 range PD would shoot units in zone + 1 away that weren't being registered (were 20 out)
                        end
                        local bIsBuilding = EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oUnit.UnitId)
                        if bIsBuilding then iMaxDist = iMaxDist - 8 end --can do more precise dist check with buildings
                        local tLZOrWZData
                        if iPlateauOrZero == 0 then
                            tLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone]
                        else
                            tLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
                        end
                        local iAdjLZOrWZ, iAdjPlateau
                        local iCurDist

                        if bDebugMessages == true then LOG(sFunctionRef..': Unit has changed zones, is table of pathing to other zones empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefLZPathingToOtherLandZones]))) end
                        if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) then
                            AiBotAir.RecordOtherLandAndWaterZonesByDistance(tLZOrWZData)
                            if bDebugMessages == true then LOG(sFunctionRef..': Is pathing to other zones still empty after updating='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefLZPathingToOtherLandZones]))) end
                        end
                        if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) == false then
                            local tbZonesByPlateauAdded = {}
                            for iEntry, tSubtable in tLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
                                if tSubtable[AiBotMap.subrefiDistance] > iMaxDist then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Are too far from the other zone so will stop searching, dist='..tSubtable[AiBotMap.subrefiDistance]..'; iMaxDist='..iMaxDist..'; Plat or Pond='..tSubtable[AiBotMap.subrefiPlateauOrPond]..'; Zone='..tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]) end
                                    --Double check all adjacent land zones have this recorded
                                    if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                                        local bInclude
                                        for _, iAdjacentLZ in tLZOrWZData[AiBotMap.subrefLZAdjacentLandZones] do
                                            if bDebugMessages == true then LOG(sFunctionRef..': Double checking that all adjacent LZs have recorded this LR unit, iAdjacentLZ='..iAdjacentLZ..'; Already considered='..tostring(tbZonesByPlateauAdded[iPlateauOrZero][iAdjacentLZ] or false)) end
                                            if not(tbZonesByPlateauAdded[iPlateauOrZero][iAdjacentLZ]) then
                                                bInclude = true
                                                local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iAdjacentLZ][AiBotMap.subrefLZTeamData][iTeam]
                                                if not(tAdjLZTeamData[sLZTeamDataLRUnitsTableRef]) then
                                                    tAdjLZTeamData[sLZTeamDataLRUnitsTableRef] = {}
                                                else
                                                    --Redundancy - make sure not already here
                                                    if AiBotConditions.IsTableOfUnitsStillValid(tAdjLZTeamData[sLZTeamDataLRUnitsTableRef]) then
                                                        for iRecordedUnit, oRecordedUnit in tAdjLZTeamData[sLZTeamDataLRUnitsTableRef] do
                                                            if bDebugMessages == true then LOG(sFunctionRef..'; Checking if unit is already recorded, ddoes oUnit equal oRecordedUnit='..tostring(oUnit == oRecordedUnit)..'; oRecordedUnit='..oRecordedUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oRecordedUnit)) end
                                                            if oUnit == oRecordedUnit then
                                                                bInclude = false
                                                                break
                                                            end
                                                        end
                                                    end
                                                end
                                                if bInclude then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Just added adjacent zone unit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to table of long range threats for zone '..iAdjacentLZ..' on plateau '..iPlateauOrZero..'; Dist to closest friendly base='.. AiBotUtilities.GetDistanceBetweenPositions(tAdjLZTeamData[AiBotMap.reftClosestFriendlyBase], oUnit:GetPosition())) end
                                                    table.insert(tAdjLZTeamData[sLZTeamDataLRUnitsTableRef], oUnit)
                                                end
                                            end
                                        end
                                    elseif AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefAdjacentLandZones]) == false then
                                        local bInclude, iAdjacentPlateau, iAdjacentLZ
                                        for _, tSubtable in tLZOrWZData[AiBotMap.subrefAdjacentLandZones] do
                                            iAdjacentPlateau = tSubtable[AiBotMap.subrefWPlatAndLZNumber][1]
                                            iAdjacentLZ = tSubtable[AiBotMap.subrefWPlatAndLZNumber][2]
                                            if bDebugMessages == true then LOG(sFunctionRef..': Double checking that all adjacent LZs have recorded this LR unit, iAdjacentLZ='..iAdjacentLZ..'; Already considered='..tostring(tbZonesByPlateauAdded[iAdjacentLZ] or false)) end
                                            if not(tbZonesByPlateauAdded[iAdjacentPlateau][iAdjacentLZ]) then
                                                bInclude = true
                                                local tAdjLZTeamData = AiBotMap.tAllPlateaus[iAdjacentPlateau][AiBotMap.subrefPlateauLandZones][iAdjacentLZ][AiBotMap.subrefLZTeamData][iTeam]
                                                if not(tAdjLZTeamData[sLZTeamDataLRUnitsTableRef]) then
                                                    tAdjLZTeamData[sLZTeamDataLRUnitsTableRef] = {}
                                                else
                                                    --Redundancy - make sure not already here
                                                    if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[sLZTeamDataLRUnitsTableRef]) == false then
                                                        for iRecordedUnit, oRecordedUnit in tAdjLZTeamData[sLZTeamDataLRUnitsTableRef] do
                                                            if oUnit == oRecordedUnit then
                                                                bInclude = false
                                                                break
                                                            end
                                                        end
                                                    end
                                                end
                                                if bInclude then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Just added adjacent zone unit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to table of long range threats for zone '..iAdjacentLZ..' on iAdjacentPlateau='..iAdjacentPlateau..'; Dist to closest friendly base='.. AiBotUtilities.GetDistanceBetweenPositions(tAdjLZTeamData[AiBotMap.reftClosestFriendlyBase], oUnit:GetPosition())) end
                                                    table.insert(tAdjLZTeamData[sLZTeamDataLRUnitsTableRef], oUnit)
                                                    if bDebugMessages == true then
                                                        local tAdjLZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iAdjacentLZ]
                                                        LOG(sFunctionRef..': Just added adjacent zone unit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to table of long range threats for zone '..iAdjacentLZ..' on plateau '..iPlateauOrZero..'; Dist between midpoints='.. AiBotUtilities.GetDistanceBetweenPositions(tAdjLZData[AiBotMap.subrefMidpoint], tAdjLZData[AiBotMap.subrefMidpoint])..'; Unit dist to adjLZData midpoint='.. AiBotUtilities.GetDistanceBetweenPositions(tAdjLZData[AiBotMap.subrefMidpoint], oUnit:GetPosition())..'; Dist to closest friendly base='.. AiBotUtilities.GetDistanceBetweenPositions(tAdjLZTeamData[AiBotMap.reftClosestFriendlyBase], oUnit:GetPosition()))
                                                        for iRecorded, oRecorded in tAdjLZTeamData[sLZTeamDataLRUnitsTableRef] do
                                                            LOG('Cycling through all recorded units post insert, oRecorded='..oRecorded.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oRecorded)..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oRecorded)))
                                                            if AiBotUnitInfo.IsUnitValid(oRecorded) then LOG('Recorded unit brain='..oRecorded:GetAIBrain().Nickname) end
                                                        end
                                                    end
                                                end
                                            end
                                        end
                                    end

                                    break
                                end
                                --Dont record long range threats in water zones
                                if not(tSubtable[AiBotMap.subrefbIsWaterZone]) then
                                    iAdjPlateau = tSubtable[AiBotMap.subrefiPlateauOrPond]
                                    iAdjLZOrWZ = tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]
                                    if not(tbZonesByPlateauAdded[iAdjPlateau]) then tbZonesByPlateauAdded[iAdjPlateau] = {} end
                                    tbZonesByPlateauAdded[iAdjPlateau][iAdjLZOrWZ] = true
                                    local tAdjLZData = AiBotMap.tAllPlateaus[iAdjPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZOrWZ]
                                    if bIsBuilding then iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tAdjLZData[AiBotMap.subrefMidpoint], oUnit:GetPosition()) else iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tAdjLZData[AiBotMap.subrefMidpoint], tLZOrWZData[AiBotMap.subrefMidpoint]) end
                                    if bDebugMessages == true then LOG(sFunctionRef..': Checking if we are close to zone '..iAdjLZOrWZ..'; Dist between midpoints to this='..AiBotUtilities.GetDistanceBetweenPositions(tAdjLZData[AiBotMap.subrefMidpoint], tLZOrWZData[AiBotMap.subrefMidpoint])..'; iMaxDist='..iMaxDist..'; iCurDist='..iCurDist) end
                                    if iCurDist <= iMaxDist then
                                        local tAdjLZTeamData = tAdjLZData[AiBotMap.subrefLZTeamData][iTeam] --wont be water zone as we are only considering non-water zones per above
                                        local bInclude = true
                                        if not(tAdjLZTeamData[sLZTeamDataLRUnitsTableRef]) then
                                            tAdjLZTeamData[sLZTeamDataLRUnitsTableRef] = {}
                                        else
                                            --Redundancy - make sure not already here
                                            if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[sLZTeamDataLRUnitsTableRef]) == false then
                                                for iRecordedUnit, oRecordedUnit in tAdjLZTeamData[sLZTeamDataLRUnitsTableRef] do
                                                    if oUnit == oRecordedUnit then
                                                        bInclude = false
                                                        break
                                                    end
                                                end
                                            end
                                        end
                                        if bInclude then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Just added unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to table of long range threats for zone '..iAdjLZOrWZ..' on plateau '..iAdjPlateau..'; base iPlateauOrZero='..iPlateauOrZero..'; Dist between midpoints='.. AiBotUtilities.GetDistanceBetweenPositions(tAdjLZData[AiBotMap.subrefMidpoint], tLZOrWZData[AiBotMap.subrefMidpoint])..'; Unit dist to adjLZData midpoint='.. AiBotUtilities.GetDistanceBetweenPositions(tAdjLZData[AiBotMap.subrefMidpoint], oUnit:GetPosition())..'; Dist to closest friendly base='.. AiBotUtilities.GetDistanceBetweenPositions(tAdjLZTeamData[AiBotMap.reftClosestFriendlyBase], oUnit:GetPosition())) end
                                            table.insert(tAdjLZTeamData[sLZTeamDataLRUnitsTableRef], oUnit)
                                        end
                                    else
                                        if bDebugMessages == true then LOG(sFunctionRef..': straight line dist is too far away so wont record') end
                                    end
                                else
                                    if bDebugMessages == true then LOG(sFunctionRef..': we dont record long range threats against water zones, only against land zones') end
                                end
                            end
                        end

                    end
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': End of loop, gametime='..GetGameTimeSeconds()) end

        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitSeconds(1)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    end
    --Reset (so the monitor gets restarted next time there is a long range enemy threat)
    tTeamData[iTeam][sreftLREnemyUnitsTableRef] = nil
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function AddUnitToLongRangeThreatTable(oUnit, iTeam, bCheckifAlreadyInTable, bDealingWithIndirectThreat)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'AddUnitToLongRangeThreatTable'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local bNotInTable = not(bCheckifAlreadyInTable)
    local sreftLREnemyUnitsTableRef
    if bDealingWithIndirectThreat then
        sreftLREnemyUnitsTableRef = reftoLongRangeEnemyIndirectUnits
    else
        sreftLREnemyUnitsTableRef = reftoLongRangeEnemyDFUnits
    end

    if not(tTeamData[iTeam][sreftLREnemyUnitsTableRef]) then
        tTeamData[iTeam][sreftLREnemyUnitsTableRef] = {}
        bNotInTable = true
        ForkThread(LongRangeDFAndIFThreatMonitor, iTeam, bDealingWithIndirectThreat)
    end
    if not(bNotInTable) then
        bNotInTable = true
        for iEntry, oExistingUnit in tTeamData[iTeam][sreftLREnemyUnitsTableRef] do
            if oUnit == oExistingUnit then
                bNotInTable = false
                break
            end
        end
    end
    if bNotInTable then
        table.insert(tTeamData[iTeam][sreftLREnemyUnitsTableRef], oUnit)
        --Considering TML if its a directfire LR threat (e.g. megalith, fatboy)
        if not(tTeamData[iTeam][refbTMLForLongRangeThreatMonitorActive]) and not(bDealingWithIndirectThreat) then
            ForkThread(ConsiderTMLForLongRangeEnemyThreat, iTeam)
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code at time '..GetGameTimeSeconds()..'; oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Added to table of long range units and started a monitor if one wasnt already started. Unit DF range='..(oUnit[AiBotUnitInfo.refiDFRange] or 'nil')) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function AddUnitToBigThreatTable(iTeam, oUnit)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'AddUnitToBigThreatTable'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    if bDebugMessages == true then LOG(sFunctionRef..': Considering ouNIt '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' for iTeam='..iTeam..'; oUnit[AiBotUnitInfo.reftbInArmyIndexBigThreatTable][iTeam]='..(oUnit[AiBotUnitInfo.reftbInArmyIndexBigThreatTable][iTeam] or 'nil')) end
    if not(oUnit[AiBotUnitInfo.reftbInArmyIndexBigThreatTable] and oUnit[AiBotUnitInfo.reftbInArmyIndexBigThreatTable][iTeam]) then
        local bAlreadyInTable = false

        for sReferenceTable, iCategory in tEnemyBigThreatCategories do
            if bDebugMessages == true then LOG(sFunctionRef..': Considering sReferenceTable='..sReferenceTable..'; Does unit contain category for this table='..tostring(EntityCategoryContains(iCategory, oUnit.UnitId))) end
            if EntityCategoryContains(iCategory, oUnit.UnitId) then
                if AiBotUtilities.IsTableEmpty(tTeamData[iTeam][sReferenceTable]) == false then
                    for iExistingUnit, oExistingUnit in tTeamData[iTeam][sReferenceTable] do
                        if oExistingUnit == oUnit then

                            bAlreadyInTable = true --redundancy
                            if not(oUnit[AiBotUnitInfo.reftbInArmyIndexBigThreatTable]) then oUnit[AiBotUnitInfo.reftbInArmyIndexBigThreatTable] = {} end
                            oUnit[AiBotUnitInfo.reftbInArmyIndexBigThreatTable][iTeam] = true
                            break
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': bAlreadyInTable='..tostring(bAlreadyInTable)) end
                if not(bAlreadyInTable) then
                    if bDebugMessages == true then LOG(sFunctionRef..': About to add unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to reference table. Is table empty='..tostring(AiBotUtilities.IsTableEmpty(tTeamData[iTeam][sReferenceTable]))..'; Unit fraction complete='..oUnit:GetFractionComplete()..'; T3 resource generation units held by owner='..oUnit:GetAIBrain():GetCurrentUnits(AiBotUnitInfo.refCategoryT3Mex + AiBotUnitInfo.refCategoryRASSACU + AiBotUnitInfo.refCategoryParagon)) end
                    if not(tTeamData[iTeam][sReferenceTable]) then tTeamData[iTeam][sReferenceTable] = {} end
                    table.insert(tTeamData[iTeam][sReferenceTable], oUnit)
                    if not(oUnit[AiBotUnitInfo.reftbInArmyIndexBigThreatTable]) then oUnit[AiBotUnitInfo.reftbInArmyIndexBigThreatTable] = {} end
                    oUnit[AiBotUnitInfo.reftbInArmyIndexBigThreatTable][iTeam] = true
                    if bDebugMessages == true then
                        LOG(sFunctionRef .. ': Have some units for experimental threat category sReferenceTable=' .. sReferenceTable .. '; is tReferenceTableEmpty after considering if civilian or pathable to us='..tostring(AiBotUtilities.IsTableEmpty(tTeamData[iTeam][sReferenceTable]))..'; tTeamData[iTeam][refbDefendAgainstArti]='..tostring(tTeamData[iTeam][refbDefendAgainstArti] or false)..'; iTeam='..iTeam..'; Is this a T3 arti or novax='..tostring(EntityCategoryContains(AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategoryNovaxCentre + AiBotUnitInfo.refCategoryExperimentalArti, oUnit.UnitId))..'; oUnit[AiBotUnitInfo.refiDFRange]='..(oUnit[AiBotUnitInfo.refiDFRange] or 'nil'))
                    end

                    --Flag if SMD built so can update nuke targeting; refiTimeOfLastCheck is used to hold the estimated time that the smd was built (which then informs whether the smd is assumed to be able to block a nuke)
                    if EntityCategoryContains(AiBotUnitInfo.refCategorySMD, oUnit.UnitId) then
                        tTeamData[iTeam][refbEnemySMDBuiltSinceLastNukeCheck] = true
                        local iTimeAssumedConstructed
                        if (oUnit.GetNukeSiloAmmoCount and oUnit:GetNukeSiloAmmoCount() >= 1) or (oUnit.GetTacticalSiloAmmoCount and oUnit:GetTacticalSiloAmmoCount() >= 1) or oUnit:GetWorkProgress() >= 0.8 then oUnit[AiBotUnitInfo.refiTimeOfLastCheck] = (oUnit[AiBotUnitInfo.refiTimeOfLastCheck] or 0) - 240 - AiBotBuilding.iTimeForSMDToBeConstructed
                            --Rough approximation of when SMD was built (ideally in future would work out the time we last scouted this area and then to be prudent assume the SMD got built 30s after that)
                        elseif oUnit:GetFractionComplete() == 1 then
                            oUnit[AiBotUnitInfo.refiTimeOfLastCheck] = GetGameTimeSeconds() - AiBotBuilding.iTimeForSMDToBeConstructed - 240 * oUnit:GetWorkProgress()
                            if bDebugMessages == true then LOG(sFunctionRef..': Are recording a constructed SMD so estimating when it was constructed,  oSMD='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Owner='..oUnit:GetAIBrain().Nickname..'; Time='..GetGameTimeSeconds()) end
                        else
                            oUnit[AiBotUnitInfo.refiTimeOfLastCheck] = GetGameTimeSeconds() - AiBotBuilding.iTimeForSMDToBeConstructed * oUnit:GetFractionComplete() --I.e. assume enemy will be able to build SMD missile c.45s sooner than would expect if it's at 99% complete
                            if bDebugMessages == true then LOG(sFunctionRef..': Are recording an underconstruction SMD so estimating when it was constructed,  oSMD='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Owner='..oUnit:GetAIBrain().Nickname..'; Fraction complete='..oUnit:GetFractionComplete()..'; Time='..GetGameTimeSeconds()) end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Just registered oSMD='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' for team '..iTeam..' at time='..GetGameTimeSeconds()..'; SMD fraction complete='..oUnit:GetFractionComplete()..'; oUnit[AiBotUnitInfo.refiTimeOfLastCheck]='..(oUnit[AiBotUnitInfo.refiTimeOfLastCheck] or 'nil')) end
                    elseif EntityCategoryContains(AiBotUnitInfo.refCategorySML, oUnit.UnitId) or oUnit.UnitId == 'uese0001' then
                        --Unpause any paused SMD
                        for iBrain, oBrain in tTeamData[iTeam][subreftoFriendlyActiveAiBotBrains] do
                            local tSMD = oBrain:GetListOfUnits(AiBotUnitInfo.refCategorySMD, false, true)
                            if AiBotUtilities.IsTableEmpty(tSMD) == false then
                                for iUnit, oUnit in tSMD do
                                    --AiBotUnitInfo.PauseOrUnpauseEnergyUsage(oUnit, false, nil, iTeam)
                                    AiBotUnitInfo.PauseOrUnpauseUnitWithoutTracking(oUnit, false)
                                    AiBotUnitInfo.SetUnitMissileAutoBuildStatus(oUnit, true)
                                    --oUnit:SetAutoMode(true)
                                end
                            end
                        end
                        --If enemy has arti then upgrade any shields
                        if (tTeamData[iTeam][refiEnemyNovaxCount] or 0)  > 0 or (tTeamData[iTeam][refiEnemyT3ArtiCount] or 0) > 0 then
                            if AiBotUtilities.IsTableEmpty(tTeamData[iTeam][reftEnemyNukeLaunchers]) == false then
                                ForkThread(AiBotBuilding.UpgradeShieldsCoveringSMD, iTeam)
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Have a nuke launcher, have finished checking if want to unpause our SMD') end
                    elseif AiBotConditions.IsUnitLongRangeThreat(oUnit) then
                        if bDebugMessages == true then LOG(sFunctionRef..': have a long ranged DF big threat unit so adding to long range threat table as well') end
                        if bDebugMessages == true then LOG(sFunctionRef..': have a long ranged DF big threat unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' so adding to long range threat table as well, unit DF range='..(oUnit[AiBotUnitInfo.refiDFRange] or 'nil')..'; IF range='..(oUnit[AiBotUnitInfo.refiIndirectRange] or 'nil')..'; Does unit appear to be primarily IF unit='..tostring(((oUnit[AiBotUnitInfo.refiDFRange] or 0) < 30 and (oUnit[AiBotUnitInfo.refiIndirectRange] or 0) > 30))) end
                        AddUnitToLongRangeThreatTable(oUnit, iTeam, false, ((oUnit[AiBotUnitInfo.refiDFRange] or 0) < 30 and (oUnit[AiBotUnitInfo.refiIndirectRange] or 0) > 30))
                    end

                    --Track T3 arti
                    if not(tTeamData[iTeam][refbDefendAgainstArti]) and EntityCategoryContains(AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategoryNovaxCentre + AiBotUnitInfo.refCategoryExperimentalArti + AiBotUnitInfo.refCategorySatellite, oUnit.UnitId) then
                        tTeamData[iTeam][refbDefendAgainstArti] = true
                        if EntityCategoryContains(AiBotUnitInfo.refCategoryFixedT3Arti, oUnit.UnitId) then tTeamData[iTeam][refiEnemyT3ArtiCount] = 1
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryExperimentalArti, oUnit.UnitId) then tTeamData[iTeam][refiEnemyT3ArtiCount] = 2
                        else tTeamData[iTeam][refiEnemyNovaxCount] = (tTeamData[iTeam][refiEnemyNovaxCount] or 0) + 1
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': have set flag to defend against T3 arti to true for team '..iTeam..'; tTeamData[iTeam][refbDefendAgainstArti]='..tostring(tTeamData[iTeam][refbDefendAgainstArti])..'; tTeamData[iTeam][refiEnemyT3ArtiCount]='..(tTeamData[iTeam][refiEnemyT3ArtiCount] or 'nil')..'; tTeamData[iTeam][refiEnemyNovaxCount]='..(tTeamData[iTeam][refiEnemyNovaxCount] or 'nil')..'; oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; owner='..oUnit:GetAIBrain().Nickname..'; iTeam='..iTeam) end
                        --Refresh shielding wanted on existing units
                        local tPotentialUnitsToShield = tTeamData[iTeam][subreftoFriendlyActiveAiBotBrains][1]:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryStructure - AiBotUnitInfo.refCategoryFixedShield - categories.TECH1, {0.5*(AiBotMap.rMapPlayableArea[1] + AiBotMap.rMapPlayableArea[3]), 0, 0.5*(AiBotMap.rMapPlayableArea[2] + AiBotMap.rMapPlayableArea[4])}, 10000, 'Ally')
                        if AiBotUtilities.IsTableEmpty(tPotentialUnitsToShield) == false then
                            for iPotentialUnit, oPotentialUnit in tPotentialUnitsToShield do
                                if oPotentialUnit:GetAIBrain().AiBotAI and oPotentialUnit:GetFractionComplete() == 1 then
                                    AiBotBuilding.CheckIfUnitWantsFixedShield(oPotentialUnit, true)
                                end
                            end
                        end
                        --Upgrade ED1 shields
                        for iBrain, oBrain in tTeamData[iTeam][subreftoFriendlyActiveAiBotBrains] do
                            local tED1Shields = oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryFixedShield * categories.BUILTBYTIER2ENGINEER * categories.CYBRAN, false, true)
                            if AiBotUtilities.IsTableEmpty(tED1Shields) == false then
                                for iShield, oShield in tED1Shields do
                                    if oShield:GetFractionComplete() == 1 then
                                        AiBotEconomy.UpgradeUnit(oShield, true)
                                    end
                                end
                            end
                        end
                    end
                end
                break
            end
        end
        if EntityCategoryContains(AiBotUnitInfo.refCategoryFixedT3Arti + AiBotUnitInfo.refCategoryExperimentalArti + AiBotUnitInfo.refCategorySatellite + AiBotUnitInfo.refCategoryNovaxCentre, oUnit.UnitId) then
            RefreshArtiAndNovaxCount(iTeam)
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end


function RecordEnemyT2ArtiAgainstNearbyZones(iTeam, oUnit, bUnitIsDead)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RecordEnemyT2ArtiAgainstNearbyZones'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if not(tTeamData[iTeam][reftoEnemyT2Arti]) then tTeamData[iTeam][reftoEnemyT2Arti] = {} end
    if not(bUnitIsDead) then
        table.insert(tTeamData[iTeam][reftoEnemyT2Arti], oUnit)
    else
        AiBotConditions.IsTableOfUnitsStillValid(tTeamData[iTeam][reftoEnemyT2Arti], false)
    end
    local tStartLZOrWZData, tStartLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, iTeam)
    if tStartLZOrWZData then
        if not(tStartLZOrWZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) then tStartLZOrWZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits] = {} end
        if not(bUnitIsDead) then
            table.insert(tStartLZOrWZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits], oUnit)
        else
            AiBotConditions.IsTableOfUnitsStillValid(tStartLZOrWZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits], false)
        end
        AiBotAir.RecordOtherLandAndWaterZonesByDistance(tStartLZOrWZData)
        if AiBotUtilities.IsTableEmpty(tStartLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) == false then
            if oUnit[AiBotUnitInfo.refiCombatRange] then
                local iDistanceThreshold = oUnit[AiBotUnitInfo.refiCombatRange] + 80
                for iEntry, tSubtable in tStartLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
                    if tSubtable[AiBotMap.subrefiDistance] > iDistanceThreshold then break end
                    local tAltLZOrWZData
                    local tAltLZOrWZTeamData
                    local iCurPlateauOrPond
                    local iCurLZOrWZRef = tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]
                    if tSubtable[AiBotMap.subrefbIsWaterZone] then
                        tAltLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iCurLZOrWZRef]][AiBotMap.subrefPondWaterZones][iCurLZOrWZRef]
                        iCurPlateauOrPond = 0
                        tAltLZOrWZTeamData = tAltLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                    else
                        iCurPlateauOrPond = tSubtable[AiBotMap.subrefiPlateauOrPond]
                        tAltLZOrWZData = AiBotMap.tAllPlateaus[iCurPlateauOrPond][AiBotMap.subrefPlateauLandZones][iCurLZOrWZRef]
                        tAltLZOrWZTeamData = tAltLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                    end
                    if not(tAltLZOrWZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits]) then tAltLZOrWZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits] = {} end
                    if not(bUnitIsDead) then
                        table.insert(tAltLZOrWZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits], oUnit)
                        if bDebugMessages == true then LOG(sFunctionRef..': Adding arti as a unit against iPlateau'..iCurPlateauOrPond..'; iCurLZOrWZRef='..iCurLZOrWZRef) end
                    else
                        AiBotConditions.IsTableOfUnitsStillValid(tAltLZOrWZTeamData[AiBotMap.subreftoAllNearbyEnemyT2ArtiUnits], false)
                    end
                end
            elseif AiBotMap.bMapLandSetupComplete and AiBotMap.bFirstAiBotTeamHasBeenInitialised and GetGameTimeSeconds() >= 5 then
                AiBotUtilities.ErrorHandler('Dont have recorded range for T2 arti despite teams being setup now')
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iTeam='..iTeam..'; Time='..GetGameTimeSeconds()..'; Is tTeamData[iTeam][reftoEnemyT2Arti] empty='..AiBotUtilities.IsTableEmpty(tTeamData[iTeam][reftoEnemyT2Arti])) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function RecordNearbyEnemyLandFactory(oUnit, iTeam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RecordNearbyEnemyLandFactory'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iPlateau, iZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iPlateau='..(iPlateau or 'nil')..'; iZone='..(iZone or 'nil')) end
    if (iPlateau or 0) > 0 and (iZone or 0) > 0 then
        local tLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iZone]
        local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][iTeam]
        --Update adjacent zones to record this as being nearby
        --How close is this to our base, and is it on the same plateau?
        if bDebugMessages == true then LOG(sFunctionRef..': tLZTeamData[AiBotMap.refiModDistancePercent]='..tLZTeamData[AiBotMap.refiModDistancePercent]..'; Dist to closest friendly base='..AiBotUtilities.GetDistanceBetweenPositions(tLZTeamData[AiBotMap.reftClosestFriendlyBase], tLZData[AiBotMap.subrefMidpoint])) end
        if tLZTeamData[AiBotMap.refiModDistancePercent] <= 0.4 and AiBotUtilities.GetDistanceBetweenPositions(tLZTeamData[AiBotMap.reftClosestFriendlyBase], tLZData[AiBotMap.subrefMidpoint]) <= 275 then
            if not(tLZTeamData[AiBotMap.subrefoNearbyEnemyLandFacs]) then tLZTeamData[AiBotMap.subrefoNearbyEnemyLandFacs] = {} end
            table.insert(tLZTeamData[AiBotMap.subrefoNearbyEnemyLandFacs], oUnit)
            if bDebugMessages == true then LOG(sFunctionRef..': Is table of adj land zones empty='..tostring(AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]))) end
            if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                local tbZonesConsidered = {}
                tbZonesConsidered[iZone] = true
                for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                    if not(tbZonesConsidered[iAdjLZ]) then
                        tbZonesConsidered[iAdjLZ] = true
                        local tAdjLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ]
                        local tAdjLZTeamData = tAdjLZData[AiBotMap.subrefLZTeamData][iTeam]
                        if not(tAdjLZTeamData[AiBotMap.subrefoNearbyEnemyLandFacs]) then tAdjLZTeamData[AiBotMap.subrefoNearbyEnemyLandFacs] = {} end
                        table.insert(tAdjLZTeamData[AiBotMap.subrefoNearbyEnemyLandFacs], oUnit)
                        if AiBotUtilities.IsTableEmpty(tAdjLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                            for _, iSecondAdjLZ in tAdjLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                if not(tbZonesConsidered[iSecondAdjLZ]) then
                                    tbZonesConsidered[iSecondAdjLZ] = true
                                    local tSecondAdjLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iSecondAdjLZ]
                                    local tSecondAdjLZTeamData = tSecondAdjLZData[AiBotMap.subrefLZTeamData][iTeam]
                                    if not(tSecondAdjLZTeamData[AiBotMap.subrefoNearbyEnemyLandFacs]) then tSecondAdjLZTeamData[AiBotMap.subrefoNearbyEnemyLandFacs] = {} end
                                    table.insert(tSecondAdjLZTeamData[AiBotMap.subrefoNearbyEnemyLandFacs], oUnit)
                                end
                            end
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Finished recording factory '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' against nearby zones, tbZonesConsidered='..repru(tbZonesConsidered)..'; iPlateau='..iPlateau..'; Time='..GetGameTimeSeconds()) end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end


--TO HELP WITH LOCATING - use AssignUnitToLandZoneOrPond instead
function RecordUnitInPlateauLandZoneOrPond()  end
---@param aiBrain userdata
---@param oUnit userdata
function AssignUnitToLandZoneOrPond(aiBrain, oUnit, bAlreadyUpdatedPosition, bAlreadyTriedReassignment, bIgnoreIfAssignedAlready)
    --Assigns oUnit to relevant table for aiBrain; Should be called if we have a unit that hasn't been considered before (check by referencing oUnit[reftbConsideredForAssignmentByTeam][iTeam]) - will decide whether the unit should be assigned to a pond, a land zone, or air units, based partially on the unit category and partially on its current position
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'AssignUnitToLandZoneOrPond'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    if AiBotUnitInfo.IsUnitValid(oUnit) then
        --Campaign specific - dont include units flagged as not being killable
        if not(oUnit.CanBeKilled == false) or not(oUnit.CanTakeDamage == false) or not(EntityCategoryContains(categories.CIVILIAN * categories.STRUCTURE, oUnit.UnitId) or not(AiBotMap.bIsCampaignMap)) then

            local bPreviouslyConsidered = (oUnit[AiBotUnitInfo.reftbConsideredForAssignmentByTeam][aiBrain.AiBotTeam] or false)
            local bIgnore = false
            if bDebugMessages == true then LOG(sFunctionRef..': Considering unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' owned by brain '..oUnit:GetAIBrain().Nickname..' - are considering the unit from aiBrain perspective of '..aiBrain.Nickname..' at time '..GetGameTimeSeconds()..'; Have we already considered this unit='..tostring(oUnit[AiBotUnitInfo.reftbConsideredForAssignmentByTeam][aiBrain.AiBotTeam] or false)..'; bIgnoreIfAssignedAlready='..tostring(bIgnoreIfAssignedAlready or false)..'; Is enemy='..tostring(IsEnemy(aiBrain:GetArmyIndex(), oUnit:GetAIBrain():GetArmyIndex()))) end
            if not(oUnit[AiBotUnitInfo.reftbConsideredForAssignmentByTeam]) then oUnit[AiBotUnitInfo.reftbConsideredForAssignmentByTeam] = {} end
            if bIgnoreIfAssignedAlready and oUnit[AiBotUnitInfo.reftbConsideredForAssignmentByTeam][aiBrain.AiBotTeam] then
                --Do nothing
            else
                if not(oUnit[AiBotUnitInfo.reftbConsideredForAssignmentByTeam][aiBrain.AiBotTeam]) then
                    oUnit[AiBotUnitInfo.reftbConsideredForAssignmentByTeam][aiBrain.AiBotTeam] = true

                    --First time considering the unit for this team
                    --Campaign specific - dont record jamming crystals as units without an aoe cant damage them, leading to strange results - e.g. gunships can end up stuck trying to kill them
                    --Also record any units that we arent recording (due to not being an enemy or an ally) in a separate table
                    if oUnit.UnitId == 'xsc9002' and AiBotMap.bIsCampaignMap then
                        if bDebugMessages == true then LOG(sFunctionRef..': Seraphim jamming crystal - want to ignore since it cant be hit by non aoe gunships') end
                        bIgnore = true
                    else

                        --Enemy based logic (first time considering)
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to apply enemy based logic to the unit for the first time it is recognised, IsEnemy='..tostring(IsEnemy(aiBrain:GetArmyIndex(), oUnit:GetAIBrain():GetArmyIndex()))) end
                        if IsEnemy(aiBrain:GetArmyIndex(), oUnit:GetAIBrain():GetArmyIndex()) then
                            if EntityCategoryContains(AiBotUnitInfo.refCategorySniperBot, oUnit.UnitId) and (oUnit[AiBotUnitInfo.refiDFRange] or 0) >= 40 then --e.g. hoplite has 37 range
                                if bDebugMessages == true then LOG(sFunctionRef..': Enemy sniper bot detected, dangerous for ACU') end
                                --Exception if this is only the first sniperbot and we have multiple friendly ACUs
                                if not(tTeamData[aiBrain.AiBotTeam][refbDangerousForACUs]) then
                                    local iUnitTechLevel = AiBotUnitInfo.GetUnitTechLevel(oUnit)
                                    if iUnitTechLevel <= 2 and AiBotUnitInfo.GetUnitLifetimeCount(oUnit) <= 4 then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Enemy doesnt have many sniperbots and theyre T2 or lower, so wont set flag yet') end
                                    elseif not(tTeamData[aiBrain.AiBotTeam][refbAssassinationOrSimilar]) and AiBotUnitInfo.GetUnitLifetimeCount(oUnit) <= math.min(8, 1 + (tTeamData[aiBrain.AiBotTeam][subrefiActiveAiBotBrainCount] - 1) * 1.5) and not(tTeamData[aiBrain.AiBotTeam][refbAssassinationOrSimilar]) and not(EntityCategoryContains(AiBotUnitInfo.refCategoryExperimentalLevel, oUnit.UnitId)) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': enemy only has 1 sniperbot, since we have multiple ACUs will risk staying out a little bit longer') end
                                    else
                                        tTeamData[aiBrain.AiBotTeam][refbDangerousForACUs] = true
                                        if bDebugMessages == true then LOG(sFunctionRef..': Sniperbot causing refbDangerousForACUs flag to true, sniperbot='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Owner='..oUnit:GetAIBrain().Nickname) end
                                    end
                                end
                            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryTransport - categories.TECH1, oUnit.UnitId) then
                                local iTeam = aiBrain.AiBotTeam
                                tTeamData[iTeam][refbEnemyHasT2PlusTransport] = true
                            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryAllAir * categories.TECH3, oUnit.UnitId) then
                                local iTeam = aiBrain.AiBotTeam
                                if not(tTeamData[iTeam][refbDangerousForACUs]) and (not(AiBotMap.bIsCampaignMap) or tTeamData[aiBrain.AiBotTeam][subrefiHighestFriendlyFactoryTech] >= 3) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Enemy T3 air detected, enemy unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..', owned by '..oUnit:GetAIBrain().Nickname..' dangerous for ACU') end
                                    --Dont set flag to true if we have 2+ ACUs, are in full share, and either it isn't a gunship, or not a large air to ground threat
                                    if tTeamData[iTeam][subrefiActiveAiBotBrainCount] >= 2 and not(tTeamData[iTeam][refbAssassinationOrSimilar]) and (not(EntityCategoryContains(AiBotUnitInfo.refCategoryGunship + AiBotUnitInfo.refCategoryBomber, oUnit.UnitId)) or tTeamData[iTeam][refiEnemyAirToGroundThreat] <= 4000) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Wont flag that it is dangerous for ACUs yet just because enemy has t3 air fac') end
                                    else
                                        if bDebugMessages == true then LOG(sFunctionRef..': enemy T3 air to ground unit so no longer safe for ACUs, setting refbDangerousForACUs to true') end
                                        tTeamData[iTeam][refbDangerousForACUs] = true
                                    end
                                end
                                --If we lack T3 air and LC of unit is 1 then set flag so we get more AA asap
                                if AiBotUnitInfo.GetUnitLifetimeCount(oUnit) == 1 and (tTeamData[iTeam][subrefiHighestFriendlyAirFactoryTech] < 3 or tTeamData[iTeam][subrefiOurAirAAThreat] < 2500) and not(tTeamData[iTeam][refbEnemyEarlyT3AirSpottedRecently]) and AiBotConditions.GetCurrentAiBotUnitsOfCategoryInTeam(AiBotUnitInfo.refCategoryAirAA * categories.TECH3, iTeam) == 0 then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Flagging enemy T3 air danger for team at time='..GetGameTimeSeconds()) end
                                    tTeamData[iTeam][refbEnemyEarlyT3AirSpottedRecently] = true
                                    AiBotUtilities.DelayChangeVariable(tTeamData[iTeam], refbEnemyEarlyT3AirSpottedRecently, false, 150)
                                end
                            elseif EntityCategoryContains(categories.COMMAND, oUnit.UnitId) then
                                --check not already in table of enemy aCUs and add to this table
                                local bInTableAlready = false
                                local iTeam = aiBrain.AiBotTeam
                                if AiBotUtilities.IsTableEmpty(tTeamData[iTeam][reftEnemyACUs]) == false then
                                    for iACU, oACU in tTeamData[iTeam][reftEnemyACUs] do
                                        if oACU == oUnit then bInTableAlready = true break end
                                    end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': Dealing with an ACU, is table of enemy ACUs empty='..tostring(AiBotUtilities.IsTableEmpty(tTeamData[iTeam][reftEnemyACUs]))..'; bInTableAlready='..tostring(bInTableAlready)) end
                                if not(bInTableAlready) then
                                    if not(tTeamData[iTeam][reftEnemyACUs]) then tTeamData[iTeam][reftEnemyACUs] = {} end
                                    table.insert(tTeamData[iTeam][reftEnemyACUs], oUnit)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Added unit to table of enemy ACUs for team '..iTeam) end
                                end
                            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryMissileShip, oUnit.UnitId) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Have enemy missile ship '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; will record as mobile TML threat') end
                                ForkThread(RecordMobileTMLThreatForAllEnemyTeams, oUnit)

                            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryMML, oUnit.UnitId) then
                                --Experiment with recording MMLs of all types with a LC of <=10 (not more for performance reasons)
                                if AiBotUnitInfo.GetUnitLifetimeCount(oUnit) <= 10 then
                                    ForkThread(RecordMobileTMLThreatForAllEnemyTeams, oUnit)
                                end
                            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryMAA * categories.TECH3, oUnit.UnitId) then
                                tTeamData[aiBrain.AiBotTeam][iEnemyT3MAAActiveCount] = (tTeamData[aiBrain.AiBotTeam][iEnemyT3MAAActiveCount] or 0) + 1
                            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory, oUnit.UnitId) then
                                if bDebugMessages == true then LOG(sFunctionRef..': About to record enemy land factory against nearby zones depending on if it is close to a friendly base') end
                                RecordNearbyEnemyLandFactory(oUnit, aiBrain.AiBotTeam)
                            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryBomber * categories.TECH1, oUnit.UnitId) then
                                --UEF and Cybran bombers - activate special tracking if low lifetime count (will also do aeon and seraphim since if engineer is stationery e.g. building something it cant reliably dodge them either)
                                if AiBotUnitInfo.GetUnitLifetimeCount(oUnit) <= 4 then --and EntityCategoryContains(categories.UEF + categories.CYBRAN, oUnit.UnitId) then
                                    ForkThread(AiBotAir.EnemyT1BomberTracker, oUnit, aiBrain.AiBotTeam)
                                end
                            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryMassFab + AiBotUnitInfo.refCategoryRASSACU, oUnit.UnitId) then
                                tTeamData[aiBrain.AiBotTeam][subrefbEnemyGettingFabsOrRAS] = true
                            elseif EntityCategoryContains(AiBotUnitInfo.refCategorySatellite, oUnit.UnitId) then
                                ForkThread(EnemyNovaxSatelliteMonitor, oUnit, aiBrain.AiBotTeam)
                                --Track the first naval fac enemy tries building in a pond so can consider bombers to harass engineers at it
                            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryNavalFactory * categories.TECH1, oUnit.UnitId) then
                                ForkThread(AiBotAir.MonitorNavalFacForBomberTarget, oUnit, aiBrain)
                            end

                            --If enemy hasnt built omni yet check whether this is omni
                            if not(tTeamData[aiBrain.AiBotTeam][subrefbEnemyBuiltOmni]) and EntityCategoryContains(AiBotUnitInfo.refCategoryT3Radar, oUnit.UnitId) and not(oUnit:GetAIBrain().AiBotTeam == aiBrain.AiBotTeam) then
                                tTeamData[aiBrain.AiBotTeam][subrefbEnemyBuiltOmni] = true
                            end


                            --Track enemy big threats
                            if bDebugMessages == true then LOG(sFunctionRef..': Is unit a big threat category='..tostring(EntityCategoryContains(AiBotUnitInfo.refCategoryBigThreatCategories, oUnit.UnitId))..'; Unit DF range='..(oUnit[AiBotUnitInfo.refiDFRange] or 'nil')..'; Unit indirect range='..(oUnit[AiBotUnitInfo.refiIndirectRange] or 'nil')..'; Is unit PD or land combat='..tostring(EntityCategoryContains(AiBotUnitInfo.refCategoryLandCombat + AiBotUnitInfo.refCategoryPD, oUnit.UnitId))..'; Unit build cost mass='..(oUnit[AiBotUnitInfo.refiUnitMassCost] or 'nil')) end
                            if EntityCategoryContains(AiBotUnitInfo.refCategoryBigThreatCategories, oUnit.UnitId) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Will try and add unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to big threat table, aiBrain='..(aiBrain.Nickname or 'nil')..' team='..(aiBrain.AiBotTeam or 'nil')) end
                                AddUnitToBigThreatTable(aiBrain.AiBotTeam, oUnit)
                                --If htis is an experimental level unit and we have human teammates then monitor to send a chat message

                                --Record if we are at the stage of the game where experimentals/similar high threats for ACU are present
                                if EntityCategoryContains(AiBotUnitInfo.refCategoryExperimentalLevel, oUnit.UnitId) then
                                    if not(tTeamData[aiBrain.AiBotTeam][refbDangerousForACUs]) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Enemy experimental level unit detected, dangerous for ACU, refbDangerousForACUs is now true') end
                                        tTeamData[aiBrain.AiBotTeam][refbDangerousForACUs] = true
                                    end
                                    if not(EntityCategoryContains(AiBotUnitInfo.refCategorySatellite + categories.INSIGNIFICANTUNIT + AiBotUnitInfo.refCategoryBattleship * categories.TECH3 * categories.SILO, oUnit.UnitId)) then
                                        ForkThread(AiBotChat.SendTextMarkerWarningWhenHaveVisualOnEnemy, aiBrain, oUnit)
                                    end
                                end
                            elseif AiBotConditions.IsUnitLongRangeThreat(oUnit) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Recording in LR threat table, unit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; DF range='..(oUnit[AiBotUnitInfo.refiDFRange] or 'nil')..'; IDF range='..(oUnit[AiBotUnitInfo.refiIndirectRange] or 'nil')..'; Primarily IF='..tostring(((oUnit[AiBotUnitInfo.refiDFRange] or 0) < 30 and (oUnit[AiBotUnitInfo.refiIndirectRange] or 0) > 30))) end
                                AddUnitToLongRangeThreatTable(oUnit, aiBrain.AiBotTeam, true, ((oUnit[AiBotUnitInfo.refiDFRange] or 0) < 30 and (oUnit[AiBotUnitInfo.refiIndirectRange] or 0) > 30))
                            end

                            --Add long range enemy T2 arti
                            if oUnit[AiBotUnitInfo.refiCombatRange] > 100 and EntityCategoryContains(AiBotUnitInfo.refCategoryFixedT2Arti, oUnit.UnitId) then
                                RecordEnemyT2ArtiAgainstNearbyZones(aiBrain.AiBotTeam, oUnit)
                            end

                            --Track potential TML targets and TMD for decision on whether to build TML (TML target selection uses more precise approach
                            if EntityCategoryContains(AiBotUnitInfo.refCategoryTMD * categories.STRUCTURE, oUnit.UnitId) then
                                local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
                                if iPlateauOrZero > 0 and iLandOrWaterZone > 0 then
                                    local tLZTeamData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone][AiBotMap.subrefLZTeamData][aiBrain.AiBotTeam]
                                    table.insert(tLZTeamData[AiBotMap.subreftoEnemyTMD], oUnit)
                                end
                            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryProtectFromTML * categories.STRUCTURE, oUnit.UnitId) then
                                local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
                                if iPlateauOrZero > 0 and iLandOrWaterZone > 0 then
                                    local tLZTeamData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone][AiBotMap.subrefLZTeamData][aiBrain.AiBotTeam]
                                    if not(tLZTeamData[AiBotMap.subreftoEnemyPotentialTMLTargets]) then tLZTeamData[AiBotMap.subreftoEnemyPotentialTMLTargets] = {} end
                                    table.insert(tLZTeamData[AiBotMap.subreftoEnemyPotentialTMLTargets], oUnit)
                                    AiBotBuilding.RecordTMLAndTMDForEnemyUnitTargetJustDetected(oUnit, aiBrain.AiBotTeam)
                                end
                            end

                            --Cloaked units
                            if EntityCategoryContains(categories.COMMAND + categories.SUBCOMMANDER, oUnit.UnitId) then
                                if oUnit:HasEnhancement('CloakingGenerator') then
                                    AiBotEvents.CloakedUnitIdentified(oUnit)
                                else
                                    local oBP = oUnit:GetBlueprint()
                                    if oBP.Enhancements and oBP.EnhancementPresetAssigned.Enhancements then
                                        for iCurUpgrade, sCurUpgrade in oBP.EnhancementPresetAssigned.Enhancements do
                                            if sCurUpgrade == 'CloakingGenerator' then
                                                AiBotEvents.CloakedUnitIdentified(oUnit)
                                                break
                                            end
                                        end
                                    end
                                end
                            end

                            --best enemy df range
                            local iPlateau = NavUtils.GetLabel(AiBotMap.refPathingTypeHover, oUnit:GetPosition())
                            if iPlateau then
                                local iTeam = aiBrain.AiBotTeam
                                if not(tTeamData[iTeam][refiHighestEnemyDFRangeByPlateau]) then tTeamData[iTeam][refiHighestEnemyDFRangeByPlateau] = {} end
                                tTeamData[iTeam][refiHighestEnemyDFRangeByPlateau][iPlateau] = math.max((tTeamData[iTeam][refiHighestEnemyDFRangeByPlateau][iPlateau] or 0), (oUnit[AiBotUnitInfo.refiDFRange] or 0))
                            end

                            --Hostile civilain units
                            if AiBotConditions.IsCivilianBrain(oUnit:GetAIBrain()) then
                                ForkThread(ConsiderHostileCivilianZoneFlagForDetectedUnit, oUnit, aiBrain.AiBotTeam)
                            end

                        else
                            --General - big threats (experimental) - include if dont have spare ACUs
                            --Record if we are at the stage of the game where experimentals/similar high threats for ACU are present
                            if not(tTeamData[aiBrain.AiBotTeam][refbDangerousForACUs])  then
                                if EntityCategoryContains(AiBotUnitInfo.refCategoryExperimentalLevel, oUnit.UnitId) then
                                    if not(tTeamData[aiBrain.AiBotTeam][refbAssassinationOrSimilar]) and tTeamData[aiBrain.AiBotTeam][subrefiActiveAiBotBrainCount] >= 3 and tTeamData[aiBrain.AiBotTeam][refiConstructedExperimentalCount] == 0 then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Exp level but we are in full share and we havent constructed any yet so will delay ACU retreat') end
                                    else
                                        if bDebugMessages == true then LOG(sFunctionRef..': Enemy experimental level unit detected, setting refbDangerousForACUs for ACU') end
                                        tTeamData[aiBrain.AiBotTeam][refbDangerousForACUs] = true
                                    end
                                end
                            end
                            --Campaign neutral units
                            --Allied unit - dont record if it isnt owned by AiBotAI brain (so we dont control allied non-AiBot units) or is owned by a different team
                            if not(oUnit:GetAIBrain().AiBotAI) or not(oUnit:GetAIBrain().AiBotTeam == aiBrain.AiBotTeam) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Unit belongs to a non-AiBot ally or non-hostile brain so wont record, with some exceptions; iTeam='..(aiBrain.AiBotTeam or 'nil')) end
                                bIgnore = true
                                if AiBotMap.bIsCampaignMap then
                                    local bAddToNeutralTable = true
                                    if AiBotUtilities.IsTableEmpty(tTeamData[aiBrain.AiBotTeam][reftoCampaignNeutralUnitsNotRecorded]) == false then
                                        for iRecorded, oRecorded in tTeamData[aiBrain.AiBotTeam][reftoCampaignNeutralUnitsNotRecorded] do
                                            if oRecorded == oUnit then
                                                bAddToNeutralTable = false
                                                break
                                            end
                                        end
                                    end
                                    if bAddToNeutralTable then
                                        table.insert(tTeamData[aiBrain.AiBotTeam][reftoCampaignNeutralUnitsNotRecorded], oUnit)
                                    end
                                end
                                --Track non-AiBot teammate units
                                if EntityCategoryContains(AiBotUnitInfo.refCategoryFactory + AiBotUnitInfo.refCategoryMex, oUnit.UnitId) then
                                    local tLZOrWZData, tLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, aiBrain.AiBotTeam)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Is tLZOrWZTeamData nil='..tostring(tLZOrWZTeamData == nil)..'; refiNonAiBotTeammateMexCount='..(tLZOrWZTeamData[AiBotMap.refiNonAiBotTeammateMexCount] or 'nil')) end
                                    if tLZOrWZTeamData then
                                        if not(oUnit[AiBotUnitInfo.reftiTeamsRecordedAsNonAiBotAlly]) then oUnit[AiBotUnitInfo.reftiTeamsRecordedAsNonAiBotAlly] = {} end
                                        table.insert(oUnit[AiBotUnitInfo.reftiTeamsRecordedAsNonAiBotAlly], aiBrain.AiBotTeam)
                                        if EntityCategoryContains(AiBotUnitInfo.refCategoryFactory, oUnit.UnitId) then
                                            tLZOrWZTeamData[AiBotMap.refiNonAiBotTeammateFactoryCount] = (tLZOrWZTeamData[AiBotMap.refiNonAiBotTeammateFactoryCount] or 0) + 1
                                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryMex, oUnit.UnitId) then
                                            tLZOrWZTeamData[AiBotMap.refiNonAiBotTeammateMexCount] = (tLZOrWZTeamData[AiBotMap.refiNonAiBotTeammateMexCount] or 0) + 1

                                            if bDebugMessages == true then
                                                local iPlateau, iZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
                                                LOG(sFunctionRef..': Recorded teammate as having a mex in this LZ, tLZTeamData[AiBotMap.refiNonAiBotTeammateMexCount] after update='..tLZOrWZTeamData[AiBotMap.refiNonAiBotTeammateMexCount]..'; iPlateau='..iPlateau..'; iZone='..iZone)
                                            end
                                        end
                                    end
                                elseif EntityCategoryContains(AiBotUnitInfo.refCategoryPD, oUnit.UnitId) then
                                    local tLZOrWZData, tLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, aiBrain.AiBotTeam)
                                    if not(tLZOrWZTeamData[AiBotMap.subreftoTeammateFixedDF]) then tLZOrWZTeamData[AiBotMap.subreftoTeammateFixedDF] = {} end
                                    table.insert(tLZOrWZTeamData[AiBotMap.subreftoTeammateFixedDF], oUnit)
                                elseif EntityCategoryContains(AiBotUnitInfo.refCategoryStructureAA, oUnit.UnitId) then
                                    local tLZOrWZData, tLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, aiBrain.AiBotTeam)
                                    if not(tLZOrWZTeamData[AiBotMap.subreftoTeammateFixedAA]) then tLZOrWZTeamData[AiBotMap.subreftoTeammateFixedAA] = {} end
                                    table.insert(tLZOrWZTeamData[AiBotMap.subreftoTeammateFixedAA], oUnit)
                                elseif EntityCategoryContains(AiBotUnitInfo.refCategoryExperimentalLevel + categories.TECH3 * AiBotUnitInfo.refCategoryNavalSurface, oUnit.UnitId) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will record experimental level or T3 navy unit if it isnt compelte yet, Fraction complete='..oUnit:GetFractionComplete()) end
                                    if oUnit:GetFractionComplete() < 1 then
                                        local bAlreadyRecorded = false
                                        local iTeam = aiBrain.AiBotTeam
                                        if AiBotUtilities.IsTableEmpty(tTeamData[iTeam][reftoNonAiBotConstructingExpAndT3Navy]) == false then
                                        elseif not(tTeamData[iTeam][reftoNonAiBotConstructingExpAndT3Navy]) then tTeamData[iTeam][reftoNonAiBotConstructingExpAndT3Navy] = {}
                                        end
                                        if not(bAlreadyRecorded) then
                                            table.insert(tTeamData[iTeam][reftoNonAiBotConstructingExpAndT3Navy], oUnit)
                                            oUnit[AiBotUnitInfo.refbNonAiBotExpConstruction] = true
                                        end
                                    end
                                end


                            else
                                --AiBotAlly only:
                                if oUnit:GetAIBrain().AiBotTeam == aiBrain.AiBotTeam and aiBrain.AiBotAI then
                                    if EntityCategoryContains(AiBotUnitInfo.refCategoryLandExperimental, oUnit.UnitId) then
                                        if not(tTeamData[aiBrain.AiBotTeam][reftoFriendlyLandExperimentals]) then tTeamData[aiBrain.AiBotTeam][reftoFriendlyLandExperimentals] = {} end
                                        if bDebugMessages == true then LOG(sFunctionRef..': Adding unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to table of friendly land experimentals') end
                                        table.insert(tTeamData[aiBrain.AiBotTeam][reftoFriendlyLandExperimentals], oUnit)
                                    end
                                end

                                --AiBot (non-ally) specific

                                --Air staging - clear any engineers in other zones constructing them if we dont ahve T3 air
                                if EntityCategoryContains(AiBotUnitInfo.refCategoryAirStaging, oUnit.UnitId) and tTeamData[oUnit:GetAIBrain().AiBotTeam][subrefiHighestFriendlyAirFactoryTech] < 3 then
                                    local iTeam = oUnit:GetAIBrain().AiBotTeam
                                    if bDebugMessages == true then LOG(sFunctionRef..': Building air staging, and dont ahve T3 air, brain count='..tTeamData[iTeam][subrefiActiveAiBotBrainCount]..'; iTeam='..iTeam) end
                                    if tTeamData[iTeam][subrefiActiveAiBotBrainCount] > 1 then
                                        local tLZData, tLZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, iTeam)
                                        for iBrain, oBrain in tTeamData[iTeam][subreftoFriendlyActiveAiBotBrains] do
                                            local tStartLZData, tStartLZTeamData = AiBotMap.GetLandOrWaterZoneData(AiBotMap.GetPlayerStartPosition(oBrain), true, iTeam)
                                            if not(tStartLZTeamData == tLZTeamData) then
                                                if AiBotUtilities.IsTableEmpty(tStartLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                                                    local bHaveAirStagingUnderConstruction = false
                                                    local tAirStaging = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryAirStaging, tStartLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                                                    if AiBotUtilities.IsTableEmpty(tAirStaging) == false then
                                                        for iAirStaging, oAirStaging in tAirStaging do
                                                            if AiBotUnitInfo.IsUnitValid(oAirStaging) and oAirStaging:GetFractionComplete() < 1 then
                                                                bHaveAirStagingUnderConstruction = true
                                                                break
                                                            end
                                                        end
                                                    end
                                                    if bDebugMessages == true then LOG(sFunctionRef..': oBrain='..oBrain.Nickname..'; bHaveAirStagingUnderConstruction='..tostring(bHaveAirStagingUnderConstruction)) end
                                                    if not(bHaveAirStagingUnderConstruction) then
                                                        local tEngineers = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer, tStartLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Is table of units of cateogyr empty for brain '..oBrain.Nickname..'='..tostring(AiBotUtilities.IsTableEmpty(tEngineers))..'; oUnit fraction complete='..oUnit:GetFractionComplete()) end
                                                        if AiBotUtilities.IsTableEmpty(tEngineers) == false then
                                                            local toEngineersToClear = {}
                                                            for iEngineer, oEngineer in tEngineers do
                                                                if bDebugMessages == true then LOG(sFunctionRef..': Considering engineer '..oEngineer.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngineer)..'; Engineer action='..(oEngineer[AiBotEngineer.refiAssignedAction] or 'nil')..'; Engineer state='..AiBotUnitInfo.GetUnitState(oEngineer)) end
                                                                if AiBotUnitInfo.IsUnitValid(oEngineer) and oEngineer[AiBotEngineer.refiAssignedAction] == AiBotEngineer.refActionBuildAirStaging then
                                                                    if not(oEngineer:IsUnitState('Building')) and not(oEngineer:IsUnitState('Repairing')) then
                                                                        table.insert(toEngineersToClear, oEngineer)
                                                                    else
                                                                        local oFocus = oEngineer:GetFocusUnit()
                                                                        if bDebugMessages == true then LOG(sFunctionRef..': Focus unit is '..(oFocus.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oFocus) or 'nil')) end
                                                                        if bDebugMessages == true and oFocus then LOG(sFunctionRef..': oFocus fraction complete='..oFocus:GetFractionComplete()) end
                                                                        if not(AiBotUnitInfo.IsUnitValid(oFocus)) or oFocus:GetFractionComplete() == 0 then
                                                                            table.insert(toEngineersToClear, oEngineer)
                                                                        end

                                                                    end
                                                                end
                                                            end
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Is table of engineers to clear empty='..tostring(AiBotUtilities.IsTableEmpty(toEngineersToClear))) end
                                                            if AiBotUtilities.IsTableEmpty(toEngineersToClear) == false then
                                                                for iEngineer, oEngineer in toEngineersToClear do
                                                                    AiBotOrders.IssueTrackedClearCommands(oEngineer)
                                                                end
                                                            end
                                                        end
                                                    end
                                                end
                                            end
                                        end
                                    end
                                end

                                --Selen assignment logic
                                if EntityCategoryContains(AiBotUnitInfo.refCategoryCombatScout, oUnit.UnitId) then
                                    ForkThread(AiBotLand.ConsiderAssigningScoutToLurkerLogic, oUnit)
                                end
                            end
                            --Update intel coverage for units being constructed and/or allied units (in addition when a radar/sonar is constructed it will also trigger the below if it hasnt already run as a redundancy)
                            if EntityCategoryContains(AiBotUnitInfo.refCategoryRadar, oUnit.UnitId) then AiBotLand.UpdateZoneIntelForRadar(oUnit)
                            elseif EntityCategoryContains(AiBotUnitInfo.refCategorySonar, oUnit.UnitId) then AiBotNavy.UpdateZoneIntelForSonar(oUnit)
                            end
                        end
                    end
                elseif bDebugMessages == true then
                    LOG(sFunctionRef..': Unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' has already been considered (considered='..tostring(oUnit[AiBotUnitInfo.reftbConsideredForAssignmentByTeam][aiBrain.AiBotTeam] or false)..')')
                end


                if bIgnore or EntityCategoryContains(AiBotUnitInfo.refCategoryWall + categories.UNSELECTABLE + categories.UNTARGETABLE + categories.BENIGN, oUnit.UnitId) then
                    --Do nothing
                    if bDebugMessages == true then LOG(sFunctionRef..': Unit is insignificant so will ignore, Unit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Is civilian brain='..tostring(AiBotConditions.IsCivilianBrain(oUnit:GetAIBrain()))..'; Build cost mass='..(oUnit[AiBotUnitInfo.refiUnitMassCost] or 'nil')) end
                    --Civilian units hopefully show up here - consider adding to table of units to reclaim; owever dont reclaim if can build from a factory as we might want to capture it instead
                    if AiBotConditions.IsCivilianBrain(oUnit:GetAIBrain()) and EntityCategoryContains(categories.RECLAIMABLE + categories.SELECTABLE - categories.BUILTBYTIER3FACTORY, oUnit.UnitId) and (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)) >= 25 then
                        if not(AiBotMap.bIsCampaignMap) or (not(tTeamData[aiBrain.AiBotTeam][rebTeamOnlyHasCampaignAI]) and not(oUnit[AiBotUnitInfo.refbIsReclaimTarget] == false)) then
                            local tUnitLZData, tUnitLZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, aiBrain.AiBotTeam)
                            local bIncluded = false
                            if not(tUnitLZTeamData[AiBotMap.subreftoUnitsToReclaim]) then tUnitLZTeamData[AiBotMap.subreftoUnitsToReclaim] = {}
                            else
                                for iReclaimUnit, oReclaimUnit in tUnitLZTeamData[AiBotMap.subreftoUnitsToReclaim] do
                                    if oReclaimUnit == oUnit then bIncluded = true break end
                                end
                            end
                            --Check not recorded as a capture target
                            if oUnit[AiBotUnitInfo.refbIsCaptureTarget] then
                                bIncluded = true
                            elseif not(bIncluded) and AiBotConditions.IsTableOfUnitsStillValid(tUnitLZData[AiBotMap.subreftoUnitsToCapture]) then
                                for iCaptureUnit, oCaptureUnit in tUnitLZData[AiBotMap.subreftoUnitsToCapture] do
                                    if oCaptureUnit == oUnit then bIncluded = true break end
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': Want to include unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' in table of units to reclaim for team '..aiBrain.AiBotTeam) end
                            if not(bIncluded) then
                                --If this is mass storage then capture, if either underwater or low mod dist
                                if EntityCategoryContains(AiBotUnitInfo.refCategoryMassStorage, oUnit.UnitId) and (tUnitLZTeamData[AiBotMap.refiModDistancePercent] <= 0.4 or AiBotUnitInfo.IsUnitUnderwater(oUnit)) then
                                    local iUnitPlateau, iUnitZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
                                    AiBotOverseer.RecordUnitAsCaptureTarget(oUnit, iUnitPlateau, iUnitZone)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Recording in table of units to capture instead, P'..iUnitPlateau..'Z'..iUnitZone..'; Is unit underwater='..tostring(AiBotUnitInfo.IsUnitUnderwater(oUnit))..'; Position='..repru(oUnit:GetPosition())) end
                                else
                                    table.insert(tUnitLZTeamData[AiBotMap.subreftoUnitsToReclaim], oUnit)
                                    local bTeamRecorded = false
                                    if not(oUnit[AiBotUnitInfo.refiTeamsWithThisAsReclaimTarget]) then oUnit[AiBotUnitInfo.refiTeamsWithThisAsReclaimTarget] = {}
                                    else
                                        for iEntry, iRecordedTeam in oUnit[AiBotUnitInfo.refiTeamsWithThisAsReclaimTarget] do
                                            if iRecordedTeam == aiBrain.AiBotTeam then
                                                bTeamRecorded = true
                                                break
                                            end
                                        end
                                    end
                                    if not(bTeamRecorded) then
                                        table.insert(oUnit[AiBotUnitInfo.refiTeamsWithThisAsReclaimTarget], aiBrain.AiBotTeam)
                                    end
                                end

                            end
                        end
                    end
                else

                    if not(bAlreadyUpdatedPosition) then
                        UpdateUnitLastKnownPosition(aiBrain, oUnit, true)
                        if IsEnemy(aiBrain:GetArmyIndex(), oUnit:GetAIBrain():GetArmyIndex()) and aiBrain.AiBotAI then UpdateEnemyTechTracking(aiBrain.AiBotTeam, oUnit) end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': aiBrain '..aiBrain.Nickname..' is Considering how to assign unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' that is owned by brain '..oUnit:GetAIBrain().Nickname..' at time '..GetGameTimeSeconds()..'; bPreviouslyConsidered='..tostring(bPreviouslyConsidered or false)) end


                    --Air units - always assign to air groups, and also to land zones if in one
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryAllAir - AiBotUnitInfo.refCategoryEngineer, oUnit.UnitId) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Have a non-engineer air unit, will record as new air unit if not already considered, bPreviouslyConsidered='..tostring(bPreviouslyConsidered)) end
                        if not(bPreviouslyConsidered) then
                            AiBotAir.RecordNewAirUnitForTeam(aiBrain.AiBotTeam, oUnit)
                        end
                        if bAlreadyUpdatedPosition then
                            --Re-check the plateau and land/water zone
                            if bDebugMessages == true then LOG(sFunctionRef..': oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' owned by '..oUnit:GetAIBrain().Nickname) end
                            local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
                            local bIsEnemyAirUnit
                            if aiBrain.AiBotTeam == oUnit:GetAIBrain().AiBotTeam then bIsEnemyAirUnit = false else bIsEnemyAirUnit = true end
                            if  (iLandOrWaterZone or 0) > 0 then
                                if iPlateauOrZero == 0 then
                                    --Water zone
                                    AddUnitToWaterZoneForBrain(aiBrain, oUnit, iLandOrWaterZone, bIsEnemyAirUnit)
                                else
                                    AddUnitToLandZoneForBrain(aiBrain, oUnit, iPlateauOrZero, iLandOrWaterZone, bIsEnemyAirUnit)
                                end

                                --Presumably air unit has fallen out of a land zone - add to table of enemy air without a LZ
                            else
                                if bDebugMessages == true then LOG(sFunctionRef..': Failed to find a plateau or zone to position '..repru(oUnit:GetPosition())..' for unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)) end
                                if not(aiBrain.AiBotTeam == oUnit:GetAIBrain().AiBotTeam) then --redundancy, - hopefully shouldnt get to this point if this isnt the case
                                    AiBotUtilities.ErrorHandler('Obsolete code, wasnt expecting it to be used, unless fighting RNG and they have offmap units or torp bomber fighting at edge of map')
                                    AiBotAir.RecordEnemyAirUnitWithNoZone(aiBrain.AiBotTeam, oUnit)
                                end
                            end
                        end
                    else
                        if oUnit:IsUnitState('Attached') then
                            if bDebugMessages == true then LOG(sFunctionRef..': Unit state is attached so will try reassigning in a bit') end
                            --Try reassigning in a bit
                            ForkThread(DelayedUnitPlateauAssignment, aiBrain, oUnit, 5, bAlreadyUpdatedPosition, true)
                        else
                            --Amphibious, hover and naval surface units = check if in water before checking if in land
                            local iSegmentX, iSegmentZ = AiBotMap.GetPathingSegmentFromPosition(oUnit:GetPosition())
                            local iWaterZone = AiBotMap.tWaterZoneBySegment[iSegmentX][iSegmentZ]
                            if iWaterZone > 0 and EntityCategoryContains(AiBotUnitInfo.refCategoryAllAmphibiousAndNavy, oUnit.UnitId) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Will add unit to water zone') end
                                AddUnitToWaterZoneForBrain(aiBrain, oUnit, iWaterZone)
                            else
                                local iPlateau, iLandZone
                                if EntityCategoryContains(categories.LAND * categories.MOBILE, oUnit.UnitId) then
                                    iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnit:GetPosition(), true, oUnit)
                                else
                                    iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnit:GetPosition())
                                end
                                if bDebugMessages == true then
                                    LOG(sFunctionRef..': Unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' owned by brain '..oUnit:GetAIBrain().Nickname..' has iPlateau='..(iPlateau or 'nil')..'; iLandZone='..(iLandZone or 'nil')..'; Will draw unit position if it has no plateau or zone. Unit state='..AiBotUnitInfo.GetUnitState(oUnit)..'; iWaterZone='..(iWaterZone or 'nil'))
                                    if not(iPlateau) then
                                        AiBotUtilities.DrawLocation(oUnit:GetPosition())
                                    end
                                end
                                if (iLandZone or 0) > 0 then
                                    --Unit is in a land zone so assign it to a land zone instead of a pond
                                    if not(iPlateau) then
                                        local iAltLandZone
                                        iPlateau, iAltLandZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
                                        if (iAltLandZone or 0) > 0 then iLandZone = iAltLandZone end
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': Adding unit to iLandZone '..iLandZone..' for plateau '..iPlateau..' and team '..aiBrain.AiBotTeam) end
                                    AddUnitToLandZoneForBrain(aiBrain, oUnit, iPlateau, iLandZone)
                                elseif iPlateau > 0 then
                                    --Is the unit in a water zone (or a unit that can move in water and is on a beach/right by the water zone start)?
                                    if bDebugMessages == true then LOG(sFunctionRef..': iWaterZone='..(iWaterZone or 'nil')..'; Unit terrain height='..GetTerrainHeight(oUnit:GetPosition()[1], oUnit:GetPosition()[3])..'; iMapWaterHeight='..AiBotMap.iMapWaterHeight) end
                                    if not(iWaterZone) and EntityCategoryContains(AiBotUnitInfo.refCategoryAllAmphibiousAndNavy, oUnit.UnitId) and AiBotMap.iMapWaterHeight > GetTerrainHeight(oUnit:GetPosition()[1], oUnit:GetPosition()[3]) then
                                        local iPotentialPlateauOrZero, iPotentialLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
                                        if bDebugMessages == true then LOG(sFunctionRef..': Dont have valid WZ based on segments, so considering WZ based on position, iPotentialPlateauOrZero='..(iPotentialPlateauOrZero or 'nil')..'; iPotentialLandOrWaterZone='..(iPotentialLandOrWaterZone or 'nil')) end
                                        if iPotentialLandOrWaterZone then
                                            if iPotentialPlateauOrZero == 0 then
                                                iWaterZone = iPotentialLandOrWaterZone
                                            else
                                                --Based on the position we think it is a land zone, but it is in water - if we move 5 towards the land zone are we on land? if not, if we move 5 towards an adjacent water zone to that LZ, are we on water?
                                                local tPotentialLZData = AiBotMap.tAllPlateaus[iPotentialPlateauOrZero][AiBotMap.subrefPlateauLandZones][iPotentialLandOrWaterZone]
                                                local iAngleToLZ = AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), tPotentialLZData[AiBotMap.subrefMidpoint])
                                                local tMoveTowardsLZ = AiBotUtilities.MoveInDirection(oUnit:GetPosition(), iAngleToLZ, 5)
                                                local iMoveTowardsSegmentX, iMoveTowardsSegmentZ = AiBotMap.GetPathingSegmentFromPosition(tMoveTowardsLZ)
                                                if AiBotMap.tLandZoneBySegment[iMoveTowardsSegmentX][iMoveTowardsSegmentZ] == iPotentialLandOrWaterZone then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Will add the unit to the land zone it is right by, iPotentialPlateauOrZero='..iPotentialPlateauOrZero..'; iPotentialLandOrWaterZone='..iPotentialLandOrWaterZone) end
                                                    iLandZone = iPotentialLandOrWaterZone
                                                    AddUnitToLandZoneForBrain(aiBrain, oUnit, iPotentialPlateauOrZero, iPotentialLandOrWaterZone)
                                                else
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Will move to logic for retrying later') end
                                                end
                                            end
                                        end
                                    end
                                    if iWaterZone > 0 then
                                        AddUnitToWaterZoneForBrain(aiBrain, oUnit, iWaterZone)
                                    elseif iLandZone and iLandZone > 0 then
                                        --Presumably already added from above
                                    else
                                        --Does the unit already have orders, and is a non-naval unit? If so then wait and try to reassign it in a bit, as e.g. may be a land unit that can path across water so has taken a shortcut
                                        if bDebugMessages == true then LOG(sFunctionRef..': Unit doesnt have al and or water zone, is this a non amphibious or hover naval unit='..tostring(EntityCategoryContains(AiBotUnitInfo.refCategoryAllNavy - AiBotUnitInfo.refCategoryAmphibious - categories.HOVER, oUnit.UnitId))..'; Nav utils naval label for unit position='..(NavUtils.GetLabel(AiBotMap.refPathingTypeNavy, oUnit:GetPosition()) or 'nil')) end
                                        if EntityCategoryContains(AiBotUnitInfo.refCategoryAllNavy, oUnit.UnitId) and (EntityCategoryContains(AiBotUnitInfo.refCategoryAllNavy - AiBotUnitInfo.refCategoryAmphibious - categories.HOVER, oUnit.UnitId) or (NavUtils.GetLabel(AiBotMap.refPathingTypeNavy, oUnit:GetPosition()) or 0) > 0) then
                                            local iCurPond = NavUtils.GetLabel(AiBotMap.refPathingTypeNavy, oUnit:GetPosition())
                                            if bDebugMessages == true then LOG(sFunctionRef..': Unit pond at cur position='..(NavUtils.GetLabel(AiBotMap.refPathingTypeNavy, oUnit:GetPosition()) or 'nil')) end
                                            if (iCurPond or 0) > 0 then
                                                --Are in valid pond, find nearest valid water zone and add this segment to that water zone
                                                iWaterZone = nil --redundancy
                                                --To find nearby water zone - cycle through a hollow box
                                                --First to the top row and bottom row
                                                for iAdjustBase = 1, 10 do
                                                    for iCurSegmentX = iSegmentX - iAdjustBase, iSegmentX + iAdjustBase, 1 do
                                                        for iCurSegmentZ = iSegmentZ - iAdjustBase, iSegmentZ + iAdjustBase, iAdjustBase * 2 do
                                                            if iCurSegmentX >= 0 and iCurSegmentZ >= 0 then
                                                                if AiBotMap.tWaterZoneBySegment[iCurSegmentX][iCurSegmentZ] then iWaterZone = AiBotMap.tWaterZoneBySegment[iCurSegmentX][iCurSegmentZ] break end
                                                            end
                                                        end
                                                        if iWaterZone then break end
                                                    end
                                                    if iWaterZone then break end
                                                    --Then do the left and right row (excl corners which ahve already done per the above)
                                                    for iCurSegmentX = iSegmentX - iAdjustBase, iSegmentX + iAdjustBase, iAdjustBase * 2 do
                                                        for iCurSegmentZ = iSegmentZ - iAdjustBase + 1, iSegmentZ + iAdjustBase - 1, 1 do
                                                            if iCurSegmentX >= 0 and iCurSegmentZ >= 0 then
                                                                if AiBotMap.tWaterZoneBySegment[iCurSegmentX][iCurSegmentZ] then iWaterZone = AiBotMap.tWaterZoneBySegment[iCurSegmentX][iCurSegmentZ] break end
                                                            end
                                                        end
                                                        if iWaterZone then break end
                                                    end
                                                    if iWaterZone then break end
                                                end
                                                if bDebugMessages == true then LOG(sFunctionRef..': Tried searching nearby segments for water zone, iWaterZone='..(iWaterZone or 'nil')) end
                                                if (iWaterZone or 0) > 0 then
                                                    AiBotMap.AddSegmentToWaterZone(iCurPond, iWaterZone, iSegmentX, iSegmentZ)
                                                    AddUnitToWaterZoneForBrain(aiBrain, oUnit, iWaterZone)
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Will add unit to water zone '..iWaterZone) end
                                                else
                                                    AiBotMap.ConsiderUnitAddingPositionToWaterZone(oUnit)
                                                    AiBotUtilities.ErrorHandler('Unable to find nearby water zone despite having a valid pond, unitID='..oUnit.UnitId..'; will try reassigning in a bit')
                                                    ForkThread(DelayedUnitPlateauAssignment, aiBrain, oUnit, 10, bAlreadyUpdatedPosition, true)
                                                end
                                            else
                                                --Reassign in a bit
                                                AiBotMap.ConsiderUnitAddingPositionToWaterZone(oUnit)
                                                ForkThread(DelayedUnitPlateauAssignment, aiBrain, oUnit, 10, bAlreadyUpdatedPosition, true)
                                                if bDebugMessages == true then LOG(sFunctionRef..': Have a non amphibious naval unit that isnt in a recognised pond, so will try to reassign in a bit') end
                                            end
                                        else
                                            --Reassign in a bit if we own it
                                            if bDebugMessages == true then LOG(sFunctionRef..': Unit has a plateau but not a LZ, and isnt a naval unit, will wait and try and reassign if this is the first time, bAlreadyTriedReassignment='..tostring(bAlreadyTriedReassignment or false)..'; aiBrain team='..aiBrain.AiBotTeam..'; Units aibrain team='..oUnit:GetAIBrain().AiBotTeam..'; aiBrain.AiBotAI='..tostring((aiBrain.AiBotAI or false))) end
                                            if not(bAlreadyTriedReassignment) or not(aiBrain.AiBotTeam == oUnit:GetAIBrain().AiBotTeam) or not(aiBrain.AiBotAI) or not(oUnit:GetAIBrain().AiBotAI) then
                                                ForkThread(DelayedUnitPlateauAssignment, aiBrain, oUnit, 20, bAlreadyUpdatedPosition, true)
                                                if bDebugMessages == true then LOG(sFunctionRef..': Will retry in a bit') end
                                            else
                                                --Have an AiBotAI trying to update date for an AiBotAI owned unit in the same team as it, and we have already tried reassigning it after a 20 tick delay; if the unit has no orders then give it new orders
                                                AiBotOrders.UpdateRecordedOrders(oUnit)
                                                if bDebugMessages == true then LOG(sFunctionRef..': Refreshed unit orders, order count='..oUnit[AiBotOrders.refiOrderCount]) end
                                                if oUnit[AiBotOrders.refiOrderCount] > 0 then
                                                    ForkThread(DelayedUnitPlateauAssignment, aiBrain, oUnit, 20, bAlreadyUpdatedPosition, true)
                                                    --If the unit is underwater and its last order was attack-move and it isnt a skirmisher then switch to being move
                                                    if not(EntityCategoryContains(AiBotUnitInfo.refCategorySkirmisher, oUnit.UnitId)) and oUnit[AiBotUnitInfo.refiDFRange] > 0 then
                                                        local tLastOrder = oUnit[AiBotOrders.reftiLastOrders][oUnit[AiBotOrders.refiOrderCount]]
                                                        if tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueAggressiveMove then
                                                            AiBotOrders.IssueTrackedMove(oUnit, { tLastOrder[AiBotOrders.subreftOrderPosition][1], tLastOrder[AiBotOrders.subreftOrderPosition][2], tLastOrder[AiBotOrders.subreftOrderPosition][3] }, 1, false, 'UWMNA', false)
                                                        end
                                                    end
                                                else
                                                    --Give unit new orders - move to the nearest land zone (this was added as a redundacny before logic for water zones was incorporated - may not be necessary now
                                                    local iNearestLandZone
                                                    local iNearestDist = 100000
                                                    local iCurDist
                                                    for iLandZone, tLZData in AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones] do
                                                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZData[AiBotMap.subrefMidpoint])
                                                        if iCurDist < iNearestDist then
                                                            iNearestDist = iCurDist
                                                            iNearestLandZone = iLandZone
                                                        end
                                                    end
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Tried looking for a nearby LZ, nearest LZ='..(iNearestLandZone or 'nil')) end
                                                    if iNearestLandZone then
                                                        AiBotOrders.IssueTrackedMove(oUnit, AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iNearestLandZone][AiBotMap.subrefMidpoint], 1, true, 'StuckMLZ'..iNearestLandZone)
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Told unit to move to the midpoint of the nearest LZ after any current orders, will assign to that land zone as well') end
                                                        AddUnitToLandZoneForBrain(aiBrain, oUnit, iPlateau, iNearestLandZone)
                                                    else
                                                        AiBotUtilities.ErrorHandler('Couldnt find a land zone for plateau '..iPlateau..' and unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit))
                                                        ForkThread(DelayedUnitPlateauAssignment, aiBrain, oUnit, 20, bAlreadyUpdatedPosition, true)
                                                    end
                                                end
                                            end
                                        end
                                    end

                                else
                                    --No valid plateau or land zone for unit so likely a pathing error; have unit move randomly if we are updating for the owner
                                    if bDebugMessages == true then LOG(sFunctionRef..': No valid plateau for unit') end
                                    ForkThread(HaveGroundUnitWithNoPlateau, aiBrain, oUnit)
                                end
                            end
                        end
                    end
                end
            end
        else
            if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..'; Have unit that cant take damage or be killed so ignoring, unit='..(oUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil')..' owned by '..(oUnit:GetAIBrain().Nickname or 'nil')..'; reprs='..reprs(oUnit)) end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function HaveGroundUnitWithNoPlateau(oTrackingBrain, oUnit)
    --Give new orders to the unit if it is an AiBot unit; aiBrain should be on the same team and is the brain that we will be updating the plateau and LZ tracking for
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'HaveGroundUnitWithNoPlateau'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    local refsTrackingVariable = 'AiBotNoPlateauActive'..oTrackingBrain:GetArmyIndex()
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    WaitTicks(1)
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if AiBotUnitInfo.IsUnitValid(oUnit) and not(oUnit[refsTrackingVariable]) then --Brain check is a redundancy
        if bDebugMessages == true then
            LOG(sFunctionRef..': Unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' doesnt appear to have a valid location, will monitor until it has a valid location; will draw unit cur position')
            AiBotUtilities.DrawLocation(oUnit:GetPosition())
        end
        oUnit[refsTrackingVariable] = true
        local iBaseAngle, iBaseDistance
        local tPotentialTempMoveLocation
        local iPlateauToTryAndFind
        local sPathing = AiBotUnitInfo.GetUnitPathingType
        local bConsiderMoving = false
        local iTeam = oTrackingBrain.AiBotTeam
        if oUnit:GetAIBrain().AiBotAI then bConsiderMoving = true end
        while AiBotUnitInfo.IsUnitValid(oUnit) do
            if (NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, oUnit:GetPosition()) or 0) > 0 then
                --Check we will get either al and or water zone if using the same approach that assignunittolandzoneorpond uses:
                local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnit:GetPosition())
                if iPlateau and iLandZone and iLandZone > 0 then
                    break
                else
                    --Do we have a water zone?
                    local iSegmentX, iSegmentZ = AiBotMap.GetPathingSegmentFromPosition(oUnit:GetPosition())
                    local iWaterZone = AiBotMap.tWaterZoneBySegment[iSegmentX][iSegmentZ]
                    if iWaterZone then
                        break
                    end
                end
            end
            --iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnit:GetPosition(), true, oUnit)
            if bDebugMessages == true then LOG(sFunctionRef..': Unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' postiion='..repru(oUnit:GetPosition())..'; Plateau label='..NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, oUnit:GetPosition()) or 0) end
            --if iPlateau > 0 then break end
            if bConsiderMoving then
                AiBotOrders.UpdateRecordedOrders(oUnit)
                if not(oUnit[AiBotOrders.reftiLastOrders]) then
                    --Give a move order to a random place
                    iBaseAngle = math.random(1, 360)
                    iBaseDistance = math.random(5, 10)
                    iPlateauToTryAndFind = (NavUtils.GetLabel(sPathing, oUnit:GetPosition()) or oUnit[AiBotLand.refiCurrentAssignmentPlateauAndLZ][1] or oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1]) --not as restrictive as terrain label
                    if not((iPlateauToTryAndFind or 0) > 0) then iPlateauToTryAndFind = nil end
                    for iAngleAdjust = 0, 45, 360 do
                        tPotentialTempMoveLocation = AiBotUtilities.MoveInDirection(oUnit:GetPosition(), iBaseAngle + iAngleAdjust, iBaseDistance, true, false, true)

                        if (iPlateauToTryAndFind and NavUtils.GetLabel(sPathing, tPotentialTempMoveLocation) == iPlateauToTryAndFind) or (not(iPlateauToTryAndFind) and NavUtils.GetLabel(sPathing, tPotentialTempMoveLocation)) then
                            break --Use this as the move location
                        end
                    end
                    AiBotOrders.IssueTrackedMove(oUnit, tPotentialTempMoveLocation, 3, false, 'RandPath')

                end
            end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitSeconds(1)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        end
        --Have a valid plateau so stop tracking and send for reassignment
        oUnit[refsTrackingVariable] = false
        AssignUnitToLandZoneOrPond(oTrackingBrain, oUnit)
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end


--[[function UpdateUnitPond(oUnit, iAiBotTeamUpdatingFor, bIsEnemy, iPondRefOverride)
