end--]]

function UpdateFactionBlueprintBlacklist(iLandSubteam)
    --Considers any blueprint specific overrides (only supports the 4 core factions and not modded units since blueprint values are hardcoded)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'UpdateFactionBlueprintBlacklist'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if iLandSubteam and not(tLandSubteamData[iLandSubteam]) then
        while not(tLandSubteamData[iLandSubteam]) and AiBotMap.bIsCampaignMap and GetGameTimeSeconds() <= 5 do
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitTicks(1)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        end
    end
    tLandSubteamData[iLandSubteam][subrefBlueprintBlacklist] = {}
    local bConsiderScoutRestrictions = false
    if tLandSubteamData[iLandSubteam][refbConsideredScoutFactionRestrictions] then bConsiderScoutRestrictions = true
    else
        local iLandScoutCount = 0
        local iBrainCount = 0
        for iBrain, oBrain in tLandSubteamData[iLandSubteam][subreftoFriendlyAiBotBrains] do
            iLandScoutCount = iLandScoutCount + AiBotConditions.GetLifetimeBuildCount(oBrain, AiBotUnitInfo.refCategoryLandScout)
            iBrainCount = iBrainCount + 1
        end
        if iLandScoutCount > iBrainCount * 4 then
            bConsiderScoutRestrictions = true
        end
    end
    if bConsiderScoutRestrictions then
        --Land scouts
        if AiBotConditions.HaveFactionTech(iLandSubteam, AiBotFactory.refiFactoryTypeLand, AiBotUnitInfo.refFactionAeon, 1) then
            --Only want Aeon land scouts (or seraphim for lurker mode)
            tLandSubteamData[iLandSubteam][subrefBlueprintBlacklist]['uel0101'] = true --UEF land scout (we have an override for land scouts in a dif island to the nearest base)
            tLandSubteamData[iLandSubteam][subrefBlueprintBlacklist]['url0101'] = true --Cybran land scout (we have an override for land scouts in a dif island to the nearest base)
            if GetGameTimeSeconds() >= 600 then tLandSubteamData[iLandSubteam][subrefBlueprintBlacklist]['xsl0101'] = true end --Seraphim land scout - want to build earlier on for lurker mode
        elseif AiBotConditions.HaveFactionTech(iLandSubteam, AiBotFactory.refiFactoryTypeLand, AiBotUnitInfo.refFactionCybran, 1) then
            --If have cybran tech then prioritise this
            tLandSubteamData[iLandSubteam][subrefBlueprintBlacklist]['uel0101'] = true --UEF land scout (we have an override for land scouts in a dif island to the nearest base)
            if GetGameTimeSeconds() >= 600 then tLandSubteamData[iLandSubteam][subrefBlueprintBlacklist]['xsl0101'] = true end --Seraphim land scout - want to build earlier on for lurker mode
        elseif AiBotConditions.HaveFactionTech(iLandSubteam, AiBotFactory.refiFactoryTypeLand, AiBotUnitInfo.refFactionUEF, 1) then
            if GetGameTimeSeconds() >= 600 then tLandSubteamData[iLandSubteam][subrefBlueprintBlacklist]['xsl0101'] = true end --Seraphim land scout - want to build earlier on for lurker mode
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code, blacklist for subteam '..iLandSubteam..' = '..repru(tLandSubteamData[iLandSubteam][subrefBlueprintBlacklist])) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function CheckForSubteamFactoryChange(oUnit, bJustBuiltNotDied)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'CheckForSubteamFactoryChange'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code for oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; bJustBuiltNotDied='..tostring(bJustBuiltNotDied or false)..'; Time='..GetGameTimeSeconds()) end
    if EntityCategoryContains(AiBotUnitInfo.refCategoryAllHQFactories + AiBotUnitInfo.refCategoryQuantumGateway, oUnit.UnitId) then
        local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnit:GetPosition())
        local iSubteam = oUnit:GetAIBrain().AiBotLandSubteam
        if iPlateau == tLandSubteamData[iSubteam][subrefiLandCorePlateau] and NavUtils.GetLabel(AiBotMap.refPathingTypeLand, oUnit:GetPosition()) == tLandSubteamData[iSubteam][subrefiLandCoreIsland] then
            local iFactoryType = AiBotUnitInfo.GetFactoryType(oUnit)
            local iFactoryTechLevel = AiBotUnitInfo.GetUnitTechLevel(oUnit)
            local iFactoryFaction = AiBotUnitInfo.GetUnitFaction(oUnit)


            local bChangedFactoryTech = false
            --Do we have any higher tech than this?
            local bHaveHigherTech = false
            if iFactoryTechLevel < 3 then
                for iHigherTech = iFactoryTechLevel + 1, 2 do
                    if (tLandSubteamData[iSubteam][subrefFactoriesByTypeFactionAndTech][iFactoryType][iFactoryFaction][iHigherTech] or 0) > 0 then
                        bHaveHigherTech = true
                        break
                    end
                end
            end

            if bDebugMessages == true then LOG(sFunctionRef..': Considering if we have had a factory tech change, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; bJustBuiltNotDied='..tostring(bJustBuiltNotDied or false)..'; iFactoryType='..iFactoryType..'; iPlateau='..iPlateau..'; IslandRef='..NavUtils.GetLabel(AiBotMap.refPathingTypeLand, oUnit:GetPosition())..'; iFactoryTechLevel='..iFactoryTechLevel..'; iFactoryFaction='..iFactoryFaction..'; iSubteam='..iSubteam..'; tLandSubteamData[iSubteam][subrefFactoriesByTypeFactionAndTech]='..repru(tLandSubteamData[iSubteam][subrefFactoriesByTypeFactionAndTech])) end

            if bJustBuiltNotDied then
                --Check if need to add the unit to the subteam table
                if (tLandSubteamData[iSubteam][subrefFactoriesByTypeFactionAndTech][iFactoryType][iFactoryFaction][iFactoryTechLevel] or 0) <= 0 then
                    if not(bHaveHigherTech) then bChangedFactoryTech = true end
                    tLandSubteamData[iSubteam][subrefFactoriesByTypeFactionAndTech][iFactoryType][iFactoryFaction][iFactoryTechLevel] = 1
                else
                    tLandSubteamData[iSubteam][subrefFactoriesByTypeFactionAndTech][iFactoryType][iFactoryFaction][iFactoryTechLevel] = tLandSubteamData[iSubteam][subrefFactoriesByTypeFactionAndTech][iFactoryType][iFactoryFaction][iFactoryTechLevel] + 1
                end
            else
                if tLandSubteamData[iSubteam][subrefFactoriesByTypeFactionAndTech][iFactoryType][iFactoryFaction][iFactoryTechLevel] == 1 then
                    if not(bHaveHigherTech) then bChangedFactoryTech = true end
                end
                tLandSubteamData[iSubteam][subrefFactoriesByTypeFactionAndTech][iFactoryType][iFactoryFaction][iFactoryTechLevel] = math.max(0, (tLandSubteamData[iSubteam][subrefFactoriesByTypeFactionAndTech][iFactoryType][iFactoryFaction][iFactoryTechLevel] or 0) - 1)
            end

            if bChangedFactoryTech then
                UpdateFactionBlueprintBlacklist(iSubteam)
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function UpdateTeamHighestAndLowestFactories(iAiBotTeam)
    --Called whenever an AiBot brain gains or loses an HQ factory; for convenience will update all factory types (even thoguh marginally more efficient to only update the type in question)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'UpdateTeamHighestAndLowestFactories'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    tTeamData[iAiBotTeam][subrefiLowestFriendlyLandFactoryTech] = 3
    tTeamData[iAiBotTeam][subrefiLowestFriendlyAirFactoryTech] = 3
    tTeamData[iAiBotTeam][subrefiLowestFriendlyNavalFactoryTech] = 3
    tTeamData[iAiBotTeam][subrefiHighestFriendlyLandFactoryTech] = 0
    tTeamData[iAiBotTeam][subrefiHighestFriendlyAirFactoryTech] = 0
    tTeamData[iAiBotTeam][subrefiHighestFriendlyNavalFactoryTech] = 0

    if bDebugMessages == true then LOG(sFunctionRef..': Lowest friendly land fac start point (will decrease to lower of this and actual tech)='..tTeamData[iAiBotTeam][subrefiLowestFriendlyLandFactoryTech]) end

    for iBrain, oBrain in tTeamData[iAiBotTeam][subreftoFriendlyActiveAiBotBrains] do
        if not(oBrain[AiBotEconomy.refiOurHighestFactoryTechLevel]) then --saves having to define the variables earlier
            oBrain[AiBotEconomy.refiOurHighestFactoryTechLevel] = 0
            oBrain[AiBotEconomy.refiOurHighestLandFactoryTech] = 0
            oBrain[AiBotEconomy.refiOurHighestAirFactoryTech] = 0
            oBrain[AiBotEconomy.refiOurHighestNavalFactoryTech] = 0
        end
        if bDebugMessages == true then LOG(sFunctionRef..': subrefiLowestFriendlyLandFactoryTech before reducing='..tTeamData[iAiBotTeam][subrefiLowestFriendlyLandFactoryTech]..'; oBrain[AiBotEconomy.refiOurHighestLandFactoryTech]='..oBrain[AiBotEconomy.refiOurHighestLandFactoryTech]..'; lower of these two='..math.min(tTeamData[iAiBotTeam][subrefiLowestFriendlyLandFactoryTech], oBrain[AiBotEconomy.refiOurHighestLandFactoryTech])) end
        tTeamData[iAiBotTeam][subrefiLowestFriendlyLandFactoryTech] = math.min(3, tTeamData[iAiBotTeam][subrefiLowestFriendlyLandFactoryTech], oBrain[AiBotEconomy.refiOurHighestLandFactoryTech])
        if bDebugMessages == true then LOG(sFunctionRef..': tTeamData[iAiBotTeam][subrefiLowestFriendlyLandFactoryTech] after update='..tTeamData[iAiBotTeam][subrefiLowestFriendlyLandFactoryTech]) end
        tTeamData[iAiBotTeam][subrefiLowestFriendlyAirFactoryTech] = math.min(3, tTeamData[iAiBotTeam][subrefiLowestFriendlyAirFactoryTech], oBrain[AiBotEconomy.refiOurHighestAirFactoryTech])
        tTeamData[iAiBotTeam][subrefiLowestFriendlyNavalFactoryTech] = math.min(3, tTeamData[iAiBotTeam][subrefiLowestFriendlyNavalFactoryTech], oBrain[AiBotEconomy.refiOurHighestNavalFactoryTech])

        tTeamData[iAiBotTeam][subrefiHighestFriendlyLandFactoryTech] = math.min(3, math.max(tTeamData[iAiBotTeam][subrefiHighestFriendlyLandFactoryTech], oBrain[AiBotEconomy.refiOurHighestLandFactoryTech]))
        tTeamData[iAiBotTeam][subrefiHighestFriendlyAirFactoryTech] = math.min(3, math.max(tTeamData[iAiBotTeam][subrefiHighestFriendlyAirFactoryTech], oBrain[AiBotEconomy.refiOurHighestAirFactoryTech]))
        tTeamData[iAiBotTeam][subrefiHighestFriendlyNavalFactoryTech] = math.min(3, math.max(tTeamData[iAiBotTeam][subrefiHighestFriendlyNavalFactoryTech], oBrain[AiBotEconomy.refiOurHighestNavalFactoryTech]))
        if bDebugMessages == true then LOG(sFunctionRef..': Considering brain '..oBrain.Nickname..'; tTeamData[iAiBotTeam][subrefiLowestFriendlyLandFactoryTech]='..tTeamData[iAiBotTeam][subrefiLowestFriendlyLandFactoryTech]..'; oBrain[AiBotEconomy.refiOurHighestLandFactoryTech]='..oBrain[AiBotEconomy.refiOurHighestLandFactoryTech]) end
    end
    tTeamData[iAiBotTeam][subrefiHighestFriendlyFactoryTech] = math.min(3, math.max(1, tTeamData[iAiBotTeam][subrefiHighestFriendlyLandFactoryTech], tTeamData[iAiBotTeam][subrefiHighestFriendlyAirFactoryTech], (tTeamData[iAiBotTeam][subrefiHighestFriendlyNavalFactoryTech] or 0)))
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function DoesBrainHaveActiveHQUpgradesOfCategory(aiBrain, iFactoryBeingUpgradedCategory, bReturnNumberInstead)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'DoesBrainHaveActiveHQUpgradesOfCategory'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': Does our team have an empty table of upgrading HQs='..tostring(AiBotUtilities.IsTableEmpty(tTeamData[aiBrain.AiBotTeam][subreftTeamUpgradingHQs]))) end
    if AiBotUtilities.IsTableEmpty(tTeamData[aiBrain.AiBotTeam][subreftTeamUpgradingHQs]) == false then
        local iTotalUpgrading
        local tiEntriesToRemove
        for iUpgrading, oUpgrading in tTeamData[aiBrain.AiBotTeam][subreftTeamUpgradingHQs] do
            if not(AiBotUnitInfo.IsUnitValid(oUpgrading)) then
                if bDebugMessages == true then LOG(sFunctionRef..': Have invalid upgrading unit='..(oUpgrading.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUpgrading) or 'nil')) end
                AiBotUtilities.ErrorHandler('Invalid oUpgrading unit')
            end
            if EntityCategoryContains(iFactoryBeingUpgradedCategory, oUpgrading.UnitId) then
                if AiBotUnitInfo.IsUnitValid(oUpgrading) and oUpgrading:GetAIBrain() == aiBrain then
                    --Check - is our last order not upgrading, and we have 0 work progress?
                    if oUpgrading:GetWorkProgress() == 0 and not(oUpgrading:IsUnitState('Upgrading')) and not(oUpgrading[AiBotUnitInfo.refbPaused]) and not(oUpgrading[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderUpgrade) and not(oUpgrading[AiBotOrders.reftiLastOrders][2]) then
                        if bDebugMessages == true then LOG(sFunctionRef..': oUpgrading unit '..oUpgrading.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUpgrading)..' owned by '..aiBrain.Nickname..' doesnt appear to actually be upgrading so will remove from table') end
                        if not(tiEntriesToRemove) then tiEntriesToRemove = {} end
                        table.insert(tiEntriesToRemove, iUpgrading)
                    else
                        if bDebugMessages == true then LOG(sFunctionRef..': The upgrading unit '..oUpgrading.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUpgrading)..' brain is equal to aiBrain '..aiBrain.Nickname) end
                        if bReturnNumberInstead then
                            iTotalUpgrading = (iTotalUpgrading or 0) + 1
                        else
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            return true
                        end
                    end
                elseif bDebugMessages == true then LOG(sFunctionRef..': Upgrading unit is either invalid or owned by a dif brain, is valid='..tostring(AiBotUnitInfo.IsUnitValid(oUpgrading)))
                end
            end
        end
        if tiEntriesToRemove then
            for iCurEntry = table.getn(tiEntriesToRemove), 1, -1 do
                table.remove(tTeamData[aiBrain.AiBotTeam][subreftTeamUpgradingHQs], iCurEntry)
            end
        end
        if bReturnNumberInstead then
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return (iTotalUpgrading or 0)
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    if bReturnNumberInstead then return 0 else
        return false
    end
end

function ConsiderPriorityLandFactoryUpgrades(iAiBotTeam)
    --Starts a land factory upgrade if we need one urgently (e.g. we are outteched, or have high gross mass so will want access to T3)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderPriorityLandFactoryUpgrades'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    --Enemy has better land tech than us, and we have no active land upgrades



    if bDebugMessages == true then
        LOG(sFunctionRef..': Highest land tech='..tTeamData[iAiBotTeam][subrefiHighestFriendlyLandFactoryTech]..'; Highest enemy tech='..tTeamData[iAiBotTeam][subrefiHighestEnemyGroundTech]..'; Gross mass='..tTeamData[iAiBotTeam][subrefiTeamGrossMass]..'; Mass stored='..tTeamData[iAiBotTeam][subrefiTeamMassStored])
    end
    if tTeamData[iAiBotTeam][subrefiHighestFriendlyLandFactoryTech] > 0 and tTeamData[iAiBotTeam][subrefiHighestFriendlyLandFactoryTech] < 3 and (tTeamData[iAiBotTeam][subrefiHighestFriendlyLandFactoryTech] < 2 or not(tTeamData[iAiBotTeam][refbFocusOnT1Spam])) then
        local bInitiallyWantUpgrade = false
        local bNearbyUpgradedEnemyACU = false
        if tTeamData[iAiBotTeam][subrefiHighestFriendlyLandFactoryTech] < tTeamData[iAiBotTeam][subrefiHighestEnemyGroundTech]
                or (tTeamData[iAiBotTeam][subrefiTeamGrossMass] >= 3.5 * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] * tTeamData[iAiBotTeam][subrefiHighestFriendlyLandFactoryTech] and (tTeamData[iAiBotTeam][subrefiTeamMassStored] >= 300 * math.min(2, tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount]) * tTeamData[iAiBotTeam][subrefiHighestFriendlyLandFactoryTech] or tTeamData[iAiBotTeam][subrefiTeamGrossMass] >= 7 * tTeamData[iAiBotTeam][subrefiHighestFriendlyLandFactoryTech] * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount]) and (tTeamData[iAiBotTeam][subrefiTeamGrossMass] >= 8.5 * (1 + (tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] - 1) *0.5) or tTeamData[iAiBotTeam][subrefiHighestFriendlyFactoryTech] == 1 or AiBotConditions.GetTeamLifetimeBuildCount(iAiBotTeam, (AiBotUnitInfo.refCategoryLandCombat * AiBotUnitInfo.ConvertTechLevelToCategory(tTeamData[iAiBotTeam][subrefiHighestFriendlyFactoryTech]) + AiBotUnitInfo.refCategoryIndirect * AiBotUnitInfo.ConvertTechLevelToCategory(tTeamData[iAiBotTeam][subrefiHighestFriendlyFactoryTech])) ) >= (20 * (2.5-tTeamData[iAiBotTeam][subrefiHighestFriendlyFactoryTech]) + 12 * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount]) * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount]))
                --Get priority upgrade to T2 if enemy has TMLs
                or (tTeamData[iAiBotTeam][subrefiHighestFriendlyFactoryTech] == 1 and AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingHQs]) and tTeamData[iAiBotTeam][subrefiTeamGrossMass] >= 0.6 and tTeamData[iAiBotTeam][subrefiTeamGrossEnergy] >= 8)
        then
            if bDebugMessages == true then LOG(sFunctionRef..': Want to get upgrade as have high eco or enemy outtechs us; however will make exception if are at T3 air and low mass') end
            bInitiallyWantUpgrade = true
            if tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored] <= 0.05 and tTeamData[iAiBotTeam][subrefiHighestFriendlyAirFactoryTech] >= 3 and GetGameTimeSeconds() - (tTeamData[iAiBotTeam][refiTimeOfLastMassStall] or -100) <= 45 and tTeamData[iAiBotTeam][refiConstructedExperimentalCount] == 0 then
                bInitiallyWantUpgrade = false
                if bDebugMessages == true then LOG(sFunctionRef..': Changed mind, dont want to upgrade yet as a priority due to low mass and having T3 air') end
            end
            --Further exception if low mass
            if tTeamData[iAiBotTeam][subrefiTeamGrossMass] <= 2.4 * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] * tTeamData[iAiBotTeam][refiHighestBrainBuildMultiplier] then
                if tTeamData[iAiBotTeam][subrefiTeamGrossMass] <= tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] * tTeamData[iAiBotTeam][refiHighestBrainBuildMultiplier] then
                    bInitiallyWantUpgrade = false
                    if bDebugMessages == true then LOG(sFunctionRef..': Have fewer than 4 t1 mex equivalent so wont get upgrade afterall') end
                elseif tTeamData[iAiBotTeam][subrefiHighestFriendlyLandFactoryTech] then
                    bInitiallyWantUpgrade = false
                    if bDebugMessages == true then LOG(sFunctionRef..': Have less than 4 t2 mex equivalent in mass so wont get T3 land upgrade yet') end
                end
            end
        end
        --Does enemy have a nearby upgraded or upgrading AUC and we lack T2 land for a brain?
        if tTeamData[iAiBotTeam][subrefiLowestFriendlyLandFactoryTech] == 1 and AiBotConditions.IsTableOfUnitsStillValid(tTeamData[iAiBotTeam][reftEnemyACUs]) then
            for iACU, oACU in tTeamData[iAiBotTeam][reftEnemyACUs] do
                if bDebugMessages == true then LOG(sFunctionRef..': Considering if enemy ACU owned by brain '..oACU:GetAIBrain().Nickname..' is upgrading or has an upgrade, upgrade count='..(oACU[AiBotACU.refiUpgradeCount] or 0)..'; Unit state='..AiBotUnitInfo.GetUnitState(oACU)..'; Is ACU upgrading='..tostring(oACU:IsUnitState('Upgrading'))) end
                if (oACU[AiBotACU.refiUpgradeCount] or 0) > 0 or (oACU:IsUnitState('Upgrading') and oACU:GetWorkProgress() >= 0.05) then
                    --Is the ACU close to a friendly base?
                    local tLZOrWZData, tLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(oACU:GetPosition(), true, iAiBotTeam)
                    local iDistFromACUToBase = AiBotUtilities.GetDistanceBetweenPositions(oACU:GetPosition(), tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase])
                    if iDistFromACUToBase <= math.min(250, math.max(175, AiBotMap.iMapSize * 0.5)) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Want to get upgrade as are worried about enemy ACU, unless are on a 5km map 1v1 nd due to t1 spam mode we would rather upgrade our own ACU') end
                        local bGetT2LandToStopACU = true
                        if AiBotMap.iMapSize <= 256 and iPlayersAtGameStart == 2 and tTeamData[iAiBotTeam][refbFocusOnT1Spam] then
                            --How close is our ACU to base?
                            if AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][reftAiBotACUs]) == false then
                                for iFriendlyACU, oFriendlyACU in tTeamData[iAiBotTeam][reftAiBotACUs] do
                                    if AiBotUtilities.GetDistanceBetweenPositions(oFriendlyACU:GetPosition(), AiBotMap.GetPlayerStartPosition(oFriendlyACU:GetAIBrain())) <= 15 + iDistFromACUToBase then
                                        --Do we have gun upgrade and similar health?
                                        if oFriendlyACU[AiBotACU.refiUpgradeCount] >= 2 or (oFriendlyACU[AiBotACU.refiUpgradeCount] == 1 and not(EntityCategoryContains(categories.AEON, oFriendlyACU.UnitId))) and AiBotUnitInfo.GetUnitCurHealthAndShield(oFriendlyACU) + 1000 > AiBotUnitInfo.GetUnitCurHealthAndShield(oACU) then
                                            bGetT2LandToStopACU = false
                                            break
                                        elseif AiBotUnitInfo.GetUnitCurHealthAndShield(oFriendlyACU) + 2000 > AiBotUnitInfo.GetUnitCurHealthAndShield(oACU) and (oFriendlyACU[AiBotACU.refiUpgradeCount] == 0 or (oFriendlyACU[AiBotACU.refiUpgradeCount] == 1 and EntityCategoryContains(categories.AEON, oFriendlyACU.UnitId))) then
                                            --Get upgrade as a priority
                                            if bDebugMessages == true then LOG(sFunctionRef..': Want friendly ACU to get upgrade instead of going to t2 land') end
                                            oFriendlyACU[AiBotACU.refbWantsPriorityUpgrade] = true
                                            bGetT2LandToStopACU = false
                                            break
                                        end
                                    end
                                end
                            end
                        end
                        if bGetT2LandToStopACU then
                            bNearbyUpgradedEnemyACU = true
                            bInitiallyWantUpgrade = true
                            break
                        end
                    end
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': bInitiallyWantUpgrade='..tostring(bInitiallyWantUpgrade)) end
        if bInitiallyWantUpgrade then
            if not(AiBotMap.bIsCampaignMap) or tTeamData[iAiBotTeam][subrefiTeamGrossMass] >= 4 * tTeamData[iAiBotTeam][subrefiHighestFriendlyAirFactoryTech] * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] then

                local bWantUpgrade = false
                local iExistingBrainsWithHQUpgrades = 0
                local tbBrainsWithActiveUpgradeByIndex = {}
                if AiBotConditions.IsTableOfUnitsStillValid(tTeamData[iAiBotTeam][subreftTeamUpgradingHQs]) then
                    for iHQ, oHQ in tTeamData[iAiBotTeam][subreftTeamUpgradingHQs] do
                        if EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory, oHQ.UnitId) then
                            if not(oHQ:GetAIBrain():IsDefeated()) then
                                tbBrainsWithActiveUpgradeByIndex[oHQ:GetAIBrain():GetArmyIndex()] = true
                            end
                        end
                    end
                end
                for iBrain, oBrain in tTeamData[iAiBotTeam][subreftoFriendlyActiveAiBotBrains] do
                    --Can we path to the nearest enemy with land, and we are behind enemy tech level with land or have lots of mass?
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering oBrain '..oBrain.Nickname..'; oBrain[AiBotMap.refbCanPathToEnemyBaseWithLand]='..tostring(oBrain[AiBotMap.refbCanPathToEnemyBaseWithLand])..'; oBrain[AiBotEconomy.refiOurHighestLandFactoryTech]='..oBrain[AiBotEconomy.refiOurHighestLandFactoryTech]..'; subrefiHighestEnemyGroundTech='..tTeamData[iAiBotTeam][subrefiHighestEnemyGroundTech]..'; tbBrainsWithActiveUpgradeByIndex='..tostring(tbBrainsWithActiveUpgradeByIndex[oBrain:GetArmyIndex()] or false)) end
                    if not(tbBrainsWithActiveUpgradeByIndex[oBrain:GetArmyIndex()]) and (not(oBrain[AiBotOverseer.refbPrioritiseLowTech]) or tTeamData[iAiBotTeam][refiConstructedExperimentalCount] > 0 or (oBrain[AiBotEconomy.refiOurHighestLandFactoryTech] < tTeamData[iAiBotTeam][subrefiHighestEnemyGroundTech] and (oBrain[AiBotEconomy.refiOurHighestLandFactoryTech] < tTeamData[iAiBotTeam][subrefiHighestEnemyGroundTech] - 1 or ((tTeamData[iAiBotTeam][subrefiHighestFriendlyFactoryTech] < tTeamData[iAiBotTeam][subrefiHighestEnemyGroundTech] or oBrain[AiBotMap.refbCanPathToEnemyBaseWithLand]) and AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingHQs]) and not(oBrain[AiBotOverseer.refbPrioritiseNavy])))) or AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][reftEnemyLandExperimentals])) and not(oBrain[AiBotOverseer.refbPrioritiseAir]) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Checking pathability') end
                        if (oBrain[AiBotMap.refbCanPathToEnemyBaseWithLand] and oBrain[AiBotEconomy.refiOurHighestLandFactoryTech] > 0 and (oBrain[AiBotEconomy.refiOurHighestLandFactoryTech] < tTeamData[iAiBotTeam][subrefiHighestEnemyGroundTech] or (bNearbyUpgradedEnemyACU and oBrain[AiBotEconomy.refiOurHighestLandFactoryTech] == 1) or (tTeamData[iAiBotTeam][subrefiTeamGrossMass] >= 6.5 * (1 + (tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] - 1) * 0.5) and tTeamData[iAiBotTeam][subrefiTeamGrossEnergy] >= 50 * (1 + (tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] - 1)*0.5)) or AiBotConditions.GetTeamLifetimeBuildCount(iAiBotTeam, (AiBotUnitInfo.refCategoryLandCombat * AiBotUnitInfo.ConvertTechLevelToCategory(tTeamData[iAiBotTeam][subrefiHighestFriendlyFactoryTech]) + AiBotUnitInfo.refCategoryIndirect * AiBotUnitInfo.ConvertTechLevelToCategory(tTeamData[iAiBotTeam][subrefiHighestFriendlyFactoryTech]))) >= 20 * (2-tTeamData[iAiBotTeam][subrefiHighestFriendlyFactoryTech]) + 15 * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount]))
                                or (AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][reftEnemyTML]) == false and tTeamData[iAiBotTeam][subrefiHighestFriendlyFactoryTech] == 1 and oBrain[AiBotMap.refbCanPathToEnemyBaseWithAmphibious] and oBrain[AiBotEconomy.refiOurHighestNavalFactoryTech] == 0)
                        then
                            --Do we have any active land factory upgrades?
                            bWantUpgrade = not(DoesBrainHaveActiveHQUpgradesOfCategory(oBrain, AiBotUnitInfo.refCategoryLandHQ))
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want to hold off so we can get air instead, oBrain[AiBotEconomy.refiOurHighestLandFactoryTech]='..oBrain[AiBotEconomy.refiOurHighestLandFactoryTech]..'; oBrain[AiBotEconomy.refiOurHighestAirFactoryTech]='..oBrain[AiBotEconomy.refiOurHighestAirFactoryTech]..'; Map size='..AiBotMap.iMapSize) end
                            if bWantUpgrade and oBrain[AiBotEconomy.refiOurHighestLandFactoryTech] >= 2 and oBrain[AiBotEconomy.refiOurHighestAirFactoryTech] <= 2 and AiBotMap.iMapSize >= 512 then
                                --Check if we are in a 'safe' start position, in which case want to not get land and instead will get air
                                local tBrainStartZoneData, tBrainStartZoneTeamData = AiBotMap.GetLandOrWaterZoneData(AiBotMap.GetPlayerStartPosition(oBrain, false), true, oBrain.AiBotTeam)
                                if tBrainStartZoneTeamData[AiBotMap.refbBaseInSafePosition] and AiBotUtilities.GetDistanceBetweenPositions(tBrainStartZoneData[AiBotMap.subrefMidpoint], tBrainStartZoneTeamData[AiBotMap.reftClosestEnemyBase]) >= 300 then bWantUpgrade = false end
                                if bDebugMessages == true then LOG(sFunctionRef..': tBrainStartZoneTeamData[AiBotMap.refbBaseInSafePosition]='..tostring(tBrainStartZoneTeamData[AiBotMap.refbBaseInSafePosition] or false)..'; Dist to closest enemy base='..AiBotUtilities.GetDistanceBetweenPositions(tBrainStartZoneData[AiBotMap.subrefMidpoint], tBrainStartZoneTeamData[AiBotMap.reftClosestEnemyBase])) end
                            end
                            --Also hold off if we have an AirHQ upgrading and dont urgently need land
                            if bWantUpgrade and oBrain:GetEconomyStoredRatio('MASS') <= 0.4 then
                                local iStartPlateauOrZero, iStartZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(AiBotMap.GetPlayerStartPosition(oBrain, false))
                                local tBrainStartZoneData, tBrainStartZoneTeamData
                                if iStartPlateauOrZero == 0 then
                                    tBrainStartZoneData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iStartZone]][AiBotMap.subrefPondWaterZones][iStartZone]
                                    tBrainStartZoneTeamData = tBrainStartZoneData[AiBotMap.subrefWZTeamData][iAiBotTeam]
                                else
                                    tBrainStartZoneData = AiBotMap.tAllPlateaus[iStartPlateauOrZero][AiBotMap.subrefPlateauLandZones][iStartZone]
                                    tBrainStartZoneTeamData = tBrainStartZoneData[AiBotMap.subrefLZTeamData][iAiBotTeam]
                                end
                                if tBrainStartZoneTeamData then
                                    local bHaveActiveAirUpgrade = DoesBrainHaveActiveHQUpgradesOfCategory(oBrain, AiBotUnitInfo.refCategoryAirHQ)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering if want to ignore this brain, tBrainStartZoneTeamData[AiBotMap.refbBaseInSafePosition]='..tostring(tBrainStartZoneTeamData[AiBotMap.refbBaseInSafePosition])..'; bHaveActiveAirUpgrade='..tostring(bHaveActiveAirUpgrade)..'; oBrain[AiBotEconomy.refiOurHighestLandFactoryTech]='..oBrain[AiBotEconomy.refiOurHighestLandFactoryTech]..'; oBrain[AiBotEconomy.refiOurHighestAirFactoryTech]='..oBrain[AiBotEconomy.refiOurHighestAirFactoryTech]..'; tBrainStartZoneTeamData[AiBotMap.subrefMexCountByTech][3]='..tBrainStartZoneTeamData[AiBotMap.subrefMexCountByTech][3]..'; Brain mass%='..oBrain:GetEconomyStoredRatio('MASS')) end
                                    if tBrainStartZoneTeamData[AiBotMap.refbBaseInSafePosition] and (bHaveActiveAirUpgrade or (GetGameTimeSeconds() <= 1200 and oBrain[AiBotEconomy.refiOurHighestLandFactoryTech] >= oBrain[AiBotEconomy.refiOurHighestAirFactoryTech]) or (oBrain[AiBotEconomy.refiOurHighestLandFactoryTech] >= 2 and tBrainStartZoneTeamData[AiBotMap.subrefMexCountByTech][3] < math.min(4, tBrainStartZoneData[AiBotMap.subrefLZOrWZMexCount])) or (tTeamData[iAiBotTeam][subrefbRushT3AirInAirSlot] and oBrain[AiBotEconomy.refiOurHighestAirFactoryTech] < 3 and tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored] < 0.3 and (oBrain[AiBotEconomy.refiOurHighestLandFactoryTech] >= 2 or tBrainStartZoneTeamData[AiBotMap.subrefMexCountByTech][3] < math.min(2, tBrainStartZoneData[AiBotMap.subrefLZOrWZMexCount])))) then
                                        bWantUpgrade = false
                                        if bDebugMessages == true then LOG(sFunctionRef..': Dont want land fac upgrade yet for air slot') end
                                    elseif bHaveActiveAirUpgrade and oBrain:GetEconomyStoredRatio('MASS') <= 0.3 and (oBrain:GetEconomyStoredRatio('MASS') <= 0.05 or oBrain[AiBotEconomy.refiOurHighestLandFactoryTech] <= oBrain[AiBotEconomy.refiOurHighestAirFactoryTech] or oBrain[AiBotOverseer.refbPrioritiseAir]) then
                                        local bWantMMLOrT3Arti, bWantT3 = AiBotConditions.SaveMassForMMLOrMobileT3ArtiForFirebase(tBrainStartZoneData, tBrainStartZoneTeamData, iStartPlateauOrZero, iAiBotTeam, true)
                                        if not(bWantMMLOrT3Arti) or (not(bWantT3 and oBrain[AiBotEconomy.refiOurHighestLandFactoryTech] >= 2)) then
                                            bWantUpgrade = false
                                        end
                                    end
                                end
                            end

                            if bWantUpgrade and (iExistingBrainsWithHQUpgrades < tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] * 0.5 or tTeamData[iAiBotTeam][subrefiTeamMassStored] >= 450 * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount]) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Will try and upgrade a land factory HQ subject to how many units the factory has built, unless we are upgrading a land fac to t3 and still have t1 mexes, refiOurHighestLandFactoryTech='..oBrain[AiBotEconomy.refiOurHighestLandFactoryTech]..'; refiMexCountByTech[3]='..tTeamData[iAiBotTeam][refiMexCountByTech][3]..'; is reftEnemyLandExperimentals empty='..tostring(AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][reftEnemyLandExperimentals]))..'; refiGrossMassBaseIncome='..oBrain[AiBotEconomy.refiGrossMassBaseIncome]..'; HaveLowMass='..tostring(AiBotConditions.HaveLowMass(oBrain))..'; subrefiHighestEnemyAirTech='..tTeamData[iAiBotTeam][subrefiHighestEnemyAirTech]..'; TeamHasLowMass='..tostring(AiBotConditions.TeamHasLowMass(iAiBotTeam))) end
                                local bWantMoreMexesInBaseFirst = false
                                if oBrain[AiBotEconomy.refiOurHighestLandFactoryTech] == 2 and tTeamData[iAiBotTeam][subrefiHighestEnemyAirTech] < 3 and tTeamData[iAiBotTeam][refiMexCountByTech][3] < 2 and AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][reftEnemyLandExperimentals]) and oBrain[AiBotEconomy.refiGrossMassBaseIncome] < 15 and (AiBotConditions.HaveLowMass(oBrain) or AiBotConditions.TeamHasLowMass(iAiBotTeam)) and GetGameTimeSeconds() <= 960 then
                                    local tLZData, tLZTeamData = AiBotMap.GetLandOrWaterZoneData(AiBotMap.GetPlayerStartPosition(oBrain), true, iAiBotTeam)
                                    if bDebugMessages == true then LOG(sFunctionRef..': subrefMexCountByTech=T3:'..tLZTeamData[AiBotMap.subrefMexCountByTech][3]..'; 2:'..tLZTeamData[AiBotMap.subrefMexCountByTech][2]..'; 1:'..tLZTeamData[AiBotMap.subrefMexCountByTech][1]..'; Is table of subrefLZOrWZMassStorageLocationsAvailable empty='..tostring(AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZOrWZMassStorageLocationsAvailable]))) end
                                    if tLZTeamData[AiBotMap.subrefMexCountByTech][2] > 0 and tLZTeamData[AiBotMap.subrefMexCountByTech][1] > 0 and tLZTeamData[AiBotMap.subrefMexCountByTech][3] == 0 and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZOrWZMassStorageLocationsAvailable]) == false and table.getn(tLZData[AiBotMap.subrefLZOrWZMassStorageLocationsAvailable]) > 4 then
                                        bWantMoreMexesInBaseFirst = true
                                        if bDebugMessages == true then LOG(sFunctionRef..': We have mass storage available and have t1 mexes in our core base, and have low mass, so want to delay getting T3 land HQ for this brain unless enemy has built a number of t3 land units, bWantMoreMexesInBaseFirst='..tostring(bWantMoreMexesInBaseFirst)) end
                                        for iEnemyTeam = 1, iTotalTeamCount do
                                            if not(iEnemyTeam == iAiBotTeam) then
                                                if AiBotConditions.GetTeamLifetimeBuildCount(iEnemyTeam, categories.DIRECTFIRE * categories.TECH3 + categories.INDIRECTFIRE * categories.TECH3) >= 2 then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Enemy has built several T3 units so will get upgrade afterall') end
                                                    bWantMoreMexesInBaseFirst = false
                                                    break
                                                end
                                            end
                                        end
                                        if bDebugMessages == true then LOG(sFunctionRef..': Finished checking enemy team T3 lifetime count, bWantMoreMexesInBaseFirst='..tostring(bWantMoreMexesInBaseFirst)) end
                                    end
                                end
                                if bWantMoreMexesInBaseFirst then
                                    --Do nothing
                                else
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will try and find land fac HQ to upgrade, bWantMoreMexesInBaseFirst='..tostring(bWantMoreMexesInBaseFirst)) end
                                    AiBotEconomy.FindAndUpgradeUnitOfCategory(oBrain, AiBotUnitInfo.refCategoryLandHQ * AiBotUnitInfo.ConvertTechLevelToCategory(oBrain[AiBotEconomy.refiOurHighestLandFactoryTech]), 7)
                                end
                            elseif not(bWantUpgrade) then
                                iExistingBrainsWithHQUpgrades = iExistingBrainsWithHQUpgrades + 1
                            end
                        end
                    end
                end
            end
        end
    end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ConsiderPriorityAirFactoryUpgrades(iAiBotTeam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderPriorityAirFactoryUpgrades'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': tTeamData[iAiBotTeam][subrefiHighestFriendlyAirFactoryTech]='..tTeamData[iAiBotTeam][subrefiHighestFriendlyAirFactoryTech]..'; tTeamData[iAiBotTeam][subrefiHighestFriendlyAirFactoryTech]='..tTeamData[iAiBotTeam][subrefiHighestFriendlyAirFactoryTech]..'; tTeamData[iAiBotTeam][subrefiHighestEnemyAirTech]='..tTeamData[iAiBotTeam][subrefiHighestEnemyAirTech]..'; refbFocusOnT1Spam='..tostring(tTeamData[iAiBotTeam][refbFocusOnT1Spam])) end

    if tTeamData[iAiBotTeam][subrefiHighestFriendlyAirFactoryTech] > 0 and tTeamData[iAiBotTeam][subrefiHighestFriendlyAirFactoryTech] < 3 and not(tTeamData[iAiBotTeam][refbFocusOnT1Spam]) then
        --Campaign specific - dont be as keen to urgently upgrade air (as it may be enemy starts at t3 air while we start at t1)
        if bDebugMessages == true then LOG(sFunctionRef..': subrefiTeamGrossMass='..tTeamData[iAiBotTeam][subrefiTeamGrossMass]..'; refiHighestBrainBuildMultiplier='..tTeamData[iAiBotTeam][refiHighestBrainBuildMultiplier]..'; subrefiTeamMassStored='..tTeamData[iAiBotTeam][subrefiTeamMassStored]..'; desired mass='..4 * tTeamData[iAiBotTeam][subrefiHighestFriendlyAirFactoryTech] * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] * tTeamData[iAiBotTeam][refiHighestBrainBuildMultiplier]  - tTeamData[iAiBotTeam][subrefiTeamMassStored] / 150) end
        if not(AiBotMap.bIsCampaignMap) or tTeamData[iAiBotTeam][subrefiTeamGrossMass] >= 4 * tTeamData[iAiBotTeam][subrefiHighestFriendlyAirFactoryTech] * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] * tTeamData[iAiBotTeam][refiHighestBrainBuildMultiplier] - tTeamData[iAiBotTeam][subrefiTeamMassStored] / 150  then
            local bWantUpgrade = false
            --Prioritise air factory if we dont have T2 air and enemy has navy
            local bAirSubteamNeedsTorps = false
            local tiAirSubteams = {}
            for iBrain, oBrain in tTeamData[iAiBotTeam][subreftoFriendlyActiveAiBotBrains] do
                tiAirSubteams[oBrain.AiBotAirSubteam] = true
            end
            for iAirSubteam, bTrue in tiAirSubteams do
                if tAirSubteamData[iAirSubteam][refbNoAvailableTorpsForEnemies] then
                    bAirSubteamNeedsTorps = true
                    break
                end
            end

            --Upgrading from T2 to T3 - Do we only have 1 air fac for the brain, and has it not yet built at least 5 units of that tech (or 15 of any tech) yet?
            local bWaitUntilBuiltMoreUnits = false
            if tTeamData[iAiBotTeam][subrefiLowestFriendlyAirFactoryTech] == 2 and tTeamData[iAiBotTeam][subrefiHighestEnemyAirTech] < 3 then
                bWaitUntilBuiltMoreUnits = true
                for iBrain, oBrain in tTeamData[iAiBotTeam][subreftoFriendlyActiveAiBotBrains] do
                    if not(oBrain[AiBotOverseer.refbPrioritiseLand]) and not(oBrain[AiBotOverseer.refbPrioritiseLowTech]) then
                        local tT2AirFactories = oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryAirFactory * categories.TECH2, false, true)
                        if AiBotUtilities.IsTableEmpty(tT2AirFactories) == false then
                            if bDebugMessages == true then LOG(sFunctionRef..': T2 air fac count for brain '..oBrain.Nickname..'='..table.getn(tT2AirFactories)) end
                            if table.getn(tT2AirFactories) >= 2 then
                                bWaitUntilBuiltMoreUnits = false
                                break
                            else
                                for iUnit, oUnit in tT2AirFactories do
                                    if bDebugMessages == true then LOG(sFunctionRef..': Lifetime build count for T2 air for factory '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'='..AiBotConditions.GetFactoryLifetimeCount(oUnit, categories.AIR * categories.TECH2)..'; Lifetime T1+T2 count='..AiBotConditions.GetFactoryLifetimeCount(oUnit, categories.TECH1 + categories.TECH2)) end
                                    if AiBotConditions.GetFactoryLifetimeCount(oUnit, categories.AIR * categories.TECH2) >= 5 or AiBotConditions.GetFactoryLifetimeCount(oUnit, categories.TECH1 + categories.TECH2) >= 15 then
                                        if bDebugMessages == true then LOG(sFunctionRef..': AIr fac has built enough T2 units for us to contemplate T3 upgrade') end
                                        bWaitUntilBuiltMoreUnits = false
                                        break
                                    end
                                end
                            end
                        end
                    end
                    if not(bWaitUntilBuiltMoreUnits) then break end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': bWaitUntilBuiltMoreUnits='..tostring(bWaitUntilBuiltMoreUnits)) end
            if not(bWaitUntilBuiltMoreUnits) then
                if tTeamData[iAiBotTeam][subrefiLowestFriendlyAirFactoryTech] < 2 and (bAirSubteamNeedsTorps or tTeamData[iAiBotTeam][subrefiHighestEnemyNavyTech] > 0) then
                    local tbBrainsWithActiveUpgradeByIndex = {}
                    if AiBotConditions.IsTableOfUnitsStillValid(tTeamData[iAiBotTeam][subreftTeamUpgradingHQs]) then
                        for iHQ, oHQ in tTeamData[iAiBotTeam][subreftTeamUpgradingHQs] do
                            if EntityCategoryContains(AiBotUnitInfo.refCategoryAirFactory, oHQ.UnitId) then
                                if not(oHQ:GetAIBrain():IsDefeated()) then
                                    tbBrainsWithActiveUpgradeByIndex[oHQ:GetAIBrain():GetArmyIndex()] = true
                                end
                            end
                        end
                    end
                    for iBrain, oBrain in tTeamData[iAiBotTeam][subreftoFriendlyActiveAiBotBrains] do
                        if not(tbBrainsWithActiveUpgradeByIndex[oBrain:GetArmyIndex()]) and oBrain[AiBotEconomy.refiOurHighestAirFactoryTech] > 0 and oBrain[AiBotEconomy.refiOurHighestAirFactoryTech] < 2 then
                            bWantUpgrade = true
                            AiBotEconomy.FindAndUpgradeUnitOfCategory(oBrain, AiBotUnitInfo.refCategoryAirHQ * categories.TECH1)
                        end
                    end
                end
                --Prioritise air factory if enemy has T3 air and we dont
                if not(bWantUpgrade) and tTeamData[iAiBotTeam][subrefiHighestFriendlyAirFactoryTech] < tTeamData[iAiBotTeam][subrefiHighestEnemyAirTech] and tTeamData[iAiBotTeam][subrefiHighestEnemyAirTech] >= 3 then
                    for iBrain, oBrain in tTeamData[iAiBotTeam][subreftoFriendlyActiveAiBotBrains] do
                        if bDebugMessages == true then LOG(sFunctionRef..': Enemy has t3 air and we dont, oBrain='..oBrain.Nickname..'; oBrain[AiBotEconomy.refiOurHighestAirFactoryTech]='..oBrain[AiBotEconomy.refiOurHighestAirFactoryTech]) end
                        if oBrain[AiBotEconomy.refiOurHighestAirFactoryTech] > 0 and oBrain[AiBotEconomy.refiOurHighestAirFactoryTech] < 3 and ((not(oBrain[AiBotOverseer.refbPrioritiseLand]) and not(oBrain[AiBotOverseer.refbPrioritiseLowTech])) or tTeamData[iAiBotTeam][refiConstructedExperimentalCount] > 0 or AiBotConditions.GetLifetimeBuildCount(oBrain, AiBotUnitInfo.refCategoryAirNonScout * AiBotUnitInfo.ConvertTechLevelToCategory(oBrain[AiBotEconomy.refiOurHighestAirFactoryTech])) >= 20) then
                            --Do we have any active air factory upgrades?
                            bWantUpgrade = not(DoesBrainHaveActiveHQUpgradesOfCategory(oBrain, AiBotUnitInfo.refCategoryAirHQ))
                            if bDebugMessages == true then LOG(sFunctionRef..': bWantUpgrade (based on if we have active HQ upgrades for air HQ)='..tostring(bWantUpgrade)) end
                            if bWantUpgrade then
                                if bDebugMessages == true then LOG(sFunctionRef..': Will try and upgrade for this tech level') end
                                AiBotEconomy.FindAndUpgradeUnitOfCategory(oBrain, AiBotUnitInfo.refCategoryAirHQ * AiBotUnitInfo.ConvertTechLevelToCategory(oBrain[AiBotEconomy.refiOurHighestAirFactoryTech]))
                            end
                        end
                    end
                end
                if not(bWantUpgrade) then
                    --Prioritise air fac if we already have T2 land and at least 4 mass per tick and 70 power per tick, or if we have 6 mass and 100 power, provided no current HQ upgrades
                    if bDebugMessages == true then LOG(sFunctionRef..': Our highest tech level='..tTeamData[iAiBotTeam][subrefiHighestFriendlyAirFactoryTech]..'; Enemy highest tech='..tTeamData[iAiBotTeam][subrefiHighestEnemyAirTech]..'; Gross energy='..tTeamData[iAiBotTeam][subrefiTeamGrossEnergy]..'; Highest resource mult='.. tTeamData[iAiBotTeam][refiHighestBrainResourceMultiplier]..'; Team T2+ engi lifetime count='..AiBotConditions.GetTeamLifetimeBuildCount(iAiBotTeam, AiBotUnitInfo.refCategoryEngineer - categories.TECH1)) end

                    if AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingHQs]) and tTeamData[iAiBotTeam][subrefiTeamGrossMass] >= 4 * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] * tTeamData[iAiBotTeam][refiHighestBrainBuildMultiplier] and tTeamData[iAiBotTeam][subrefiTeamGrossEnergy] >= 70 * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] * tTeamData[iAiBotTeam][refiHighestBrainBuildMultiplier] and (tTeamData[iAiBotTeam][subrefiHighestFriendlyLandFactoryTech] >= 2 or (tTeamData[iAiBotTeam][subrefiTeamGrossMass] >= 6 * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] * tTeamData[iAiBotTeam][refiHighestBrainBuildMultiplier] and tTeamData[iAiBotTeam][subrefiTeamGrossEnergy] >= 102 * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] * tTeamData[iAiBotTeam][refiHighestBrainBuildMultiplier]))
                            and (tTeamData[iAiBotTeam][subrefiHighestFriendlyAirFactoryTech] <= tTeamData[iAiBotTeam][subrefiHighestEnemyAirTech] or (tTeamData[iAiBotTeam][subrefiTeamGrossEnergy] >= 70 * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] * tTeamData[iAiBotTeam][refiHighestBrainResourceMultiplier] and AiBotConditions.GetTeamLifetimeBuildCount(iAiBotTeam, AiBotUnitInfo.refCategoryEngineer - categories.TECH1) >= 3 + 2 * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount]))
                    then
                        for iBrain, oBrain in tTeamData[iAiBotTeam][subreftoFriendlyActiveAiBotBrains] do
                            if oBrain[AiBotEconomy.refiOurHighestAirFactoryTech] > 0 and oBrain[AiBotEconomy.refiOurHighestAirFactoryTech] < 3 and (tTeamData[iAiBotTeam][refiConstructedExperimentalCount] > 0 or (not(oBrain[AiBotOverseer.refbPrioritiseLand]) and not(oBrain[AiBotOverseer.refbPrioritiseLowTech]))) then
                                --Do we have any active air factory upgrades? (redundancy - should already have excluded via above)
                                bWantUpgrade = not(DoesBrainHaveActiveHQUpgradesOfCategory(oBrain, AiBotUnitInfo.refCategoryAirHQ))
                                if bWantUpgrade then
                                    local iMinUnits = 4
                                    --Added below due to one scenario where our t2 air fac started a t3 upgrade despite nearby enemy navy
                                    if tTeamData[iAiBotTeam][subrefiHighestEnemyAirTech] < 3 and oBrain[AiBotEconomy.refiOurHighestAirFactoryTech] == 2 then
                                        local iCurAirFactories = oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryAirFactory * categories.TECH2)
                                        if iCurAirFactories <= 1 then
                                            iMinUnits = 10
                                        elseif iCurAirFactories == 2 then
                                            iMinUnits = 7
                                        end
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': iMinUnits='..iMinUnits..'; oBrain='..oBrain.Nickname) end
                                    AiBotEconomy.FindAndUpgradeUnitOfCategory(oBrain, AiBotUnitInfo.refCategoryAirHQ * AiBotUnitInfo.ConvertTechLevelToCategory(oBrain[AiBotEconomy.refiOurHighestAirFactoryTech]), iMinUnits)
                                end
                            end
                        end
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ConsiderPriorityNavalFactoryUpgrades(iAiBotTeam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderPriorityNavalFactoryUpgrades'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, time='..GetGameTimeSeconds()..'; tTeamData[iAiBotTeam][subrefiHighestFriendlyNavalFactoryTech]='..tTeamData[iAiBotTeam][subrefiHighestFriendlyNavalFactoryTech]) end

    if tTeamData[iAiBotTeam][subrefiHighestFriendlyNavalFactoryTech] > 0 and tTeamData[iAiBotTeam][subrefiHighestFriendlyNavalFactoryTech] < math.min(3, tTeamData[iAiBotTeam][subrefiHighestEnemyNavyTech]) then
        local bWantUpgrade = false
        for iBrain, oBrain in tTeamData[iAiBotTeam][subreftoFriendlyActiveAiBotBrains] do
            if bDebugMessages == true then LOG(sFunctionRef..': Considering brain '..oBrain.Nickname..'; Highest naval tech='..oBrain[AiBotEconomy.refiOurHighestNavalFactoryTech]..'; Highest air tech='..oBrain[AiBotEconomy.refiOurHighestAirFactoryTech]..'; Highest enemy naval tech='..tTeamData[iAiBotTeam][subrefiHighestEnemyNavyTech]) end
            if not(oBrain[AiBotOverseer.refbPrioritiseLowTech]) and oBrain[AiBotEconomy.refiOurHighestNavalFactoryTech] > 0 and oBrain[AiBotEconomy.refiOurHighestAirFactoryTech] < math.min(3, tTeamData[iAiBotTeam][subrefiHighestEnemyNavyTech]) then
                --Do we have any active air factory upgrades?
                bWantUpgrade = not(DoesBrainHaveActiveHQUpgradesOfCategory(oBrain, AiBotUnitInfo.refCategoryNavalHQ))

                if bWantUpgrade then
                    --First check total build count of naval factories
                    local tNavalFactories
                    if tTeamData[iAiBotTeam][subrefiHighestFriendlyNavalFactoryTech] == 2 then tNavalFactories = oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryNavalFactory * categories.TECH2, false, true)
                    else tNavalFactories = oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryNavalFactory, false, true)
                    end
                    local iTotalBuildCount = 0
                    if AiBotUtilities.IsTableEmpty(tNavalFactories) == false then
                        for iFactory, oFactory in tNavalFactories do
                            iTotalBuildCount = iTotalBuildCount + (oFactory[AiBotFactory.refiTotalBuildCount] or 0)
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': iTotalBuildCount='..iTotalBuildCount..'; tTeamData[iAiBotTeam][subrefiHighestFriendlyNavalFactoryTech]='..tTeamData[iAiBotTeam][subrefiHighestFriendlyNavalFactoryTech]) end

                    --Campaign maps where still relatively early, or games where we have poor gross mass, where considering upgrading to T3 (or T2 if have built fewer than 4 units)
                    if iTotalBuildCount <= 8 and tTeamData[iAiBotTeam][subrefiHighestFriendlyNavalFactoryTech] <= 2 then
                        local iEcoConditionFactor = 1
                        if tTeamData[iAiBotTeam][subrefiHighestFriendlyNavalFactoryTech] == 1 then iEcoConditionFactor = 0.3 end
                        iEcoConditionFactor = iEcoConditionFactor * tTeamData[iAiBotTeam][refiHighestBrainBuildMultiplier]
                        if AiBotMap.bIsCampaignMap and GetGameTimeSeconds() <= 600 and tTeamData[iAiBotTeam][subrefiTeamGrossMass] <= 20 * iEcoConditionFactor then
                            bWantUpgrade = false
                        elseif tTeamData[iAiBotTeam][subrefiTeamGrossMass] <= 10 * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] * iEcoConditionFactor then
                            --Only upgrade to T3 if we have built a number of T2 units
                            if iTotalBuildCount <= 8 then
                                bWantUpgrade = false
                            end
                        elseif iTotalBuildCount <= 4 then
                            bWantUpgrade = false
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': We have lower naval tech than enemy, and dont have an active HQ upgrade, bWantUpgrade after low mass checks='..tostring(bWantUpgrade)) end
                    if bWantUpgrade then
                        AiBotEconomy.FindAndUpgradeUnitOfCategory(oBrain, AiBotUnitInfo.refCategoryNavalHQ * AiBotUnitInfo.ConvertTechLevelToCategory(oBrain[AiBotEconomy.refiOurHighestNavalFactoryTech]))
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ConsiderPriorityMexUpgrades(iAiBotTeam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderPriorityMexUpgrades'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..'; Is table of upgrading mexes empty='..tostring(AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingMexes]))..'; tTeamData[iAiBotTeam][subrefiTeamMassStored]='..tTeamData[iAiBotTeam][subrefiTeamMassStored]..'; tTeamData[iAiBotTeam][subrefiTeamNetMass]='..tTeamData[iAiBotTeam][subrefiTeamNetMass]..'; tTeamData[iAiBotTeam][subrefiMassUpgradesStartedThisCycle]='..tTeamData[iAiBotTeam][subrefiMassUpgradesStartedThisCycle]..'; or AiBotOverseer.bNoRushActive='..tostring(AiBotOverseer.bNoRushActive or false)) end
    local iExistingT1MexUpgrades = 0
    local iExistingT2MexUpgrades = 0
    local iExistingT3PlusMexUpgrades = 0 --e.g. loud which allows T3 to be ugpraded into t4, with t4 often being more efficient; hence want to treat these as less significant as t2 upgrades to avoid significantly slowing down ecoing
    if not(tTeamData[iAiBotTeam][refbFocusOnT1Spam]) or (tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored] >= 0.95 and tTeamData[iAiBotTeam][subrefiTeamNetEnergy] > 1 and tTeamData[iAiBotTeam][subrefiTeamAverageEnergyPercentStored] >= 0.98 and AiBotConditions.GetCurrentAiBotUnitsOfCategoryInTeam(AiBotUnitInfo.refCategoryFactory, iAiBotTeam) >= 4) then
        if AiBotConditions.IsTableOfUnitsStillValid(tTeamData[iAiBotTeam][subreftTeamUpgradingMexes])  then
            for iUpgradingMex, oUpgradingMex in tTeamData[iAiBotTeam][subreftTeamUpgradingMexes] do
                if EntityCategoryContains(categories.TECH1, oUpgradingMex.UnitId) then
                    iExistingT1MexUpgrades = iExistingT1MexUpgrades + 1
                elseif EntityCategoryContains(categories.TECH2, oUpgradingMex.UnitId) then
                    iExistingT2MexUpgrades = iExistingT2MexUpgrades + 1
                else
                    iExistingT3PlusMexUpgrades = iExistingT3PlusMexUpgrades + 1
                    --AiBotUtilities.ErrorHandler('Are somehow upgrading a mex  that is neither t1 nor t2')
                end
            end
        end
        --T1 mex upgrading to T2 = c.8 mass per sec; T2 to T3 = c.18 mass per sec; so treat 1 T2 mex upgrading as equiv to 2.5 T1 mex
        --Want to be spending at least 1/3 of gross income on upgrading mexes assuming we have safe mexes to upgrade
        local bHaveSafeMexToUpgrade = GetSafeMexToUpgrade(iAiBotTeam, true)
        local iUpgradingMexValue = iExistingT1MexUpgrades + 2.5 * iExistingT2MexUpgrades + iExistingT3PlusMexUpgrades * 1.5
        local iWantedUpgradingMexValue = 0
        local bBehindOnT3OrNotStartedT2Mex = false
        local iMexesOnMap = table.getn(AiBotMap.tMassPoints)
        if tTeamData[iAiBotTeam][subrefiTeamGrossMass] >= 2.5 * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] then
            --if tTeamData[iAiBotTeam][subrefiTeamGrossMass] >= 2.5 * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] and iMexesOnMap > 60 then
            iWantedUpgradingMexValue = 1
            if not(tTeamData[iAiBotTeam][subrefbTeamIsStallingEnergy]) then
                if tTeamData[iAiBotTeam][subrefiTeamGrossMass] >= 12 or AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive then
                    iWantedUpgradingMexValue = iWantedUpgradingMexValue + 1
                end
                if tTeamData[iAiBotTeam][refiMexCountByTech][3] < AiBotConditions.GetHighestOtherTeamT3MexCount(iAiBotTeam) then
                    bBehindOnT3OrNotStartedT2Mex = true
                    iWantedUpgradingMexValue = iWantedUpgradingMexValue * 1.5
                    if AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive then iWantedUpgradingMexValue = iWantedUpgradingMexValue + 1 end
                end
                if (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and tTeamData[iAiBotTeam][subrefiTeamAverageEnergyPercentStored] >= 0.5 and tTeamData[iAiBotTeam][subrefiTeamGrossEnergy] >= 12 * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] then
                    --Further increases
                    if tTeamData[iAiBotTeam][subrefiTeamGrossMass] >= 6 then iWantedUpgradingMexValue = iWantedUpgradingMexValue + 1 end
                end
            end
        elseif (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and tTeamData[iAiBotTeam][subrefiTeamAverageEnergyPercentStored] >= 0.5 and not(tTeamData[iAiBotTeam][subrefbTeamIsStallingEnergy]) and tTeamData[iAiBotTeam][subrefiTeamGrossEnergy] >= 12 * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] and tTeamData[iAiBotTeam][subrefiTeamGrossMass] >= 1.25 * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] then
            iWantedUpgradingMexValue = 1
            if tTeamData[iAiBotTeam][subrefiTeamGrossMass] >= 6 and (tTeamData[iAiBotTeam][refiMexCountByTech][3] == 0 or tTeamData[iAiBotTeam][refiMexCountByTech][3] >= 4) then iWantedUpgradingMexValue = iWantedUpgradingMexValue + 1 end
            if tTeamData[iAiBotTeam][refiMexCountByTech][3] < AiBotConditions.GetHighestOtherTeamT3MexCount(iAiBotTeam) then
                bBehindOnT3OrNotStartedT2Mex = true
                iWantedUpgradingMexValue = iWantedUpgradingMexValue * 1.5 + 1
            end
            --[[elseif tTeamData[iAiBotTeam][subrefiTeamGrossMass] >= 1.25 * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] and iMexesOnMap <= 60 then
                iWantedUpgradingMexValue = 2
                if tTeamData[iAiBotTeam][subrefiTeamGrossMass] >= 6 then iWantedUpgradingMexValue = iWantedUpgradingMexValue + 2 end
                if tTeamData[iAiBotTeam][refiMexCountByTech] < AiBotConditions.GetHighestOtherTeamT3MexCount(iAiBotTeam) then
                    bBehindOnT3OrNotStartedT2Mex = true
                    iWantedUpgradingMexValue = iWantedUpgradingMexValue * 3
                end--]]
        end
        if not(bBehindOnT3OrNotStartedT2Mex) and tTeamData[iAiBotTeam][refiMexCountByTech][3] == 0 then
            local iOurT2MexCount = tTeamData[iAiBotTeam][refiMexCountByTech][2]
            local iEnemyT2AndT3MexCount = AiBotConditions.GetHighestOtherTeamT2AndT3MexCount(iAiBotTeam)
            if iEnemyT2AndT3MexCount >= math.max(2, 2 * iOurT2MexCount) then
                bBehindOnT3OrNotStartedT2Mex = true
            end
        end
        if bHaveSafeMexToUpgrade or AiBotOverseer.bNoRushActive then
            --if upgrading 1 mex from t1 to t2 costs roughly 0.8 mass per tick, and we want to be spenting 1/3 of mass per tick on this, then want 1/3 of gross mass / 0.8, i.e. 0.4167
            --However, are finding we are spending too much mass with this approach and end up always mass stalling, and only upgrading mexes, meaning HQs dont upgrade (when using a value of 0.4167 * gross mass income)
            iWantedUpgradingMexValue = math.max(iWantedUpgradingMexValue, (tTeamData[iAiBotTeam][subrefiTeamGrossMass] - 2 * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount]) * 0.3, tTeamData[iAiBotTeam][subrefiTeamGrossMass] * 0.125)
            --if are already upgrading 1 mex per brain and are stalling mass, then reduce the amount wanted
            if (tTeamData[iAiBotTeam][subrefiTeamMassStored] < 50 or tTeamData[iAiBotTeam][subrefbTeamIsStallingMass]) and AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingMexes]) == false and (table.getn(tTeamData[iAiBotTeam][subreftTeamUpgradingMexes]) > 1 + (tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] - 1) * 0.5 and tTeamData[iAiBotTeam][subrefiTeamNetMass] <= -math.max(-0.5, tTeamData[iAiBotTeam][subrefiTeamGrossMass] * 0.08)) then
                iWantedUpgradingMexValue = iWantedUpgradingMexValue * 0.2
            end
            --Adjust maount wanted for any build power modifier
            iWantedUpgradingMexValue = iWantedUpgradingMexValue / tTeamData[iAiBotTeam][refiHighestBrainBuildMultiplier]
        end

        local bWantMassForProduction = false
        for _, iAirSubteam in tTeamData[iAiBotTeam][subrefAirSubteamsInTeam] do
            if tAirSubteamData[iAirSubteam][refbNoAvailableTorpsForEnemies] then
                bWantMassForProduction = true
                break
            end
        end

        if bDebugMessages == true then LOG(sFunctionRef..': bWantMassForProduction='..tostring(bWantMassForProduction)..'; Is table of upgrading mexes empty='..tostring( AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingMexes]))..'; Is table of upgrading HQs empty='..tostring(AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingHQs]))) end
        if not(bWantMassForProduction) or AiBotOverseer.bNoRushActive or (bBehindOnT3OrNotStartedT2Mex and not(tTeamData[iAiBotTeam][subrefbTeamIsStallingMass])) or (AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingMexes]) and AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingHQs])) then
            local bPrioritiseProduction = false
            local tbLandSubteams = {}
            for iBrain, oBrain in tTeamData[iAiBotTeam][subreftoFriendlyActiveAiBotBrains] do
                tbLandSubteams[oBrain.AiBotLandSubteam] = true
            end
            for iLandSubteam, _ in  tbLandSubteams do
                if tLandSubteamData[iLandSubteam][refbPrioritiseProduction] then bPrioritiseProduction = true break end
            end

            if (not(tTeamData[iAiBotTeam][refbFocusOnT1Spam]) and not(bPrioritiseProduction)) or AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingMexes]) or table.getn(tTeamData[iAiBotTeam][subreftTeamUpgradingMexes]) * 2 + 4 <= AiBotConditions.GetCurrentAiBotUnitsOfCategoryInTeam(AiBotUnitInfo.refCategoryFactory, iAiBotTeam) then
                if bDebugMessages == true then LOG(sFunctionRef..': iWantedUpgradingMexValue='..iWantedUpgradingMexValue..'; iUpgradingMexValue='..iUpgradingMexValue..'; bHaveSafeMexToUpgrade='..tostring(bHaveSafeMexToUpgrade)..'; iExistingT1MexUpgrades='..iExistingT1MexUpgrades..'; iExistingT2MexUpgrades='..iExistingT2MexUpgrades..'; iExistingT3PlusMexUpgrades='..iExistingT3PlusMexUpgrades..'; Active brain count='..tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount]..'; Total mass stored='..tTeamData[iAiBotTeam][subrefiTeamMassStored]) end
                if AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingMexes]) or iWantedUpgradingMexValue > iUpgradingMexValue or (tTeamData[iAiBotTeam][subrefiTeamMassStored] >= 800 and (tTeamData[iAiBotTeam][subrefiTeamNetMass] - tTeamData[iAiBotTeam][subrefiMassUpgradesStartedThisCycle]) > 0) then
                    --Do we have enough energy?
                    if bDebugMessages == true then LOG(sFunctionRef..': Checking if we have enough energy, tTeamData[iAiBotTeam][subrefiTeamNetEnergy]='..tTeamData[iAiBotTeam][subrefiTeamNetEnergy]..'; tTeamData[iAiBotTeam][subrefiEnergyUpgradesStartedThisCycle]='..tTeamData[iAiBotTeam][subrefiEnergyUpgradesStartedThisCycle]..'; tTeamData[iAiBotTeam][subrefiTeamAverageEnergyPercentStored]='..tTeamData[iAiBotTeam][subrefiTeamAverageEnergyPercentStored]) end
                    if (tTeamData[iAiBotTeam][subrefiTeamNetEnergy] - tTeamData[iAiBotTeam][subrefiEnergyUpgradesStartedThisCycle] > 0 or (AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingMexes]) and tTeamData[iAiBotTeam][subrefiTeamAverageEnergyPercentStored] >= 0.98)) and
                            (tTeamData[iAiBotTeam][subrefiTeamAverageEnergyPercentStored] >= 0.75 or tTeamData[iAiBotTeam][subrefiTeamNetEnergy] - tTeamData[iAiBotTeam][subrefiEnergyUpgradesStartedThisCycle] >= 5) then
                        --Do we have mexes in start positions that are lower than the enemy's highest tech, or 2 lower than the highest mex in that LZ? Or are in norush mode? Or just want to be spending more mass on upgrading safe mexes?
                        local iTechLevelToUpgrade = math.min(3, (tTeamData[iAiBotTeam][subrefiHighestFriendlyFactoryTech] or 1)) - 1 --, (tTeamData[iAiBotTeam][subrefiHighestEnemyMexTech] or 0))) - 1
                        if AiBotOverseer.bNoRushActive then iTechLevelToUpgrade = math.max(1, iTechLevelToUpgrade) end

                        if (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and (tTeamData[iAiBotTeam][subrefiTeamGrossEnergy] >= 25 * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] or iMexesOnMap <= 20 * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount]) then
                            iTechLevelToUpgrade = math.max(1, iTechLevelToUpgrade)
                            if tTeamData[iAiBotTeam][subrefiTeamGrossMass] > tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] * 6 then
                                iTechLevelToUpgrade = 2
                            elseif tTeamData[iAiBotTeam][subrefiTeamGrossMass] > tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] * 3 and iMexesOnMap <= 20 * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] then
                                iTechLevelToUpgrade = 2
                            end
                        end

                        if iTechLevelToUpgrade <= 0 and tTeamData[iAiBotTeam][subrefiTeamMassStored] >= 1000 and ( tTeamData[iAiBotTeam][subrefiTeamMassStored] >= 1600 or tTeamData[iAiBotTeam][subrefiTeamNetMass] > 0 or (tTeamData[iAiBotTeam][subrefiTeamMassStored] >= 1250 and tTeamData[iAiBotTeam][subrefiTeamNetMass] > -1)) and (tTeamData[iAiBotTeam][subrefiTeamAverageEnergyPercentStored] >= 0.7 or ((AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and tTeamData[iAiBotTeam][subrefiTeamNetEnergy] > 0)) and (tTeamData[iAiBotTeam][subrefiTeamEnergyStored] >= 9000 or tTeamData[iAiBotTeam][subrefiTeamAverageEnergyPercentStored] >= 0.9) and tTeamData[iAiBotTeam][subrefiTeamGrossEnergy] >= 30 then iTechLevelToUpgrade = 1 end

                        --Dont upgrade if have ACUs in rush mode on the team and are already upgrading
                        if iTechLevelToUpgrade >= 1 and AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingMexes]) == false then
                            local iNormalBrains = 0
                            local iRushBrains = 0
                            for iBrain, oBrain in tTeamData[iAiBotTeam][subreftoFriendlyActiveAiBotBrains] do
                                if oBrain[AiBotOverseer.refbPrioritiseLowTech] then iRushBrains = iRushBrains + 1
                                else iNormalBrains = iNormalBrains + 1
                                end
                            end
                            if iRushBrains > 0 then
                                local iUpgradingMexes = table.getn(tTeamData[iAiBotTeam][subreftTeamUpgradingMexes])
                                if iUpgradingMexes > iNormalBrains * 2 then iTechLevelToUpgrade = 0 end
                            end
                        end

                        --Override techlevel to upgrade
                        if iTechLevelToUpgrade >= 2 and not(AiBotConditions.WantAnotherT3MexUpgrade(iAiBotTeam)) then iTechLevelToUpgrade = 1 end

                        if bDebugMessages == true then LOG(sFunctionRef..': iTechLevelToUpgrade='..iTechLevelToUpgrade..'; tTeamData[iAiBotTeam][subrefiHighestFriendlyFactoryTech]='..tTeamData[iAiBotTeam][subrefiHighestFriendlyFactoryTech]..'; bHaveSafeMexToUpgrade='..tostring(bHaveSafeMexToUpgrade or false)) end
                        if iTechLevelToUpgrade >= 1 then
                            if bHaveSafeMexToUpgrade then
                                GetSafeMexToUpgrade(iAiBotTeam, false, iTechLevelToUpgrade <= 1)
                            else

                                --If dont have safe mex to upgrade - cycle through each brain looking for mex to upgrade
                                local iPlateau, iLandZone, tMexesToConsiderUpgrading
                                local bAbort = false

                                --Want to be upgrading at least 1 mex on our team, or more if we have positive mass income, subject to gross income
                                local tiExtraMassStoredPerUpgrade = {[1] = 300, [2] = 1000, [3] = 300} --T3 - if in LOUD then makes sense to upgrade a T3 mex to advanced T3 mex immediately; will usually happen via separate code ,but put in here for niche cases where this logic would try and upgrade
                                local iMassStoredToKeepUpgrading = 0
                                if AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingMexes]) == false then
                                    for iUnit, oUnit in tTeamData[iAiBotTeam][subreftTeamUpgradingMexes] do
                                        iMassStoredToKeepUpgrading = iMassStoredToKeepUpgrading + tiExtraMassStoredPerUpgrade[AiBotUnitInfo.GetUnitTechLevel(oUnit)]
                                    end
                                end

                                for iBrain, oBrain in tTeamData[iAiBotTeam][subreftoFriendlyActiveAiBotBrains] do
                                    bAbort = false
                                    iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(AiBotMap.GetPlayerStartPosition(oBrain))
                                    local tLZOrWZTeamData
                                    if (iLandZone or 0) > 0 then
                                        tLZOrWZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTeamData][iAiBotTeam]
                                    else
                                        local iWaterZone = AiBotMap.GetWaterZoneFromPosition(AiBotMap.GetPlayerStartPosition(oBrain))
                                        if (iWaterZone or 0) > 0 then
                                            tLZOrWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iWaterZone]][AiBotMap.subrefPondWaterZones][iWaterZone][AiBotMap.subrefWZTeamData][iAiBotTeam]
                                        end
                                    end
                                    --Want base to always have a mex of the desired tech level upgrading; however dont do priority upgrade if this location already has an upgrade, unless we have high mass income for this brain and T1 mexes
                                    if bDebugMessages == true then LOG(sFunctionRef..': Does brain '..oBrain.Nickname..' have an empty table of active upgrades in its start position LZ/WZ='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoActiveUpgrades]))) end
                                    if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subreftoActiveUpgrades]) or (oBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 4 and tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][1] > 0) then
                                        for iMexTech = 1, iTechLevelToUpgrade do
                                            if bDebugMessages == true then LOG(sFunctionRef..': Considering mexes for iMexTech='..iMexTech..'; count='..tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][iMexTech]) end
                                            if tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][iMexTech] > 0 then
                                                tMexesToConsiderUpgrading = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMex * AiBotUnitInfo.ConvertTechLevelToCategory(iMexTech), tLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                                                if AiBotUtilities.IsTableEmpty(tMexesToConsiderUpgrading) == false then
                                                    for iMex, oMex in tMexesToConsiderUpgrading do
                                                        if not(oMex:IsUnitState('Upgrading')) and oMex:GetFractionComplete() == 1 and not(oMex.Dead) then
                                                            if oMex:GetAIBrain().AiBotAI and oMex:GetAIBrain().AiBotTeam == iAiBotTeam then
                                                                if bDebugMessages == true then LOG(sFunctionRef..': Will try to upgrade mex in starting zone, iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; Mex='..oMex.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oMex)..'; Owned by '..oMex:GetAIBrain().Nickname..'; Mex unit state='..AiBotUnitInfo.GetUnitState(oMex)) end
                                                                AiBotEconomy.UpgradeUnit(oMex, true)
                                                                iMassStoredToKeepUpgrading = iMassStoredToKeepUpgrading + tiExtraMassStoredPerUpgrade[iMexTech]
                                                                bAbort = true
                                                                break
                                                            end
                                                        end
                                                    end
                                                end
                                            end
                                            if bAbort then break end
                                        end
                                    end
                                    if bAbort then
                                        --Do we have positive mass income or lots of mass stored? If so then proceed to upgrade for other brains
                                        if tTeamData[iAiBotTeam][subrefiTeamNetEnergy] - tTeamData[iAiBotTeam][subrefiEnergyUpgradesStartedThisCycle] > 0 then
                                            if (tTeamData[iAiBotTeam][subrefiTeamNetMass] - tTeamData[iAiBotTeam][subrefiMassUpgradesStartedThisCycle]) > 0 or tTeamData[iAiBotTeam][subrefiTeamMassStored] >= iMassStoredToKeepUpgrading then
                                                bAbort = false
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function AddPotentialUnitsToShortlist(toUnitShortlist, tPotentialUnits, bDontCheckIfSafe, iOptionalHighestTechBuildCountRequirement)
    if AiBotUtilities.IsTableEmpty(tPotentialUnits) == false then
        for iUnit, oUnit in tPotentialUnits do
            if AiBotUnitInfo.IsUnitValid(oUnit) and not(oUnit:IsUnitState('Upgrading')) and oUnit:GetFractionComplete() == 1 then
                --Extra check for factories
                if not(AiBotConditions.CheckIfNeedMoreEngineersOrSnipeUnitsBeforeUpgrading(oUnit)) then
                    local bUnitIsHighestTechFactoryForOptionalCount = false
                    if not(iOptionalHighestTechBuildCountRequirement) then bUnitIsHighestTechFactoryForOptionalCount = true
                    else
                        local iUnitTechLevel = AiBotUnitInfo.GetUnitTechLevel(oUnit)
                        if iUnitTechLevel >= 3 then bUnitIsHighestTechFactoryForOptionalCount = true
                        else
                            if EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory, oUnit.UnitId) then
                                if iUnitTechLevel >= oUnit:GetAIBrain()[AiBotEconomy.refiOurHighestLandFactoryTech] then bUnitIsHighestTechFactoryForOptionalCount = true end

                            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryAirFactory, oUnit.UnitId) then
                                if iUnitTechLevel >= oUnit:GetAIBrain()[AiBotEconomy.refiOurHighestAirFactoryTech] then bUnitIsHighestTechFactoryForOptionalCount = true end
                            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryNavalFactory, oUnit.UnitId) then
                                if iUnitTechLevel >= oUnit:GetAIBrain()[AiBotEconomy.refiOurHighestNavalFactoryTech] then bUnitIsHighestTechFactoryForOptionalCount = true end
                            end
                        end
                    end
                    if (not(bUnitIsHighestTechFactoryForOptionalCount) or iOptionalHighestTechBuildCountRequirement <= (oUnit[AiBotFactory.refiTotalBuildCount] or 0)) and (bDontCheckIfSafe or AiBotConditions.SafeToUpgradeUnit(oUnit)) then
                        table.insert(toUnitShortlist, oUnit)
                    end
                end
            end
        end
    end
end

function GetSafeMexToUpgrade(iAiBotTeam, bReturnIfSafeInsteadOfUpgrading, bDontUpgradeT2Plus)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetSafeMexToUpgrade'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local toSafeUnitsToUpgrade = {}
    local tPotentialUnits
    local tiMexCategory
    if bDontUpgradeT2Plus then
        --Dont want to upgrade t2 mexes as we have enough upgrading already
        tiMexCategory = {[1] = AiBotUnitInfo.refCategoryT1Mex}
    else
        --First prioritise T1 mexes
        tiMexCategory = {[1] = AiBotUnitInfo.refCategoryT1Mex, [2]=AiBotUnitInfo.refCategoryT2Mex}
        if AiBotEconomy.bT3MexCanBeUpgraded then table.insert(tiMexCategory, AiBotUnitInfo.refCategoryT3Mex) end
    end
    for iTech, iMexCategory in tiMexCategory do
        for iBrain, oBrain in tTeamData[iAiBotTeam][subreftoFriendlyActiveAiBotBrains] do
            tPotentialUnits = oBrain:GetListOfUnits(iMexCategory, false, true)
            AddPotentialUnitsToShortlist(toSafeUnitsToUpgrade, tPotentialUnits)
        end
        if AiBotUtilities.IsTableEmpty(toSafeUnitsToUpgrade) == false then
            break
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Finished searching for units to upgrade at time '..GetGameTimeSeconds()..', is table empty='..tostring(AiBotUtilities.IsTableEmpty(toSafeUnitsToUpgrade))) end
    if bReturnIfSafeInsteadOfUpgrading then
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return not(AiBotUtilities.IsTableEmpty(toSafeUnitsToUpgrade))
    else
        if AiBotUtilities.IsTableEmpty(toSafeUnitsToUpgrade) == false then

            local oUnitToUpgrade = AiBotEconomy.GetBestUnitToUpgrade(toSafeUnitsToUpgrade)
            if bDebugMessages == true then LOG(sFunctionRef..': Have a total of '..table.getn(toSafeUnitsToUpgrade)..' units to upgrade, will pick the best one, oUnitToUpgrade = '..(oUnitToUpgrade.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnitToUpgrade) or 'nil')) end
            if oUnitToUpgrade then
                if bDebugMessages == true then LOG(sFunctionRef..': Will try to upgrade unit '..oUnitToUpgrade.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitToUpgrade)) end
                AiBotEconomy.UpgradeUnit(oUnitToUpgrade, true)
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GetSafeHQUpgrade(iAiBotTeam, bOnlyConsiderLandFactory)
    --if bRunningThisAsBackupUpgradeOption then wont upgrade T2 land fac that hasnt built much
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetSafeHQUpgrade'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local toSafeUnitsToUpgrade = {}
    local tPotentialUnits

    --First identify any players that have a T1 land or air HQ
    for iBrain, oBrain in tTeamData[iAiBotTeam][subreftoFriendlyActiveAiBotBrains] do
        if bDebugMessages == true then LOG(sFunctionRef..': Considering brain '..oBrain.Nickname..'; Highest air fac tech='..oBrain[AiBotEconomy.refiOurHighestAirFactoryTech]..'; Highest land fac tech='..oBrain[AiBotEconomy.refiOurHighestLandFactoryTech]..'; bOnlyConsiderLandFactory='..tostring(bOnlyConsiderLandFactory or false)) end
        if oBrain[AiBotEconomy.refiOurHighestAirFactoryTech] == 1 and (not(bOnlyConsiderLandFactory) or oBrain[AiBotOverseer.refbPrioritiseAir]) and (not(oBrain[AiBotOverseer.refbPrioritiseLand]) or oBrain[AiBotEconomy.refiOurHighestLandFactoryTech] > 2) then
            if not(DoesBrainHaveActiveHQUpgradesOfCategory(oBrain, AiBotUnitInfo.refCategoryAirHQ)) then
                --Check we dont already have an active upgrade
                tPotentialUnits = oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryAirHQ * categories.TECH1, false, true)
                AddPotentialUnitsToShortlist(toSafeUnitsToUpgrade, tPotentialUnits)
            end
        end
        if oBrain[AiBotEconomy.refiOurHighestLandFactoryTech] == 1 and (not(oBrain[AiBotOverseer.refbPrioritiseAir]) or oBrain[AiBotEconomy.refiOurHighestAirFactoryTech] > 2) and (not(oBrain[AiBotOverseer.refbPrioritiseNavy] or oBrain[AiBotEconomy.refiOurHighestNavalFactoryTech] >= 2 or oBrain[AiBotEconomy.refiOurHighestAirFactoryTech] >= 3)) then
            if bDebugMessages == true then LOG(sFunctionRef..': Does brain have active Land HQ upgrades='..tostring(DoesBrainHaveActiveHQUpgradesOfCategory(oBrain, AiBotUnitInfo.refCategoryLandHQ))) end
            if not(DoesBrainHaveActiveHQUpgradesOfCategory(oBrain, AiBotUnitInfo.refCategoryLandHQ)) then
                tPotentialUnits = oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryLandHQ * categories.TECH1, false, true)
                if bDebugMessages == true then LOG(sFunctionRef..': Adding T1 land HQs to shortlist, is tPotentialUnits empty='..tostring(AiBotUtilities.IsTableEmpty(tPotentialUnits))) end
                AddPotentialUnitsToShortlist(toSafeUnitsToUpgrade, tPotentialUnits)
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Finished checking for units to upgrade, is table of safe units empty='..tostring(AiBotUtilities.IsTableEmpty(toSafeUnitsToUpgrade))) end
    if AiBotUtilities.IsTableEmpty(toSafeUnitsToUpgrade) then
        --Get T2 upgrades if all our land and air are at T2
        if not(tTeamData[iAiBotTeam][refbFocusOnT1Spam]) then
            for iBrain, oBrain in tTeamData[iAiBotTeam][subreftoFriendlyActiveAiBotBrains] do
                if oBrain[AiBotEconomy.refiOurHighestAirFactoryTech] == 2 and (not(bOnlyConsiderLandFactory) or oBrain[AiBotOverseer.refbPrioritiseAir]) and (not(oBrain[AiBotOverseer.refbPrioritiseLand]) or oBrain[AiBotEconomy.refiOurHighestLandFactoryTech] > 2) then
                    if not(DoesBrainHaveActiveHQUpgradesOfCategory(oBrain, AiBotUnitInfo.refCategoryAirHQ)) then
                        --If we need torp bombers then be less likely to upgrade
                        tPotentialUnits = oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryAirHQ * categories.TECH2, false, true)
                        --Dont add factories that havent built much (for air fac will consider T1+ since may be building inties
                        local iLifetimeThreshold = 5
                        if tAirSubteamData[oBrain.AiBotSubteamData][refbNoAvailableTorpsForEnemies] then iLifetimeThreshold = 20 end
                        if bDebugMessages == true then LOG(sFunctionRef..': Added table of air facs for brain '..oBrain.Nickname..'; is tPotentialUnits empty='..tostring(AiBotUtilities.IsTableEmpty(tPotentialUnits))..'; iLifetimeThreshold='..iLifetimeThreshold..'; tAirSubteamData[oBrain.AiBotSubteamData][refbNoAvailableTorpsForEnemies]='..tostring(tAirSubteamData[oBrain.AiBotSubteamData][refbNoAvailableTorpsForEnemies] or false)) end
                        for iFactory, oFactory in tPotentialUnits do
                            if AiBotConditions.GetFactoryLifetimeCount(oFactory, categories.MOBILE - AiBotUnitInfo.refCategoryAirScout) > iLifetimeThreshold or (oBrain[AiBotEconomy.refiOurHighestAirFactoryTech] <= oBrain[AiBotEconomy.refiOurHighestLandFactoryTech] and not(tAirSubteamData[oBrain.AiBotSubteamData][refbNoAvailableTorpsForEnemies])) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Will add factory '..oFactory.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFactory)..' with mobile lifetime count='..AiBotConditions.GetFactoryLifetimeCount(oFactory, categories.MOBILE - AiBotUnitInfo.refCategoryAirScout)..' to the table') end
                                AddPotentialUnitsToShortlist(toSafeUnitsToUpgrade, { oFactory })
                            end
                        end
                    end
                end
                if oBrain[AiBotEconomy.refiOurHighestLandFactoryTech] == 2 and (not(oBrain[AiBotOverseer.refbPrioritiseAir]) or (oBrain[AiBotEconomy.refiOurHighestAirFactoryTech] > 2 and (AiBotUtilities.IsTableEmpty(toSafeUnitsToUpgrade) or oBrain[AiBotEconomy.refiOurHighestLandFactoryTech] == 2))) and (not(oBrain[AiBotOverseer.refbPrioritiseNavy] or oBrain[AiBotEconomy.refiOurHighestNavalFactoryTech] >= 3)) then
                    if not(DoesBrainHaveActiveHQUpgradesOfCategory(oBrain, AiBotUnitInfo.refCategoryLandHQ)) then
                        tPotentialUnits = oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryLandHQ * categories.TECH2, false, true)
                        if AiBotUtilities.IsTableEmpty(tPotentialUnits) == false then
                            for iFactory, oFactory in tPotentialUnits do
                                --Dont add factories that havent built much
                                if AiBotConditions.GetFactoryLifetimeCount(oFactory, categories.MOBILE * categories.TECH2) > 6 then
                                    AddPotentialUnitsToShortlist(toSafeUnitsToUpgrade, { oFactory })
                                end
                            end
                        end
                    end
                end
                if oBrain[AiBotOverseer.refbPrioritiseNavy] and oBrain[AiBotEconomy.refiOurHighestNavalFactoryTech] == 1 then
                    tPotentialUnits = oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryNavalHQ, false, true)
                end
            end
        end
    end

    if AiBotUtilities.IsTableEmpty(toSafeUnitsToUpgrade) == false then
        local oUnitToUpgrade = AiBotEconomy.GetBestUnitToUpgrade(toSafeUnitsToUpgrade)
        if oUnitToUpgrade then
            if bDebugMessages == true then LOG(sFunctionRef..': Will upgrade factory '..oUnitToUpgrade.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitToUpgrade)) end
            AiBotEconomy.UpgradeUnit(oUnitToUpgrade, true)
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GetAnyMexOrFactoryToUpgrade(iAiBotTeam)
    --Backup logic for finding an upgrade if we have failed to find one through previous searches for a mex or factory; requires the factory to have built something though

    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetAnyMexOrFactoryToUpgrade'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local toUnitsThatCouldUpgrade = {}
    local tPotentialUnits
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code at time '..GetGameTimeSeconds()) end
    local bConsiderT3Mex = AiBotConditions.WantAnotherT3MexUpgrade(iAiBotTeam)

    --First consider any t1 factories
    for iBrain, oBrain in tTeamData[iAiBotTeam][subreftoFriendlyActiveAiBotBrains] do
        --if oBrain[AiBotEconomy.refiOurHighestAirFactoryTech] == 1 then
        if not(DoesBrainHaveActiveHQUpgradesOfCategory(oBrain, AiBotUnitInfo.refCategoryAirHQ * categories.TECH1)) then
            tPotentialUnits = oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryAirHQ * categories.TECH1, false, true)
            AddPotentialUnitsToShortlist(toUnitsThatCouldUpgrade, tPotentialUnits, true, 1)
        end
        --[[elseif oBrain[AiBotEconomy.refiOurHighestAirFactoryTech] == 2 then
            if not(DoesBrainHaveActiveHQUpgradesOfCategory(oBrain, AiBotUnitInfo.refCategoryAirHQ)) then
                tPotentialUnits = oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryAirHQ * categories.TECH2, false, true)
                AddPotentialUnitsToShortlist(toUnitsThatCouldUpgrade, tPotentialUnits, true)
            end--]]
        --end
        --if oBrain[AiBotEconomy.refiOurHighestLandFactoryTech] == 1 then
        if not(DoesBrainHaveActiveHQUpgradesOfCategory(oBrain, AiBotUnitInfo.refCategoryLandHQ * categories.TECH1)) then
            tPotentialUnits = oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryLandHQ * categories.TECH1, false, true)
            AddPotentialUnitsToShortlist(toUnitsThatCouldUpgrade, tPotentialUnits, true, 4)
        end

        if not(DoesBrainHaveActiveHQUpgradesOfCategory(oBrain, AiBotUnitInfo.refCategoryNavalHQ * categories.TECH1)) then
            tPotentialUnits = oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryNavalHQ * categories.TECH1, false, true)
            AddPotentialUnitsToShortlist(toUnitsThatCouldUpgrade, tPotentialUnits, true, 4)
        end
        --[[elseif oBrain[AiBotEconomy.refiOurHighestLandFactoryTech] == 2 then
            if not(DoesBrainHaveActiveHQUpgradesOfCategory(oBrain, AiBotUnitInfo.refCategoryLandHQ)) then
                tPotentialUnits = oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryLandHQ * categories.TECH2, false, true)
                AddPotentialUnitsToShortlist(toUnitsThatCouldUpgrade, tPotentialUnits, true)
            end --]]
        --end
        if bConsiderT3Mex then
            tPotentialUnits = oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryT1Mex + AiBotUnitInfo.refCategoryT2Mex, false, true)
        else
            tPotentialUnits = oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryT1Mex, false, true)
        end
        AddPotentialUnitsToShortlist(toUnitsThatCouldUpgrade, tPotentialUnits, true)
    end
    if AiBotUtilities.IsTableEmpty(toUnitsThatCouldUpgrade) then
        --If at T3 consider upgrading T2 support factories
        for iBrain, oBrain in tTeamData[iAiBotTeam][subreftoFriendlyActiveAiBotBrains] do
            if oBrain[AiBotEconomy.refiOurHighestAirFactoryTech] >= 3 then
                tPotentialUnits = oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryAirFactory - categories.TECH3, false, true)
                if bDebugMessages == true then LOG(sFunctionRef..': We have T3+ air for brain '..oBrian.Nickname..' so will upgrade t2 support factories to T3, oBrain[AiBotEconomy.refiOurHighestAirFactoryTech]='..(oBrain[AiBotEconomy.refiOurHighestAirFactoryTech] or 'nil')..'; Is tPotentialUnits empty='..tostring(AiBotUtilities.IsTableEmpty(tPotentialUnits))) end
                AddPotentialUnitsToShortlist(toUnitsThatCouldUpgrade, tPotentialUnits, true, 1)
            end
            if oBrain[AiBotEconomy.refiOurHighestLandFactoryTech] >= 3 then
                tPotentialUnits = oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryLandFactory - categories.TECH3, false, true)
                if bDebugMessages == true then LOG(sFunctionRef..': We have T3+ land for brain '..oBrain.Nickname..' so will upgrade t2 support factories to T3, oBrain[AiBotEconomy.refiOurHighestLandFactoryTech]='..(oBrain[AiBotEconomy.refiOurHighestLandFactoryTech] or 'nil')..'; Is tPotentialUnits empty='..tostring(AiBotUtilities.IsTableEmpty(tPotentialUnits))) end
                AddPotentialUnitsToShortlist(toUnitsThatCouldUpgrade, tPotentialUnits, true, 4)
            end
            if oBrain[AiBotEconomy.refiOurHighestNavalFactoryTech] >= 3 then
                tPotentialUnits = oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryNavalFactory - categories.TECH3, false, true)
                AddPotentialUnitsToShortlist(toUnitsThatCouldUpgrade, tPotentialUnits, true, 4)
            else
                tPotentialUnits = oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryNavalFactory * categories.TECH1, false, true)
                AddPotentialUnitsToShortlist(toUnitsThatCouldUpgrade, tPotentialUnits, true, 4)
            end
        end

        --If still no units to upgrade, and have positive net mass income and at least 40% mass stored, then consider factory upgrades
    end
    if AiBotUtilities.IsTableEmpty(toUnitsThatCouldUpgrade) == false then
        local oUnitToUpgrade = AiBotEconomy.GetBestUnitToUpgrade(toUnitsThatCouldUpgrade)
        if bDebugMessages == true then LOG(sFunctionRef..': Have potential units to upgrade, oUnitToUpgrade='..(oUnitToUpgrade.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnitToUpgrade) or 'nil')) end
        if oUnitToUpgrade then
            AiBotEconomy.UpgradeUnit(oUnitToUpgrade, true)
        end
    else
        if bDebugMessages == true then LOG(sFunctionRef..': No potential units to ugprade') end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function HaveEcoToSupportUpgrades(iAiBotTeam)
    --Returns true if we think we can support another upgrade (for normal non-priority logic), but is less likely to return true early game if we want more land factories
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'HaveEcoToSupportUpgrades'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    local bBoomMode = AiBotOverseer.IsTeamBoomMode(iAiBotTeam)
    local iMinEnergyStoredRatio = bBoomMode and 0.25 or 0.4
    local iMinGrossEnergyPerBrain = bBoomMode and 18 or 25


    --Do we have enough energy?
    tTeamData[iAiBotTeam][subrefbTooLittleEnergyForUpgrade] = true --will change to false below if we have enough
    if bDebugMessages == true then LOG(sFunctionRef..': Start, GameTime='..GetGameTimeSeconds()..'; Gross energy='..(tTeamData[iAiBotTeam][subrefiTeamGrossEnergy] or 'nil')..'; % stored='..(tTeamData[iAiBotTeam][subrefiTeamAverageEnergyPercentStored] or 'nil')..'; Net energy='..(tTeamData[iAiBotTeam][subrefiTeamNetEnergy] or 'nil')..'; tTeamData[iAiBotTeam][subrefiHighestFriendlyFactoryTech]='..(tTeamData[iAiBotTeam][subrefiHighestFriendlyFactoryTech] or 'nil')..'; Active brain count='..(tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] or 'nil')..'; tTeamData[iAiBotTeam][subrefiTeamGrossEnergy]='..(tTeamData[iAiBotTeam][subrefiTeamGrossEnergy] or 'nil')..'; Net energy='..(tTeamData[iAiBotTeam][subrefiTeamNetEnergy] or 'nil')..'; Min energy per tech='..(AiBotEconomy.tiMinEnergyPerTech[tTeamData[iAiBotTeam][subrefiHighestFriendlyFactoryTech]] or 'nil')) end
    if (tTeamData[iAiBotTeam][subrefiTeamGrossEnergy] >= AiBotEconomy.tiMinEnergyPerTech[tTeamData[iAiBotTeam][subrefiHighestFriendlyFactoryTech]] * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] * (1 + (tTeamData[iAiBotTeam][refiHighestBrainResourceMultiplier] - 1)*0.5) or (tTeamData[iAiBotTeam][subrefiTeamNetEnergy] > 5 * tTeamData[iAiBotTeam][subrefiHighestFriendlyFactoryTech] * tTeamData[iAiBotTeam][subrefiHighestFriendlyFactoryTech] and tTeamData[iAiBotTeam][subrefiTeamAverageEnergyPercentStored] >= 0.98)) and tTeamData[iAiBotTeam][subrefiTeamAverageEnergyPercentStored] >= iMinEnergyStoredRatio and (tTeamData[iAiBotTeam][subrefiTeamGrossEnergy] >= iMinGrossEnergyPerBrain * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] or tTeamData[iAiBotTeam][subrefiTeamAverageEnergyPercentStored] >= 0.9) and tTeamData[iAiBotTeam][subrefiTeamNetEnergy] > 0 then
        --If already have active HQ upgrades, then double min energy wanted if net poweri sn't that high
        if tTeamData[iAiBotTeam][subrefiTeamNetEnergy] > 15 or AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingHQs]) or tTeamData[iAiBotTeam][subrefiTeamGrossEnergy] >= AiBotEconomy.tiMinEnergyPerTech[tTeamData[iAiBotTeam][subrefiHighestFriendlyFactoryTech]] * 2 * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] then
            local iNetEnergyIncomeWanted
            if tTeamData[iAiBotTeam][subrefiTeamAverageEnergyPercentStored] >= 0.99 then iNetEnergyIncomeWanted = math.max(-tTeamData[iAiBotTeam][subrefiTeamGrossEnergy] * 0.03, -25)
            elseif tTeamData[iAiBotTeam][subrefiTeamAverageEnergyPercentStored] >= 0.95 then iNetEnergyIncomeWanted = tTeamData[iAiBotTeam][subrefiTeamGrossEnergy] * 0.01
            elseif tTeamData[iAiBotTeam][subrefiTeamAverageEnergyPercentStored] >= 0.9 then iNetEnergyIncomeWanted = math.max(4, tTeamData[iAiBotTeam][subrefiTeamGrossEnergy] * 0.03)
            elseif tTeamData[iAiBotTeam][subrefiTeamAverageEnergyPercentStored] >= 0.7 then iNetEnergyIncomeWanted = math.max(6, tTeamData[iAiBotTeam][subrefiTeamGrossEnergy] * 0.06)
            else iNetEnergyIncomeWanted = 100
            end

            local iBrainEcoModifier = 0
            local iTechBrains = 0
            local iRushBrains = 0
            local iNormalBrains = 0
            for iBrain, oBrain in tTeamData[iAiBotTeam][subreftoFriendlyActiveAiBotBrains] do
                if oBrain[AiBotOverseer.refbPrioritiseLowTech] then iRushBrains = iRushBrains + 1
                elseif oBrain[AiBotOverseer.refbPrioritiseHighTech] then iTechBrains = iTechBrains + 1
                else iNormalBrains = iNormalBrains + 1
                end
            end
            iBrainEcoModifier = (iTechBrains * 0.75 + iNormalBrains + iRushBrains * 2) / (iTechBrains + iRushBrains + iNormalBrains)
            iNetEnergyIncomeWanted = iNetEnergyIncomeWanted * iBrainEcoModifier
            if bBoomMode and iNetEnergyIncomeWanted > 0 then iNetEnergyIncomeWanted = iNetEnergyIncomeWanted * 0.5 end

            if bDebugMessages == true then LOG(sFunctionRef..': Have enough gross energy, iNetEnergyIncomeWanted='..iNetEnergyIncomeWanted..'; iBrainEcoModifier='..iBrainEcoModifier) end

            if (tTeamData[iAiBotTeam][subrefiTeamNetEnergy] - tTeamData[iAiBotTeam][subrefiEnergyUpgradesStartedThisCycle] > iNetEnergyIncomeWanted) then
                tTeamData[iAiBotTeam][subrefbTooLittleEnergyForUpgrade] = false
                --Do we have enough mass to support the upgrade?
                local iNetMassIncomeWanted
                if tTeamData[iAiBotTeam][subrefiTeamMassStored] >= 4000 then
                    if tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored] >= 0.9 then iNetMassIncomeWanted = math.min(-30, -tTeamData[iAiBotTeam][subrefiTeamGrossMass] * 0.3)
                    elseif tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored] >= 0.7 then iNetMassIncomeWanted = math.min(-15, -tTeamData[iAiBotTeam][subrefiTeamGrossMass] * 0.25)
                    elseif tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored] >= 0.4 then iNetMassIncomeWanted = math.min(-4, -tTeamData[iAiBotTeam][subrefiTeamGrossMass] * 0.2)
                    elseif tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored] >= 0.3 then iNetMassIncomeWanted = math.min(-3, - tTeamData[iAiBotTeam][subrefiTeamGrossMass] * 0.15)
                    elseif tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored] >= 0.2 then iNetMassIncomeWanted = math.min(-2, - tTeamData[iAiBotTeam][subrefiTeamGrossMass] * 0.1)
                    else iNetMassIncomeWanted = math.min(-1, - tTeamData[iAiBotTeam][subrefiTeamGrossMass] * 0.075) end
                else
                    if tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored] >= 0.9 then iNetMassIncomeWanted = math.min(-1.5, -tTeamData[iAiBotTeam][subrefiTeamGrossMass] * 0.3)
                    elseif tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored] >= 0.7 then iNetMassIncomeWanted = math.min(-1.2, -tTeamData[iAiBotTeam][subrefiTeamGrossMass] * 0.25)
                    elseif tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored] >= 0.4 then iNetMassIncomeWanted = math.min(-0.9, -tTeamData[iAiBotTeam][subrefiTeamGrossMass] * 0.2)
                    elseif tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored] >= 0.3 then iNetMassIncomeWanted = math.min(-0.6, - tTeamData[iAiBotTeam][subrefiTeamGrossMass] * 0.15)
                    elseif tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored] >= 0.2 and tTeamData[iAiBotTeam][subrefiTeamMassStored] >= 600 then iNetMassIncomeWanted = math.min(-0.5, - tTeamData[iAiBotTeam][subrefiTeamGrossMass] * 0.1)
                    elseif tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored] >= 0.1 and tTeamData[iAiBotTeam][subrefiTeamMassStored] >= 325 then iNetMassIncomeWanted = math.min(-0.4, - tTeamData[iAiBotTeam][subrefiTeamGrossMass] * 0.075)
                    elseif tTeamData[iAiBotTeam][subrefiTeamMassStored] >= 325 then iNetMassIncomeWanted = - tTeamData[iAiBotTeam][subrefiTeamGrossMass] * 0.05
                    else iNetMassIncomeWanted = 0.1
                    end
                    --Early game exception - if dont have many land factories then increase net mass income wanted
                    if GetGameTimeSeconds() <= 300 and tTeamData[iAiBotTeam][subrefiTeamMassStored] <= 500 * (1 + (tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] - 1) * 0.5)  and tTeamData[iAiBotTeam][subrefiTeamGrossMass] <= 2 * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] * tTeamData[iAiBotTeam][refiHighestBrainResourceMultiplier] and AiBotConditions.GetTeamLifetimeBuildCount(iAiBotTeam, AiBotUnitInfo.refCategoryFactory) <= 3 * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] then
                        iNetMassIncomeWanted = math.max(iNetMassIncomeWanted, 0.05)
                        --Early to t2 stage of the game with a negative net mass income wanted - increase net mass requirements if we have lots of active upgrades
                    elseif iNetMassIncomeWanted < 0 and GetGameTimeSeconds() <= 1200 and tTeamData[iAiBotTeam][subrefiHighestFriendlyFactoryTech] <= 2 and tTeamData[iAiBotTeam][subrefiTeamMassStored] <= 2000 and AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingMexes]) == false then
                        local iActiveUpgradingMexes = table.getn( tTeamData[iAiBotTeam][subreftTeamUpgradingMexes])
                        if iActiveUpgradingMexes >= 2 * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] then
                            if iActiveUpgradingMexes >= 4 * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] then
                                iNetMassIncomeWanted = 0
                            else
                                iNetMassIncomeWanted = iNetMassIncomeWanted * 0.5 --we are negative, so this should reduce it
                            end
                        end

                    end
                end

                if tTeamData[iAiBotTeam][subrefiTeamMassStored] >= 5000 then iNetMassIncomeWanted = math.min(-5, iNetMassIncomeWanted - tTeamData[iAiBotTeam][subrefiTeamGrossMass] * 0.02) end
                if not(iBrainEcoModifier == 1) then
                    if iNetMassIncomeWanted > 0 then iNetMassIncomeWanted = iNetMassIncomeWanted * iBrainEcoModifier
                    else --Negative value so invert
                        iNetMassIncomeWanted = iNetMassIncomeWanted / iBrainEcoModifier
                    end

                end
                if bBoomMode then iNetMassIncomeWanted = iNetMassIncomeWanted - tTeamData[iAiBotTeam][subrefiTeamGrossMass] * 0.1 end

                if AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingMexes]) then
                    iNetMassIncomeWanted = iNetMassIncomeWanted - tTeamData[iAiBotTeam][subrefiTeamGrossMass] * 0.05
                    if tTeamData[iAiBotTeam][subrefiTeamMassStored] >= 600 then iNetMassIncomeWanted = iNetMassIncomeWanted - tTeamData[iAiBotTeam][subrefiTeamGrossMass] * 0.05 end
                else
                    --Adjust net mass income wanted if we will use up our stored mass quickly and have active mex upgrades
                    if (iNetMassIncomeWanted < 0 and tTeamData[iAiBotTeam][subrefiTeamNetMass] < 0) or tTeamData[iAiBotTeam][subrefiTeamMassStored] <= 650 then
                        if tTeamData[iAiBotTeam][subrefiTeamMassStored] <= 400 then iNetMassIncomeWanted = math.max(0, iNetMassIncomeWanted)
                        else
                            local iTimeUntilUseUpStoredMass = tTeamData[iAiBotTeam][subrefiTeamMassStored] / -10 * (tTeamData[iAiBotTeam][subrefiTeamNetMass] - tTeamData[iAiBotTeam][subrefiMassUpgradesStartedThisCycle])
                            if iTimeUntilUseUpStoredMass <= 80 then
                                iNetMassIncomeWanted = math.max(-0.2, iNetMassIncomeWanted)
                            elseif iTimeUntilUseUpStoredMass <= 150 and (tTeamData[iAiBotTeam][subrefiHighestFriendlyFactoryTech] >= 3 or (tTeamData[iAiBotTeam][subrefiHighestFriendlyFactoryTech] >= 2 and GetGameTimeSeconds() - (tTeamData[iAiBotTeam][refiTimeOfLastEnergyStall] or -20) < 20)) then
                                iNetMassIncomeWanted = math.max(-0.2, iNetMassIncomeWanted)
                            end
                        end
                        --Early game or low gross mass - restrict number of upgrades further
                        if (tTeamData[iAiBotTeam][subrefiTeamGrossMass] < 2 * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] or GetGameTimeSeconds() <= 300) and tTeamData[iAiBotTeam][subrefiTeamMassStored] <= 650 then
                            iNetMassIncomeWanted = math.max(0.8, iNetMassIncomeWanted)
                        end
                    end
                end

                --Very high mass storage level adjustments
                if tTeamData[iAiBotTeam][subrefiTeamMassStored] >= 5000 and iNetMassIncomeWanted <= -1 then
                    --Want to be spending mass at a rate taht means in 75 seconds we will have used up all the amount stored
                    iNetMassIncomeWanted = math.min(iNetMassIncomeWanted, -tTeamData[iAiBotTeam][subrefiTeamGrossMass] * 0.3, -tTeamData[iAiBotTeam][subrefiTeamMassStored] / 75)
                end




                --Average out our mass from the last 5 cycles as well
                local iLowestNetMass = tTeamData[iAiBotTeam][subrefiTeamNetMass]
                for iLastEntry = 1, 5 do
                    iLowestNetMass = math.min(iLowestNetMass, (tTeamData[iAiBotTeam][subreftiPrevTeamNetMass][iLastEntry] or tTeamData[iAiBotTeam][subrefiTeamNetMass]))
                end

                if bDebugMessages == true then LOG(sFunctionRef..': Consideringi f have enough mass, tTeamData[iAiBotTeam][subrefiTeamMassStored]='..tTeamData[iAiBotTeam][subrefiTeamMassStored]..'; % mass stored='..tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored]..'; Gross mass income='..tTeamData[iAiBotTeam][subrefiTeamGrossMass]..'; Net mass income='..tTeamData[iAiBotTeam][subrefiTeamNetMass]..'; Net mass wanted='..iNetMassIncomeWanted..'; Is table of upgrading mexes empty='..tostring(AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingMexes]))..'; tTeamData[iAiBotTeam][subreftiPrevTeamNetMass]='..repru(tTeamData[iAiBotTeam][subreftiPrevTeamNetMass])..'; iLowestNetMass - tTeamData[iAiBotTeam][subrefiMassUpgradesStartedThisCycle]='..iLowestNetMass - tTeamData[iAiBotTeam][subrefiMassUpgradesStartedThisCycle]..'; tTeamData[iAiBotTeam][refiUpgradedMexCount]='..(tTeamData[iAiBotTeam][refiUpgradedMexCount] or 'nil')) end
                if AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingMexes]) and (tTeamData[iAiBotTeam][refiUpgradedMexCount] or 0) > 0 then iNetMassIncomeWanted = math.min(iNetMassIncomeWanted, 0) end

                if (iLowestNetMass - tTeamData[iAiBotTeam][subrefiMassUpgradesStartedThisCycle]) > iNetMassIncomeWanted then
                    if bDebugMessages == true then LOG(sFunctionRef..': We have enough energy and mass to get an upgrade; will now factor in if we would rather build more factories if are early game and enemy doesnt have T2, Time='..GetGameTimeSeconds()..'; iLowestNetMass='..iLowestNetMass..'; % mass stored='..tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored]..'; Gross mass income='..tTeamData[iAiBotTeam][subrefiTeamGrossMass]..'; Highest enemy tech='..tTeamData[iAiBotTeam][subrefiHighestEnemyGroundTech]..'; Map playable area size='..AiBotMap.rMapPlayableArea[3] - AiBotMap.rMapPlayableArea[1]) end
                    if not(bBoomMode) and tTeamData[iAiBotTeam][subrefiTeamMassStored] <= 450 and GetGameTimeSeconds() <= 600 and tTeamData[iAiBotTeam][subrefiHighestEnemyGroundTech] <= 1 and AiBotMap.iMapSize <= 512 then
                        if bDebugMessages == true then LOG(sFunctionRef..': Early game on 10km or smaller map so want to only get a mex upgrade if we have loads of mass') end
                        if tTeamData[iAiBotTeam][subrefiTeamMassStored] <= 600 and (AiBotMap.iMapSize <= 256 or (iLowestNetMass <= 0.6 * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] and tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored] <= 0.6)) then --or (tTeamData[iAiBotTeam][subrefiTeamMassStored] <= 600 and tTeamData[iAiBotTeam][subrefiTeamGrossMass] < 2 * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount]) then
                            if bDebugMessages == true then LOG(sFunctionRef..': We dont actually have eco to support upgrade due to being early game') end
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            return false
                        else
                            if bDebugMessages == true then LOG(sFunctionRef..': We still have eco to support upgrade despite being early game') end
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            return true
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Either not early game or we have lots of mass stored so think we have eco to get upgrade') end
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    return true
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': We dont have the eco to get an upgrade') end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return false
end


function ConsiderNormalUpgrades(iAiBotTeam)
    --We should have already considered high priority upgrades before, now we want to consider upgrades if we have the eco to support upgrades generally
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderNormalUpgrades'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local iMassUpgradesAtLoopStart
    local iCycleCount = 0

    local bLookForMexNotHQ

    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, HaveEcoToSupportUpgrades for iAiBotTeam '..iAiBotTeam..'='..tostring(HaveEcoToSupportUpgrades(iAiBotTeam))..'; Is table of mex upgrades empty='..tostring(AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingMexes]))..'; Is table of factory upgrades empty='..tostring(AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingHQs]))) end
    --Dont proceed with upgrade even if we have the eco to support it, if we are under a critical threat from navy
    local bWantMassForProduction = false
    for _, iAirSubteam in tTeamData[iAiBotTeam][subrefAirSubteamsInTeam] do
        if tAirSubteamData[iAirSubteam][refbNoAvailableTorpsForEnemies] then
            bWantMassForProduction = true
            break
        end
    end
    if not(bWantMassForProduction) then
        local tbLandSubteams = {}
        for iBrain, oBrain in tTeamData[iAiBotTeam][subreftoFriendlyActiveAiBotBrains] do
            tbLandSubteams[oBrain.AiBotLandSubteam] = true
        end
        for iLandSubteam, _ in  tbLandSubteams do
            if tLandSubteamData[iLandSubteam][refbPrioritiseProduction] then bWantMassForProduction = true break end
        end
        if bWantMassForProduction then
            if not(AiBotConditions.TeamHasLowMass(iAiBotTeam)) then bWantMassForProduction = false end
        end
    end

    if bDebugMessages == true then LOG(sFunctionRef..': bWantMassForProduction='..tostring(bWantMassForProduction)..'; Is table of upgrading mexes empty='..tostring(AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingMexes]))..'; Is table of upgrading HQs empty='..tostring(AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingHQs]))..'; tTeamData[iAiBotTeam][subrefiHighestFriendlyAirFactoryTech]='..tTeamData[iAiBotTeam][subrefiHighestFriendlyAirFactoryTech]..'; refbFocusOnT1Spam='..tostring(tTeamData[iAiBotTeam][refbFocusOnT1Spam])) end
    if not(bWantMassForProduction) or (AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingMexes]) and AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingHQs])) or tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored] >= 0.3 or tTeamData[iAiBotTeam][subrefiHighestFriendlyAirFactoryTech] <= 1 then
        --T1 spam mode - be much less likely to get upgrades early game
        if AiBotOverseer.IsTeamBoomMode(iAiBotTeam) or not(tTeamData[iAiBotTeam][refbFocusOnT1Spam]) or (AiBotOverseer.bLikelyGunUpgrade and (AiBotMap.iMapSize > 256 or GetGameTimeSeconds() >= 480)) or AiBotConditions.GetTeamLifetimeBuildCount(iAiBotTeam, AiBotUnitInfo.refCategoryFactory) >= 10 or (AiBotConditions.GetCurrentAiBotUnitsOfCategoryInTeam(AiBotUnitInfo.refCategoryFactory, iAiBotTeam) >= 6 and tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored] >= 0.75 and (tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored] >= 0.95 or GetGameTimeSeconds() >= 300 / math.max(tTeamData[iAiBotTeam][refiHighestBrainResourceMultiplier], tTeamData[iAiBotTeam][refiHighestBrainBuildMultiplier]))) then
            local bPreferLandToAirHQ = false
            if iPlayersAtGameStart <= 4 and tTeamData[iAiBotTeam][subrefiHighestFriendlyLandFactoryTech] < 2 and (tTeamData[iAiBotTeam][subrefiHighestEnemyNavyTech] or 0) == 0 then bPreferLandToAirHQ = true end
            while HaveEcoToSupportUpgrades(iAiBotTeam) do
                iCycleCount = iCycleCount + 1
                iMassUpgradesAtLoopStart = tTeamData[iAiBotTeam][subrefiMassUpgradesStartedThisCycle] --so we can check we actually upgraded something
                if bDebugMessages == true then LOG(sFunctionRef..': We think we have enough eco to support another upgrade, will decide if we want a mex or a factoroy, iCycleCOunt='..iCycleCount..'; bPreferLandToAirHQ='..tostring(bPreferLandToAirHQ)) end

                bLookForMexNotHQ = not(tTeamData[iAiBotTeam][refbFocusOnT1Spam])

                --Get preferred upgrade type - ideally are always improving mass income (if have safe mexes to upgrade)
                if AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingMexes]) == false and (not(AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) or not(AiBotConditions.TeamHasLowMass(iAiBotTeam))) then
                    --Already have mexes upgrading - do we want to also upgrade an HQ instead of a mex?
                    if (tTeamData[iAiBotTeam][subrefiTeamGrossMass] >= 2.5 and (tTeamData[iAiBotTeam][subrefiTeamGrossMass] >= 5 and (tTeamData[iAiBotTeam][subrefiLowestFriendlyLandFactoryTech] == 1 or tTeamData[iAiBotTeam][subrefiLowestFriendlyAirFactoryTech] == 1) or (tTeamData[iAiBotTeam][subrefiLowestFriendlyLandFactoryTech] == 1 and tTeamData[iAiBotTeam][subrefiLowestFriendlyAirFactoryTech] == 1))) or ((tTeamData[iAiBotTeam][subrefiLowestFriendlyLandFactoryTech] == 2 or tTeamData[iAiBotTeam][subrefiLowestFriendlyAirFactoryTech] == 2) and tTeamData[iAiBotTeam][subrefiTeamGrossMass] >= 8) then
                        --Do we already ahve a factory HQ upgrading? If so then consider income based on player count
                        if AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingHQs]) then
                            bLookForMexNotHQ = false
                        else
                            if (tTeamData[iAiBotTeam][subrefiTeamGrossMass] >= math.max(1.5, tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount]) * 5 and (tTeamData[iAiBotTeam][subrefiLowestFriendlyLandFactoryTech] == 1 or tTeamData[iAiBotTeam][subrefiLowestFriendlyAirFactoryTech] == 1)) or ((tTeamData[iAiBotTeam][subrefiLowestFriendlyLandFactoryTech] == 2 or tTeamData[iAiBotTeam][subrefiLowestFriendlyAirFactoryTech] == 2) and tTeamData[iAiBotTeam][subrefiTeamGrossMass] >= math.max(1.5, tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount]) * 8) then
                                bLookForMexNotHQ = false
                            end
                        end
                        if not(bLookForMexNotHQ) and tTeamData[iAiBotTeam][subrefiHighestFriendlyFactoryTech] >= 3 then
                            --If we have T3 tech and lack t3 mex or t3 power then dont look for HQ yet
                            local bHaveBrainWhereWeShouldGetHQ = false
                            for iBrain, oBrain in tTeamData[iAiBotTeam][subreftoFriendlyActiveAiBotBrains] do
                                if oBrain[AiBotEconomy.refiOurHighestFactoryTechLevel] < 3 and (oBrain[AiBotEconomy.refiGrossMassBaseIncome] > 9 or oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryMex * categories.TECH3) >= 2) then
                                    bHaveBrainWhereWeShouldGetHQ = true
                                    break
                                elseif oBrain[AiBotEconomy.refiOurHighestFactoryTechLevel] == 3 and ((oBrain[AiBotEconomy.refiOurHighestAirFactoryTech] <= 2 and not(oBrain[AiBotOverseer.refbPrioritiseLand])) or (oBrain[AiBotEconomy.refiOurHighestLandFactoryTech] <= 2 and not(oBrain[AiBotOverseer.refbPrioritiseAir])))
                                        and oBrain[AiBotEconomy.refiGrossMassBaseIncome] >= 10 and oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryMex * categories.TECH3) >= 2 then
                                    bHaveBrainWhereWeShouldGetHQ = true
                                    break
                                end
                            end
                            bLookForMexNotHQ = not(bHaveBrainWhereWeShouldGetHQ)
                        end
                    end
                else
                    --No mex ugprading, but might want factory if we dont have access to T2/T3 yet and have high mass income
                    if bDebugMessages == true then LOG(sFunctionRef..': Dont have a mex upgrading, will see if want a factory instead of a mex, tTeamData[iAiBotTeam][subrefiHighestFriendlyLandFactoryTech='..tTeamData[iAiBotTeam][subrefiHighestFriendlyLandFactoryTech]..'; tTeamData[iAiBotTeam][subrefiHighestFriendlyAirFactoryTech]='..tTeamData[iAiBotTeam][subrefiHighestFriendlyAirFactoryTech]..'; tTeamData[iAiBotTeam][subrefiTeamGrossMass]='..tTeamData[iAiBotTeam][subrefiTeamGrossMass]..'; Player count='..tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount]..'; tTeamData[iAiBotTeam][subrefiHighestFriendlyFactoryTech]='..tTeamData[iAiBotTeam][subrefiHighestFriendlyFactoryTech]) end
                    if AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingHQs]) then --since no mex upgrading, dont want to upgrade more than 1 factory at once
                        if tTeamData[iAiBotTeam][subrefiHighestFriendlyFactoryTech] == 1 then
                            if tTeamData[iAiBotTeam][subrefiTeamGrossMass] >= math.max(1, tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] * 0.7) * 4 and tTeamData[iAiBotTeam][subrefiTeamGrossEnergy] >= 25 * math.max(1, tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] * 0.75) then
                                bLookForMexNotHQ = false
                            end
                        elseif tTeamData[iAiBotTeam][subrefiHighestFriendlyFactoryTech] == 2 then
                            if tTeamData[iAiBotTeam][subrefiTeamGrossMass] > 8 * math.max(1, tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] * 0.7) and tTeamData[iAiBotTeam][subrefiTeamGrossEnergy] >= 100 then
                                bLookForMexNotHQ = false
                            end
                        end
                    end

                end

                if bDebugMessages == true then LOG(sFunctionRef..': iCycleCount='..iCycleCount..'; bLookForMexNotHQ='..tostring(bLookForMexNotHQ)..'; Is table of upgrading mexes empty='..tostring(AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingMexes]))..'; Is table of upgrading HQs empty='..tostring(AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingHQs]))..'; Team gross mass='..tTeamData[iAiBotTeam][subrefiTeamGrossMass]..'; Lowest land fac tech='..tTeamData[iAiBotTeam][subrefiLowestFriendlyLandFactoryTech]..'; Lowest air fac tech='..tTeamData[iAiBotTeam][subrefiLowestFriendlyAirFactoryTech]) end
                if bLookForMexNotHQ then
                    local bWantAnotherT3MexByDefault = AiBotConditions.WantAnotherT3MexUpgrade(iAiBotTeam)
                    GetSafeMexToUpgrade(iAiBotTeam, false, not(bWantAnotherT3MexByDefault))
                    --Backup - if didnt find anything then get a HQ upgrade if we dont already ahve a HQ upgrade active
                    if bDebugMessages == true then LOG(sFunctionRef..': Tried to get a mex upgrade, tTeamData[iAiBotTeam][subrefiMassUpgradesStartedThisCycle]='..tTeamData[iAiBotTeam][subrefiMassUpgradesStartedThisCycle]..'; iMassUpgradesAtLoopStart='..iMassUpgradesAtLoopStart) end
                    if tTeamData[iAiBotTeam][subrefiMassUpgradesStartedThisCycle] == iMassUpgradesAtLoopStart then
                        if not(bWantAnotherT3MexByDefault) then
                            GetSafeMexToUpgrade(iAiBotTeam, false, false)
                        end
                        if bWantAnotherT3MexByDefault or tTeamData[iAiBotTeam][subrefiMassUpgradesStartedThisCycle] == iMassUpgradesAtLoopStart then
                            if tTeamData[iAiBotTeam][subrefiTeamGrossMass] >= 4 and AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingHQs]) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Trying backup HQ upgrade as no mexes could be found') end
                                GetSafeHQUpgrade(iAiBotTeam, bPreferLandToAirHQ)
                            end
                        end
                    end
                else
                    if bDebugMessages == true then LOG(sFunctionRef..': About to get safe HQ as want HQ not mex, bPreferLandToAirHQ='..tostring(bPreferLandToAirHQ or false)..'; is subreftTeamUpgradingHQs empty='..tostring(AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingHQs]))..'; Landtech subrefiHighestFriendlyLandFactoryTech='..tTeamData[iAiBotTeam][subrefiHighestFriendlyLandFactoryTech]) end
                    GetSafeHQUpgrade(iAiBotTeam, bPreferLandToAirHQ)
                    if tTeamData[iAiBotTeam][subrefiMassUpgradesStartedThisCycle] == iMassUpgradesAtLoopStart and (not(tTeamData[iAiBotTeam][refbFocusOnT1Spam]) or tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored] >= 0.8) then
                        --Further check - want to have 100% E or no upgrading mexes, or be overflowing mass
                        if tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored] > 0.99 or  tTeamData[iAiBotTeam][subrefiTeamAverageEnergyPercentStored] > 0.99 or GetGameTimeSeconds() >= 600 or (iPlayersAtGameStart > 4 and AiBotMap.iMapSize >= 750) then
                            GetSafeMexToUpgrade(iAiBotTeam, false, AiBotConditions.WantAnotherT3MexUpgrade(iAiBotTeam))
                        end
                    end
                end
                --If failed to find a mex or HQ upgrade from above:
                if tTeamData[iAiBotTeam][subrefiMassUpgradesStartedThisCycle] == iMassUpgradesAtLoopStart then
                    --Only consider upgrading if have lots of mass
                    bFailedEcoToTryAlternatives = true
                    if tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored] >= 0.5 and tTeamData[iAiBotTeam][subrefiTeamMassStored] >= 700 and (tTeamData[iAiBotTeam][subrefiTeamMassStored] >= 7000 or (tTeamData[iAiBotTeam][subrefiTeamMassStored] >= 4000 and tTeamData[iAiBotTeam][subrefiTeamNetMass] > -1) or tTeamData[iAiBotTeam][subrefiTeamNetMass] > 0.5) then
                        if tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored] > 0.99 or tTeamData[iAiBotTeam][subrefiTeamAverageEnergyPercentStored] > 0.99 or GetGameTimeSeconds() >= 600 or (iPlayersAtGameStart > 4 and AiBotMap.iMapSize >= 750) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Will try and get any mex or HQ to upgrade as failed to find something to upgrade and have lots of mass, tTeamData[iAiBotTeam][subrefiTeamNetMass]='..tTeamData[iAiBotTeam][subrefiTeamNetMass]..'; mass stored='..tTeamData[iAiBotTeam][subrefiTeamMassStored]) end
                            bFailedEcoToTryAlternatives = false
                            GetAnyMexOrFactoryToUpgrade(iAiBotTeam)
                        end
                    end
                end

                --Keep searching for upgrades (if we have the eco to support) if we have just found something to upgrade
                if tTeamData[iAiBotTeam][subrefiMassUpgradesStartedThisCycle] > iMassUpgradesAtLoopStart then
                    --Check if about to overflow mass and have enough E - if we are, then consider multiple upgrades
                    if tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored] > 0.8 and tTeamData[iAiBotTeam][subrefiTeamAverageEnergyPercentStored] > 0.99 and (tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored] > 0.99 or tTeamData[iAiBotTeam][subrefiTeamNetMass] > -tTeamData[iAiBotTeam][subrefiTeamGrossMass]*0.03) then
                        if iCycleCount >= 50 then
                            AiBotUtilities.ErrorHandler('Likely infinite loop')
                            break
                        end
                    else
                        if bDebugMessages == true then LOG(sFunctionRef..': Not about to overflow so will wait for next cycle to try and upgrade something') end
                        break
                    end
                else
                    --Failed ot upgrade anything so abort to avoid risk of infinite loop
                    break
                end
                if bWantMassForProduction then break end
            end
        end
    end

    --T2 land factory exception even if dont have eco to support upgrades - if have a lot of mass, then consider upgrading even if lack energy, provided not early game (subject to AIx modifier)
    if bDebugMessages == true then LOG(sFunctionRef..': Finished considering normal upgrades; will now consider if we want a T2 factory even if we have low energy. tTeamData[iAiBotTeam][subrefiHighestFriendlyFactoryTech]='..tTeamData[iAiBotTeam][subrefiHighestFriendlyFactoryTech]..'; tTeamData[iAiBotTeam][subrefiTeamGrossMass]='..tTeamData[iAiBotTeam][subrefiTeamGrossMass]..'; tTeamData[iAiBotTeam][subrefiTeamGrossEnergy]='..tTeamData[iAiBotTeam][subrefiTeamGrossEnergy]..'; tTeamData[iAiBotTeam][subrefiTeamNetEnergy]='..tTeamData[iAiBotTeam][subrefiTeamNetEnergy]..'; Stored mass='..tTeamData[iAiBotTeam][subrefiTeamMassStored]..'; Is table of upgrading HQs empty='..tostring(AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingHQs]))..'; tTeamData[iAiBotTeam][subrefiLowestFriendlyLandFactoryTech]='..tTeamData[iAiBotTeam][subrefiLowestFriendlyLandFactoryTech]..'; tTeamData[iAiBotTeam][subrefiMassUpgradesStartedThisCycle]='..tTeamData[iAiBotTeam][subrefiMassUpgradesStartedThisCycle]) end
    if tTeamData[iAiBotTeam][subrefiHighestFriendlyFactoryTech] == 1 and tTeamData[iAiBotTeam][subrefiLowestFriendlyLandFactoryTech] == 1 and tTeamData[iAiBotTeam][subrefiTeamGrossMass] >= 4 and tTeamData[iAiBotTeam][subrefiTeamGrossEnergy] >= 25 and (tTeamData[iAiBotTeam][subrefiTeamNetEnergy] > 0 or tTeamData[iAiBotTeam][subrefiTeamGrossEnergy] >= 40) and tTeamData[iAiBotTeam][subrefiMassUpgradesStartedThisCycle] == 0 and (AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingMexes]) or tTeamData[iAiBotTeam][subrefiTeamMassStored] >= 500) and AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingHQs]) and (GetGameTimeSeconds() >= 390 or GetGameTimeSeconds() >= 390 / tTeamData[iAiBotTeam][refiHighestBrainBuildMultiplier] or (tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] > 1 and AiBotConditions.GetCurrentAiBotUnitsOfCategoryInTeam(AiBotUnitInfo.refCategoryFactory, iAiBotTeam) >= 4 * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount]) or tTeamData[iAiBotTeam][subrefiTeamGrossMass] >= 6 * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] * tTeamData[iAiBotTeam][refiHighestBrainResourceMultiplier]) then
        if bDebugMessages == true then LOG(sFunctionRef..': Dont have good eco but will get land fac upgrade anyway to help improve energy long term as are only at T1') end
        GetSafeHQUpgrade(iAiBotTeam, true)
    end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ConsiderGettingUpgrades(iAiBotTeam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderGettingUpgrades'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..'; tTeamData[iAiBotTeam][subrefiTeamAverageEnergyPercentStored]='..tTeamData[iAiBotTeam][subrefiTeamAverageEnergyPercentStored]..'; Stalling energy='..tostring(tTeamData[iAiBotTeam][subrefbTeamIsStallingEnergy])..'; Stalling mass='..tostring(tTeamData[iAiBotTeam][subrefbTeamIsStallingMass])..'; tTeamData[iAiBotTeam][subrefiTeamGrossMass]='..tTeamData[iAiBotTeam][subrefiTeamGrossMass]..'; tTeamData[iAiBotTeam][subrefiTeamGrossEnergy]='..tTeamData[iAiBotTeam][subrefiTeamGrossEnergy]..'; tTeamData[iAiBotTeam][subrefiTeamMassStored]='..tTeamData[iAiBotTeam][subrefiTeamMassStored]..'; tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored]='..tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored]..'; tTeamData[iAiBotTeam][subrefiTeamNetEnergy]='..tTeamData[iAiBotTeam][subrefiTeamNetEnergy]) end
    local iMinimumStoredEnergy = AiBotOverseer.IsTeamBoomMode(iAiBotTeam) and 0.35 or 0.6
    if tTeamData[iAiBotTeam][subrefiTeamAverageEnergyPercentStored] >= iMinimumStoredEnergy and (GetGameTimeSeconds() >= 150 or (GetGameTimeSeconds() >= 60 and GetGameTimeSeconds() >= 150 / tTeamData[iAiBotTeam][refiHighestBrainResourceMultiplier]) or (tTeamData[iAiBotTeam][subrefiTeamGrossMass] >= 3 * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] and tTeamData[iAiBotTeam][subrefiTeamGrossEnergy] >= 50 * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount]) or (tTeamData[iAiBotTeam][subrefiTeamMassStored] >= 700 and tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored] >= 0.9 and tTeamData[iAiBotTeam][subrefiTeamNetEnergy] >= 3 and tTeamData[iAiBotTeam][subrefiTeamAverageEnergyPercentStored] >= 0.95) or (AiBotMap.bIsLowMexMap and tTeamData[iAiBotTeam][subrefiTeamAverageEnergyPercentStored] >= 0.5 and tTeamData[iAiBotTeam][subrefiTeamAverageEnergyPercentStored] >= 0.99 or (tTeamData[iAiBotTeam][subrefiTeamGrossEnergy] >= 6 * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount]))) and not(tTeamData[iAiBotTeam][subrefbTeamIsStallingEnergy]) then
        --Further general eco conditions on upgrading early game
        if GetGameTimeSeconds() >= 300 or AiBotMap.bIsCampaignMap or GetGameTimeSeconds() >= 60 + 240 / (0.5 + tTeamData[iAiBotTeam][refiHighestBrainResourceMultiplier] * 0.5) - 30 * math.min(3, math.max(0, tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] - 1.5)) or tTeamData[iAiBotTeam][subrefiTeamGrossMass] >= 6 * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] * (0.5 + tTeamData[iAiBotTeam][refiHighestBrainResourceMultiplier] * 0.5) or (tTeamData[iAiBotTeam][subrefiTeamMassStored] >= 700 and tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored] >= 0.4) or AiBotMap.bIsLowMexMap or AiBotOverseer.bNoRushActive or AiBotOverseer.IsTeamBoomMode(iAiBotTeam) or ((AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and GetGameTimeSeconds() >= 200) then
            if bDebugMessages == true then LOG(sFunctionRef..': Have enough energy that we will check for priority upgrades and then normal upgrades') end
            tTeamData[iAiBotTeam][subrefiMassUpgradesStartedThisCycle] = 0
            tTeamData[iAiBotTeam][subrefiEnergyUpgradesStartedThisCycle] = 0

            --Priority upgrades even with poor eco:
            if (not(tTeamData[iAiBotTeam][subrefbTeamIsStallingMass]) or (AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingHQs]) and AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingMexes]))) then
                ConsiderPriorityLandFactoryUpgrades(iAiBotTeam)

                ConsiderPriorityAirFactoryUpgrades(iAiBotTeam)

                ConsiderPriorityNavalFactoryUpgrades(iAiBotTeam)

                --Consider priority mex upgrades (e.g. we are falling far behind enemy on eco)
                ConsiderPriorityMexUpgrades(iAiBotTeam)

                ConsiderNormalUpgrades(iAiBotTeam)
            elseif tTeamData[iAiBotTeam][subrefbTeamIsStallingMass] then
                --Want to keep upgrading mexes even if stalling mass
                --Also still consider upgrading HQ if have no upgrading HQs
                if AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingHQs]) and AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingMexes]) == false and tTeamData[iAiBotTeam][subrefiTeamGrossMass] >= 4 * tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] * tTeamData[iAiBotTeam][subrefiHighestFriendlyFactoryTech] then
                    if tTeamData[iAiBotTeam][subrefiHighestFriendlyLandFactoryTech] == 1 then ConsiderPriorityLandFactoryUpgrades(iAiBotTeam) else ConsiderPriorityAirFactoryUpgrades(iAiBotTeam) end
                    if AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingHQs]) then
                        if tTeamData[iAiBotTeam][subrefiHighestFriendlyLandFactoryTech] == 1 then ConsiderPriorityAirFactoryUpgrades(iAiBotTeam) else ConsiderPriorityLandFactoryUpgrades(iAiBotTeam) end
                        if AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftTeamUpgradingHQs]) then
                            ConsiderPriorityNavalFactoryUpgrades(iAiBotTeam)
                        end
                    end
                end
                ConsiderPriorityMexUpgrades(iAiBotTeam)
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function TeamEconomyRefresh(iAiBotTeam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'TeamEconomyRefresh'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    if bDebugMessages == true then LOG(sFunctionRef..': Start of code for team '..iAiBotTeam..' at time='..GetGameTimeSeconds()..'; AiBotMap.bMapLandSetupComplete='..tostring(AiBotMap.bMapLandSetupComplete)..'; bWaterZoneInitialCreation='..tostring(AiBotMap.bWaterZoneInitialCreation)) end
    if AiBotMap.bMapLandSetupComplete and AiBotMap.bWaterZoneInitialCreation then
        local bIncludeHumanBrains = true
        if not(AiBotOrders.bDontConsiderCombinedArmy) then
            for iBrain, oBrain in tTeamData[iAiBotTeam][subreftoFriendlyActiveAiBotBrains] do
                if oBrain.BrainType == 'AI' then bIncludeHumanBrains = false break end
            end
        end
        tTeamData[iAiBotTeam][subrefiTeamGrossEnergy] = 0
        tTeamData[iAiBotTeam][subrefiTeamNetEnergy] = 0
        tTeamData[iAiBotTeam][subrefiTeamGrossMass] = 0
        tTeamData[iAiBotTeam][subrefiTeamNetMass] = 0
        tTeamData[iAiBotTeam][subrefiTeamEnergyStored] = 0
        tTeamData[iAiBotTeam][subrefiTeamMassStored] = 0
        tTeamData[iAiBotTeam][subrefiTeamAverageEnergyPercentStored] = 1
        tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored] = 1
        tTeamData[iAiBotTeam][subrefiLowestEnergyStorageCount] = 100

        local iEnergyPercentTotal = 0
        local iMassPercentTotal = 0
        local iEnergyBrainCount = 0
        local iMassBrainCount = 0


        for iBrain, oBrain in tTeamData[iAiBotTeam][subreftoFriendlyActiveAiBotBrains] do
            if bIncludeHumanBrains or oBrain.BrainType == 'AI' then
                tTeamData[iAiBotTeam][subrefiTeamGrossEnergy] = tTeamData[iAiBotTeam][subrefiTeamGrossEnergy] + (oBrain[AiBotEconomy.refiGrossEnergyBaseIncome] or 0)
                tTeamData[iAiBotTeam][subrefiTeamGrossMass] = tTeamData[iAiBotTeam][subrefiTeamGrossMass] + (oBrain[AiBotEconomy.refiGrossMassBaseIncome] or 0)
                --Adjust gross values if the recorded values seem significantly differnet - decided to leave out as there seems to be a 1 tick delay which causes discrepencies
                --[[if math.abs(oBrain[AiBotEconomy.refiGrossEnergyBaseIncome] - oBrain:GetEconomyIncome('ENERGY')) >= math.max(30, oBrain[AiBotEconomy.refiGrossEnergyBaseIncome] * 0.1) then
                    AiBotUtilities.ErrorHandler('We have calculated gross energy income to be '..oBrain[AiBotEconomy.refiGrossEnergyBaseIncome]..'; including reclaim though it appears to be '..oBrain:GetEconomyIncome('ENERGY')..'; will use the system generated value as wouldnt expect reclaim to cause such a big difference', true)
                    oBrain[AiBotEconomy.refiGrossEnergyBaseIncome] = oBrain:GetEconomyIncome('ENERGY')
                end--]]

                tTeamData[iAiBotTeam][subrefiTeamNetEnergy] = tTeamData[iAiBotTeam][subrefiTeamNetEnergy] + (oBrain[AiBotEconomy.refiNetEnergyBaseIncome] or 0)
                tTeamData[iAiBotTeam][subrefiTeamNetMass] = tTeamData[iAiBotTeam][subrefiTeamNetMass] + (oBrain[AiBotEconomy.refiNetMassBaseIncome] or 0)


                if oBrain:GetEconomyStored('ENERGY') > 0 then
                    iEnergyPercentTotal = iEnergyPercentTotal + oBrain:GetEconomyStoredRatio('ENERGY')
                    tTeamData[iAiBotTeam][subrefiTeamEnergyStored] = tTeamData[iAiBotTeam][subrefiTeamEnergyStored] + oBrain:GetEconomyStored('ENERGY')
                    iEnergyBrainCount = iEnergyBrainCount + 1
                end

                if oBrain:GetEconomyStored('MASS') > 0 then
                    tTeamData[iAiBotTeam][subrefiTeamMassStored] = tTeamData[iAiBotTeam][subrefiTeamMassStored] + oBrain:GetEconomyStored('MASS')
                    iMassPercentTotal = iMassPercentTotal + oBrain:GetEconomyStoredRatio('MASS')
                    iMassBrainCount = iMassBrainCount + 1
                end

                --tTeamData[iAiBotTeam][subrefiTeamAverageEnergyPercentStored] = math.min(tTeamData[iAiBotTeam][subrefiTeamAverageEnergyPercentStored], oBrain:GetEconomyStoredRatio('ENERGY'))
                --tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored] = math.min(tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored], oBrain:GetEconomyStoredRatio('MASS'))
                tTeamData[iAiBotTeam][subrefiLowestEnergyStorageCount] = math.min(tTeamData[iAiBotTeam][subrefiLowestEnergyStorageCount], oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryEnergyStorage + AiBotUnitInfo.refCategoryParagon + AiBotUnitInfo.refCategoryQuantumOptics))
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Considering brain '..oBrain.Nickname..'; Brain mass stored='..oBrain:GetEconomyStored('MASS')..'; Percent stored='..oBrain:GetEconomyStoredRatio('MASS')..'; iMassPercentTotal='..iMassPercentTotal..'; iEnergyPercentTotal='..iEnergyPercentTotal..'; oBrain:IsDefeated()='..tostring(oBrain:IsDefeated())..'; oBrain.AiBotIsDefeated='..tostring(oBrain.AiBotIsDefeated or false)..'; bIncludeHumanBrains='..tostring(bIncludeHumanBrains)) end
        end
        tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored] = iMassPercentTotal / math.max(1, iMassBrainCount)
        tTeamData[iAiBotTeam][subrefiTeamAverageEnergyPercentStored] = iEnergyPercentTotal / math.max(1, iEnergyBrainCount)

        if tTeamData[iAiBotTeam][subrefiTeamAverageEnergyPercentStored] <= 0.05 and (GetGameTimeSeconds() >= 120 or tTeamData[iAiBotTeam][subrefiTeamAverageEnergyPercentStored] <= 0.001) then tTeamData[iAiBotTeam][subrefbTeamIsStallingEnergy] = true end
        if tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored] == 0 and tTeamData[iAiBotTeam][subrefiTeamMassStored] < tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] * 25 then
            if not(tTeamData[iAiBotTeam][subrefbTeamIsStallingMass]) then tTeamData[iAiBotTeam][subrefbStallingMassFlaggedFromTeamEconomy] = true end
            tTeamData[iAiBotTeam][subrefbTeamIsStallingMass] = true
            tTeamData[iAiBotTeam][refiTimeOfLastMassStall] = GetGameTimeSeconds()
        end

        if bDebugMessages == true then LOG(sFunctionRef..': Prev team net mass before update='..repru(tTeamData[iAiBotTeam][subreftiPrevTeamNetMass])) end
        for iLastEntry = 5, 2, -1 do
            tTeamData[iAiBotTeam][subreftiPrevTeamNetMass][iLastEntry] = (tTeamData[iAiBotTeam][subreftiPrevTeamNetMass][iLastEntry-1] or 0)
        end
        tTeamData[iAiBotTeam][subreftiPrevTeamNetMass][1] = tTeamData[iAiBotTeam][subrefiTeamNetMass]
        if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..'; Prev team net mass after update='..repru(tTeamData[iAiBotTeam][subreftiPrevTeamNetMass])..'; team net mass='..tTeamData[iAiBotTeam][subrefiTeamNetMass]..'; Team new gross mass='..tTeamData[iAiBotTeam][subrefiTeamGrossMass]..'; tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored]='..tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored]) end

        ForkThread(ConsiderGettingUpgrades, iAiBotTeam)

        ForkThread(AiBotEconomy.ManageEnergyStalls, iAiBotTeam)

        if tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored] >= 0.9 then
            if bDebugMessages == true then LOG(sFunctionRef..': Are overflowing mass so will try and manage by clearing engineers with reclaim orders') end
            if tTeamData[iAiBotTeam][subrefiTeamMassStored] < 200 then
                local iTeamMaxMassStorage = 0
                for iBrain, oBrain in tTeamData[iAiBotTeam][subreftoFriendlyActiveAiBotBrains] do
                    iTeamMaxMassStorage = iTeamMaxMassStorage + oBrain[AiBotEconomy.refiMaxMassStorage]
                end
                if iTeamMaxMassStorage < 200 then
                    --E.g. sandbox games we might still have units but no storage capacity
                    if tTeamData[iAiBotTeam][subrefiTeamNetMass] < 0 then
                        tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored] = 0.2 --Avoids some of the 'we are overflowing mass majorly' logic
                    else
                        tTeamData[iAiBotTeam][subrefiTeamAverageMassPercentStored] = 0.5 --Avoids some of the 'we are overflowing mass majorly' logic
                    end
                else
                    AiBotUtilities.ErrorHandler('We think we are overflowing mass but we have less than 200 stored; if have engineer in core base we should try and build mass storage soon, iAiBotTeam='..(iAiBotTeam or 'nil')..'; Active AiBot on team='..tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount]..'; iTeamMaxMassStorage='..iTeamMaxMassStorage)
                    if bDebugMessages == true then
                        for iBrain, oBrain in tTeamData[iAiBotTeam][subreftoFriendlyActiveAiBotBrains] do
                            LOG(sFunctionRef..': oBrain='..oBrain.Nickname..'; Is defeated='..tostring(oBrain:IsDefeated())..'; AiBotIsDefeated='..tostring(oBrain.AiBotIsDefeated or false)..'; Cur units='..oBrain:GetCurrentUnits(categories.ALLUNITS)..'; ScenarioInfo.Options.Victory='..(ScenarioInfo.Options.Victory or 'nil'))
                        end
                    end
                end
            end
            ForkThread(AiBotEconomy.ManageMassOverflow, iAiBotTeam)
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function CheckEnemyACUStatus(iTeam)
    if not(tTeamData[iTeam][refbEnemyHasUpgradedACU]) then
        local aiBrain
        for iBrain, oBrain in tTeamData[iTeam][subreftoFriendlyActiveAiBotBrains] do
            aiBrain = oBrain
            break
        end
        if AiBotUtilities.IsTableEmpty(tTeamData[iTeam][reftEnemyACUs]) == false then
            for iACU, oACU in  tTeamData[iTeam][reftEnemyACUs] do
                if AiBotUnitInfo.IsUnitValid(oACU) and (GetGameTimeSeconds() >= 600 or (aiBrain.GetArmyIndex and AiBotUnitInfo.CanSeeUnit(aiBrain, oACU))) then --after 10m of gametime a human would assume enemy will have gun anyway
                    if oACU:IsUnitState('Upgrading') or (oACU[AiBotACU.refiUpgradeCount] or 0) > 0 then
                        tTeamData[iTeam][refbEnemyHasUpgradedACU] = true
                    end
                end
            end
        end
    end
end
function CheckForUnitsWithDisabledWeapons(iTeam)
    if AiBotUtilities.IsTableEmpty(tTeamData[iTeam][reftoUnitsWithDisabledWeapons]) == false then
        local iRecordedUnits = table.getn(tTeamData[iTeam][reftoUnitsWithDisabledWeapons])
        for iCurUnit = iRecordedUnits, 1, -1 do
            local oUnit = tTeamData[iTeam][reftoUnitsWithDisabledWeapons][iCurUnit]
            if AiBotUnitInfo.IsUnitValid(oUnit) then
                --Has it been a while since we last wanted to disable the weapon?
                if GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiTimeLastDisabledWeapon] or 0) >= 2.01 then
                    AiBotUnitInfo.EnableUnitWeapon(oUnit)
                end
            else
                --Unit not valid, remove from table
                table.remove(tTeamData[iTeam][reftoUnitsWithDisabledWeapons], iCurUnit)
            end
        end
    end
end

function TeamOverseer(iAiBotTeam)
    while tTeamData[iAiBotTeam][subrefiActiveAiBotBrainCount] > 0 do
        ForkThread(TeamEconomyRefresh, iAiBotTeam)
        ForkThread(CheckEnemyACUStatus, iAiBotTeam)
        ForkThread(CheckForUnitsWithDisabledWeapons, iAiBotTeam)
        ForkThread(RefreshRecentEnemyTeleportLocations, iAiBotTeam)
        WaitTicks(10)
    end
end

function TeamInitialisation(iAiBotTeam)
    --First check if we have any AiBot brains in this team (otherwise dont do anything further)
    --NOTE: CreateNewTeam function includes various team setup variables
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'TeamInitialisation'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if bDebugMessages == true then LOG(sFunctionRef..': Will initialise team based logic for the team '..iAiBotTeam..'; Is the table of friendly active AiBot brains empty='..tostring(AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftoFriendlyActiveAiBotBrains]))..'; Do we already have an active team cycler='..tostring(tTeamData[iAiBotTeam]['AiBotTeamActiveTeamCycler'] or false)) end

    AiBotMap.bFirstAiBotTeamHasBeenInitialised = true
    if AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftoFriendlyActiveAiBotBrains]) == false then
        if not(tTeamData[iAiBotTeam]['AiBotTeamActiveTeamCycler']) then
            tTeamData[iAiBotTeam]['AiBotTeamActiveTeamCycler'] = true
            if bDebugMessages == true then LOG(sFunctionRef..': About to start land zone overseer which carries out main over time loop') end
            ForkThread(AiBotLand.LandZoneOverseer, iAiBotTeam)
            ForkThread(TeamOverseer, iAiBotTeam)
            ForkThread(AiBotEconomy.TeamResourceSharingMonitor, iAiBotTeam)
            ForkThread(AiBotNavy.WaterZoneOverseer, iAiBotTeam)
            ForkThread(SnipeOverseer, iAiBotTeam)
        end
    end

    --Include variables for land zones
    for iPlateau, tPlateauData in AiBotMap.tAllPlateaus do
        for iLZ, tLZData in tPlateauData[AiBotMap.subrefPlateauLandZones] do
            if bDebugMessages == true then LOG(sFunctionRef..': Recording team data for iPlateau='..iPlateau..'; iLZ='..iLZ..'; iTeam='..iAiBotTeam) end
            if not(tLZData[AiBotMap.subrefLZTeamData]) then tLZData[AiBotMap.subrefLZTeamData] = {} end
            tLZData[AiBotMap.subrefLZTeamData][iAiBotTeam] = {}
            tLZData[AiBotMap.subrefLZTeamData][iAiBotTeam][AiBotMap.subreftoLZOrWZAlliedUnits] = {}
