            tLZData[AiBotMap.subrefLZTeamData][iAiBotTeam][AiBotMap.subrefSpareBPByTech] = {}
        end
    end
    --NOTE: Water zone data is handled via RecordClosestAllyAndEnemyBaseForEachWaterZone, to ensure it is run after water zones are created
    if AiBotUtilities.IsTableEmpty(tTeamData[iAiBotTeam][subreftoFriendlyActiveAiBotBrains]) == false then
        if bDebugMessages == true then LOG(sFunctionRef..': Team has active AiBot brains, iAiBotTeam='..iAiBotTeam..'; Time='..GetGameTimeSeconds()..'; bWaterZoneInitialCreation='..tostring(AiBotMap.bWaterZoneInitialCreation or false)) end
        TeamEconomyRefresh(iAiBotTeam)
        ForkThread(AiBotMap.RecordClosestAllyAndEnemyBaseForEachLandZone, iAiBotTeam)
        ForkThread(AiBotMap.RecordClosestAllyAndEnemyBaseForEachWaterZone, iAiBotTeam)
        ForkThread(ConsiderSpecialStrategyAssignment, iAiBotTeam)
        AiBotAir.AirTeamInitialisation(iAiBotTeam)
        local iAiBotCount = 0
        for iBrain, oBrain in tTeamData[iAiBotTeam][subreftoFriendlyActiveAiBotBrains] do
            iAiBotCount = iAiBotCount + 1
        end
        tTeamData[iAiBotTeam][subrefiOrigAiBotBrainCount] = iAiBotCount

    else
        tTeamData[iAiBotTeam][subrefiOrigAiBotBrainCount] = 0
    end

    SetIfLoseGameOnACUDeath(iAiBotTeam)

    if bDebugMessages == true then LOG(sFunctionRef..': End of code for team '..iAiBotTeam..' at time='..GetGameTimeSeconds()) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

