function WaterZoneTeamInitialisation(iTeam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'WaterZoneTeamInitialisation'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    AiBotMap.bWaterZoneFirstTeamInitialisation = true
    tTeamData[iTeam][subrefiWaterZonesWantingSignificantMAAByPlateau] = {}
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code at gamestime='..GetGameTimeSeconds()..', iTeam='..iTeam) end
    for iPond, tPondSubtable in AiBotMap.tPondDetails do
        for iWaterZone, tWZData in tPondSubtable[AiBotMap.subrefPondWaterZones] do
            if bDebugMessages == true then LOG(sFunctionRef..': Setting starting values for iPond='..iPond..'; iWaterZone='..iWaterZone) end
            SetWaterZoneDefaultTeamValues(tWZData, iTeam)
        end
    end
    --Record any start positions of friendly AiBotAI that are on water as waterstartposition for team data
    local tUnderwaterAiBotStartPoints = {}
    for iBrain, oBrain in tTeamData[iTeam][subreftoFriendlyActiveAiBotBrains] do
        local iStartPositionX, iStartPositionZ = AiBotMap.GetPlayerStartPosition(oBrain, true)
        local tStartPoint = {iStartPositionX, GetSurfaceHeight(iStartPositionX, iStartPositionZ), iStartPositionZ}
        if bDebugMessages == true then LOG(sFunctionRef..': tStartPoint='..repru(tStartPoint)..'; iStartPositionX='..iStartPositionX..'; iStartPositionZ='..iStartPositionZ..'; Surface height='..GetSurfaceHeight(iStartPositionX, iStartPositionZ)..'; Terrain height='..GetTerrainHeight(iStartPositionX, iStartPositionZ)) end
        if GetTerrainHeight(iStartPositionX, iStartPositionZ) < tStartPoint[2] then
            table.insert(tUnderwaterAiBotStartPoints, tStartPoint )
        end
    end
    if AiBotUtilities.IsTableEmpty(tUnderwaterAiBotStartPoints) == false then
        for iEntry, tStartPoint in tUnderwaterAiBotStartPoints do
            local iPlateauOrZero, iWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tStartPoint)
            if iPlateauOrZero == 0 and (iWaterZone or 0) > 0 then
                local tWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iWaterZone]][AiBotMap.subrefPondWaterZones][iWaterZone][AiBotMap.subrefWZTeamData][iTeam]
                tWZTeamData[AiBotMap.subrefWZbContainsUnderwaterStart] = true
                if bDebugMessages == true then LOG(sFunctionRef..': Recording that iWaterzone'..iWaterZone..' is underwater for the AiBot start position '..repru(tStartPoint)) end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function UpdateEnemyTechTracking(iAiBotTeam, oUnit)
    local iUnitTechLevel = AiBotUnitInfo.GetUnitTechLevel(oUnit)
    if EntityCategoryContains(categories.LAND, oUnit.UnitId) then
        tTeamData[iAiBotTeam][subrefiHighestEnemyGroundTech] = math.max(tTeamData[iAiBotTeam][subrefiHighestEnemyGroundTech], iUnitTechLevel)
        if iUnitTechLevel == 3 then
            if not(tTeamData[iAiBotTeam][refbEnemyHasPerciesOrBricks]) then
                if oUnit.UnitId == 'xel0305' or oUnit.UnitId == 'xrl0305' then tTeamData[iAiBotTeam][refbEnemyHasPerciesOrBricks] = true end
            end
            if AiBotUtilities.bQuietModActive and not(tTeamData[iAiBotTeam][refbEnemyHasHeavyLandT3]) then
                if oUnit.UnitId == 'xel0305' or oUnit.UnitId == 'xrl0305' or oUnit.UnitId == 'sal0311' or oUnit.UnitId == 'bsl0310' then tTeamData[iAiBotTeam][refbEnemyHasHeavyLandT3] = true end
            end
        elseif iUnitTechLevel == 2 then
            if AiBotUtilities.bQuietModActive and not(tTeamData[iAiBotTeam][refbEnemyHasHeavyLandT2]) then
                if oUnit.UnitId == 'wel0304' or oUnit.UnitId == 'brmt2medm' or oUnit.UnitId == 'brot2asb' or oUnit.UnitId == 'brpt2btbot' then tTeamData[iAiBotTeam][refbEnemyHasHeavyLandT2] = true end
            end
        elseif iUnitTechLevel == 1 then
            if AiBotUtilities.bQuietModActive and not(tTeamData[iAiBotTeam][refbEnemyHasHeavyLandT1]) then
                if oUnit.UnitId == 'uel0108' or oUnit.UnitId == 'brmt1exm1' or oUnit.UnitId == 'brot1exm1' or oUnit.UnitId == 'brpt1exm1' then tTeamData[iAiBotTeam][refbEnemyHasHeavyLandT1] = true end
            end
        end
    elseif EntityCategoryContains(categories.AIR, oUnit.UnitId) then tTeamData[iAiBotTeam][subrefiHighestEnemyAirTech] = math.max(tTeamData[iAiBotTeam][subrefiHighestEnemyAirTech], iUnitTechLevel)
    elseif EntityCategoryContains(categories.NAVAL, oUnit.UnitId) then tTeamData[iAiBotTeam][subrefiHighestEnemyNavyTech] = math.max(tTeamData[iAiBotTeam][subrefiHighestEnemyNavyTech], iUnitTechLevel)
    end
end

function GetCurrentUnitsOfCategory(iAiBotTeam, iCategory)
    local iCurUnits = 0
    for iBrain, oBrain in tTeamData[iAiBotTeam][subreftoFriendlyActiveAiBotBrains] do
        iCurUnits = iCurUnits + oBrain:GetCurrentUnits(iCategory)
    end
    return iCurUnits
end

function TransferUnitsToPlayer(tUnits, iArmyIndex, bCaptured)
    if AiBotOrders.bDontConsiderCombinedArmy then
        import('/lua/SimUtils.lua').TransferUnitsOwnership(tUnits, iArmyIndex, bCaptured)
    else
        local tUnitsToTransfer = {}
        for iUnit, oUnit in tUnits do
            if oUnit.AiBotActive then
                table.insert(tUnitsToTransfer, oUnit)
            end
        end
        if AiBotUtilities.IsTableEmpty(tUnitsToTransfer) == false then
            import('/lua/SimUtils.lua').TransferUnitsOwnership(tUnitsToTransfer, iArmyIndex, bCaptured)
        end
    end
end

function DelayedUnitTransferToPlayer(tUnits, iReceivingBrainIndex, iSecondsToWait)
    WaitSeconds(iSecondsToWait)
    TransferUnitsToPlayer(tUnits, iReceivingBrainIndex, false)
end

function GiveAllResourcesToAllies(aiBrain)
    local iMassToGive = aiBrain:GetEconomyStored('MASS')
    local iEnergyToGive = aiBrain:GetEconomyStored('ENERGY')
    local iSpareMassStorage
    local iSpareEnergyStorage
    for iBrain, oBrain in tTeamData[aiBrain.AiBotTeam][subreftoFriendlyHumanAndAIBrains] do
        if not(oBrain.AiBotIsDefeated) and (oBrain.AiBotAI or ScenarioInfo.Options.AiBotTeammate == 1) then
            iSpareMassStorage = 0
            iSpareEnergyStorage = 0
            if iMassToGive > 0 and aiBrain:GetEconomyStoredRatio('MASS') < 1 then
                iSpareMassStorage = AiBotEconomy.GetMassStorageMaximum(aiBrain) * (1 -aiBrain:GetEconomyStoredRatio('MASS'))
            end
            if iEnergyToGive > 0 and aiBrain:GetEconomyStoredRatio('ENERGY') < 1 then
                iSpareEnergyStorage = AiBotEconomy.GetEnergyStorageMaximum(aiBrain) * (1 -aiBrain:GetEconomyStoredRatio('ENERGY'))
            end

            if iSpareMassStorage + iSpareEnergyStorage > 0 then
                AiBotEconomy.GiveResourcesToPlayer(aiBrain, oBrain, math.min(iMassToGive, iSpareMassStorage), math.min(iEnergyToGive, iSpareEnergyStorage))
            end

        end
        if iMassToGive + iEnergyToGive < 0 then break end
    end
end

function RefreshActiveBrainListForBrainDeath(oDefeatedBrain)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RefreshActiveBrainListForBrainDeath'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, time='..GetGameTimeSeconds()..'; brain '..oDefeatedBrain.Nickname..' has died, will update all teams for this, iTotalTeamCount='..iTotalTeamCount) end

    LOG('Brain death detected for '..oDefeatedBrain.Nickname)
    AiBotOverseer.iTimeLastPlayerDefeat = GetGameTimeSeconds()

    --AiBot brains - monitor their start position and consider resetting core baes flag
    if oDefeatedBrain.AiBotAI then
        ForkThread(AiBotOverseer.ReviewTreatingOldBaseAsCoreBase, oDefeatedBrain)
    end

    for iTeam = 1, iTotalTeamCount do
        if oDefeatedBrain.AiBotTeam == iTeam then
            if AiBotUtilities.IsTableEmpty(tTeamData[iTeam][subreftoFriendlyHumanAndAIBrains]) == false then

                for iBrain, oBrain in tTeamData[iTeam][subreftoFriendlyHumanAndAIBrains] do
                    if oBrain == oDefeatedBrain then
                        if oBrain.AiBotAI then
                            for iAiBotBrain, oAiBotBrain in tTeamData[iTeam][subreftoFriendlyActiveAiBotBrains] do
                                if oAiBotBrain == oBrain then
                                    table.remove(tTeamData[iTeam][subreftoFriendlyActiveAiBotBrains], iAiBotBrain)
                                    break
                                end
                            end
                            tTeamData[iTeam][subrefiActiveAiBotBrainCount] = tTeamData[iTeam][subrefiActiveAiBotBrainCount] - 1
                        end
                        table.remove(tTeamData[iTeam][subreftoFriendlyHumanAndAIBrains], iBrain)
                        break
                    end
                end
            end
        else --Enemy team
            if AiBotUtilities.IsTableEmpty(tTeamData[iTeam][subreftoEnemyBrains]) == false then
                for iBrain, oBrain in tTeamData[iTeam][subreftoEnemyBrains] do
                    if oBrain == oDefeatedBrain then
                        table.remove(tTeamData[iTeam][subreftoEnemyBrains], iBrain)
                        break
                    end
                end
            end
            if AiBotUtilities.IsTableEmpty(tTeamData[iTeam][subreftoEnemyBrains]) then
                tTeamData[iTeam][subrefbAllEnemiesDefeated] = true
            end
        end
    end

    --Remove from air subteam
    local iAirSubteam = oDefeatedBrain.AiBotAirSubteam
    if AiBotUtilities.IsTableEmpty(tAirSubteamData[iAirSubteam][subreftoFriendlyAiBotBrains]) == false then
        for iBrain, oBrain in tAirSubteamData[iAirSubteam][subreftoFriendlyAiBotBrains] do
            if oBrain == oDefeatedBrain then
                table.remove(tAirSubteamData[iAirSubteam][subreftoFriendlyAiBotBrains], iBrain)
                break
            end
        end
    end

    --Remove from land subteam
    local iLandSubteam = oDefeatedBrain.AiBotLandSubteam
    if AiBotUtilities.IsTableEmpty(tLandSubteamData[iLandSubteam][subreftoFriendlyAiBotBrains]) == false then
        for iBrain, oBrain in tLandSubteamData[iLandSubteam][subreftoFriendlyAiBotBrains] do
            if oBrain == oDefeatedBrain then
                table.remove(tLandSubteamData[iLandSubteam][subreftoFriendlyAiBotBrains], iBrain)
                break
            end
        end
    end



    for iArmyIndex, oBrain in AiBotOverseer.tAllAIBrainsByArmyIndex do
        if oDefeatedBrain == oBrain then
            if AiBotOverseer.tAllAIBrainsByArmyIndex[iArmyIndex] == oDefeatedBrain then
                AiBotOverseer.tAllAIBrainsByArmyIndex[iArmyIndex] = nil
                if bDebugMessages == true then LOG(sFunctionRef..': Removed brain '..oBrain.Nickname..' from table of all AI Brains') end
            else --redundancy (due to issues having with ActiveAiBotBrains table)
                if bDebugMessages == true then LOG(sFunctionRef..': Activated redundancy for removing brain '..oBrain.Nickname..' from table of all AI Brains') end
                for iRecordedBrain, oRecordedBrain in AiBotOverseer.tAllAIBrainsByArmyIndex do
                    if oRecordedBrain == oDefeatedBrain then
                        AiBotOverseer.tAllAIBrainsByArmyIndex[iRecordedBrain] = nil
                        break
                    end
                end
            end
            if oBrain.AiBotAI then
                if AiBotOverseer.tAllActiveAiBotBrains[iArmyIndex] == oDefeatedBrain then
                    AiBotOverseer.tAllActiveAiBotBrains[iArmyIndex] = nil
                    if bDebugMessages == true then LOG(sFunctionRef..': Removed brain '..oBrain.Nickname..' from table of active AiBot Brains') end
                else
                    if bDebugMessages == true then LOG(sFunctionRef..': Activated redundancy for removing brain '..oBrain.Nickname..' from table of active AiBot brains') end
                    for iAiBotBrainEntry, oAiBotBrain in AiBotOverseer.tAllActiveAiBotBrains do
                        if oAiBotBrain == oDefeatedBrain then
                            AiBotOverseer.tAllActiveAiBotBrains[iAiBotBrainEntry] = nil
                            break
                        end
                    end
                end
            end
            break
        end
    end

    --Update primary enemy base locations for AiBot brain if their nearest brain is now defeated
    if AiBotUtilities.IsTableEmpty(AiBotOverseer.tAllActiveAiBotBrains) == false then
        for iBrain, oBrain in AiBotOverseer.tAllActiveAiBotBrains do
            if oBrain[AiBotOverseer.refoNearestEnemyBrain].AiBotIsDefeated then
                AiBotMap.UpdateNewPrimaryEnemyBaseLocation(oBrain)
            end
        end
    end

    --Set if down to last ACU
    SetIfLoseGameOnACUDeath(oDefeatedBrain.AiBotTeam)

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function TeamDeathChecker()
    WaitSeconds(1) --Make sure have given time for brains to be setup
    if not(bActiveTeamDeathChecker) and not(ScenarioInfo.Options.Victory == "demoralization") then
        bActiveTeamDeathChecker = true
        while AiBotUtilities.bAiBotAIInGame do
            --Treat any players as defeated when they show as defeated
            WaitSeconds(1)
            for iBrain, oBrain in ArmyBrains do
                if oBrain:IsDefeated() and not(oBrain.AiBotIsDefeated) then
                    ForkThread(AiBotEvents.OnPlayerDefeated, oBrain)
                end
            end
        end
        bActiveTeamDeathChecker = false
    end
end

function DelayedPlayerDeathCheck()
    WaitSeconds(1)
    for iBrain, oBrain in ArmyBrains do
        if oBrain:IsDefeated() and not(oBrain.AiBotIsDefeated) then
            AiBotEvents.OnPlayerDefeated(oBrain)
        end
    end
end

function ConsiderGiftingStorageToTeammate(oEnergyStorage)
    --If have a teammate with less energy storage then will gift the energy storage to them
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderGiftingStorageToTeammate'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local aiBrain = oEnergyStorage:GetAIBrain()
    local iTeam = aiBrain.AiBotTeam
    if bDebugMessages == true then LOG(sFunctionRef..': Brain '..aiBrain.Nickname..' has just built energy storage '..oEnergyStorage.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnergyStorage)..'; active AiBot brain count for team '..iTeam..' = '..tTeamData[iTeam][subrefiActiveAiBotBrainCount]..'; Total no. of storage for this brain='..aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryEnergyStorage + AiBotUnitInfo.refCategoryParagon + AiBotUnitInfo.refCategoryQuantumOptics)..'; lowest storage count for team='..tTeamData[iTeam][subrefiLowestEnergyStorageCount]) end
    if tTeamData[iTeam][subrefiActiveAiBotBrainCount] > 1 then
        local iOurEnergyStorage = aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryEnergyStorage + AiBotUnitInfo.refCategoryParagon + AiBotUnitInfo.refCategoryQuantumOptics)
        if iOurEnergyStorage >= 2 and iOurEnergyStorage > 1 + tTeamData[iTeam][subrefiLowestEnergyStorageCount] then
            for iBrain, oBrain in  tTeamData[iTeam][subreftoFriendlyActiveAiBotBrains] do
                if not(oBrain == aiBrain) and oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryEnergyStorage + AiBotUnitInfo.refCategoryParagon + AiBotUnitInfo.refCategoryQuantumOptics) + 1 < iOurEnergyStorage then
                    --We have 2 less energy storage so want to give this storage to them
                    if bDebugMessages == true then LOG(sFunctionRef..': Brain '..oBrain.Nickname..' only has '..oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryEnergyStorage + AiBotUnitInfo.refCategoryParagon + AiBotUnitInfo.refCategoryQuantumOptics)..' energy storage type buildings so will gift this storage to them') end
                    TransferUnitsToPlayer({ oEnergyStorage }, oBrain:GetArmyIndex(), false)
                    ForkThread(TeamEconomyRefresh, iTeam)
                    break
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GetFirstActiveAiBotBrain(iTeam)
    if AiBotUtilities.IsTableEmpty(tTeamData[iTeam][subreftoFriendlyActiveAiBotBrains]) == false then
        for iBrain, oBrain in tTeamData[iTeam][subreftoFriendlyActiveAiBotBrains] do
            if not(oBrain.AiBotIsDefeated) then
                return oBrain
            end
        end
    end
end

function GiftAdjacentStorageToMexOwner(oJustBuilt, oOptionalBrainToGiftTo)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GiftAdjacentStorageToMexOwner'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local tMexLocation = oJustBuilt:GetPosition()
    local rSearchRectangle = AiBotUtilities.GetRectAroundLocation(tMexLocation, 2.749) --If changing this also change AiBotEconomy and AiBotEngineer similar value
    local tNearbyUnits = GetUnitsInRect(rSearchRectangle) --at 1.5 end up with storage thats not adjacent being gifted in some cases but not in others; at 1 none of it gets gifted; the mass storage should be exactly 2 from the mex; however even at 2.1, 2.25 and 2.499 had cases where the mex wasnt identified so will try 2.75 since distances can vary/be snapped to the nearest 0.5 I think
    local iBrainIndexToGiftTo
    if oOptionalBrainToGiftTo then iBrainIndexToGiftTo = oOptionalBrainToGiftTo:GetArmyIndex()
    else iBrainIndexToGiftTo = oJustBuilt:GetAIBrain():GetArmyIndex()
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Storage gifting where built mex - oJustBuilt='..oJustBuilt.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oJustBuilt)..'; owner='..oJustBuilt:GetAIBrain().Nickname..'; is tNearbyUnits empty='..tostring(AiBotUtilities.IsTableEmpty(tNearbyUnits))) end
    if AiBotUtilities.IsTableEmpty(tNearbyUnits) == false then
        local tNearbyStorage = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMassStorage, tNearbyUnits)
        if AiBotUtilities.IsTableEmpty(tNearbyStorage) == false then
            local oCurBrain
            for iUnit, oUnit in tNearbyStorage do
                oCurBrain = oUnit:GetAIBrain()
                if not(oCurBrain.AiBotIsDefeated) and not(oCurBrain:IsDefeated()) and not(iBrainIndexToGiftTo == oCurBrain:GetArmyIndex()) then
                    if IsAlly(iBrainIndexToGiftTo, oUnit:GetAIBrain():GetArmyIndex()) and (oUnit:GetAIBrain().AiBotAI or ScenarioInfo.Options.AiBotTeammate == 1) then
                        if bDebugMessages == true then LOG(sFunctionRef..': About to transfer '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' from brain '..oUnit:GetAIBrain().Nickname..' to '..oJustBuilt:GetAIBrain().Nickname..'; Dist from unit to tMexLocation='..AiBotUtilities.GetDistanceBetweenPositions(tMexLocation, oUnit:GetPosition())) end
                        if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tMexLocation) <= 2.25 then
                            if bDebugMessages == true then LOG(sFunctionRef..': Will try and gift the storage to the player that built the mex') end
                            TransferUnitsToPlayer({oUnit}, iBrainIndexToGiftTo, false)
                        end
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function RecordMobileEnemyTMLForTeam(oTML, iTeam)
    local bAlreadyIncluded = false
    if not(tTeamData[iTeam][reftEnemyMobileTML]) then
        tTeamData[iTeam][reftEnemyMobileTML] = {}
    elseif AiBotUtilities.IsTableEmpty(tTeamData[iTeam][reftEnemyMobileTML]) == false then
        for iUnit, oUnit in tTeamData[iTeam][reftEnemyMobileTML] do
            if oUnit == oTML then bAlreadyIncluded = true end
        end
    end
    if not(bAlreadyIncluded) then
        table.insert(tTeamData[iTeam][reftEnemyMobileTML], oTML)
        oTML[AiBotBuilding.reftMobileTMLLastLocationChecked] = nil
        ForkThread(MonitorEnemyMobileTMLThreats, iTeam)
    end
end

function RecordMobileTMLThreatForAllEnemyTeams(oTML)
    --Intended for ACUs, SACUs, and potentially UEF/Sera cruisers and Aeon missile ship
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RecordMobileTMLThreatForAllEnemyTeams'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    while not(AiBotMap.bMapLandSetupComplete) do
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitTicks(1)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        if GetGameTimeSeconds() >= 10 then break end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code for oTML='..(oTML.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oTML) or 'nil')) end
    if AiBotUnitInfo.IsUnitValid(oTML) then
        if AiBotUtilities.IsTableEmpty(AiBotOverseer.tAllActiveAiBotBrains) == false then
            local tiTeamsToUpdate = {}
            local iTMLArmyIndex = oTML:GetAIBrain():GetArmyIndex()
            local bUnitIsValid = true
            for iBrain, oBrain in AiBotOverseer.tAllActiveAiBotBrains do
                if not(tiTeamsToUpdate[oBrain.AiBotTeam]) and IsEnemy(oBrain:GetArmyIndex(), iTMLArmyIndex) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering oBrain='..oBrain.Nickname..'; Team='..(oBrain.AiBotTeam or 'nil')) end
                    while not(oBrain.AiBotTeam) do --Cybran mission 4 causes lua error due to this triggering before teams have been assigned
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                        WaitTicks(1)
                        bUnitIsValid = false
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                        if GetGameTimeSeconds() >= 10 then break end
                    end
                    if not(bUnitIsValid) then bUnitIsValid = AiBotUnitInfo.IsUnitValid(oTML) end
                    if bUnitIsValid then
                        tiTeamsToUpdate[oBrain.AiBotTeam] = true
                    end
                end
                if AiBotUtilities.IsTableEmpty(tiTeamsToUpdate) == false and bUnitIsValid then
                    for iTeam, bUpdate in tiTeamsToUpdate do
                        RecordMobileEnemyTMLForTeam(oTML, iTeam)
                    end
                end
            end
        end
    end
end

function MonitorEnemyMobileTMLThreats(iTeam)
    --Whenever an enemy mobile TML threat has moved by more than 15 from its last recorded postiion, update its targets
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'MonitorEnemyMobileTMLThreats'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, activem TML monitor='..tostring(tTeamData[iTeam][refbActiveMobileTMLMonitor] or false)..'; Gametime='..GetGameTimeSeconds()) end
    if not(tTeamData[iTeam][refbActiveMobileTMLMonitor]) then
        tTeamData[iTeam][refbActiveMobileTMLMonitor] = true
        if bDebugMessages == true then LOG(sFunctionRef..': Is table of enemy mobile TML empty='..tostring(AiBotUtilities.IsTableEmpty(tTeamData[iTeam][reftEnemyMobileTML]))) end
        local iCurTableSize = 0
        local iMinTickDelay = 50
        local iDistFromLastCheck, iTimeFromLastCheck

        local iMinDistToHaveMoved
        local iModerateDistToHaveMoved
        local iMinSecondsSinceLastCheck
        local iMaxSecondsSinceLastCheck

        local iLargeTableSize = 40
        local iSmallTableSize = 10
        local iPercentageTableSize


        while AiBotUtilities.IsTableEmpty(tTeamData[iTeam][reftEnemyMobileTML]) == false do
            local iTicksWaitedThisCycle = 0
            if AiBotConditions.IsTableOfUnitsStillValid(tTeamData[iTeam][reftEnemyMobileTML]) then
                iCurTableSize = table.getn(tTeamData[iTeam][reftEnemyMobileTML])

                if iCurTableSize >= iLargeTableSize then
                    iMinDistToHaveMoved = 15
                    iModerateDistToHaveMoved = 60
                    iMinSecondsSinceLastCheck = 10
                    iMaxSecondsSinceLastCheck = 90
                    iMinTickDelay = 100

                elseif iCurTableSize <= iSmallTableSize then
                    iMinDistToHaveMoved = 5
                    iModerateDistToHaveMoved = 15
                    iMinSecondsSinceLastCheck = 3
                    iMaxSecondsSinceLastCheck = 30
                    iMinTickDelay = 50
                else
                    iPercentageTableSize = (iCurTableSize - iSmallTableSize)/(iLargeTableSize - iSmallTableSize)
                    iMinDistToHaveMoved = 5 + 10 * iPercentageTableSize
                    iModerateDistToHaveMoved = 15 + 45 * iPercentageTableSize
                    iMinSecondsSinceLastCheck = 3 + 7 * iPercentageTableSize
                    iMaxSecondsSinceLastCheck = 30 + 60 * iPercentageTableSize
                    iMinTickDelay = 50 + 50 * iPercentageTableSize
                end
                if AiBotUtilities.bCPUPerformanceMode then
                    iMinDistToHaveMoved = iMinDistToHaveMoved + 5
                    iModerateDistToHaveMoved = iModerateDistToHaveMoved + 10
                    iMinSecondsSinceLastCheck = iMinSecondsSinceLastCheck + 5
                    iMaxSecondsSinceLastCheck = iMaxSecondsSinceLastCheck + 30
                end

                --oUnit[refbRecentlyCheckedTMDOrTML]
                for iUnit, oUnit in tTeamData[iTeam][reftEnemyMobileTML] do
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to update oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Cur position='..repru(oUnit:GetPosition())..'; Last location checked='..repru(oUnit[AiBotBuilding.reftMobileTMLLastLocationChecked])..'; Time since last hceck='..GetGameTimeSeconds() - (oUnit[AiBotBuilding.refiTimeMobileTMLLastChecked] or -1000)) end
                    if oUnit[AiBotBuilding.reftMobileTMLLastLocationChecked] then iDistFromLastCheck = AiBotUtilities.GetDistanceBetweenPositions(oUnit[AiBotBuilding.reftMobileTMLLastLocationChecked], oUnit:GetPosition())
                    else iDistFromLastCheck = 10000
                    end
                    iTimeFromLastCheck = GetGameTimeSeconds() - (oUnit[AiBotBuilding.refiTimeMobileTMLLastChecked] or -100)
                    if iTimeFromLastCheck >= iMaxSecondsSinceLastCheck
                            or (iDistFromLastCheck >= iMinDistToHaveMoved and iTimeFromLastCheck >= iMinSecondsSinceLastCheck and (iDistFromLastCheck >= iModerateDistToHaveMoved or (oUnit[AiBotUnitInfo.refiLastWeaponEvent] and GetGameTimeSeconds() - oUnit[AiBotUnitInfo.refiLastWeaponEvent] <= 5 and oUnit[AiBotBuilding.refbTMDBuiltSinceLastChecked]))) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Will record units in range of TML now') end
                        AiBotBuilding.RecordUnitsInRangeOfTMLAndAnyTMDProtection(oUnit, nil, false)
                        oUnit[AiBotBuilding.refbTMDBuiltSinceLastChecked] = false
                        oUnit[AiBotBuilding.reftMobileTMLLastLocationChecked] = {oUnit:GetPosition()[1], oUnit:GetPosition()[2], oUnit:GetPosition()[3]}
                        oUnit[AiBotBuilding.refiTimeMobileTMLLastChecked] = GetGameTimeSeconds()
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                        WaitTicks(1)
                        iTicksWaitedThisCycle = iTicksWaitedThisCycle + 1
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                    end
                end
            else
                break
            end
            if iTicksWaitedThisCycle < iMinTickDelay then --Want to refresh no more quickly than once every 5s
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                WaitTicks(iMinTickDelay - iTicksWaitedThisCycle)
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            end
        end
        tTeamData[iTeam][refbActiveMobileTMLMonitor] = false
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function RefreshPotentialTeleSnipeTargets(iTeam, iOptionalMaxTimeDelayInSeconds)
    --Refresh every 5s (or iOptionalMaxTimeDelayInSeconds if specified)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RefreshPotentialTeleSnipeTargets'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': Start of code for iTeam '..iTeam..'; iOptionalMaxTimeDelayInSeconds='..(iOptionalMaxTimeDelayInSeconds or 'nil')..'; Time since last snipe refresh='..GetGameTimeSeconds() - (tTeamData[iTeam][refiTimeOfLastTeleSnipeRefresh] or -100)) end
    if GetGameTimeSeconds() - (tTeamData[iTeam][refiTimeOfLastTeleSnipeRefresh] or -100) >= (iOptionalMaxTimeDelayInSeconds or 5) then
        tTeamData[iTeam][refiTimeOfLastTeleSnipeRefresh] = GetGameTimeSeconds()
        tTeamData[iTeam][reftoPotentialTeleSnipeTargets] = {}
        --Target enemy gameenders, T3 arti, and ACUs (in assassination)
        local tEnemyUnitsToConsider = {}
        local aiBrain = GetFirstActiveAiBotBrain(iTeam)
        function AddTableOfUnits(sRef, bMobileUnitChecks)
            if AiBotUtilities.IsTableEmpty(tTeamData[iTeam][sRef]) == false then
                for iUnit, oUnit in tTeamData[iTeam][sRef] do
                    --require unit to be visible so we are more likely to have determined what PD is around it
                    if bDebugMessages == true and AiBotUnitInfo.IsUnitValid(oUnit) then LOG(sFunctionRef..': Considering whether to add to table of units to consider, sRef='..sRef..'; oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Can see unit='..tostring(AiBotUnitInfo.CanSeeUnit(aiBrain, oUnit))..'; Fraction complete='..oUnit:GetFractionComplete()..'; Unit state='..AiBotUnitInfo.GetUnitState(oUnit)) end
                    if AiBotUnitInfo.IsUnitValid(oUnit) and AiBotUnitInfo.CanSeeUnit(aiBrain, oUnit) and oUnit:GetFractionComplete() >= 0.5 then
                        if not(bMobileUnitChecks) or (not(AiBotUnitInfo.IsUnitUnderwater(oUnit)) and not(oUnit:IsUnitState('Moving')) and not(oUnit:IsUnitState('Attached')) and not(oUnit:IsUnitState('Attacking'))) then
                            table.insert(tEnemyUnitsToConsider, oUnit)
                        end
                    end
                end
            end
        end
        AddTableOfUnits(reftEnemyArtiAndExpStructure)
        if ScenarioInfo.Options.Victory == "demoralization" then AddTableOfUnits(reftEnemyACUs, true) end
        if bDebugMessages == true then LOG(sFunctionRef..': Is table of enemy units empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyUnitsToConsider))) end
        if AiBotUtilities.IsTableEmpty(tEnemyUnitsToConsider) == false then
            local iCurPlateauOrZero, iCurLandOrWaterZone
            for iUnit, oUnit in tEnemyUnitsToConsider do
                --Consider the nearby threat at the location
                iCurPlateauOrZero, iCurLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
                if bDebugMessages == true then LOG(sFunctionRef..': Considering ifu nit is a viable target, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iCurPlateauOrZero='..(iCurPlateauOrZero or 'nil')..'; iCurLandOrWaterZone='..(iCurLandOrWaterZone or 'nil')) end
                if iCurPlateauOrZero > 0 and (iCurLandOrWaterZone or 0) > 0 then
                    local tLZData = AiBotMap.tAllPlateaus[iCurPlateauOrZero][AiBotMap.subrefPlateauLandZones][iCurLandOrWaterZone]
                    local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][iTeam]
                    --Ignore zones with large threat just in the zone itself
                    if bDebugMessages == true then LOG(sFunctionRef..': tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal]='..tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal]..'; tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]='..tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]..'; tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat]='..tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat]) end
                    if tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] < 10000 and tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] <= 30000 and tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] <= 2500 then
                        local tPDInZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryPD, tLZTeamData[AiBotMap.subrefTEnemyUnits])
                        if not(tPDInZone) then tPDInZone = {} end
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering P'..iCurPlateauOrZero..'Z'..iCurLandOrWaterZone..'; Is table of adj LZs empty='..tostring(AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]))) end
                        if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                            for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                local tAdjLZData = AiBotMap.tAllPlateaus[iCurPlateauOrZero][AiBotMap.subrefPlateauLandZones][iAdjLZ]
                                local tAdjLZTeamData = tAdjLZData[AiBotMap.subrefLZTeamData][iTeam]
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering iAdjLZ='..iAdjLZ..'; Is subrefTEnemyUnits empty='..tostring(AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefTEnemyUnits]))) end
                                if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                                    local tAdjPD = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryPD, tAdjLZTeamData[AiBotMap.subrefTEnemyUnits])
                                    if bDebugMessages == true then LOG(sFunctionRef..': Is tAdjPD empty='..tostring( AiBotUtilities.IsTableEmpty(tAdjPD))) end
                                    if AiBotUtilities.IsTableEmpty(tAdjPD) == false then
                                        for iPD, oPD in tAdjPD do
                                            table.insert(tPDInZone, oPD)
                                        end
                                    end
                                end
                            end
                            local iNearbyPDThreat = 0
                            if AiBotUtilities.IsTableEmpty(tPDInZone) == false then
                                local tPDInRange = {}
                                for iPD, oPD in tPDInZone do
                                    if AiBotUnitInfo.IsUnitValid(oPD) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Dist between PD and target unit='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oPD:GetPosition())..'; PD DF range='..oPD[AiBotUnitInfo.refiDFRange]) end
                                        if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oPD:GetPosition()) <= 5 + oPD[AiBotUnitInfo.refiDFRange] then
                                            table.insert(tPDInRange, oPD)
                                        end
                                    end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': Is tPDInRange empty='..tostring(AiBotUtilities.IsTableEmpty(tPDInRange))) end
                                if AiBotUtilities.IsTableEmpty(tPDInRange) == false then
                                    iNearbyPDThreat = AiBotUnitInfo.GetMassCostOfUnits(tPDInRange)
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': iNearbyPDThreat='..iNearbyPDThreat) end
                            if iNearbyPDThreat <= 2000 then
                                if bDebugMessages == true then LOG(sFunctionRef..': Adding unit to table of potential tele snipe targets as not much PD threat') end
                                table.insert(tTeamData[iTeam][reftoPotentialTeleSnipeTargets], oUnit)
                            else
                                --Still add if there is al ocation with low PD threat
                                if not(oUnit[AiBotUnitInfo.refbTooMuchPDForSnipe]) then
                                    if AiBotACU.GetBestLocationForTeleSnipeTarget(nil, oUnit, iTeam, true) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': We shoudl be able to teleport out of range of most of the PD so will still add as a telesnipe target') end
                                        table.insert(tTeamData[iTeam][reftoPotentialTeleSnipeTargets], oUnit)
                                    else
                                        oUnit[AiBotUnitInfo.refbTooMuchPDForSnipe] = true
                                        if bDebugMessages == true then LOG(sFunctionRef..': Unable to find al ocation that puts us out of range of the PD') end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end
    if bDebugMessages == true then
        if AiBotUtilities.IsTableEmpty(tTeamData[iTeam][reftoPotentialTeleSnipeTargets]) then LOG(sFunctionRef..': End of code, no telesnipe targets')
        else LOG(sFunctionRef..': End of code, size of telesnipe targets table='..table.getn(tTeamData[iTeam][reftoPotentialTeleSnipeTargets]))
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function CheckIfCampaignTeamHasBuildings(iTeam)
    --Call via forkthread; will check if the aiBrain in question has any buildings (so can decide if should be very aggressive)
    local sFunctionRef = 'CheckIfCampaignAIHasBuildings'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if not(tTeamData[iTeam]['AiBotBuildingCheckerActive']) then
        tTeamData[iTeam]['AiBotBuildingCheckerActive'] = true
        tTeamData[iTeam][refbDontHaveBuildingsOrACUInPlayableArea] = false
        --Wait number of ticks based on army index
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitTicks(iTeam)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        while tTeamData[iTeam][subrefiActiveAiBotBrainCount] >= 1 do
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitSeconds(10)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            local bHaveBuildingsInPlayableArea = false

            for iBrain, oBrain in tTeamData[iTeam][subreftoFriendlyActiveAiBotBrains] do
                local tStructuresOrACU = oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryStructure + categories.COMMAND, false, true)
                if AiBotUtilities.IsTableEmpty(tStructuresOrACU) == false then
                    for iUnit, oUnit in tStructuresOrACU do
                        if oUnit:GetFractionComplete() == 1 then
                            if AiBotConditions.IsLocationInPlayableArea(oUnit:GetPosition()) then
                                bHaveBuildingsInPlayableArea = true
                                break
                            end
                        end
                    end
                end
                if bHaveBuildingsInPlayableArea then break end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Finished checking if iTeam='..iTeam..' has any buildings or ACU at time='..GetGameTimeSeconds()..'; bHaveBuildingsInPlayableArea='..tostring(bHaveBuildingsInPlayableArea or false)) end
            tTeamData[iTeam][refbDontHaveBuildingsOrACUInPlayableArea] = not(bHaveBuildingsInPlayableArea)
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GetEnemyMainCampaignBase(iTeam)
    --Intended fro campaign maps wher the enemy main base location is unreliable - will periodically refresh this and get the zone with the highest enemy structure threat in the playable area; failing that will get the first enemy brain start position in the playable area
    if GetGameTimeSeconds() - (tTeamData[iTeam][refiLastUpdatedMainBase] or -100) >= 60 then
        tTeamData[iTeam][refiLastUpdatedMainBase] = GetGameTimeSeconds()
        local iBestSValue = 0
        local tBestValueMidpoint, iCurSValue
        for iPlateau, tPlateauSubtable in AiBotMap.tAllPlateaus do
            for iLandZone, tLZData in tPlateauSubtable[AiBotMap.subrefPlateauLandZones] do
                if AiBotConditions.IsLocationInPlayableArea(tLZData[AiBotMap.subrefMidpoint]) then
                    local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][iTeam]
                    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                        local tBuildings = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryStructure, tLZTeamData[AiBotMap.subrefTEnemyUnits])
                        if AiBotUtilities.IsTableEmpty(tBuildings) == false then
                            iCurSValue = AiBotUnitInfo.GetMassCostOfUnits(tBuildings, true)
                            if iCurSValue > iBestSValue then
                                iBestSValue = iCurSValue
                                tBestValueMidpoint = {tLZData[AiBotMap.subrefMidpoint][1], tLZData[AiBotMap.subrefMidpoint][2], tLZData[AiBotMap.subrefMidpoint][3]}
                            end
                        end
                    end
                end
            end
        end
        tTeamData[iTeam][reftEnemyCampaignMainBase] = tBestValueMidpoint
    end
    return tTeamData[iTeam][reftEnemyCampaignMainBase]

end

function ConsiderGiftingSupportFactoriesToTeammateWithBetterHQ(aiBrain, sHQJustDiedOrSupportFacID)
    --Should call vai forkthread so happens after we have updated our highest tech level for the aiBrain
    local sFunctionRef = 'ConsiderGiftingSupportFactoriesToTeammateWithBetterHQ'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, brain='..aiBrain.Nickname..'; sHQJustDiedOrSupportFacID='..sHQJustDiedOrSupportFacID..' time='..GetGameTimeSeconds()) end
    if aiBrain.AiBotAI then
        local sBrainFactoryTechVaraible
        local iFactoryCategory
        if EntityCategoryContains(AiBotUnitInfo.refCategoryLandFactory, sHQJustDiedOrSupportFacID) then
            sBrainFactoryTechVaraible = AiBotEconomy.refiOurHighestLandFactoryTech
            iFactoryCategory = AiBotUnitInfo.refCategoryLandFactory
        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryAirFactory, sHQJustDiedOrSupportFacID) then
            sBrainFactoryTechVaraible = AiBotEconomy.refiOurHighestAirFactoryTech
            iFactoryCategory = AiBotUnitInfo.refCategoryAirFactory
        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryNavalFactory, sHQJustDiedOrSupportFacID) then
            sBrainFactoryTechVaraible = AiBotEconomy.refiOurHighestNavalFactoryTech
            iFactoryCategory = AiBotUnitInfo.refCategoryNavalFactory
        end
        if sBrainFactoryTechVaraible then
            local iTeam = aiBrain.AiBotTeam
            local iTechLevelDied = AiBotUnitInfo.GetBlueprintTechLevel(sHQJustDiedOrSupportFacID)
            local iOurHighestTechLevelOfFactoryType = aiBrain[sBrainFactoryTechVaraible]
            if bDebugMessages == true then LOG(sFunctionRef..': iOurHighestTechLevelOfFactoryType='..iOurHighestTechLevelOfFactoryType..'; iTechLevelDied='..iTechLevelDied) end
            if iOurHighestTechLevelOfFactoryType < iTechLevelDied then
                local iFactionType = AiBotUnitInfo.GetFactionNumberFromBlueprint(sHQJustDiedOrSupportFacID)
                if bDebugMessages == true then LOG(sFunctionRef..': iFactionType='..iFactionType) end
                local iFactionCategory = AiBotUnitInfo.ConvertFactionToCategory(iFactionType)
                local iTechCategory
                if iOurHighestTechLevelOfFactoryType <= 1 then
                    iTechCategory = categories.TECH2 + categories.TECH3
                else
                    iTechCategory = categories.TECH3
                end


                --Do we have support factories?
                local toSupportFactoriesToConsiderTransferring = aiBrain:GetListOfUnits(iFactoryCategory * categories.SUPPORTFACTORY * iTechCategory * iFactionCategory, false, true)
                if bDebugMessages == true then LOG(sFunctionRef..': Is table of support facs empty='..tostring(AiBotUtilities.IsTableEmpty(toSupportFactoriesToConsiderTransferring))) end
                if AiBotUtilities.IsTableEmpty(toSupportFactoriesToConsiderTransferring) == false then
                    local oTeammateToTransferTo
                    for iBrain, oBrain in tTeamData[iTeam][subreftoFriendlyActiveAiBotBrains] do
                        --Xfer support factories to the first teammate with a better tech level
                        if oBrain[sBrainFactoryTechVaraible] > math.max(1, iOurHighestTechLevelOfFactoryType) then
                            --Check if we have HQ of the right faction
                            local iUnitsOfCategory = oBrain:GetCurrentUnits(iFactionCategory * iTechCategory * AiBotUnitInfo.refCategoryAllHQFactories)
                            if bDebugMessages == true then LOG(sFunctionRef..': iUnitsOfCategory for brain '..oBrain.Nickname..'='..iUnitsOfCategory) end
                            if iUnitsOfCategory > 0 then
                                if bDebugMessages == true then LOG(sFunctionRef..': Will transfer units to this brain') end
                                oTeammateToTransferTo = oBrain
                                break
                            end
                        end
                    end
                    if oTeammateToTransferTo then
                        if bDebugMessages == true then LOG(sFunctionRef..': About to transfer all support factories to teammate '..oTeammateToTransferTo.Nickname..'; will list out toSupportFactoriesToConsiderTransferring')
                            for iUnit, oUnit in toSupportFactoriesToConsiderTransferring do
                                LOG(sFunctionRef..': Will transfer unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit))
                            end
                        end
                        TransferUnitsToPlayer(toSupportFactoriesToConsiderTransferring, oTeammateToTransferTo:GetArmyIndex(), false)
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function RefreshArtiAndNovaxCount(iTeam)
    tTeamData[iTeam][refiEnemyNovaxCount] = 0
    tTeamData[iTeam][refiEnemyT3ArtiCount] = 0
    if AiBotUtilities.IsTableEmpty(tTeamData[iTeam][reftEnemyArtiAndExpStructure]) == false then
        local iSatelliteCount = 0
        local iCentreCount = 0
        local iT3ArtiCount = 0
        for iUnit, oUnit in tTeamData[iTeam][reftEnemyArtiAndExpStructure] do
            if EntityCategoryContains(AiBotUnitInfo.refCategoryFixedT3Arti, oUnit.UnitId) then iT3ArtiCount = iT3ArtiCount + 1
            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryExperimentalArti, oUnit.UnitId) then iT3ArtiCount = iT3ArtiCount + 3
            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryNovaxCentre, oUnit.UnitId) then iCentreCount = iCentreCount + 1
            elseif EntityCategoryContains(AiBotUnitInfo.refCategorySatellite, oUnit.UnitId) then iSatelliteCount = iSatelliteCount + 1
            end
        end
        tTeamData[iTeam][refiEnemyNovaxCount] = math.max(iSatelliteCount, iCentreCount)
        tTeamData[iTeam][refiEnemyT3ArtiCount] = iT3ArtiCount
    end
    --If enemy has nuke and novax/t3 arti then upgrade shields covering SMD
    if (tTeamData[iTeam][refiEnemyNovaxCount] > 0 or tTeamData[iTeam][refiEnemyT3ArtiCount] > 0) then
        if AiBotUtilities.IsTableEmpty(tTeamData[iTeam][reftEnemyNukeLaunchers]) == false then
            ForkThread(AiBotBuilding.UpgradeShieldsCoveringSMD, iTeam)
        end
    end
end

function ConsiderAddingUnitAsSnipeTarget(oUnit, iTeam)
    local sFunctionRef = 'ConsiderAddingUnitAsSnipeTarget'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local bAddAsSnipeTarget = false
    local bIsUnderwater
    --Low health%:
    if AiBotUnitInfo.IsUnitValid(oUnit) then
        bIsUnderwater = AiBotUnitInfo.IsUnitUnderwater(oUnit)
        local iCurHealth = oUnit:GetHealth() oUnit:GetMaxHealth()
        local iMaxHealth = oUnit:GetMaxHealth()
        local iHealthPercent = iCurHealth / iMaxHealth
        local iBaseHealthThreshold = 0.5
        if bIsUnderwater then iBaseHealthThreshold = 0.3 end
        --For maps like UEF Mission 2 where AI ACU can sometimes move outside of safe location and take damage from not moving, and we have gunships who could suicide into it
        local bCampaignOrCombinedSnipe = false --Also use where we have a 2 friendly ACU vs 1 enemy ACU scenario via the ACU attack logic, and both are in range
        if AiBotMap.bIsCampaignMap and EntityCategoryContains(categories.COMMAND, oUnit.UnitId) then
            local iCampaignFactor = (oUnit[AiBotUnitInfo.refiCampaignSnipeAttempts] or 0)
            if oUnit[AiBotUnitInfo.refbIsSnipeTarget] then iCampaignFactor = iCampaignFactor - 1 end
            if bDebugMessages == true then LOG(sFunctionRef..': Considering campaign snipe on injured enemy ACU, iCampaignFactor='..iCampaignFactor..'; refiOurGunshipThreat='..(tTeamData[iTeam][subrefiOurGunshipThreat] or 'nil')..'; Have air control='..tostring(AiBotConditions.TeamHasAirControl(iTeam))..'; bIsUnderwater='..tostring(bIsUnderwater)..'; Brain target='..oUnit:GetAIBrain().Nickname..'; Time since ACU last fired='..GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiLastWeaponEvent] or 0)) end
            --First attempt we will go even if ACU is on full health if it has no nearby AA and has fired at us recently (with 20s buffer if it is already a snipe target, use - since shoudl be -1 campaign factor)
            if iCampaignFactor <= 5 and (iHealthPercent < 0.9 or iCampaignFactor <= 0 and oUnit[AiBotUnitInfo.refiLastWeaponEvent] and GetGameTimeSeconds() - oUnit[AiBotUnitInfo.refiLastWeaponEvent] <= (20 - 20 * iCampaignFactor)) and tTeamData[iTeam][subrefiOurGunshipThreat] >= 9600 + 1000 * iCampaignFactor and AiBotConditions.TeamHasAirControl(iTeam) and not(bIsUnderwater) and oUnit:GetAIBrain().BrainType == 'AI' and not(AiBotConditions.DoesAINicknameContainAiBot(oUnit:GetAIBrain().Nickname)) then
                --If enemy ACU is full health add extra check for nearby AA
                local bContinue = true
                if iHealthPercent >= 0.8 then
                    if iHealthPercent >= 0.9 then bContinue = false end
                    local iSearchRange = 40
                    if oUnit[AiBotUnitInfo.refbIsSnipeTarget] then iSearchRange = 20 end
                    local tNearbyEnemyAA = oUnit:GetAIBrain():GetUnitsAroundPoint(AiBotUnitInfo.refCategoryGroundAA, oUnit:GetPosition(), iSearchRange, 'Ally')
                    local iEnemyNearbyAAThreat = 0
                    if AiBotUtilities.IsTableEmpty(tNearbyEnemyAA) == false then iEnemyNearbyAAThreat = AiBotUnitInfo.GetAirThreatLevel(tNearbyEnemyAA, true, false, true, false, false, false) end
                    if bDebugMessages == true then LOG(sFunctionRef..': iEnemyNearbyAAThreat='..iEnemyNearbyAAThreat..'; 35% of our gunship threat='..tTeamData[iTeam][subrefiOurGunshipThreat] * 0.3) end
                    if iEnemyNearbyAAThreat <= tTeamData[iTeam][subrefiOurGunshipThreat] * 0.35 then
                        bContinue = false
                        iBaseHealthThreshold = 1
                        bCampaignOrCombinedSnipe = true
                    end
                end
                if bContinue then
                    if bDebugMessages == true then LOG(sFunctionRef..': Campaign so will be more likely to snipe') end
                    iBaseHealthThreshold = 0.8
                    bCampaignOrCombinedSnipe = true
                end
            end
        elseif oUnit[AiBotACU.reftCommonACUTarget] and AiBotACU.IsEnemyACUBeingTargetedByMultipleOfOurACUs(oUnit, iTeam) then
            --Is the health of our 2 ACUs significantly more than the health of their ACU?
            for iExistingEntry, tSubtable in oUnit[AiBotACU.reftCommonACUTarget] do
                if GetGameTimeSeconds() - (tSubtable[AiBotACU.subrefiTimeLastRecorded] or 0) <= 10 and AiBotUnitInfo.IsUnitValid(tSubtable[AiBotACU.subrefoSecondEnemyACU]) and tSubtable[AiBotACU.subrefoSecondEnemyACU]:GetAIBrain().AiBotTeam == iTeam and AiBotUnitInfo.IsUnitValid(tSubtable[AiBotACU.subrefoEnemyACU]) then
                    --Are we in range of both the ACUs?
                    if AiBotUtilities.GetDistanceBetweenPositions(tSubtable[AiBotACU.subrefoSecondEnemyACU]:GetPosition(), oUnit:GetPosition()) <= tSubtable[AiBotACU.subrefoSecondEnemyACU][AiBotUnitInfo.refiDFRange] and AiBotUtilities.GetDistanceBetweenPositions(tSubtable[AiBotACU.subrefoEnemyACU]:GetPosition(), oUnit:GetPosition()) <= tSubtable[AiBotACU.subrefoEnemyACU][AiBotUnitInfo.refiDFRange] then
                        local iEnemyHealthAndShield = AiBotUnitInfo.GetUnitCurHealthAndShield(oUnit)
                        local iOurHealthAndShield = AiBotUnitInfo.GetUnitCurHealthAndShield(tSubtable[AiBotACU.subrefoSecondEnemyACU]) + AiBotUnitInfo.GetUnitCurHealthAndShield(tSubtable[AiBotACU.subrefoEnemyACU])
                        if bDebugMessages == true then LOG(sFunctionRef..': iEnemyHealthAndShield='..iEnemyHealthAndShield..'; iOurHealthAndShield='..iOurHealthAndShield) end
                        if iOurHealthAndShield >= 1.5 * iEnemyHealthAndShield then
                            iBaseHealthThreshold = 0.85
                            bCampaignOrCombinedSnipe = true
                            break
                        end
                    end                    
                end
            end            
        end
        if oUnit[AiBotUnitInfo.refbIsSnipeTarget] then iBaseHealthThreshold = iBaseHealthThreshold+ 0.1 end
        if bDebugMessages == true then LOG(sFunctionRef..': Considering health threshold, iHealthPercent='..iHealthPercent..'; iBaseHealthThreshold='..iBaseHealthThreshold..'; bCampaignOrCombinedSnipe='..tostring(bCampaignOrCombinedSnipe)) end
        if iHealthPercent < iBaseHealthThreshold then
            --Check for shield
            local iCurShield, iMaxShield = AiBotUnitInfo.GetCurrentAndMaximumShield(oUnit, true)
            if iMaxShield > 0 then
                iCurHealth = iCurHealth + iCurShield
                iMaxHealth = iMaxHealth + iMaxShield
                iHealthPercent = iCurHealth / iMaxHealth
                if AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive then
                    iBaseHealthThreshold = iBaseHealthThreshold * 0.3 --be much less likely to choose snipe target for a unit that has a shield, especially in LOUD due to the short shield recharge
                else
                    iBaseHealthThreshold = iBaseHealthThreshold * 0.6 --be less likely to choose snipe target for a unit that has a shield
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Updated ACU target for shield, iCurShield='..iCurShield..'; iMaxShield='..iMaxShield..'; iHealthPercent post update='..iHealthPercent..'; iBaseHealthThreshold='..iBaseHealthThreshold) end
            end
            if iMaxShield == 0 or (iHealthPercent < iBaseHealthThreshold and (iHealthPercent < 0.4 or iCurShield / iMaxShield < 0.3)) then
                --Dont try and snipe lowest rated players on enemy team in full share
                local bLowRatedTarget = false
                local iBrainCount = 0
                if AiBotUtilities.bFAFActive and not(tTeamData[oUnit:GetAIBrain().AiBotTeam][refbAssassinationOrSimilar]) and ScenarioInfo.Options.Share == 'FullShare' and oUnit:GetAIBrain().Rating < 1500 and not(AiBotMap.bIsCampaignMap) then
                    --Get the average rating on the enemy team
                    local iTotalRating = 0
                    local iHighestRating = -1000
                    for iBrain, oBrain in tTeamData[oUnit:GetAIBrain().AiBotTeam][subreftoFriendlyHumanAndAIBrains] do
                        if not(oBrain:IsDefeated()) then
                            iTotalRating = iTotalRating + (oBrain.Rating or 0)
                            iBrainCount = iBrainCount + 1
                            iHighestRating = math.max(iHighestRating, (oBrain.Rating or 0))
                        end
                    end
                    if iBrainCount > 1 and oUnit:GetAIBrain().Rating < math.min(iTotalRating / iBrainCount, iHighestRating - 500) then
                        bLowRatedTarget = true
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering unit owned by brain '..oUnit:GetAIBrain().Nickname..'; that brains rating is '..(oUnit:GetAIBrain().Rating or 'nil')..'; Team iHighestRating='..iHighestRating..'; Team average rating='..iTotalRating / iBrainCount..'; bLowRatedTarget='..tostring(bLowRatedTarget)) end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': bLowRatedTarget='..tostring(bLowRatedTarget)) end
                if not(bLowRatedTarget) or (bCampaignOrCombinedSnipe and iHealthPercent + 0.1 < iBaseHealthThreshold) or (iHealthPercent < 0.2 and iHealthPercent < iBaseHealthThreshold * 0.5 and (oUnit:GetHealth() <= 1500 or iBrainCount == 2 or oUnit:GetAIBrain().Rating >= 1000)) then

                    --Very low health - attack
                    if (iHealthPercent < 0.175 or (iHealthPercent < 0.2 and oUnit[AiBotUnitInfo.refbIsSnipeTarget])) and (oUnit:GetHealth() <= 2000 or (oUnit[AiBotUnitInfo.refbIsSnipeTarget] and oUnit:GetHealth() <= 2500)) then
                        if bDebugMessages == true then LOG(sFunctionRef..': So low health that we might kill just with air') end
                        bAddAsSnipeTarget = true
                    elseif bCampaignOrCombinedSnipe then
                        bAddAsSnipeTarget = true
                        --Track attempts made so we can increase requirements to avoid being stuck in a failing pattern
                        if not(oUnit[AiBotUnitInfo.refbIsSnipeTarget]) then
                            oUnit[AiBotUnitInfo.refiCampaignSnipeAttempts] = (oUnit[AiBotUnitInfo.refiCampaignSnipeAttempts] or 0) + 1
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Will add as a campagin target, refiCampaignSnipeAttempts after adjustment='.. (oUnit[AiBotUnitInfo.refiCampaignSnipeAttempts] or 0)) end
                    else
                        --Is there a friendly ACU nearby with more health? Also factor in if that ACU has a better upgrade
                        local tNearbyAvailableACUs = {}
                        if AiBotConditions.IsTableOfUnitsStillValid(tTeamData[iTeam][reftAiBotACUs]) then
                            local iPlateauWanted = NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, oUnit:GetPosition())
                            local iMaxDistUntilInRange = 15
                            local iFriendlyACUHealthThreshold = math.min(iBaseHealthThreshold * 1.3, 0.95)
                            if iHealthPercent >= 0.5 then iFriendlyACUHealthThreshold = math.min(0.95, iFriendlyACUHealthThreshold * 1.1) end
                            local iFriendlyACUHealthPercent
                            if oUnit[AiBotUnitInfo.refbIsSnipeTarget] then iFriendlyACUHealthThreshold = iFriendlyACUHealthThreshold * 0.75 end
                            if oUnit[AiBotUnitInfo.refbIsSnipeTarget] then iMaxDistUntilInRange = iMaxDistUntilInRange + 15 end
                            local iDistAdjustment
                            for iFriendlyACU, oFriendlyACU in tTeamData[iTeam][reftAiBotACUs] do
                                if bDebugMessages == true then LOG(sFunctionRef..': Is friendly ACU owend by brain '..oFriendlyACU:GetAIBrain().Nickname..' available to do snipe attakc='..tostring(oFriendlyACU[AiBotACU.refbACUAvailableToDoSnipeAttack] or false)) end
                                if oFriendlyACU[AiBotACU.refbACUAvailableToDoSnipeAttack] then
                                    if NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, oFriendlyACU:GetPosition()) == iPlateauWanted then
                                        iDistAdjustment = 0
                                        if not(tTeamData[iTeam][refbDangerousForACUs]) and (oFriendlyACU[AiBotUnitInfo.refiDFRange] > oUnit[AiBotUnitInfo.refiDFRange] or (oFriendlyACU[AiBotACU.refiUpgradeCount] >= 2 and (oFriendlyACU[AiBotACU.refiUpgradeCount] >= 3 or not(EntityCategoryContains(categories.AEON, oFriendlyACU.UnitId))) and oFriendlyACU[AiBotACU.refiUpgradeCount] > (oUnit[AiBotACU.refiUpgradeCount] or 0))) then
                                            iDistAdjustment = 30
                                        end
                                        if bDebugMessages == true then LOG(sFunctionRef..': Dist to friendly ACU='..AiBotUtilities.GetDistanceBetweenPositions(oFriendlyACU:GetPosition(), oUnit:GetPosition())..'; DF range='..oFriendlyACU[AiBotUnitInfo.refiDFRange]..'; iMaxDistUntilInRange='..iMaxDistUntilInRange..'; Friendly ACU health%='.. AiBotUnitInfo.GetUnitHealthPercent(oFriendlyACU)) end
                                        if AiBotUtilities.GetDistanceBetweenPositions(oFriendlyACU:GetPosition(), oUnit:GetPosition()) <= oFriendlyACU[AiBotUnitInfo.refiDFRange] + iMaxDistUntilInRange + iDistAdjustment then
                                            iFriendlyACUHealthPercent = AiBotUnitInfo.GetUnitHealthPercent(oFriendlyACU)
                                            if iFriendlyACUHealthPercent >= iFriendlyACUHealthThreshold or (iFriendlyACUHealthPercent >= iFriendlyACUHealthThreshold * 0.8 and oFriendlyACU[AiBotUnitInfo.refiDFRange] > (oUnit[AiBotUnitInfo.refiCombatRange] or 0)) then
                                                table.insert(tNearbyAvailableACUs, oFriendlyACU)
                                            end
                                        end
                                    end
                                end
                            end
                            if AiBotUtilities.IsTableEmpty(tNearbyAvailableACUs) == false then
                                if bDebugMessages == true then LOG(sFunctionRef..': We have nearby available ACUs, size of table='..table.getn(tNearbyAvailableACUs)) end
                                if table.getn(tNearbyAvailableACUs) >= 2 or iHealthPercent < iBaseHealthThreshold - 0.1 then
                                    bAddAsSnipeTarget = true
                                    for iUnit, oUnit in tNearbyAvailableACUs do
                                        oUnit[AiBotACU.refbUseACUAggressively] = true
                                        --Note - ACU code has logic to set ACU target priorities if there is a nearby snipe target
                                    end
                                end
                            end
                        end
                        if not(bAddAsSnipeTarget) then
                            --Consider sniping if we could kill it with c. 2 bombers based on our current air tech
                            local iHealthThreshold
                            if tTeamData[iTeam][subrefiHighestFriendlyAirFactoryTech] == 1 then
                                iHealthThreshold = 1000
                            elseif tTeamData[iTeam][subrefiHighestFriendlyAirFactoryTech] == 2 then
                                iHealthThreshold = 2500
                            else iHealthThreshold = 4250
                            end
                            if oUnit[AiBotUnitInfo.refbIsSnipeTarget] then iHealthThreshold = iHealthThreshold + 500 end
                            if tTeamData[iTeam][subrefiOurT1ToT3BomberThreat] >= 500 then
                                iHealthThreshold = iHealthThreshold + math.min(750, tTeamData[iTeam][subrefiOurT1ToT3BomberThreat] * 0.5)
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering sniping if we could probably get enough bombers, iHealthThreshold='..iHealthThreshold..'; Unit health='..oUnit:GetHealth()..'; iHealthPercent='..iHealthPercent..'; Team bomber threat='..tTeamData[iTeam][subrefiOurT1ToT3BomberThreat]) end
                            if oUnit:GetHealth() <= iHealthThreshold then
                                local iShield = 0
                                if oUnit.MyShield.GetHealth then iShield = oUnit.MyShield:GetHealth() end
                                if iShield == 0 or oUnit:GetHealth() + iShield <= iHealthThreshold then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Adding as snipe target due to bomber vulnerability') end
                                    bAddAsSnipeTarget = true
                                end
                            end

                            if not(bAddAsSnipeTarget) and iHealthPercent <= 0.5 then
                                --If we have a significant threat in range of the ACU then treat it as a snipe target if we also have more threat than the enemy
                                local tACULZData, tACULZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, iTeam)
                                if tACULZTeamData and tACULZTeamData[AiBotMap.subrefThreatEnemyDFStructures] <= 1200 and tACULZTeamData[AiBotMap.subrefiNearbyEnemyLongRangeDFThreat] == 0 then
                                    local aiBrain = GetFirstActiveAiBotBrain(iTeam)
                                    local iNearbyThreatToACUSearchDist = 35
                                    if oUnit[AiBotUnitInfo.refbIsSnipeTarget] then iNearbyThreatToACUSearchDist = 45 end
                                    local toNearbyDFUnits
                                    if aiBrain and not(aiBrain:IsDefeated()) then
                                        toNearbyDFUnits = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryMobileDFLand - AiBotUnitInfo.refCategorySkirmisher, oUnit:GetPosition(), iNearbyThreatToACUSearchDist, 'Ally')
                                    end
                                    if AiBotUtilities.IsTableEmpty(toNearbyDFUnits) == false then
                                        local iNearbyFriendlyDFThreat = AiBotUnitInfo.GetCombatThreatRating(toNearbyDFUnits, false, false)
                                        local iMinThreatWanted
                                        local iACUCombatThreat = AiBotUnitInfo.GetCombatThreatRating({oUnit}, true, false)
                                        if iHealthPercent <= 0.3 then iMinThreatWanted = math.max(450, iACUCombatThreat + ((tACULZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0) - iACUCombatThreat) * 0.4)
                                        else iMinThreatWanted = math.max(600, AiBotUnitInfo.GetCombatThreatRating({oUnit}, true, false) + ((tACULZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0) - iACUCombatThreat) * 0.8)
                                        end
                                        if oUnit[AiBotACU.refiUpgradeCount] >= 2 and (oUnit[AiBotACU.refiUpgradeCount] >= 3 or oUnit:GetMaxHealth() >= 14000 or (oUnit.MyShield.GetHealth and oUnit.MyShield:GetHealth() > 0)) then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Dealing with heavily upgraded ACU') end
                                            iMinThreatWanted = iMinThreatWanted * 1.75
                                        end
                                        if oUnit[AiBotUnitInfo.refbIsSnipeTarget] then iMinThreatWanted = iMinThreatWanted * 0.85 end
                                        if bDebugMessages == true then LOG(sFunctionRef..': iNearbyFriendlyDFThreat='..iNearbyFriendlyDFThreat..'; iMinThreatWanted='..iMinThreatWanted..'; Enemy iACUCombatThreat='..iACUCombatThreat..'; Enemy mobile DF threat in zone of ACU less ACU value (since ACU included in this)='..((tACULZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0) - iACUCombatThreat)) end
                                        if iNearbyFriendlyDFThreat >= iMinThreatWanted then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Adding as snipe target due to snigificant nearby ground DF threat') end
                                            bAddAsSnipeTarget = true
                                        end
                                    end
                                end
                            end
                        end
                    end
                    if bAddAsSnipeTarget then
                        --Does the target have fixed shield coverage, or significant mobile shield coverage (WZ)?
                        local tTargetLZData, tTargetLZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, iTeam)
                        if bIsUnderwater then
                            if (tTargetLZTeamData[AiBotMap.subrefThreatEnemyShield] or 0) > 0 then
                                bAddAsSnipeTarget = false
                                if bDebugMessages == true then LOG(sFunctionRef..': Enemy has shields in this WZ') end
                            end
                        else
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering whether enemy target has fixed shield coverage, (tTargetLZTeamData[AiBotMap.subrefThreatEnemyShield]='..(tTargetLZTeamData[AiBotMap.subrefThreatEnemyShield] or 0)) end
                            if (tTargetLZTeamData[AiBotMap.subrefThreatEnemyShield] or 0) > 0 then
                                local tFixedAndMobileShields = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFixedShield + AiBotUnitInfo.refCategoryMobileLandShield, tTargetLZTeamData[AiBotMap.subrefTEnemyUnits])
                                local iMaxDistanceToShield = 10
                                local iCurDist, iCurShield, iMaxShield
                                if oUnit[AiBotUnitInfo.refbIsSnipeTarget] then iMaxDistanceToShield = 0 end
                                if AiBotUtilities.IsTableEmpty(tFixedAndMobileShields) == false then
                                    for iShield, oShield in tFixedAndMobileShields do
                                        if AiBotUnitInfo.IsUnitValid(oShield) then
                                            iCurShield, iMaxShield = AiBotUnitInfo.GetCurrentAndMaximumShield(oShield, false)
                                            if bDebugMessages == true then LOG(sFunctionRef..': Considering shield '..oShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield)..'; iCurShield='..iCurShield..'; Dist to ACU='..AiBotUtilities.GetDistanceBetweenPositions(oShield:GetPosition(), oUnit:GetPosition())..'; Shield radius='..(oShield:GetBlueprint().Defense.Shield.ShieldSize or 10) * 0.5) end
                                            if iCurShield >= 4000 or (iCurShield >= 2000 and iCurShield / iMaxShield >= 0.4) then
                                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oShield:GetPosition())
                                                if iCurDist <= iMaxDistanceToShield then
                                                    bAddAsSnipeTarget = false
                                                else
                                                    local iShieldRadius = (oShield:GetBlueprint().Defense.Shield.ShieldSize or 10) * 0.5
                                                    if iCurDist - iShieldRadius <= iMaxDistanceToShield then
                                                        bAddAsSnipeTarget = false
                                                    end
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Finished deciding if want to add as a snipe target, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' for iTeam='..iTeam..', was this a snipe target before='..tostring((oUnit[AiBotUnitInfo.refbIsSnipeTarget] or false))..'; bAddAsSnipeTarget='..tostring(bAddAsSnipeTarget)..'; bIsUnderwater='..tostring(bIsUnderwater)..'; Time='..GetGameTimeSeconds()) end
    if bIsUnderwater then
        local bRecordedAlready
        local tbSubteamsChecked = {}
        local iAirSubteam
        for iBrain, oBrain in tTeamData[iTeam][subreftoFriendlyActiveAiBotBrains] do
            iAirSubteam = oBrain.AiBotAirSubteam
            if not(tbSubteamsChecked[iAirSubteam]) then
                tbSubteamsChecked[iAirSubteam] = true
                bRecordedAlready = false
                if AiBotUtilities.IsTableEmpty(tAirSubteamData[iAirSubteam][reftoPriorityTorpedoUnitTargets]) == false then
                    for iRecorded, oRecorded in tAirSubteamData[iAirSubteam][reftoPriorityTorpedoUnitTargets] do
                        if oRecorded == oUnit then
                            bRecordedAlready = true
                            break
                        end
                    end
                end
                if bAddAsSnipeTarget == bRecordedAlready then
                    --Do nothing
                else
                    if bDebugMessages == true then LOG(sFunctionRef..': Deciding if want to add to the air subteam '..iAirSubteam..'; bAddAsSnipeTarget='..tostring(bAddAsSnipeTarget)..'; havent recorded already') end
                    if bAddAsSnipeTarget then
                        if tAirSubteamData[iAirSubteam][reftoPriorityTorpedoUnitTargets] == nil then tAirSubteamData[iAirSubteam][reftoPriorityTorpedoUnitTargets] = {} end
                        table.insert(tAirSubteamData[iAirSubteam][reftoPriorityTorpedoUnitTargets], oUnit)
                        if bDebugMessages == true then LOG(sFunctionRef..': Adding to priority torpedo unit targets') end
                    else
                        if AiBotUtilities.IsTableEmpty(tAirSubteamData[iAirSubteam][reftoPriorityTorpedoUnitTargets]) == false then --redundancy
                            for iRecorded, oRecorded in tAirSubteamData[iAirSubteam][reftoPriorityTorpedoUnitTargets] do
                                if oRecorded == oUnit then
                                    table.remove(tAirSubteamData[iAirSubteam][reftoPriorityTorpedoUnitTargets], iRecorded)
                                    break
                                end
                            end
                        end
                    end
                end
            end
        end
    elseif bAddAsSnipeTarget == (oUnit[AiBotUnitInfo.refbIsSnipeTarget] or false) then
        --Do nothing
    else
        --Are either removing or adding to snipe table
        if bAddAsSnipeTarget then
            table.insert(tTeamData[iTeam][toActiveSnipeTargets], oUnit)
        else
            for iEntry, oEntry in tTeamData[iTeam][toActiveSnipeTargets] do
                if oEntry == oUnit then
                    table.remove(tTeamData[iTeam][toActiveSnipeTargets], iEntry)
                    break
                end
            end
        end
        oUnit[AiBotUnitInfo.refbIsSnipeTarget] = bAddAsSnipeTarget
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function CheckForHidingACU(iTeam, iAirSubteam)
    --Intended to cover humans trying to keep their ACU hidden e.g. in a transport or underwater; called via air team overseer on a loop
    local sFunctionRef = 'CheckForHidingACU'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    
    if bDebugMessages == true then LOG(sFunctionRef..': Considering for iTeam='..(iTeam or 'nil')..'; iAirSubteam='..(iAirSubteam or 'nil')..'; Have air control='..tostring(tAirSubteamData[iAirSubteam][refbHaveAirControl] or false)..'; Highest friendly air fac tech='..(tTeamData[iTeam][subrefiHighestFriendlyAirFactoryTech] or 'nil')..'; Gross mass='..(tTeamData[iTeam][subrefiTeamGrossMass] or 'nil')..'; Enemy air to ground='..(tTeamData[iTeam][refiEnemyAirToGroundThreat] or 'nil')..'; Our bomber threat='..(tAirSubteamData[iAirSubteam][subrefiOurT1ToT3BomberThreat] or 'nil')..'; Our gunship threat='..(tAirSubteamData[iAirSubteam][subrefiOurGunshipThreat] or 'nil')..'; Time='..GetGameTimeSeconds()) end
    if tAirSubteamData[iAirSubteam][refbHaveAirControl] and tTeamData[iTeam][subrefiHighestFriendlyAirFactoryTech] >= 3 and tTeamData[iTeam][subrefiTeamGrossMass] >= 20 and math.max(tTeamData[iTeam][refiEnemyAirToGroundThreat], 500) < math.max(tAirSubteamData[iAirSubteam][subrefiOurT1ToT3BomberThreat], tAirSubteamData[iAirSubteam][subrefiOurGunshipThreat]) * 0.1 then
        if AiBotUtilities.IsTableEmpty(tTeamData[iTeam][reftEnemyACUs]) == false then
            --Check we have much more mass than all enemies
            local iEnemyMass = 0
            for iBrain, oBrain in tTeamData[iTeam][subreftoEnemyBrains] do
                if not(oBrain:IsDefeated()) then
                    iEnemyMass = iEnemyMass + oBrain:GetEconomyIncome('MASS')
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': iEnemyMass='..iEnemyMass) end
            local bEnemyHasBigThreat
            if iEnemyMass * 10 < math.min(tTeamData[iTeam][subrefiTeamGrossMass], 40) then
                --for sReferenceTable, iCategory in tEnemyBigThreatCategories do
                local bRecorded
                local aiBrain
                for iBrain, oBrain in tAirSubteamData[iAirSubteam][subreftoFriendlyAiBotBrains] do
                    aiBrain = oBrain
                    break
                end

                function CheckForBigThreats()
                    if bEnemyHasBigThreat == nil then
                        bEnemyHasBigThreat = false
                        --Check no big threat categories
                        for sReferenceTable, iCategory in tEnemyBigThreatCategories do
                            if AiBotUtilities.IsTableEmpty(tTeamData[iTeam][sReferenceTable]) == false then
                                for iBigThreat, oBigThreat in tTeamData[iTeam][sReferenceTable] do
                                    if not(EntityCategoryContains(categories.COMMAND, oBigThreat.UnitId)) then
                                        bEnemyHasBigThreat = true
                                        break
                                    end
                                end
                            end
                        end
                    end
                end
                for iACU, oACU in tTeamData[iTeam][reftEnemyACUs] do
                    if not(AiBotUnitInfo.CanSeeUnit(aiBrain, oACU)) then
                        CheckForBigThreats()
                        if bEnemyHasBigThreat then break end
                        bRecorded = false

                        if not(tAirSubteamData[iAirSubteam][reftPriorityUnitsWantingAirScout]) then
                            tAirSubteamData[iAirSubteam][reftPriorityUnitsWantingAirScout] = {}
                        elseif oACU[AiBotAir.refiTimeLastWantedPriorityAirScout] and AiBotUtilities.IsTableEmpty(tAirSubteamData[iAirSubteam][reftPriorityUnitsWantingAirScout]) == false then
                            for iUnit, oUnit in tAirSubteamData[iAirSubteam][reftPriorityUnitsWantingAirScout] do
                                if oUnit == oACU then bRecorded = true break end
                            end
                        end
                        oACU[AiBotAir.refiTimeLastWantedPriorityAirScout] = GetGameTimeSeconds()
                        if not(bRecorded) then
                            if bDebugMessages == true then LOG(sFunctionRef..': recording we have a priority scout target, for enemy ACU owned by '..oACU:GetAIBrain().Nickname) end
                            table.insert(tAirSubteamData[iAirSubteam][reftPriorityUnitsWantingAirScout], oACU)
                        end
                    elseif AiBotUnitInfo.IsUnitUnderwater(oACU) then
                        CheckForBigThreats()
                        if bEnemyHasBigThreat then break end
                        bRecorded = false
                        if not(tAirSubteamData[iAirSubteam][reftoPriorityTorpedoUnitTargets]) then
                            tAirSubteamData[iAirSubteam][reftoPriorityTorpedoUnitTargets] = {}
                        elseif AiBotUtilities.IsTableEmpty(tAirSubteamData[iAirSubteam][reftoPriorityTorpedoUnitTargets]) == false then
                            for iUnit, oUnit in tAirSubteamData[iAirSubteam][reftoPriorityTorpedoUnitTargets] do
                                if oUnit == oACU then bRecorded = true end
                            end
                        end
                        if not(bRecorded) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Adding ACU as a priority target for torpedo bombers') end
                            table.insert(tAirSubteamData[iAirSubteam][reftoPriorityTorpedoUnitTargets], oACU)
                        end
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end


function SnipeOverseer(iTeam)
    local sFunctionRef = 'SnipeOverseer'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    while true do
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitSeconds(1)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

        --Decide if want to stop monitoring
        if AiBotUtilities.IsTableEmpty(tTeamData[iTeam][toActiveSnipeTargets]) then
            if tTeamData[iTeam][refiEnemyAirAAThreat] >= 10000 and (tTeamData[iTeam][refiEnemyAirToGroundThreat] >= 10000 or not(AiBotConditions.TeamHasAirControl(iTeam))) and tTeamData[iTeam][refiConstructedExperimentalCount] > 0 and GetGameTimeSeconds() >= 1200 and (GetGameTimeSeconds() >= 1800 or AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryBomber - categories.TECH1 - categories.TECH2) >= 10) then
                if bDebugMessages == true then LOG(sFunctionRef..': We want to stop monitoring for snipe targets as game has gotten too late, iTeam='..iTeam..'; TIme='..GetGameTimeSeconds()) end
                break
            end
            if AiBotUtilities.IsTableEmpty(tTeamData[iTeam][reftEnemyACUs]) == false then
                for iUnit, oUnit in tTeamData[iTeam][reftEnemyACUs] do
                    ConsiderAddingUnitAsSnipeTarget(oUnit, iTeam)
                end
            end
        else
            --Either way we want to consider ACUs, since hte function will consider removing them from snipe targets or adding other snipe targets
            if AiBotUtilities.IsTableEmpty(tTeamData[iTeam][reftEnemyACUs]) == false then
                for iUnit, oUnit in tTeamData[iTeam][reftEnemyACUs] do
                    ConsiderAddingUnitAsSnipeTarget(oUnit, iTeam)
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': end of code') end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function MonitorLeavingT1SpamMode(iTeam)
    local sFunctionRef = 'MonitorLeavingT1SpamMode'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if bDebugMessages == true then LOG(sFunctionRef..': Will start monitoring whether we want to cancel our t1 spam flag for iTeam='..iTeam..'; Start of code, time='..GetGameTimeSeconds()) end
    if not(tTeamData[iTeam][refbActiveT1SpamMonitor]) and tTeamData[iTeam][refbFocusOnT1Spam] then
        tTeamData[iTeam][refbActiveT1SpamMonitor] = true

        local iMexesWantedToExitPre10m = table.getn(AiBotMap.tMassPoints) * 0.75
        local iMexesWantedToExitPost10mOrEnemyT2 = table.getn(AiBotMap.tMassPoints) * 0.65
        if bDebugMessages == true then LOG(sFunctionRef..': We are focusing on t1 spam at the moment, about to start main loop, iMexesWantedToExit='..iMexesWantedToExit) end
        while tTeamData[iTeam][refbFocusOnT1Spam] do --(allows us turning this off elsewhere, e.g. when we build enough T2 power that we can start reclaiming t1 power)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitSeconds(1)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            --Various cases where we want to stop t1 spam:
            if GetGameTimeSeconds() >= 1080 or (tTeamData[iTeam][subrefiHighestEnemyAirTech] or 0) >= 3 or (tTeamData[iTeam][subrefiHighestEnemyGroundTech] or 0) >= 3 or (tTeamData[iTeam][subrefiHighestEnemyGroundTech] or 0) >= 3
                    or (tTeamData[iTeam][refiEnemyAirToGroundThreat] or 0) >= 1000 or tTeamData[iTeam][subrefiTeamGrossMass] >= 20 or AiBotUtilities.IsTableEmpty(tTeamData[iTeam][reftoEnemyT2Arti]) == false
                    or tTeamData[iTeam][subrefiHighestFriendlyFactoryTech] >= 3 or tTeamData[iTeam][subrefiHighestFriendlyNavalFactoryTech] >= 2
                    or AiBotUtilities.IsTableEmpty(tTeamData[iTeam][reftoLongRangeEnemyDFUnits]) == false
                    or AiBotConditions.GetHighestOtherTeamT3MexCount(iTeam) >= 2 or AiBotUtilities.IsTableEmpty(tTeamData[iTeam][reftEnemyLandExperimentals]) == false or AiBotUtilities.IsTableEmpty(tTeamData[iTeam][refiConstructedExperimentalCount]) == false
                    or AiBotOverseer.bNoRushActive
                    --If built an average of 100 T1 tanks per player (+ up to 48 based on how long has elapsed) then also abort
                    or GetGameTimeSeconds() >= 420 and AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryMobileDFLand) >= (100 + math.max(0, (900 - GetGameTimeSeconds()))*0.1) * tTeamData[iTeam][subrefiActiveAiBotBrainCount]
            then
                if bDebugMessages == true then LOG(sFunctionRef..': Want to cancel t1 spam based on one of basic flags') end
                break
            else
                local bAllPersonalitiesDontWantSpam = true

                --How many mexes do we have
                local iTotalMexCount = 0
                for iBrain, oBrain in tTeamData[iTeam][subreftoFriendlyActiveAiBotBrains] do
                    iTotalMexCount = iTotalMexCount + oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryMex)
                    if not(oBrain[AiBotOverseer.refbPrioritiseDefence] or oBrain[AiBotOverseer.refbPrioritiseHighTech] or oBrain[AiBotOverseer.refbPrioritiseNavy] or oBrain[AiBotOverseer.refbPrioritiseAir]) then
                        bAllPersonalitiesDontWantSpam = false
                    end
                end
                if (iTotalMexCount >= iMexesWantedToExitPre10m and GetGameTimeSeconds() <= 600) or (iTotalMexCount >= iMexesWantedToExitPost10mOrEnemyT2 and (GetGameTimeSeconds() >= 600 or tTeamData[iTeam][subrefiHighestEnemyGroundTech] >= 2 or tTeamData[iTeam][subrefiHighestEnemyAirTech] >= 2)) then
                    if bDebugMessages == true then LOG(sFunctionRef..': Want to leave as have most of hte mexes on the map') end
                    break
                elseif bAllPersonalitiesDontWantSpam then
                    if bDebugMessages == true then LOG(sFunctionRef..': bAllPersonalitiesDontWantSpam is true so wont do t1 spam') end
                    break
                end
                --Exit t1 spam mode early on 10km maps
                if AiBotMap.iMapSize >= 512 and (GetGameTimeSeconds() >= 600 or (tTeamData[iTeam][subrefiHighestEnemyNavyTech] or 0) >= 1 or (tTeamData[iTeam][subrefiHighestFriendlyNavalFactoryTech] or 0) >= 1 or (tTeamData[iTeam][subrefiHighestFriendlyAirFactoryTech] or 0) >= 2 or tTeamData[iTeam][subrefiTeamGrossEnergy] >= 900 * tTeamData[iTeam][refiHighestBrainResourceMultiplier]) then
                    if bDebugMessages == true then LOG(sFunctionRef..': 10km so want to leave earlier than if was 5k') end
                    break
                end
                if bDebugMessages == true then LOG(sFunctionRef..': End of loop at time='..GetGameTimeSeconds()..'; want to continue with t1 spam for now') end
            end

        end
        if bDebugMessages == true then LOG(sFunctionRef..': Exiting t1 spam mode now for team '..iTeam..', time='..GetGameTimeSeconds()) end
        tTeamData[iTeam][refbFocusOnT1Spam] = false
        tTeamData[iTeam][refbActiveT1SpamMonitor] = false

    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function MonitorVulnerableFatboys(iTeam)
    if not(tTeamData[iTeam][refbActiveVulnerableFatboyMonitor]) then
        tTeamData[iTeam][refbActiveVulnerableFatboyMonitor] = true
        local iCurShield, iMaxShield
        while AiBotConditions.IsTableOfUnitsStillValid(tTeamData[iTeam][reftoVulnerableFatboys]) do
            for iCurFatboy = table.getn(tTeamData[iTeam][reftoVulnerableFatboys]), 1, -1 do
                local oFatboy = tTeamData[iTeam][reftoVulnerableFatboys][iCurFatboy]
                iCurShield, iMaxShield = AiBotUnitInfo.GetCurrentAndMaximumShield(oFatboy, true)
                if (iCurShield >= 1500 and iCurShield / iMaxShield >= 0.6) or AiBotUnitInfo.IsUnitUnderwater(oFatboy) then
                    table.remove(tTeamData[iTeam][reftoVulnerableFatboys], iCurFatboy)
                    if AiBotUtilities.IsTableEmpty(tTeamData[iTeam][refbActiveVulnerableFatboyMonitor]) then break end
                end
            end
            WaitSeconds(10)
        end
        tTeamData[iTeam][refbActiveVulnerableFatboyMonitor] = false
    end
end

function RefreshRecentEnemyTeleportLocations(iTeam)
    local sFunctionRef = 'RefreshRecentEnemyTeleportLocations'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if AiBotUtilities.IsTableEmpty(tTeamData[iTeam][reftRecentEnemyTeleportDetails]) == false then
        for iCurEntry = table.getn(tTeamData[iTeam][reftRecentEnemyTeleportDetails]), 1, -1 do
            local tCurEntry = tTeamData[iTeam][reftRecentEnemyTeleportDetails][iCurEntry]
            if bDebugMessages == true then LOG(sFunctionRef..': Considering entry '..iCurEntry..'; Is teleport unit valid='..tostring(AiBotUnitInfo.IsUnitValid(tCurEntry[subrefoTeleportUnit]))..'; reftActiveTeleportLocation='..repru(tCurEntry[subrefoTeleportUnit][AiBotUnitInfo.reftActiveTeleportLocation])..'; Cur time='..GetGameTimeSeconds()..'; Time since teleport attempt='..GetGameTimeSeconds() - tCurEntry[subrefiTeleportTime]) end
            if not(AiBotUnitInfo.IsUnitValid(tCurEntry[subrefoTeleportUnit])) or GetGameTimeSeconds() - tCurEntry[subrefiTeleportTime] >= 180 or not(tCurEntry[subrefoTeleportUnit][AiBotUnitInfo.reftActiveTeleportLocation]) or AiBotUtilities.GetDistanceBetweenPositions(tCurEntry[subrefoTeleportUnit][AiBotUnitInfo.reftActiveTeleportLocation], tCurEntry[subreftTeleportTarget]) >= 5 then
                table.remove(tTeamData[iTeam][reftRecentEnemyTeleportDetails], iCurEntry)
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function EnemyNovaxSatelliteMonitor(oNovax, iTeam)
    --Tracks enemy novax and flags for zones that are near it (so they can e.g. get more mobile shielding)
    local sFunctionRef = 'EnemyNovaxSatelliteMonitor'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iNearbyZoneMidpointDistThreshold  --Dist between the novax zone midpoint and the cur zone midpoint - want to beh igher than main search range in case novax is towards the edge of the midpoint
    local iNovaxDistToMidpointThreshold
    if AiBotMap.iMapSize >= 1000 then
        iNovaxDistToMidpointThreshold = 150
        iNearbyZoneMidpointDistThreshold = 200
    else
        iNearbyZoneMidpointDistThreshold = 150
        iNovaxDistToMidpointThreshold = 100
    end
    while AiBotUnitInfo.IsUnitValid(oNovax) and tTeamData[iTeam][subrefiActiveAiBotBrainCount] > 0 do
        local tStartLZOrWZData, tStartLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(oNovax:GetPosition(), true, iTeam)
        if tStartLZOrWZData then
            tStartLZOrWZTeamData[AiBotMap.refiTimeOfNearbyEnemyNovax] = GetGameTimeSeconds()
            AiBotAir.RecordOtherLandAndWaterZonesByDistance(tStartLZOrWZData)
            if AiBotUtilities.IsTableEmpty(tStartLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) == false then
                for iEntry, tSubtable in tStartLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
                    if tSubtable[AiBotMap.subrefiDistance] > iNearbyZoneMidpointDistThreshold then break end
                    local tAltLZOrWZData
                    local iCurLZOrWZRef = tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]
                    if tSubtable[AiBotMap.subrefbIsWaterZone] then
                        tAltLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iCurLZOrWZRef]][AiBotMap.subrefPondWaterZones][iCurLZOrWZRef]
                    else
                        tAltLZOrWZData = AiBotMap.tAllPlateaus[tSubtable[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPlateauLandZones][iCurLZOrWZRef]
                    end
                    if AiBotUtilities.GetDistanceBetweenPositions(oNovax:GetPosition(), tAltLZOrWZData[AiBotMap.subrefMidpoint]) <= iNovaxDistToMidpointThreshold then
                        local tAltLZOrWZTeamData
                        if tSubtable[AiBotMap.subrefbIsWaterZone] then
                            tAltLZOrWZTeamData = tAltLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                        else
                            tAltLZOrWZTeamData = tAltLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                        end
                        tAltLZOrWZTeamData[AiBotMap.refiTimeOfNearbyEnemyNovax] = GetGameTimeSeconds()
                    end
                end
            end
        end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitSeconds(1)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end


function SetIfLoseGameOnACUDeath(iTeam)
    local bAssassinationOrSimilar = true
    if ScenarioInfo.Options.Share == 'FullShare' or ScenarioInfo.Options.Victory == 'team_assassination' or not(AiBotUtilities.bFAFActive) then --For non-faf can xfer units to teammate when ACU dies; FAF prevents this
        if tTeamData[iTeam][subrefiActiveAiBotBrainCount] > 1 then
            bAssassinationOrSimilar = false
            if ScenarioInfo.Options.Victory == 'decapitation' and AiBotUtilities.bFAFActive then
                --Check as if only 1 ACU left on team then should be assassination
                local iPlayerWithACUCount = 0
                for iBrain, oBrain in tTeamData[iTeam][subreftoFriendlyHumanAndAIBrains] do
                    if not(oBrain.AiBotIsDefeated) and not(oBrain:IsDefeated()) then
                        if oBrain:GetCurrentUnits(categories.COMMAND) >= 1 then
                            iPlayerWithACUCount = iPlayerWithACUCount + 1
                        end
                    end
                end
                if iPlayerWithACUCount <= 1 then
                    bAssassinationOrSimilar = true
                end
            end
        else
            local iFriendlyBrainCount = 0
            if AiBotUtilities.IsTableEmpty(tTeamData[iTeam][subreftoFriendlyHumanAndAIBrains]) == false then
                for iBrain, oBrain in tTeamData[iTeam][subreftoFriendlyHumanAndAIBrains] do
                    if not(oBrain.AiBotIsDefeated) and not(oBrain:IsDefeated()) then
                        iFriendlyBrainCount = iFriendlyBrainCount + 1
                    end
                end
            end
            if iFriendlyBrainCount > 1 then
                bAssassinationOrSimilar = false
            else
                bAssassinationOrSimilar = true
            end
        end
    elseif ScenarioInfo.Options.Victory == 'demoralization' or ScenarioInfo.Options.Victory == 'decapitation' then
        bAssassinationOrSimilar = true
    else
        bAssassinationOrSimilar = false
    end
    tTeamData[iTeam][refbAssassinationOrSimilar] = bAssassinationOrSimilar
end

function ConsiderSpecialStrategyAssignment(iTeam)
    local sFunctionRef = 'ConsiderSpecialStrategyAssignment'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    --Ignore for campaign
    local bContinue = true
    if AiBotMap.bIsCampaignMap then
        bContinue = false
    end
    --Wait until map setup complete
    while bContinue and not(AiBotMap.bMapLandSetupComplete) or not(AiBotMap.bNearestEnemyBaseLZSetupComplete) do
        WaitTicks(1)
        if GetGameTimeSeconds() >= 6 then
            AiBotUtilities.ErrorHandler('Aborting special strategy as land zones not setup yet')
            bContinue = false
            break
        end
    end
    if bContinue then
        AiBotMap.CheckIfLowMexMap()
        if not(AiBotMap.bIsLowMexMap) and not(AiBotOverseer.bNoRushActive) then
            --Early bomber chance - lower if fewer enemies, lowest being 1v1 on small map
            local iBomberChance
            if AiBotMap.iMapSize <= 256 and iPlayersAtGameStart <= 4 then
                iBomberChance = 0.1
            elseif AiBotMap.iMapSize <= 512 and iPlayersAtGameStart <= 4 then
                iBomberChance = 0.175
            else
                iBomberChance = math.max(0.1, (0.3 * math.min(10, iPlayersAtGameStart) / 10))
            end
            if ScenarioInfo.Options.Score == 'yes' then --Reduce bomber chance as score can indicate if AiBot is going first bomber
                iBomberChance = math.max(math.min(0.1, iBomberChance * 0.6), iBomberChance * 0.35)
            end
            --If have AiBotAir or AiBotRush on team then make it slightly more likely
            local iAirOrRushCount = 0
            for iBrain, oBrain in tTeamData[iTeam][subreftoFriendlyActiveAiBotBrains] do
                if oBrain[AiBotOverseer.refbPrioritiseAir] then
                    iAirOrRushCount = iAirOrRushCount + 1
                elseif oBrain[AiBotOverseer.refbPrioritiseLowTech] then
                    iAirOrRushCount = iAirOrRushCount + 0.5
                end
            end
            if iAirOrRushCount > 0 then
                if bDebugMessages == true then LOG(sFunctionRef..': Increasing chance of bomber as we have air or rush on team, iAirOrRushCount='..iAirOrRushCount..'; total brains on team='..table.getn(tTeamData[iTeam][subreftoFriendlyActiveAiBotBrains])) end
                iBomberChance = math.min(0.5, iBomberChance * (1 + 0.6 * iAirOrRushCount / table.getn(tTeamData[iTeam][subreftoFriendlyActiveAiBotBrains])))
            end

            if bDebugMessages == true then LOG(sFunctionRef..': iBomberChance='..iBomberChance..'; ScenarioInfo.Options.Score='..ScenarioInfo.Options.Score) end
            if iBomberChance * 100 >= math.random(1, 100) then
                --Consider early bomber strategy for brain with closest enemy (unless in LOUD since bombers suck in LOUD)
                if bDebugMessages == true then LOG(sFunctionRef..': Considering if want to go first bomber, AiBotUtilities.bQuietModActive='..tostring(AiBotUtilities.bQuietModActive or false)..'; Time='..GetGameTimeSeconds()) end
                if not(AiBotUtilities.bLoudModActive) then
                    local iClosestEnemy = 700 --Dont want to consider if enemy is further away than this; e.g. burial mounds in LOUD players were 792 apart, and is probably at a borderline distnce for if want to
                    local oAiBotBrainWithClosestEnemy, iCurDist, iCurPlateau, iCurZone
                    local tFirstClosestEnemyBase

                    for iBrain, oBrain in tTeamData[iTeam][subreftoFriendlyActiveAiBotBrains] do
                        --Ignore if have chosen a land AI, or cant build bombers or t1 air facs
                        if not(oBrain[AiBotOverseer.refbPrioritiseLand]) and not(oBrain.AiBotEasy) and not(AiBotUnitInfo.IsUnitRestricted('uea0103', oBrain:GetArmyIndex())) and not(AiBotUnitInfo.IsUnitRestricted('ueb0102', oBrain:GetArmyIndex())) then
                            --Get dist to closest enemy
                            local tCurStart = AiBotMap.GetPlayerStartPosition(oBrain)
                            iCurPlateau, iCurZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tCurStart)
                            if iCurPlateau > 0 and iCurZone then
                                local tLZTeamData = AiBotMap.tAllPlateaus[iCurPlateau][AiBotMap.subrefPlateauLandZones][iCurZone][AiBotMap.subrefLZTeamData][iTeam]
                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tCurStart, tLZTeamData[AiBotMap.reftClosestEnemyBase])
                                if bDebugMessages == true then LOG(sFunctionRef..': iCurPlateau='..iCurPlateau..'; iCurZone='..iCurZone..'; tCurStart='..repru(tCurStart)..'; tLZTeamData[AiBotMap.reftClosestEnemyBase]='..repru(tLZTeamData[AiBotMap.reftClosestEnemyBase])..'; iCurDist='..iCurDist..'; Time='..GetGameTimeSeconds()..'; If in QUIET will increase curdist for UEF as their bombers are bad') end
                                --UEF T1 bombers arent good at 1-shotting enemy engineers in QUIET
                                if AiBotUtilities.bQuietModActive and oBrain:GetFactionIndex() == AiBotUnitInfo.refFactionUEF then iCurDist = iCurDist + 100 end
                                if iCurDist < iClosestEnemy then
                                    iClosestEnemy = iCurDist
                                    oAiBotBrainWithClosestEnemy = oBrain
                                    tFirstClosestEnemyBase = {tLZTeamData[AiBotMap.reftClosestEnemyBase][1], tLZTeamData[AiBotMap.reftClosestEnemyBase][2], tLZTeamData[AiBotMap.reftClosestEnemyBase][3]}
                                end
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Flagging we want first bomber for oAiBotBrainWithClosestEnemy='..(oAiBotBrainWithClosestEnemy.Nickname or 'nil')) end
                    if oAiBotBrainWithClosestEnemy then
                        oAiBotBrainWithClosestEnemy[AiBotOverseer.refbFirstBomber] = true
                        tAirSubteamData[oAiBotBrainWithClosestEnemy.AiBotAirSubteam][refbDontBuildEngiHunterEngineers] = true
                        --Chance of having 2nd brain go first bomber if they have a different base they are closest to
                        if tTeamData[iTeam][subrefiActiveAiBotBrainCount] >= 2 and math.random(1, 2) == 1 then
                            local tSecondClosestEnemyBase
                            local oSecondClosestBrain
                            local iSecondClosestEnemy = 700
                            for iBrain, oBrain in tTeamData[iTeam][subreftoFriendlyActiveAiBotBrains] do
                                --Ignore if have chosen a land AI, or cant build bombers or t1 air facs
                                if not(oBrain[AiBotOverseer.refbPrioritiseLand]) and not(oBrain == oAiBotBrainWithClosestEnemy) and not(AiBotUnitInfo.IsUnitRestricted('uea0103', oBrain:GetArmyIndex())) and not(AiBotUnitInfo.IsUnitRestricted('ueb0102', oBrain:GetArmyIndex())) then
                                    --Get dist to closest enemy
                                    local tCurStart = AiBotMap.GetPlayerStartPosition(oBrain)
                                    iCurPlateau, iCurZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tCurStart)
                                    if iCurPlateau > 0 and iCurZone then
                                        local tLZTeamData = AiBotMap.tAllPlateaus[iCurPlateau][AiBotMap.subrefPlateauLandZones][iCurZone][AiBotMap.subrefLZTeamData][iTeam]
                                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tCurStart, tLZTeamData[AiBotMap.reftClosestEnemyBase])
                                        if bDebugMessages == true then LOG(sFunctionRef..': iCurPlateau='..iCurPlateau..'; iCurZone='..iCurZone..'; tCurStart='..repru(tCurStart)..'; tLZTeamData[AiBotMap.reftClosestEnemyBase]='..repru(tLZTeamData[AiBotMap.reftClosestEnemyBase])..'; iCurDist='..iCurDist..'; Time='..GetGameTimeSeconds()) end
                                        if iCurDist < iSecondClosestEnemy then
                                            iSecondClosestEnemy = iCurDist
                                            oSecondClosestBrain = oBrain
                                            tSecondClosestEnemyBase = {tLZTeamData[AiBotMap.reftClosestEnemyBase][1], tLZTeamData[AiBotMap.reftClosestEnemyBase][2], tLZTeamData[AiBotMap.reftClosestEnemyBase][3]}
                                        end
                                    end
                                end
                            end
                            if oSecondClosestBrain and tSecondClosestEnemyBase and AiBotUtilities.GetDistanceBetweenPositions(tSecondClosestEnemyBase, tFirstClosestEnemyBase) >= 30 then
                                oSecondClosestBrain[AiBotOverseer.refbFirstBomber] = true
                                if bDebugMessages == true then LOG(sFunctionRef..': Flagging a second player ot go early bomber, oSecondClosestBrain='..oSecondClosestBrain.Nickname) end
                            end
                        end
                    end
                end
            end
            --Disable early bomber engineers some of the time
            if math.random(1,10) <= 3 then
                for iBrain, oBrain in tTeamData[iTeam][subreftoFriendlyActiveAiBotBrains] do
                    if not(oBrain[AiBotOverseer.refbPrioritiseAir]) and (oBrain[AiBotMap.refbCanPathToEnemyBaseWithLand] or math.random(1,3) == 1 or AiBotMap.iMapSize >= 700) then
                        tAirSubteamData[oBrain.AiBotAirSubteam][refbDontBuildEngiHunterEngineers] = true
                    end
                end
            end
            --Dont build LABs at all some of the time
            if not(ScenarioInfo.Options.AiBotPrioritiseBPs == 2) and math.random(1, 10) <= 4 then
                for iBrain, oBrain in tTeamData[iTeam][subreftoFriendlyActiveAiBotBrains] do
                    local overrides = oBrain[AiBotFactory.reftBlueprintPriorityOverride]
                    if overrides then
                        overrides['ual0106'] = -1000 --LAB
                        overrides['url0106'] = -1000 --LAB
                        overrides['uel0106'] = -1000 --Mechmarine
                    end
                end
            end
            --Non-LOUD - consider T2 bomber snipes as Cybran, and sometimes as Seraphim
            local iRandBomberSnipe = math.random(1, 100)
            local iThreshold = 5
            if AiBotUtilities.bLoudModActive then
                iThreshold = 4
            elseif AiBotMap.iMapSize <= 1024 and iPlayersAtGameStart >= 5 then
                if not(AiBotUtilities.bQuietModActive) and tTeamData[iTeam][refbAssassinationOrSimilar] then
                    iThreshold = 18
                else
                    iThreshold = 9
                end
            end
            if iRandBomberSnipe <= iThreshold then
                --Do we have cybran or seraphim on team? (only consider Seraphim some of the time though)
                local bHaveSuitableBrain = false
                local toBrainsToConsiderSniping = {}
                for iBrain, oBrain in tTeamData[iTeam][subreftoFriendlyActiveAiBotBrains] do
                    if not(oBrain.AiBotEasy) and oBrain[AiBotOverseer.refbPrioritiseAir] or not(oBrain[AiBotOverseer.refbPrioritiseLand] or oBrain[AiBotOverseer.refbPrioritiseNavy] or oBrain[AiBotOverseer.refbPrioritiseHighTech]) then
                        if oBrain:GetFactionIndex() == AiBotUnitInfo.refFactionCybran then
                            bHaveSuitableBrain = true
                            table.insert(toBrainsToConsiderSniping, oBrain)
                        elseif iRandBomberSnipe <= iThreshold * 0.5 and oBrain:GetFactionIndex() == AiBotUnitInfo.refFactionSeraphim then
                            bHaveSuitableBrain = true
                            table.insert(toBrainsToConsiderSniping, oBrain)
                        end
                    end
                end
                if bHaveSuitableBrain then
                    for iBrain, oBrain in toBrainsToConsiderSniping do
                        oBrain[AiBotOverseer.refbBomberSnipe] = true
                        if bDebugMessages == true then LOG(sFunctionRef..': Brain '..oBrain.Nickname..' should consider doing a t2 bomber snipe') end
                    end
                end
            end
            --Strats over gunships
            local iStratRNG = math.random(1,100)
            if not(AiBotUtilities.bLoudModActive) and (iStratRNG <= 10 or (AiBotUtilities.bQuietModActive and iStratRNG <= 50)) then
                for iBrain, oBrain in tTeamData[iTeam][subreftoFriendlyActiveAiBotBrains] do
                    oBrain[AiBotOverseer.refbStratsOverGunships] = true
                end
            end
            --Early T3 air rush if air slot
            if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to rush T3 air, subrefiActiveAiBotBrainCount='..tTeamData[iTeam][subrefiActiveAiBotBrainCount]) end
            if tTeamData[iTeam][subrefiActiveAiBotBrainCount] >= 3 and AiBotUtilities.bFAFActive then
                if math.random(1, 100) >= 50 then
                    if bDebugMessages == true then LOG(sFunctionRef..': Will rush T3 air if have base in a safe position') end
                    tTeamData[iTeam][subrefbRushT3AirInAirSlot] = true
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ConsiderTMLForLongRangeEnemyThreat(iTeam)
    local sFunctionRef = 'ConsiderTMLForLongRangeEnemyThreat'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if not(tTeamData[iTeam][refbTMLForLongRangeThreatMonitorActive]) then
        tTeamData[iTeam][refbTMLForLongRangeThreatMonitorActive] = true
        --Decide on key TML zone to counter enemy LR threats
        local iClosestLREnemy = 100000
        local oClosestLREnemy, iCurDist
        local iCurPlateau
        local iClosestPlateau, iClosestZone
        if AiBotUtilities.IsTableEmpty(tTeamData[iTeam][reftoLongRangeEnemyDFUnits]) == false then
            for iUnit, oUnit in tTeamData[iTeam][reftoLongRangeEnemyDFUnits] do
                iCurPlateau = (oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] or NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, oUnit:GetPosition()))
                if iCurPlateau > 0 and AiBotUtilities.IsTableEmpty(tTeamData[iTeam][reftiCoreZonesByPlateau][iCurPlateau]) == false then
                    for iZone, bTrue in tTeamData[iTeam][reftiCoreZonesByPlateau][iCurPlateau] do
                        local tLZData = AiBotMap.tAllPlateaus[iCurPlateau][AiBotMap.subrefPlateauLandZones][iZone]
                        if bDebugMessages == true then LOG(sFunctionRef..': iCurPlateau='..iCurPlateau..'; iZone='..iZone..'; tLZData[AiBotMap.subrefMidpoint]='..repru(tLZData[AiBotMap.subrefMidpoint])..'; Unit position='..repru(oUnit:GetPosition())) end
                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZData[AiBotMap.subrefMidpoint])
                        --Ignore if we have a TML battery near this zone
                        local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][iTeam]
                        if not(tLZTeamData[AiBotMap.refbNearbyTMLBattery]) then
                            --Reduce dist if we have TML battery flagged for this zone already (so e.g. when a 2nd long range enemy unit is detected we are less likely to build multiple tml batteries)
                            if tLZTeamData[AiBotMap.refbGetTMLBattery] then iCurDist = iCurDist - 50 end
                            if iCurDist < iClosestLREnemy and (iCurDist > 100 or tLZTeamData[AiBotMap.refbGetTMLBattery]) then --no point building at a core zone close to the enemy
                                iClosestLREnemy = iCurDist
                                iClosestPlateau = iCurPlateau
                                iClosestZone = iZone
                                oClosestLREnemy = oUnit
                                if bDebugMessages == true then LOG(sFunctionRef..': Setting oClosestLREnemy='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iZone='..(iZone or 'nil')..'; iClosestPlateau='..(iClosestPlateau or 'nil')) end
                            end
                        end
                    end
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Finished searching for oClosestLREnemy, oClosestLREnemy='..(oClosestLREnemy.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestLREnemy) or 'nil')..'; iClosestZone='..(iClosestZone or 'nil')) end
        if oClosestLREnemy then
            --Wait until it is enough of a threat to warrant a response
            while AiBotUnitInfo.IsUnitValid(oClosestLREnemy) and oClosestLREnemy:GetFractionComplete() < 0.25 do
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                WaitSeconds(10)
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            end
            if AiBotUnitInfo.IsUnitValid(oClosestLREnemy) and oClosestLREnemy:GetFractionComplete() >= 0.75 and EntityCategoryContains(AiBotUnitInfo.refCategoryLandExperimental, oClosestLREnemy.UnitId) then
                --Flag this zone to get TMLs, and nearby zones that they dont need to
                local tLZData = AiBotMap.tAllPlateaus[iClosestPlateau][AiBotMap.subrefPlateauLandZones][iClosestZone]
                local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][iTeam]
                if tLZTeamData then
                    tLZTeamData[AiBotMap.refbGetTMLBattery] = true
                    if bDebugMessages == true then LOG(sFunctionRef..': Flagging primary TML battery iCurPlateau='..iCurPlateau..'; iClosestZone='..iClosestZone) end
                    if bDebugMessages == true then LOG(sFunctionRef..': Flagging primary TML battery iCurPlateau='..iCurPlateau..'; iClosestZone='..iClosestZone..' due to '..oClosestLREnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestLREnemy)..' owned by '..oClosestLREnemy:GetAIBrain().Nickname..' at time='..GetGameTimeSeconds()) end
                    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                        for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                            local tAdjLZTeamData = AiBotMap.tAllPlateaus[iClosestPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                            tAdjLZTeamData[AiBotMap.refbNearbyTMLBattery] = true
                        end
                    end
                    while AiBotUnitInfo.IsUnitValid(oClosestLREnemy) do --i.e. if the unit we built TML in response to is dead, then dont consider others
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                        WaitTicks(AiBotLand.iTicksPerLandCycle)
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                    end
                    --Clear the LZ flag if hte unit we built TML battery in response to is dead, and free up monitor so can build in another zone if needed
                    tLZTeamData[AiBotMap.refbGetTMLBattery] = false
                else
                    AiBotUtilities.ErrorHandler('Somehow have a closest enemy but not a valid land zone', false, true)
                end
            end
        end
        tTeamData[iTeam][refbTMLForLongRangeThreatMonitorActive] = false
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function MonitorEnemyTeleportUpgrade(oACU, iTeam, sEnhancement)
    --If AiBot is an enemy then monitor for each enemy AiBot team to see if we gain visual of the ACU, and if/when we have visual, wait until they are 15% done with the teleport upgrade and then flag that enemy has teleport (so we can start taking countermeasures)
    local sFunctionRef = 'MonitorEnemyTeleportUpgrade'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local oAiBotBrain = GetFirstActiveAiBotBrain(iTeam)
    local iProgressToWorryAboutTeleDefence = math.random(15, 50)/100
    local bHaveSeenUpgradingOrSimilar = false
    local iPrevProgress = 0
    if AiBotUnitInfo.IsUnitValid(oACU) then iPrevProgress = oACU:GetWorkProgress() end
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, oACU='..oACU.UnitId..' owned by '..oACU:GetAIBrain().Nickname..'; iTeam='..iTeam..'; oAiBotBrain='..oAiBotBrain.Nickname..'; sEnhancement='..sEnhancement..'; Unit state='..AiBotUnitInfo.GetUnitState(oACU)..'; Is ACU upgrading='..tostring(oACU:IsUnitState('Upgrading'))..'; tTeamData[iTeam][refbEnemyHasTeleport]='..tostring(tTeamData[iTeam][refbEnemyHasTeleport] or false)..'; First 2 conditions='..tostring(AiBotUnitInfo.IsUnitValid(oACU) and oACU:IsUnitState('Upgrading'))..'; Second two='..tostring(not(oAiBotBrain.AiBotIsDefeated) and not(tTeamData[iTeam][refbEnemyHasTeleport]))..'; oAiBotBrain.AiBotIsDefeated='..tostring(oAiBotBrain.AiBotIsDefeated or false)..'; iProgressToWorryAboutTeleDefence='..iProgressToWorryAboutTeleDefence..'; Time='..GetGameTimeSeconds()) end

    while AiBotUnitInfo.IsUnitValid(oACU) and oACU:IsUnitState('Upgrading') and not(oAiBotBrain.AiBotIsDefeated) and not(tTeamData[iTeam][refbEnemyHasTeleport]) do
        --If progress has decreased cancel as enemy may have switched upgrades
        if bDebugMessages == true then LOG(sFunctionRef..': Start of loop, ACU progress='..oACU:GetWorkProgress()..'; Can see unit='..tostring(AiBotUnitInfo.CanSeeUnit(oAiBotBrain, oACU, true))..'; oACU[AiBotUnitInfo.refsLastEnhancementStarted]='..(oACU[AiBotUnitInfo.refsLastEnhancementStarted] or 'nil')) end
        if not(oACU[AiBotUnitInfo.refsLastEnhancementStarted] == sEnhancement) or oACU:GetWorkProgress() < iPrevProgress then
            if bDebugMessages == true then LOG(sFunctionRef..': Dont think we are still getting the upgrade') end
            break
        else
            if bHaveSeenUpgradingOrSimilar or AiBotUnitInfo.CanSeeUnit(oAiBotBrain, oACU, true) or oACU:GetWorkProgress() >= iProgressToWorryAboutTeleDefence then
                bHaveSeenUpgradingOrSimilar = true
                if oACU:GetWorkProgress() >= 0.1 then

                    if bDebugMessages == true then LOG(sFunctionRef..': Enemy is upgrading teleporter, setting flag for iTeam='..iTeam..' at time='..GetGameTimeSeconds()..'; ACU work progress='..oACU:GetWorkProgress()) end
                    tTeamData[iTeam][refbEnemyHasTeleport] = true
                    break
                end
            end
        end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitSeconds(1)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        if bDebugMessages == true then LOG(sFunctionRef..': End of loop at time='..GetGameTimeSeconds()..'; Is ACU valid='..tostring(AiBotUnitInfo.IsUnitValid(oACU))..'; oAiBotBrain.IsDefeated='..tostring(oAiBotBrain.IsDefeated or false)..'; Enemy has teleport='..tostring(tTeamData[iTeam][refbEnemyHasTeleport] or false)..'; ACU unit state='..AiBotUnitInfo.GetUnitState(oACU)) end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ConsiderDelayedMexDetection(oMex)
    WaitSeconds(30) --Competent human will be able to infer a mex is built within this timeframe typically
    if AiBotUnitInfo.IsUnitValid(oMex) then
        local oBuiltBrain = oMex:GetAIBrain()
        local tTeamsUpdated = {}
        for iBrain, oBrain in tTeamData[oBuiltBrain.AiBotTeam][subreftoEnemyBrains] do
            if oBrain.AiBotAI and not(tTeamsUpdated[oBrain.AiBotTeam]) then
                tTeamsUpdated[oBrain.AiBotTeam] = true
                if not(oMex[AiBotUnitInfo.reftbConsideredForAssignmentByTeam][oBrain.AiBotTeam]) then
                    AssignUnitToLandZoneOrPond(oBrain, oMex, false, false, true)
                end
            end
        end
    end
end

function TeamHasLostAIxOmniVision(iTeam)
    tTeamData[iTeam][subrefbTeamHasOmniVision] = false
    --Go through every land and water zone and reset radar and omni values
    function ResetLandOrWaterZone(tCurLZOrWZTeamData)
        tCurLZOrWZTeamData[AiBotMap.refiRadarCoverage] = 0
        tCurLZOrWZTeamData[AiBotMap.refiOmniCoverage] = 0
        if tCurLZOrWZTeamData[AiBotMap.refiSonarCoverage] then tCurLZOrWZTeamData[AiBotMap.refiSonarCoverage] = 0 end
        if tCurLZOrWZTeamData[AiBotMap.refoBestSonar] then
            tCurLZOrWZTeamData[AiBotMap.refoBestSonar]['AiBotUpdatedIntel'] = nil
            AiBotMap.UpdateZoneIntelForSonar(tCurLZOrWZTeamData[AiBotMap.refoBestSonar])
        end
        if tCurLZOrWZTeamData[AiBotMap.refoBestRadar] then
            tCurLZOrWZTeamData[AiBotMap.refoBestRadar]['AiBotUpdatedIntel'] = nil
            AiBotMap.UpdateZoneIntelForRadar(tCurLZOrWZTeamData[AiBotMap.refoBestRadar])
        end
    end
    for iPlateau, tPlateauData in AiBotMap.tAllPlateaus do
        for iLZ, tLZData in tPlateauData[AiBotMap.subrefPlateauLandZones] do
            ResetLandOrWaterZone(tLZData[AiBotMap.subrefLZTeamData][iTeam])
        end
    end
    for iPond, tPondSubtable in AiBotMap.tPondDetails do
        for iWaterZone, tWZData in tPondSubtable[AiBotMap.subrefPondWaterZones] do
            ResetLandOrWaterZone(tWZData[AiBotMap.subrefWZTeamData][iTeam])
        end
    end
end

function ConsiderHostileCivilianZoneFlagForDetectedUnit(oUnit, iTeam, bUnitDied)
    if bUnitDied then
        if AiBotUtilities.IsTableEmpty(tTeamData[iTeam][subreftoFriendlyActiveAiBotBrains]) == false then
            local iPlateauOrZero, iLandOrWaterZone, tLZOrWZTeamData
            if (oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] and oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]) then
                iPlateauOrZero = oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1]
                iLandOrWaterZone = oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]
                tLZOrWZTeamData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone][AiBotMap.subrefLZTeamData][iTeam]
            elseif oUnit[AiBotUnitInfo.reftAssignedWaterZoneByTeam][iTeam] then
                iPlateauOrZero = 0
                iLandOrWaterZone = oUnit[AiBotUnitInfo.reftAssignedWaterZoneByTeam][iTeam]
                tLZOrWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone][AiBotMap.subrefWZTeamData][iTeam]
            end
            if tLZOrWZTeamData[AiBotMap.refbHostileImmobileCombatCiviliansInZone] then
                local bStillHaveHostileImmobile = false
                if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                    for iEnemy, oEnemy in tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits] do
                        if oEnemy[AiBotUnitInfo.refbHostileImmobileCivilian] and not(oEnemy.Dead) and not(oEnemy == oUnit) then
                            bStillHaveHostileImmobile = true
                            break
                        end
                    end
                end
                tLZOrWZTeamData[AiBotMap.refbHostileImmobileCombatCiviliansInZone] = bStillHaveHostileImmobile
            end
        end
    else
        --First wait 1s to give a chance to see if unit is immobile
        WaitSeconds(1)
        if AiBotUnitInfo.IsUnitValid(oUnit) then
            --Check unit isn't moving, and has a combat attack
            if (EntityCategoryContains(categories.STRUCTURE, oUnit.UnitId) or AiBotUnitInfo.GetUnitSpeed(oUnit) <= 0.01)
                    and (oUnit[AiBotUnitInfo.refiDFRange] or 0) > 10 or (oUnit[AiBotUnitInfo.refiIndirectRange] or 0) > 0 or (oUnit[AiBotUnitInfo.refiAntiNavyRange] or 0) > 0 then
                --Wait until we have assigned the unit a land or water zone
                local iPlateauOrZero, iLandOrWaterZone
                local iCurCycle = 0
                local tLZOrWZTeamData
                while AiBotUnitInfo.IsUnitValid(oUnit) do
                    if (oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] and oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]) then
                        iPlateauOrZero = oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1]
                        iLandOrWaterZone = oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]
                        tLZOrWZTeamData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone][AiBotMap.subrefLZTeamData][iTeam]
                    elseif oUnit[AiBotUnitInfo.reftAssignedWaterZoneByTeam][iTeam] then
                        iPlateauOrZero = 0
                        iLandOrWaterZone = oUnit[AiBotUnitInfo.reftAssignedWaterZoneByTeam][iTeam]
                        tLZOrWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone][AiBotMap.subrefWZTeamData][iTeam]
                    end
                    iCurCycle = iCurCycle + 1
                    if iCurCycle >= 10 then break end
                    WaitSeconds(5)
                end
                if tLZOrWZTeamData then
                    tLZOrWZTeamData[AiBotMap.refbHostileImmobileCombatCiviliansInZone] = true
                    oUnit[AiBotUnitInfo.refbHostileImmobileCivilian] = true
                end
            end
        end
    end
end
